def carpeta_cartas():
    """Busca la carpeta de cartas y devuelve una ruta válida o None."""
    base = os.path.dirname(os.path.abspath(__file__))
    posibles = [
        os.environ.get("TRUCO_CARTAS", ""),
        os.path.join(base, "cartas"),
        "/storage/emulated/0/Download/truco_argentino_offline_pydroid3/cartas",
    ]
    for carpeta in posibles:
        if carpeta and os.path.isdir(carpeta):
            return carpeta
    return None


def carpeta_audios():
    """Busca Audios; si no existe, conserva la ruta esperada junto al .py."""
    base = os.path.dirname(os.path.abspath(__file__))
    posibles = [
        os.path.join(base, "Audios"),
        "/storage/emulated/0/Download/truco_argentino_offline_pydroid3/Audios",
    ]
    for carpeta in posibles:
        if os.path.isdir(carpeta):
            return carpeta
    return posibles[0]


def carpeta_escudos():
    """Carpeta 'escudos' (PNG/JPG con el nombre del club) junto al .py o dentro de cartas."""
    base = os.path.dirname(os.path.abspath(__file__))
    for carpeta in (os.environ.get("TRUCO_ESCUDOS", ""), os.path.join(base, "escudos"),
                    os.path.join(base, "Escudos"),
                    "/storage/emulated/0/Download/truco_argentino_offline_pydroid3/escudos"):
        if carpeta and os.path.isdir(carpeta):
            return carpeta
    return None


_CACHE_ESCUDOS = {}


def ruta_escudo(club):
    """Archivo de escudo para un club o None. Acepta 'Boca Juniors.png', 'boca_juniors.jpg', etc."""
    if club in _CACHE_ESCUDOS:
        return _CACHE_ESCUDOS[club]
    ruta = None
    carpeta = carpeta_escudos()
    if carpeta:
        clave = normalizar(club)
        try:
            for archivo in sorted(os.listdir(carpeta)):
                if archivo.lower().endswith((".png", ".jpg", ".jpeg", ".webp")) and normalizar(archivo) == clave:
                    ruta = os.path.join(carpeta, archivo)
                    break
        except OSError:
            ruta = None
    _CACHE_ESCUDOS[club] = ruta
    return ruta


def iniciales_club(club):
    if str(club) == "Cualquier club":
        return "?"
    palabras = [p for p in str(club).replace("'", " ").split() if p.lower() not in ("de", "la", "del", "y", "en")]
    if len(palabras) >= 2:
        return (palabras[0][0] + palabras[1][0]).upper()
    return str(club)[:2].upper()


def color_club(club):
    """Color estable por nombre (para el escudo genérico cuando falta la imagen)."""
    h = sum((i + 1) * ord(c) for i, c in enumerate(str(club)))
    r = random.Random(h)
    return (0.25 + r.random() * 0.55, 0.25 + r.random() * 0.55, 0.25 + r.random() * 0.55, 1)


