MADERA_CLARA = (0.50, 0.33, 0.16, 1)
MADERA_OSCURA = (0.20, 0.11, 0.05, 1)
PAÑO = (0.03, 0.12, 0.08, 1)
PAÑO_LUZ = (0.10, 0.30, 0.20, 1)
COLOR_BOTON = (0.14, 0.11, 0.08, 1)
