def ancho_marco(ancho, alto):
    return max(8.0, min(ancho, alto) * 0.022)


ORO = (0.86, 0.68, 0.25, 1)
ORO_OSCURO = (0.52, 0.38, 0.10, 1)


def _fichas(cx, cy, cantidad, radio, color, borde):
    """Pila de monedas vista de costado: pastillas apiladas con borde oscuro."""
    figuras = []
    h = radio * 0.55
    for i in range(cantidad):
        y = cy + i * h * 0.78
        figuras.append(((0, 0, 0, 0.28), True, (cx - radio + 2, y - 2, radio * 2, h), h / 2.0))
        figuras.append((borde, True, (cx - radio, y, radio * 2, h), h / 2.0))
        figuras.append((color, True, (cx - radio + 1.5, y + h * 0.18, radio * 2 - 3, h * 0.64), h * 0.32))
    return figuras


def _mazo(cx, cy, ancho_carta):
    """Mazo de cartas apoyado en la mesa, con sombra y leve desorden."""
    alto_carta = ancho_carta * 1.5
    figuras = [((0, 0, 0, 0.30), True, (cx - ancho_carta / 2.0 + 3, cy - 3, ancho_carta, alto_carta), 4)]
    for i in range(5):
        dx, dy = (i % 2) * 1.2, i * 1.6
        figuras.append(((0.93, 0.90, 0.80, 1), True, (cx - ancho_carta / 2.0 + dx, cy + dy, ancho_carta, alto_carta), 4))
    figuras.append(((0.45, 0.07, 0.07, 1), True,
                    (cx - ancho_carta / 2.0 + 4, cy + 12, ancho_carta - 8, alto_carta - 8), 3))
    figuras.append(((0.80, 0.62, 0.22, 1), True,
                    (cx - ancho_carta * 0.22, cy + 12 + alto_carta * 0.38, ancho_carta * 0.44, alto_carta * 0.22), 3))
    return figuras


def plan_de_bar(w, h, y_lejos, y_cerca, dpi=1.0):
    """Fondo de bar desenfocado que se ve detrás de la mesa: piso de baldosas en perspectiva, pared con zócalo,
    estantería con botellas, luces y sillas. Devuelve figuras ('rect'|'quad'|'elip'|'rrect', color, datos) con
    coordenadas relativas al widget (y hacia arriba). Los contrastes son bajos a propósito: simula el desenfoque."""
    ops = []
    alto_fondo = max(1.0, h - y_lejos)
    yh = y_lejos + alto_fondo * 0.46                      # línea donde el piso se une con la pared

    # --- Pared: degradé cálido (más claro cerca del piso, oscuro arriba) ---
    bandas = 18
    for i in range(bandas):
        t = i / float(bandas - 1)                          # 0 = junto al piso, 1 = arriba
        col = (0.34 - 0.22 * t, 0.19 - 0.12 * t, 0.10 - 0.06 * t, 1)
        ya = yh + (h - yh) * i / float(bandas)
        ops.append(("rect", col, (0, ya, w, (h - yh) / float(bandas) + 1)))
    # zócalo de madera y su moldura
    zoc = (h - yh) * 0.16
    ops.append(("rect", (0.20, 0.11, 0.05, 1), (0, yh, w, zoc)))
    ops.append(("rect", (0.55, 0.36, 0.18, 0.55), (0, yh + zoc, w, max(1.0, dpi * 2))))
    # estantería con botellas (fuera de foco)
    yb = yh + (h - yh) * 0.50
    ops.append(("rect", (0.10, 0.06, 0.03, 0.85), (0, yb - dpi * 3, w, dpi * 4)))
    botella = [(0.62, 0.38, 0.12), (0.18, 0.36, 0.18), (0.45, 0.20, 0.10), (0.70, 0.52, 0.20), (0.25, 0.25, 0.30)]
    rnd = _bar_azar(3)
    x = w * 0.03
    while x < w * 0.97:
        bw = w * rnd.uniform(0.018, 0.030)
        bh = (h - yb) * rnd.uniform(0.22, 0.42)
        c = botella[rnd.randrange(len(botella))]
        ops.append(("rrect", c + (0.55,), (x, yb, bw, bh, bw * 0.4)))
        ops.append(("rrect", c + (0.55,), (x + bw * 0.28, yb + bh * 0.9, bw * 0.44, bh * 0.35, bw * 0.2)))
        x += bw + w * rnd.uniform(0.012, 0.028)
    # luces cálidas desenfocadas
    for fx, fy, fr, fa in ((0.18, 0.78, 0.075, 0.10), (0.42, 0.88, 0.060, 0.09), (0.66, 0.74, 0.085, 0.10),
                           (0.88, 0.90, 0.055, 0.08), (0.30, 0.62, 0.045, 0.08), (0.78, 0.60, 0.050, 0.08)):
        cx, cy, r = w * fx, yh + (h - yh) * fy, w * fr
        ops.append(("elip", (1.0, 0.72, 0.30, fa), (cx - r, cy - r, 2 * r, 2 * r)))
        ops.append(("elip", (1.0, 0.80, 0.45, fa * 0.9), (cx - r * 0.55, cy - r * 0.55, 1.1 * r, 1.1 * r)))

    # --- Piso: baldosas rojas y crema en perspectiva (se achican hacia el fondo) ---
    y_abajo = y_lejos - h * 0.12
    y0 = y_lejos
    s_max = (yh - y_abajo) / max(1.0, (yh - y0))
    tw0 = w * 0.16
    rojo, crema = (0.44, 0.18, 0.14, 1), (0.62, 0.50, 0.37, 1)
    s, k = s_max, 0
    while s > 0.10:
        s2 = s * 0.80
        ya, yb2 = yh - (yh - y0) * s, yh - (yh - y0) * s2     # ya (más cerca, abajo) < yb2 (más lejos, arriba)
        twa, twb = tw0 * s ** 0.35, tw0 * s2 ** 0.35   # las baldosas se achican con la misma inclinación que los costados de la mesa
        n = int(w / max(1.0, twa)) // 2 + 3
        for i in range(-n, n):
            col = rojo if (i + k) % 2 == 0 else crema
            ops.append(("quad", col, (w / 2 + i * twa, ya, w / 2 + (i + 1) * twa, ya,
                                      w / 2 + (i + 1) * twb, yb2, w / 2 + i * twb, yb2)))
        s, k = s2, k + 1
    # velo cálido que apaga el piso y baja el contraste (efecto desenfoque)
    ops.append(("rect", (0.20, 0.11, 0.055, 0.62), (0, y_abajo, w, yh - y_abajo)))
    for fx, fr in ((0.20, 0.20), (0.55, 0.26), (0.85, 0.18)):   # manchas de luz grandes: borran el filo de las baldosas
        r = w * fr
        ops.append(("elip", (0.95, 0.65, 0.30, 0.07), (w * fx - r, (y_lejos + yh) / 2 - r * 0.35, 2 * r, 0.7 * r)))
    # sombra del zócalo sobre el piso
    for i in range(5):
        ops.append(("rect", (0, 0, 0, 0.07), (0, yh - dpi * (i + 1) * 3, w, dpi * 3)))

    # --- Sillas de bar (siluetas oscuras y suaves) ---
    base = y_lejos + (yh - y_lejos) * 0.12
    alto_s = (yh - y_lejos) * 0.95
    for cx in (w * 0.10, w * 0.90):
        ancho_s = w * 0.115
        col = (0.13, 0.07, 0.035, 0.80)
        ops.append(("rrect", col, (cx - ancho_s / 2, base + alto_s * 0.45, ancho_s, alto_s * 0.50, ancho_s * 0.25)))   # respaldo
        ops.append(("rrect", (0.20, 0.11, 0.05, 0.75), (cx - ancho_s * 0.38, base + alto_s * 0.56, ancho_s * 0.76, alto_s * 0.28, ancho_s * 0.18)))
        ops.append(("rrect", col, (cx - ancho_s * 0.55, base + alto_s * 0.38, ancho_s * 1.10, alto_s * 0.12, alto_s * 0.05)))   # asiento
        for dx in (-0.45, 0.45):
            ops.append(("rect", col, (cx + ancho_s * dx - dpi * 1.5, base - alto_s * 0.05, dpi * 3, alto_s * 0.45)))     # patas

    # --- Viñeta: arriba se oscurece para que se lean el nombre y las cartas del rival ---
    for i in range(10):
        t = i / 9.0
        ops.append(("rect", (0, 0, 0, 0.30 * (1 - t) ** 1.5), (0, h - (h * 0.30) * (i + 1) / 10.0, w, h * 0.30 / 10.0 + 1)))
    return ops


def _bar_azar(semilla):
    import random as _r
    return _r.Random(semilla)


def plan_de_mesa(ancho, alto, props=False, luz=False):
    if ancho <= 0 or alto <= 0:
        return []

    marco = ancho_marco(ancho, alto)
    figuras = [
        (MADERA, False, (0, 0, ancho, alto), 0),
        (MADERA_CLARA, False, (0, alto - marco * 0.22, ancho, marco * 0.10), 0),
        (MADERA_CLARA, False, (0, marco * 0.12, ancho, marco * 0.10), 0),
    ]

    # Vetas de la madera (franjas largas y finas, siempre iguales).
    rnd = random.Random(11)
    for _ in range(min(60, int(alto / 14))):
        y = rnd.uniform(0, alto)
        claro = rnd.random() < 0.5
        figuras.append(((1, 0.85, 0.6, 0.05) if claro else (0, 0, 0, 0.06), False,
                        (0, y, ancho, max(1.0, rnd.uniform(0.8, 2.4))), 0))

    for i in range(3):
        paso = marco * (0.30 + 0.22 * i)
        grosor = max(1.0, marco * 0.05)
        figuras.append((VENTA_OSCURA, False, (marco * 0.2, paso, ancho - marco * 0.4, grosor), 0))
        figuras.append((VENTA_OSCURA, False, (marco * 0.2, alto - paso - grosor, ancho - marco * 0.4, grosor), 0))

    figuras.append((MADERA_OSCURA, False, (marco, marco, ancho - 2 * marco, alto - 2 * marco), 0))
    borde = marco * 1.35
    # Sombra del paño hundido, vivo dorado y paño.
    figuras.append(((0, 0, 0, 0.35), True, (borde - 3, borde - 5, ancho - 2 * borde + 6, alto - 2 * borde + 6), borde * 0.95))
    figuras.append((ORO_OSCURO, True, (borde - 2, borde - 2, ancho - 2 * borde + 4, alto - 2 * borde + 4), borde * 0.92))
    figuras.append((PAÑO, True, (borde, borde, ancho - 2 * borde, alto - 2 * borde), borde * 0.9))
    # Viñeta: bordes del paño más oscuros, centro iluminado.
    figuras.append(((0, 0, 0, 0.30), True, (borde, borde, ancho - 2 * borde, alto - 2 * borde), borde * 0.9))

    for factor in (0.94, 0.82, 0.68, 0.54, 0.40, 0.26):
        w = (ancho - 2 * borde) * factor
        h = (alto - 2 * borde) * factor
        figuras.append(((PAÑO_LUZ[0], PAÑO_LUZ[1], PAÑO_LUZ[2], 0.07), True,
                        (ancho / 2.0 - w / 2.0, alto / 2.0 - h / 2.0, w, h), borde * 0.6))

    if luz:
        # Lámpara de bar colgada sobre la mesa: círculo de luz cálida en el centro y penumbra hacia los bordes.
        for factor, a in ((0.98, 0.030), (0.84, 0.036), (0.70, 0.042), (0.56, 0.048), (0.42, 0.054), (0.30, 0.060), (0.18, 0.060)):
            w = (ancho - 2 * borde) * factor
            h = (alto - 2 * borde) * factor * 0.90
            figuras.append(((1.0, 0.86, 0.52, a), True, (ancho / 2.0 - w / 2.0, alto * 0.54 - h / 2.0, w, h), min(w, h) / 2.0))
        # Penumbra: franjas oscuras pegadas al borde del paño, más fuertes cuanto más cerca de la madera.
        for k in range(5):
            d = borde * (1.0 + 0.45 * k)
            a = 0.085 * (5 - k) / 5.0
            fino = borde * 0.45
            figuras.append(((0, 0, 0, a), False, (borde, d, ancho - 2 * borde, fino), 0))
            figuras.append(((0, 0, 0, a), False, (borde, alto - d - fino, ancho - 2 * borde, fino), 0))
            figuras.append(((0, 0, 0, a), False, (d, borde, fino, alto - 2 * borde), 0))
            figuras.append(((0, 0, 0, a), False, (ancho - d - fino, borde, fino, alto - 2 * borde), 0))
        # Reflejo suave de la lámpara sobre el paño.
        rw, rh = (ancho - 2 * borde) * 0.34, (alto - 2 * borde) * 0.10
        figuras.append(((1, 0.95, 0.80, 0.045), True, (ancho / 2.0 - rw / 2.0, alto * 0.66, rw, rh), rh / 2.0))

    # Grano del paño (puntitos fijos, sin costo de imágenes externas).
    rnd = random.Random(5)
    for _ in range(min(260, int(ancho * alto / 1500))):
        x = rnd.uniform(borde * 1.3, ancho - borde * 1.3)
        y = rnd.uniform(borde * 1.3, alto - borde * 1.3)
        figuras.append(((1, 1, 1, 0.035) if rnd.random() < 0.5 else (0, 0, 0, 0.07), False,
                        (x, y, 1.6, 1.6), 0))

    if props and ancho > 220 and alto > 220:
        r = max(9.0, min(ancho, alto) * 0.045)
        m = borde + r * 1.7
        figuras += _fichas(ancho - m, alto - m - r * 2.2, 5, r, ORO, ORO_OSCURO)
        figuras += _fichas(ancho - m - r * 2.5, alto - m - r * 1.6, 3, r, (0.75, 0.15, 0.15, 1), (0.40, 0.06, 0.06, 1))
        figuras += _mazo(m + r * 0.6, alto - m - r * 3.2, r * 2.4)
        if alto > 700:
            figuras += _fichas(m + r, m, 4, r, (0.15, 0.35, 0.70, 1), (0.07, 0.17, 0.38, 1))
            figuras += _fichas(ancho - m, m, 6, r, ORO, ORO_OSCURO)

    return figuras


def estilo_boton(texto, font_size="12sp"):
    return {"text": texto, "font_size": font_size, "background_color": COLOR_BOTON, "color": (1, 1, 1, 1)}


class BotonMenu(ButtonBehavior, Label):
    """Botón con el estilo del menú principal: fondo de esquinas redondeadas con borde dorado.
    Conserva `background_color` (color de relleno) para el código que lo cambia (trivia, chat)."""
    background_color = ListProperty(COLOR_BOTON)

    def __init__(self, **kwargs):
        kwargs.setdefault("halign", "center")
        kwargs.setdefault("valign", "middle")
        super().__init__(**kwargs)
        self.bind(pos=self._dibujar, size=self._dibujar, state=self._dibujar, disabled=self._dibujar,
                  background_color=self._dibujar)
        self.bind(width=lambda w, *_: setattr(w, "text_size", (max(0, w.width - dp(12)), None)))
        self._dibujar()

    def _dibujar(self, *_):
        c = self.background_color
        abajo = self.state == "down"
        apagado = self.disabled
        self.canvas.before.clear()
        with self.canvas.before:
            Color(0, 0, 0, 0.30)
            RoundedRectangle(pos=self.pos, size=self.size, radius=[dp(10)])
            Color(c[0], c[1], c[2], c[3] * (0.55 if apagado else 1))
            RoundedRectangle(pos=self.pos, size=self.size, radius=[dp(10)])
            if abajo:
                Color(0.96, 0.78, 0.15, 0.22)
                RoundedRectangle(pos=self.pos, size=self.size, radius=[dp(10)])
            Color(0.96, 0.78, 0.15, 0.25 if apagado else (0.95 if abajo else 0.65))
            Line(rounded_rectangle=(self.x, self.y, self.width, self.height, dp(10)), width=1.1)


def boton_oscuro(texto, font_size="12sp"):
    return BotonMenu(**estilo_boton(texto, font_size))


def buscar_dorso(carpeta, archivos):
    for archivo in sorted(archivos):
        if not archivo.lower().endswith(EXTENSIONES):
            continue
        nombre = normalizar(archivo)
        if any(clave in nombre for clave in CLAVES_DORSO):
            return os.path.join(carpeta, archivo)
    return None


def fuerza(carta):
    numero, palo = carta
    if numero == 1 and palo == "espada": return 14
    if numero == 1 and palo == "basto": return 13
    if numero == 7 and palo == "espada": return 12
    if numero == 7 and palo == "oro": return 11
    if numero == 3: return 10
    if numero == 2: return 9
    if numero == 1: return 8
    if numero == 12: return 7
    if numero == 11: return 6
    if numero == 10: return 5
    if numero == 7: return 4
    if numero == 6: return 3
    if numero == 5: return 2
    if numero == 4: return 1
    return 0


def fuerza_mano(mano):
    return sum(fuerza(c) for c in mano)


def ganador_de_bazas(bazas, mano_inicial):
    """Misma regla que la mano real: devuelve 0 (jugador), 1 (IA) o None si todavía no se decidió."""
    j, ia = bazas.count(0), bazas.count(1)
    if j >= 2:
        return 0
    if ia >= 2:
        return 1
    if len(bazas) >= 3:
        return 0 if j > ia else 1 if ia > j else mano_inicial
    if len(bazas) == 2:
        if bazas[0] == -1 and bazas[1] == -1:
            return None
        if bazas[0] == bazas[1]:
            return bazas[0]
        if bazas[0] == -1:
            return bazas[1]
        if bazas[1] == -1:
            return bazas[0]
    return None


def _carta_sim(mano, rival_mesa, n_baza):
    """Política rápida que usan ambos lados dentro de las simulaciones; saca la carta de `mano`."""
    if rival_mesa is not None:
        fr = fuerza(rival_mesa)
        ganan = [c for c in mano if fuerza(c) > fr]
        if ganan:
            carta = min(ganan, key=fuerza)          # la más barata que gana
        else:
            iguales = [c for c in mano if fuerza(c) == fr]
            carta = iguales[0] if iguales else min(mano, key=fuerza)   # parda o tirar la peor
    else:
        orden = sorted(mano, key=fuerza)
        if n_baza == 0 and len(orden) > 2 and random.random() < 0.45:
            carta = orden[len(orden) // 2]           # a veces guarda la mejor
        else:
            carta = orden[-1]
    mano.remove(carta)
    return carta


def simular_mano_truco(ia_mano, riv_mano, bazas, mano_inicial, turno, ia_mesa=None, riv_mesa=None):
    """Juega la mano hasta el final con la política rápida. True si gana la IA."""
    ia, rv, bz = list(ia_mano), list(riv_mano), list(bazas)
    while True:
        ganador = ganador_de_bazas(bz, mano_inicial)
        if ganador is not None:
            return ganador == 1
        n = len(bz)
        if ia_mesa is None and riv_mesa is None:
            if turno == 1:
                ia_mesa = _carta_sim(ia, None, n)
                riv_mesa = _carta_sim(rv, ia_mesa, n)
            else:
                riv_mesa = _carta_sim(rv, None, n)
                ia_mesa = _carta_sim(ia, riv_mesa, n)
        elif ia_mesa is None:
            ia_mesa = _carta_sim(ia, riv_mesa, n)
        elif riv_mesa is None:
            riv_mesa = _carta_sim(rv, ia_mesa, n)
        fi, fr = fuerza(ia_mesa), fuerza(riv_mesa)
        g = 1 if fi > fr else 0 if fr > fi else -1
        bz.append(g)
        ia_mesa = riv_mesa = None
        turno = g if g in (0, 1) else mano_inicial


class MesaBox(BoxLayout):
    def __init__(self, props=False, luz=False, **kwargs):
        self.props = props
        self.luz = luz
        super().__init__(**kwargs)
        self.bind(pos=self.dibujar_fondo, size=self.dibujar_fondo)
        self.dibujar_fondo()

    def dibujar_fondo(self, *_):
        self.canvas.before.clear()
        with self.canvas.before:
            for color, redondeada, rect, radio in plan_de_mesa(self.width, self.height, self.props, self.luz):
                x, y, w, h = rect
                Color(*color)
                if redondeada:
                    RoundedRectangle(pos=(self.x + x, self.y + y), size=(w, h), radius=[radio])
                else:
                    Rectangle(pos=(self.x + x, self.y + y), size=(w, h))


class MesaPerspectiva(MesaBox):
    """Mesa de juego vista en perspectiva (como una mesa de bar vista desde la silla).

    El borde lejano es angosto, los costados se abren hacia abajo y se salen de la pantalla,
    y el borde cercano (con la mano) queda cortado por los lados del celular.
    """
    INSET_LEJOS = 0.08     # cuánto se mete el borde lejano desde cada costado (fracción del ancho)
    PENDIENTE = 0.40       # cuánto se abren los costados por cada píxel que baja (más = más inclinada)

    def __init__(self, **kwargs):
        self.ref_lejos = None
        self.ref_cerca = None
        self._redibujar = Clock.create_trigger(lambda dt: self.dibujar_fondo(), 0)
        super().__init__(**kwargs)

    def enlazar(self, lejos, cerca):
        """lejos: widget sobre el borde lejano (cartas del rival). cerca: widget de la mano."""
        self.ref_lejos, self.ref_cerca = lejos, cerca
        for wd in (lejos, cerca):
            wd.bind(pos=self._redibujar, size=self._redibujar)
        self._redibujar()

    @staticmethod
    def _mezcla(a, b, t):
        return tuple(a[i] + (b[i] - a[i]) * t for i in range(3)) + (1,)

    def dibujar_fondo(self, *_):
        self.canvas.before.clear()
        w, h = self.width, self.height
        if w <= 0 or h <= 0:
            return
        ox, oy = self.x, self.y
        if self.ref_lejos is not None and self.ref_cerca is not None and self.ref_cerca.height > 1:
            y_lejos = self.ref_lejos.y + self.ref_lejos.height * 0.25 - oy
            y_cerca = self.ref_cerca.y + self.ref_cerca.height * 0.30 - oy
        else:
            y_lejos, y_cerca = h * 0.80, h * 0.30
        y_lejos = min(max(y_lejos, h * 0.2), h)
        y_cerca = min(max(y_cerca, 0), y_lejos - 10)
        inset = w * self.INSET_LEJOS
        k = self.PENDIENTE

        def xl(y): return inset - k * (y_lejos - y)
        def xr(y): return w - inset + k * (y_lejos - y)

        riel = max(dp(10), w * 0.036)     # grosor del borde de madera (lados)
        riel_f = max(dp(7), h * 0.014)    # grosor del borde lejano
        saliente = max(dp(16), h * 0.040) # canto de madera cercano (donde apoya la mano)

        with self.canvas.before:
            # Pared / fondo del bar: salón desenfocado (piso a cuadros, estantería, sillas).
            Color(*MADERA_OSCURA)
            Rectangle(pos=(ox, oy), size=(w, h))
            for tipo, col, d in plan_de_bar(w, h, y_lejos, y_cerca, dp(1)):
                Color(*col)
                if tipo == "rect":
                    Rectangle(pos=(ox + d[0], oy + d[1]), size=(d[2], d[3]))
                elif tipo == "rrect":
                    RoundedRectangle(pos=(ox + d[0], oy + d[1]), size=(d[2], d[3]), radius=[d[4]])
                elif tipo == "elip":
                    Ellipse(pos=(ox + d[0], oy + d[1]), size=(d[2], d[3]))
                else:
                    Quad(points=(ox + d[0], oy + d[1], ox + d[2], oy + d[3], ox + d[4], oy + d[5], ox + d[6], oy + d[7]))

            # Frente de la mesa (debajo del canto cercano): madera oscura con vetas.
            Color(0.26, 0.15, 0.07, 1)
            Rectangle(pos=(ox, oy), size=(w, max(0, y_cerca - saliente)))
            rnd = random.Random(7)
            for _ in range(int(max(0, y_cerca) / 9)):
                yy = rnd.uniform(0, max(1, y_cerca - saliente))
                Color(0, 0, 0, 0.10) if rnd.random() < 0.5 else Color(1, 0.8, 0.5, 0.04)
                Rectangle(pos=(ox, oy + yy), size=(w, rnd.uniform(1, 2.2)))

            # Madera que rodea el paño (costados y borde lejano).
            Color(*MADERA_CLARA)
            Quad(points=(ox + xl(y_cerca) - riel, oy + y_cerca,
                         ox + xl(y_lejos) - riel, oy + y_lejos + riel_f,
                         ox + xr(y_lejos) + riel, oy + y_lejos + riel_f,
                         ox + xr(y_cerca) + riel, oy + y_cerca))
            # Bisel del marco: borde exterior oscuro, vetas largas y brillo en el filo interior.
            borde_ext = [ox + xl(y_cerca) - riel, oy + y_cerca, ox + xl(y_lejos) - riel, oy + y_lejos + riel_f,
                         ox + xr(y_lejos) + riel, oy + y_lejos + riel_f, ox + xr(y_cerca) + riel, oy + y_cerca]
            Color(0, 0, 0, 0.40)
            Line(points=borde_ext, width=max(1.0, dp(1.3)))
            rv = random.Random(21)
            for fr in (0.28, 0.50, 0.74):
                dd = riel * fr
                Color(0, 0, 0, 0.10 + 0.06 * rv.random()) if rv.random() < 0.6 else Color(1, 0.85, 0.55, 0.07)
                Line(points=[ox + xl(y_cerca) - dd, oy + y_cerca, ox + xl(y_lejos) - dd, oy + y_lejos + riel_f * (1 - fr) + 0.5,
                             ox + xr(y_lejos) + dd, oy + y_lejos + riel_f * (1 - fr) + 0.5, ox + xr(y_cerca) + dd, oy + y_cerca],
                     width=max(0.8, dp(0.8)))
            Color(1, 0.88, 0.60, 0.30)   # brillo del filo interior (donde la luz pega en el canto)
            Line(points=[ox + xl(y_cerca) - dp(3), oy + y_cerca, ox + xl(y_lejos) - dp(3), oy + y_lejos + dp(3),
                         ox + xr(y_lejos) + dp(3), oy + y_lejos + dp(3), ox + xr(y_cerca) + dp(3), oy + y_cerca],
                 width=max(1.0, dp(1.2)))
            # Sombra del canto lejano sobre la pared.
            Color(0, 0, 0, 0.35)
            Rectangle(pos=(ox + xl(y_lejos) - riel, oy + y_lejos + riel_f), size=(xr(y_lejos) - xl(y_lejos) + 2 * riel, dp(3)))
            # Vivo dorado entre madera y paño.
            Color(*ORO_OSCURO)
            Quad(points=(ox + xl(y_cerca) - dp(2), oy + y_cerca,
                         ox + xl(y_lejos) - dp(2), oy + y_lejos + dp(2),
                         ox + xr(y_lejos) + dp(2), oy + y_lejos + dp(2),
                         ox + xr(y_cerca) + dp(2), oy + y_cerca))

            # Paño: la luz de la lámpara forma un óvalo (se apaga hacia adelante, atrás y los costados).
            franjas, columnas = 30, 9
            base = tuple(c * 0.72 for c in PAÑO[:3]) + (1,)   # fieltro en sombra, más oscuro que antes
            for i in range(franjas):
                ta, tb = i / float(franjas), (i + 1) / float(franjas)      # 0 = cerca, 1 = lejos
                ya = y_cerca + (y_lejos - y_cerca) * ta
                yb = y_cerca + (y_lejos - y_cerca) * tb + 1.0
                luz_y = max(0.0, 1.0 - abs((ta + tb) / 2.0 - 0.55) * 1.9)
                for j in range(columnas):
                    ja, jb = j / float(columnas), (j + 1) / float(columnas)
                    luz_x = max(0.0, 1.0 - abs((ja + jb) / 2.0 - 0.5) * 2.0)
                    luz = (luz_y ** 1.2) * (0.25 + 0.75 * luz_x ** 1.3)
                    Color(*self._mezcla(base, PAÑO_LUZ, 1.0 * luz))
                    xa0, xa1 = xl(ya) + (xr(ya) - xl(ya)) * ja, xl(ya) + (xr(ya) - xl(ya)) * jb + 0.8
                    xb0, xb1 = xl(yb) + (xr(yb) - xl(yb)) * ja, xl(yb) + (xr(yb) - xl(yb)) * jb + 0.8
                    Quad(points=(ox + xa0, oy + ya, ox + xa1, oy + ya, ox + xb1, oy + yb, ox + xb0, oy + yb))
            # Penumbra pegada al borde lejano y a los costados.
            for i in range(6):
                d = (i + 1) * dp(5)
                Color(0, 0, 0, 0.10 * (6 - i) / 6.0)
                Rectangle(pos=(ox + xl(y_lejos - d), oy + y_lejos - d), size=(xr(y_lejos - d) - xl(y_lejos - d), dp(5)))
            for lado in (0, 1):
                for i in range(4):
                    a = 0.10 * (4 - i) / 4.0
                    d = (i + 1) * dp(6)
                    Color(0, 0, 0, a)
                    if lado == 0:
                        Quad(points=(ox + xl(y_cerca), oy + y_cerca, ox + xl(y_lejos), oy + y_lejos,
                                     ox + xl(y_lejos) + d, oy + y_lejos, ox + xl(y_cerca) + d, oy + y_cerca))
                    else:
                        Quad(points=(ox + xr(y_cerca), oy + y_cerca, ox + xr(y_lejos), oy + y_lejos,
                                     ox + xr(y_lejos) - d, oy + y_lejos, ox + xr(y_cerca) - d, oy + y_cerca))

            # Grano del paño.
            # (más fibras de fieltro: motitas y hebras cortitas, más marcadas cerca de la mano)
            rnd = random.Random(5)
            for _ in range(900):
                yy = rnd.uniform(y_cerca, y_lejos)
                xx = rnd.uniform(max(0, xl(yy)) + dp(4), min(w, xr(yy)) - dp(4))
                cerca = 1.0 - (yy - y_cerca) / max(1.0, (y_lejos - y_cerca))
                if rnd.random() < 0.55:
                    Color(1, 1, 1, 0.03 + 0.04 * cerca) if rnd.random() < 0.5 else Color(0, 0, 0, 0.06 + 0.05 * cerca)
                    Rectangle(pos=(ox + xx, oy + yy), size=(1.6, 1.6))
                else:   # hebra
                    Color(0.75, 0.95, 0.80, 0.035 + 0.03 * cerca) if rnd.random() < 0.5 else Color(0, 0, 0, 0.06)
                    Rectangle(pos=(ox + xx, oy + yy), size=(rnd.uniform(3, 7), 0.8))

            # Canto cercano de madera (de lado a lado) donde apoya la mano.
            Color(*MADERA_CLARA)
            Rectangle(pos=(ox, oy + y_cerca - saliente), size=(w, saliente))
            Color(1, 0.85, 0.55, 0.18)
            Rectangle(pos=(ox, oy + y_cerca - dp(2)), size=(w, dp(2)))
            Color(0, 0, 0, 0.35)
            Rectangle(pos=(ox, oy + y_cerca - saliente), size=(w, dp(2)))
            # Cara baja del canto (más oscura) y sombra que cae hacia el frente de la mesa.
            Color(0, 0, 0, 0.16)
            Rectangle(pos=(ox, oy + y_cerca - saliente), size=(w, saliente * 0.45))
            for i in range(5):
                Color(0, 0, 0, 0.26 * (5 - i) / 5.0)
                Rectangle(pos=(ox, oy + y_cerca - saliente - dp(3) * (i + 1)), size=(w, dp(3)))
            # Sombra del canto sobre el paño.
            Color(0, 0, 0, 0.30)
            Rectangle(pos=(ox, oy + y_cerca), size=(w, dp(6)))


class FilaPanel(Label):
    """Fila de tabla con fondo de tarjeta (opcionalmente resaltada)."""
    def __init__(self, fondo=(0, 0, 0, 0.28), borde=None, **kwargs):
        kwargs.setdefault("halign", "left")
        kwargs.setdefault("valign", "middle")
        super().__init__(**kwargs)
        self.fondo = fondo
        self.borde = borde
        self.bind(pos=self._dibujar, size=self._dibujar)
        self.bind(size=self._ajustar_texto)
        self._ajustar_texto()
        self._dibujar()

    def _ajustar_texto(self, *_):
        self.text_size = (max(0, self.width - dp(16)), self.height)

    def _dibujar(self, *_):
        self.canvas.before.clear()
        with self.canvas.before:
            if self.borde:
                Color(*self.borde)
                RoundedRectangle(pos=(self.x - 1, self.y - 1), size=(self.width + 2, self.height + 2), radius=[dp(7)])
            Color(*self.fondo)
            RoundedRectangle(pos=self.pos, size=self.size, radius=[dp(6)])


class Escudo(Widget):
    """Escudo del club: imagen si existe en la carpeta 'escudos', si no una insignia genérica con iniciales."""
    def __init__(self, club, lado=34, **kwargs):
        super().__init__(size_hint=(None, None), size=(dp(lado), dp(lado)), **kwargs)
        self.club = club
        self.ruta = ruta_escudo(club)
        self.etiqueta = None
        if self.ruta:
            self.imagen = Image(source=self.ruta, allow_stretch=True, keep_ratio=True)
            self.add_widget(self.imagen)
        else:
            self.imagen = None
            self.etiqueta = Label(text=iniciales_club(club), bold=True, font_size="%dsp" % max(9, int(lado * 0.36)),
                                  color=(1, 1, 1, 1))
            self.add_widget(self.etiqueta)
        self.bind(pos=self._dibujar, size=self._dibujar)
        self._dibujar()

    def _dibujar(self, *_):
        self.canvas.before.clear()
        with self.canvas.before:
            if not self.ruta:
                c = color_club(self.club)
                Color(0, 0, 0, 0.35)
                RoundedRectangle(pos=(self.x + 1, self.y - 1), size=self.size, radius=[self.width / 2.0])
                Color(1, 1, 1, 0.9)
                RoundedRectangle(pos=self.pos, size=self.size, radius=[self.width / 2.0])
                Color(*c)
                RoundedRectangle(pos=(self.x + dp(2), self.y + dp(2)),
                                 size=(self.width - dp(4), self.height - dp(4)), radius=[self.width / 2.0])
        if self.imagen is not None:
            self.imagen.pos = self.pos
            self.imagen.size = self.size
        if self.etiqueta is not None:
            self.etiqueta.pos = self.pos
            self.etiqueta.size = self.size


class Fosforos(Widget):
    """Tanteador con palitos de fósforo: cada cuadrito son 5 puntos (4 lados + diagonal).
    Arriba las malas (primera mitad) y abajo las buenas (segunda mitad); cada mitad es una fila
    (a 18: 9 malas y 9 buenas = un cuadrito de 5 y otro de 4 palitos por fila)."""
    def __init__(self, total=PUNTOS_PARTIDA, **kwargs):
        super().__init__(**kwargs)
        self.total = total
        self.puntos = 0
        self.bind(pos=self._dibujar, size=self._dibujar)

    def set_puntos(self, puntos):
        self.puntos = max(0, min(int(puntos), self.total))
        self._dibujar()

    def _palito(self, a, b, lado):
        """Un fósforo de a hacia b: madera clara y cabeza roja en b."""
        dx, dy = b[0] - a[0], b[1] - a[1]
        largo = math.hypot(dx, dy) or 1.0
        ux, uy = dx / largo, dy / largo
        ext = lado * 0.09
        x1, y1 = a[0] - ux * ext, a[1] - uy * ext
        x2, y2 = b[0] + ux * ext, b[1] + uy * ext
        grosor = max(dp(1.6), lado * 0.09)
        Color(0, 0, 0, 0.35)
        Line(points=[x1 + 1, y1 - 1, x2 + 1, y2 - 1], width=grosor, cap="round")
        Color(0.94, 0.83, 0.55, 1)
        Line(points=[x1, y1, x2, y2], width=grosor, cap="round")
        radio = grosor * 0.95
        Color(0.80, 0.14, 0.08, 1)
        Ellipse(pos=(x2 - radio, y2 - radio), size=(radio * 2, radio * 2))

    def _dibujar(self, *_):
        self.canvas.clear()
        mitad = int(math.ceil(self.total / 2.0))   # puntos de cada fila: malas arriba, buenas abajo
        por_fila = int(math.ceil(mitad / 5.0))
        filas = 2
        celda_w = self.width / float(por_fila)
        celda_h = self.height / float(filas)
        lado = max(dp(6), min(celda_w, celda_h) * 0.66)
        with self.canvas:
            Color(1, 1, 1, 0.20)
            Line(points=[self.x + dp(4), self.y + self.height / 2.0,
                         self.right - dp(4), self.y + self.height / 2.0], width=1)
            for k in range(por_fila * filas):
                fila, col = divmod(k, por_fila)
                cap = max(0, min(5, mitad - 5 * col))   # el último cuadrito de la fila puede tener menos de 5 palitos
                cx = self.x + celda_w * (col + 0.5)
                cy = self.top - celda_h * (fila + 0.5)
                l, r = cx - lado / 2.0, cx + lado / 2.0
                b, t = cy - lado / 2.0, cy + lado / 2.0
                Color(1, 1, 1, 0.07)
                Line(rectangle=(l, b, lado, lado), width=1)
                n = max(0, min(cap, self.puntos - (fila * mitad + 5 * col)))
                lados = [((l, b), (r, b)), ((r, b), (r, t)), ((r, t), (l, t)),
                         ((l, t), (l, b)), ((l, b), (r, t))]
                for i in range(n):
                    self._palito(lados[i][0], lados[i][1], lado)


PIEL = (0.93, 0.74, 0.60, 1)
PIEL_SOMBRA = (0.74, 0.53, 0.41, 1)
PIEL_UNA = (0.98, 0.86, 0.78, 1)


# Foto de la mano recortada (PNG con transparencia). FRENTE = pulgar y palma; ATRAS = mano completa, va detrás de las cartas.
MANO_FRENTE_B64 = ""
MANO_ATRAS_B64 = ""
MANO_REC = (180, 455, 405, 470)      # recorte usado de la foto original: x, y, ancho, alto (px)
MANO_PUNTA = (285, 600)               # punta del pulgar en la foto original
# Mano de mujer (perfil "Mujer"): uñas rojas y anillos dorados. Misma idea: capa de atrás (mano entera) y de frente (solo el pulgar).
MANO_M_ATRAS_B64 = ""
MANO_M_FRENTE_B64 = ""
MANO_M_REC = (297, 304, 359, 416)     # recorte usado de la foto: x, y, ancho, alto (px)
MANO_M_PUNTA = (382, 430)             # punta del pulgar en la foto
MANO_M_PULGAR = 125.0                 # ancho de referencia del pulgar (px de la foto): el pulgar queda más fino que el de la mano de hombre


class ManoSosteniendo(Widget):
    """La mano que sostiene el abanico de cartas, dibujada con formas (sin imágenes).

    capa="atras": palma y muñeca, detrás de las cartas.
    capa="frente": el pulgar apoyado sobre la carta del medio.
    Se agregan al contenedor de la mano: una antes y otra después de las cartas.
    """
    def __init__(self, capa="atras", **kwargs):
        super().__init__(size_hint=(None, None), **kwargs)
        self.capa = capa
        self.n = 0
        self.cx = self.ancho = self.alto = 0
        self.bind(pos=self._dibujar, size=self._dibujar)

    @staticmethod
    def _es_mujer():
        app = App.get_running_app()
        return ((getattr(app, "perfil_usuario", None) or {}).get("genero") == "Mujer")

    def ajustar(self, x, y, w, h, cx, ancho, alto, n):
        self.pos = (x, y)
        self.size = (w, h)
        self.cx, self.ancho, self.alto, self.n = cx, ancho, alto, n
        self._dibujar()

    def _dibujar(self, *_):
        self.canvas.clear()
        if self.n <= 0 or self.width <= 1 or self.height <= 1:
            return
        frente = self.capa == "frente"
        try:
            if self._es_mujer():                  # perfil "Mujer": la mano de uñas rojas y anillos
                tex = textura_embebida("mano_m_frente" if frente else "mano_m_atras",
                                       MANO_M_FRENTE_B64 if frente else MANO_M_ATRAS_B64)
                rx, ry, rw, rh = MANO_M_REC
                px, py = MANO_M_PUNTA
                pulgar = MANO_M_PULGAR
            else:
                tex = textura_embebida("mano_frente" if frente else "mano_atras",
                                       MANO_FRENTE_B64 if frente else MANO_ATRAS_B64)
                rx, ry, rw, rh = MANO_REC
                px, py = MANO_PUNTA
                pulgar = 140.0
        except Exception:
            return
        s = (self.ancho * 0.50) / pulgar         # dp por píxel de la foto: el pulgar mide ~medio ancho de carta
        x = self.cx - self.ancho * 0.02 - (px - rx) * s
        y = self.y - dp(6)                        # la mano sale desde detrás de los botones
        tam = (rw * s, rh * s)
        with self.canvas:
            if self.capa == "frente":
                # Sombra suave del pulgar sobre las cartas.
                Color(0, 0, 0, 0.30)
                Rectangle(texture=tex, pos=(x + dp(4), y - dp(2)), size=tam)
            Color(1, 1, 1, 1)
            Rectangle(texture=tex, pos=(x, y), size=tam)


class RetratoPersonaje(Widget):
    """Retrato en caricatura dibujado con formas (sin imágenes). La boca se mueve mientras el personaje habla."""
    def __init__(self, look, circular=False, **kwargs):
        super().__init__(size_hint=(None, 1), **kwargs)
        self.look = look
        self.circular = circular   # True: se recorta en un círculo con aro dorado (cara del rival en la mesa)
        self.t = random.random() * 3.0
        self._ev = None
        self.bind(pos=self._dibujar, size=self._dibujar)
        self._dibujar()

    def iniciar(self):
        if self._ev is None:
            self._ev = Clock.schedule_interval(self._tick, 1 / 15.0)

    def detener(self):
        if self._ev is not None:
            self._ev.cancel()
            self._ev = None

    def _tick(self, dt):
        if self.get_root_window() is None:
            self.detener()
            return False
        self.t += dt
        self._dibujar()
        return True

    def _dibujar(self, *_):
        self.canvas.clear()
        if self.width < 8 or self.height < 8:
            return
        L = self.look
        u = min(self.width, self.height) / 100.0
        ox = self.x + (self.width - 100 * u) / 2.0
        oy = self.y + (self.height - 100 * u) / 2.0
        P = lambda x, y: (ox + x * u, oy + y * u)
        S = lambda w, h: (w * u, h * u)
        piel = L["piel"]
        sombra = tuple(c * 0.82 for c in piel)
        pelo = L["pelo"]
        habla = (self.t % 5.0) < 3.4                   # habla en tandas y después descansa
        o = (0.5 + 0.5 * abs(math.sin(self.t * 11.0))) * (0.65 + 0.35 * math.sin(self.t * 3.1)) if habla else 0.0
        b = math.sin(self.t * 6.0) * 0.9 if habla else math.sin(self.t * 1.6) * 0.4   # leve cabeceo
        parpadeo = (self.t % 3.3) < 0.13
        with self.canvas:
            if self.circular:
                StencilPush()
                Color(1, 1, 1, 1)
                Ellipse(pos=P(0, 0), size=S(100, 100))
                StencilUse()
            # Fondo y luz.
            Color(*L["fondo"], 1)
            RoundedRectangle(pos=P(0, 0), size=S(100, 100), radius=[u * 14])
            Color(1, 1, 1, 0.10)
            Ellipse(pos=P(8, 28), size=S(84, 72))
            # Torso y cuello.
            Color(*L["ropa"], 1)
            RoundedRectangle(pos=P(14, 0), size=S(72, 34), radius=[u * 24, u * 24, 0, 0])
            if L.get("poncho"):
                for k, col in enumerate(((0.95, 0.80, 0.25), (0.25, 0.55, 0.35), (0.95, 0.95, 0.9))):
                    Color(*col, 1)
                    Rectangle(pos=P(26 + k * 4, 0), size=S(3, 24 - k * 3))
                    Rectangle(pos=P(70 - k * 4, 0), size=S(3, 24 - k * 3))
            Color(*sombra, 1)
            Rectangle(pos=P(42, 26), size=S(16, 14))
            if L.get("bufanda"):
                Color(*L["bufanda"], 1)
                RoundedRectangle(pos=P(33, 25), size=S(34, 11), radius=[u * 5])
                Rectangle(pos=P(56, 8), size=S(9, 22))
            # Pelo de atrás, orejas y aros.
            Color(*pelo, 1)
            if L["peinado"] == "largo":
                Ellipse(pos=P(18, 16 + b), size=S(64, 72))
            elif L["peinado"] == "trenzas":
                Ellipse(pos=P(15, 8 + b), size=S(13, 50))
                Ellipse(pos=P(72, 8 + b), size=S(13, 50))
            Color(*piel, 1)
            Ellipse(pos=P(20, 50 + b), size=S(9, 13))
            Ellipse(pos=P(71, 50 + b), size=S(9, 13))
            if L.get("aros"):
                Color(0.95, 0.78, 0.25, 1)
                Ellipse(pos=P(19, 42 + b), size=S(6, 6))
                Ellipse(pos=P(75, 42 + b), size=S(6, 6))
            # Cara.
            Color(*piel, 1)
            Ellipse(pos=P(25, 26 + b), size=S(50, 59))
            if L.get("mejillas"):
                Color(1, 0.45, 0.45, 0.28)
                Ellipse(pos=P(29, 43 + b), size=S(11, 8))
                Ellipse(pos=P(60, 43 + b), size=S(11, 8))
            if L.get("barba"):
                Color(*pelo, 1)
                Ellipse(pos=P(28, 22 + b), size=S(44, 30))
            # Ojos y cejas.
            for ex in (34, 55):
                if parpadeo:
                    Color(0.25, 0.15, 0.12, 1)
                    Line(points=[*P(ex, 61 + b), *P(ex + 11, 61 + b)], width=max(1.0, u * 1.2))
                else:
                    Color(1, 1, 1, 1)
                    Ellipse(pos=P(ex, 56 + b), size=S(11, 10))
                    Color(0.13, 0.08, 0.06, 1)
                    Ellipse(pos=P(ex + 3.2, 57 + b), size=S(5.2, 6.4))
                    Color(1, 1, 1, 0.9)
                    Ellipse(pos=P(ex + 5.2, 61 + b), size=S(1.8, 1.8))
            Color(*(tuple(c * 0.55 for c in pelo)), 1)
            Line(points=[*P(33, 70 + b), *P(39, 72.5 + b), *P(46, 70.5 + b)], width=max(1.0, u * 1.7))
            Line(points=[*P(54, 70.5 + b), *P(61, 72.5 + b), *P(67, 70 + b)], width=max(1.0, u * 1.7))
            if L.get("lentes"):
                Color(0.8, 0.9, 1, 0.20)
                Ellipse(pos=P(31, 52 + b), size=S(17, 16))
                Ellipse(pos=P(52, 52 + b), size=S(17, 16))
                Color(0.15, 0.10, 0.10, 1)
                Line(ellipse=(*P(31, 52 + b), *S(17, 16)), width=max(1.0, u * 1.3))
                Line(ellipse=(*P(52, 52 + b), *S(17, 16)), width=max(1.0, u * 1.3))
                Line(points=[*P(48, 61 + b), *P(52, 61 + b)], width=max(1.0, u * 1.2))
            # Nariz, bigote y boca.
            Color(*sombra, 1)
            Ellipse(pos=P(46.5, 47 + b), size=S(7, 9))
            if L.get("bigote"):
                Color(*pelo, 1)
                Ellipse(pos=P(36, 41 + b), size=S(15, 7))
                Ellipse(pos=P(49, 41 + b), size=S(15, 7))
            if o > 0.12:
                alto_boca = 2.0 + 7.0 * o
                Color(*L["labios"], 1)
                Ellipse(pos=P(42, 38.5 - alto_boca + b), size=S(16, alto_boca + 2))
                Color(0.22, 0.05, 0.07, 1)
                Ellipse(pos=P(43.5, 39 - alto_boca + b), size=S(13, alto_boca))
                Color(0.85, 0.30, 0.35, 1)
                Ellipse(pos=P(46, 39 - alto_boca + 0.4 + b), size=S(8, alto_boca * 0.5))
            else:
                Color(*L["labios"], 1)
                Line(bezier=[*P(42, 37 + b), *P(47, 32.5 + b), *P(53, 32.5 + b), *P(58, 37 + b)], width=max(1.2, u * 1.8))
            # Pelo de adelante.
            Color(*pelo, 1)
            est = L["peinado"]
            if est in ("corto", "largo", "rodete", "trenzas"):
                Ellipse(pos=P(23, 62 + b), size=S(54, 29))
                if est == "rodete":
                    Ellipse(pos=P(38, 86 + b), size=S(24, 15))
            elif est == "ralo":
                Ellipse(pos=P(21, 54 + b), size=S(10, 24))
                Ellipse(pos=P(69, 54 + b), size=S(10, 24))
                Ellipse(pos=P(30, 77 + b), size=S(40, 12))
            # Sombrero, gorra, gorro o pañuelo.
            sb = L.get("sombrero")
            if sb in ("capitan", "chofer"):
                tela = (0.96, 0.96, 0.96) if sb == "capitan" else L["sombrero_color"]
                banda = (0.10, 0.15, 0.35) if sb == "capitan" else tuple(c * 0.6 for c in tela)
                Color(0.05, 0.05, 0.08, 1)
                Ellipse(pos=P(30, 72 + b), size=S(40, 9))
                Color(*tela, 1)
                RoundedRectangle(pos=P(26, 77 + b), size=S(48, 19), radius=[u * 12, u * 12, u * 2, u * 2])
                Color(*banda, 1)
                Rectangle(pos=P(26, 77 + b), size=S(48, 6))
                Color(0.95, 0.78, 0.25, 1)
                Ellipse(pos=P(45, 78 + b), size=S(10, 8))
            elif sb == "ala":
                Color(*L["sombrero_color"], 1)
                Ellipse(pos=P(7, 71 + b), size=S(86, 16))
                RoundedRectangle(pos=P(27, 77 + b), size=S(46, 21), radius=[u * 12, u * 12, u * 2, u * 2])
                Color(*(tuple(c * 0.6 for c in L["sombrero_color"])), 1)
                Rectangle(pos=P(27, 77 + b), size=S(46, 5))
            elif sb == "gorro":
                Color(*L["sombrero_color"], 1)
                Ellipse(pos=P(23, 64 + b), size=S(54, 32))
                Ellipse(pos=P(44, 89 + b), size=S(12, 11))
                Color(*(tuple(c * 0.7 for c in L["sombrero_color"])), 1)
                RoundedRectangle(pos=P(23, 68 + b), size=S(54, 9), radius=[u * 4])
            elif sb == "mago":
                Color(*L["sombrero_color"], 1)
                Ellipse(pos=P(11, 69 + b), size=S(78, 15))
                Triangle(points=[*P(27, 77 + b), *P(73, 77 + b), *P(60, 99 + b)])
                Color(*(tuple(c * 0.6 for c in L["sombrero_color"])), 1)
                Rectangle(pos=P(29, 77 + b), size=S(42, 5))
                Color(1, 0.90, 0.40, 1)
                for dx, dy in ((46, 82), (56, 87), (52, 92)):
                    Ellipse(pos=P(dx, dy + b), size=S(4, 4))
            elif sb == "panuelo":
                Color(*L["sombrero_color"], 1)
                Ellipse(pos=P(21, 62 + b), size=S(58, 32))
                Ellipse(pos=P(64, 73 + b), size=S(16, 11))
                Color(1, 1, 1, 0.85)
                for dx, dy in ((30, 78), (42, 84), (54, 80), (64, 72)):
                    Ellipse(pos=P(dx, dy + b), size=S(3, 3))
            # Marco dorado.
            if self.circular:
                StencilUnUse()
                Color(1, 1, 1, 1)
                Ellipse(pos=P(0, 0), size=S(100, 100))
                StencilPop()
                Color(0.85, 0.66, 0.20, 1)
                Line(circle=(ox + 50 * u, oy + 50 * u, 49 * u), width=max(1.5, dp(1.6)))
            else:
                Color(0.85, 0.66, 0.20, 1)
                Line(rounded_rectangle=(ox, oy, 100 * u, 100 * u, 14 * u), width=1.5)


class GlobitoDialogo(BoxLayout):
    """Globito de diálogo con colita hacia el personaje que habla."""
    def __init__(self, texto, **kwargs):
        super().__init__(padding=[dp(22), dp(10), dp(12), dp(10)], **kwargs)
        self.etiqueta = Label(text=texto, font_size="13sp", color=(0.14, 0.09, 0.05, 1), halign="left", valign="middle")
        self.etiqueta.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        self.add_widget(self.etiqueta)
        self.bind(pos=self._dibujar, size=self._dibujar)
        self._dibujar()

    def _dibujar(self, *_):
        self.canvas.before.clear()
        if self.width < 10 or self.height < 10:
            return
        x, y, w, h = self.x + dp(10), self.y + dp(4), self.width - dp(10), self.height - dp(8)
        cy = y + h * 0.40
        with self.canvas.before:
            Color(0.85, 0.66, 0.20, 1)
            RoundedRectangle(pos=(x - dp(1), y - dp(1)), size=(w + dp(2), h + dp(2)), radius=[dp(14)])
            Triangle(points=[x + dp(1), cy + dp(9), x - dp(10), cy, x + dp(1), cy - dp(9)])
            Color(1, 0.97, 0.88, 1)
            RoundedRectangle(pos=(x, y), size=(w, h), radius=[dp(13)])
            Triangle(points=[x + dp(2), cy + dp(7.5), x - dp(8.5), cy, x + dp(2), cy - dp(7.5)])


class ConversacionDesafio(BoxLayout):
    """Retrato del personaje + globito con lo que dice, como si estuviera hablando con vos."""
    def __init__(self, look, frase, **kwargs):
        super().__init__(orientation="horizontal", size_hint_y=None, height=dp(150), spacing=dp(2), **kwargs)
        self.retrato = RetratoPersonaje(look, width=dp(118))
        self.add_widget(self.retrato)
        self.add_widget(GlobitoDialogo(frase))

    def iniciar(self):
        self.retrato.iniciar()

    def detener(self):
        self.retrato.detener()


class ConversacionFoto(BoxLayout):
    """Rival del Desafío con ilustración: la imagen arriba y su globito de diálogo abajo."""
    def __init__(self, clave, frase, tex=None, cara_y=None, **kwargs):
        """tex: textura propia (si no, la del Desafío `clave`). cara_y: altura de la cara en la foto (px desde arriba); con ella
        la foto se recorta en franja horizontal encuadrando la cara, en vez de mostrar el centro."""
        super().__init__(orientation="vertical", size_hint_y=None, spacing=dp(2), **kwargs)
        if tex is None:
            tex = textura_embebida("desafio_" + clave, DESAFIO_FOTO_B64[clave], "jpg")
        if cara_y is not None:
            alto_franja = tex.width / 1.7
            arriba = min(max(cara_y - 0.62 * alto_franja, 0), tex.height - alto_franja)
            tex = tex.get_region(0, tex.height - arriba - alto_franja, tex.width, alto_franja)
        self.add_widget(Image(texture=tex, size_hint_y=None, height=dp(168), fit_mode="cover"))
        self.add_widget(GlobitoDialogo(frase, size_hint_y=None, height=dp(110)))
        self.height = dp(168) + dp(110) + self.spacing


class CartaElegible(ButtonBehavior, Image):
    """Carta del selector del Poder del mago: se marca con un borde dorado cuando está elegida."""
    def __init__(self, carta, **kwargs):
        super().__init__(fit_mode="contain", **kwargs)
        self.carta = carta
        self.elegida = False
        self._rotulo = None
        if not kwargs.get("source"):   # sin imagen de la carta: se muestra su nombre
            self._rotulo = Label(text=nombre_carta(carta).replace(" de ", "\nde\n"), font_size="10sp", halign="center", valign="middle")
            self.add_widget(self._rotulo)
        self.bind(pos=self._dibujar, size=self._dibujar)

    def poner(self, elegida):
        self.elegida = elegida
        self._dibujar()

    def _dibujar(self, *_):
        if self._rotulo is not None:
            self._rotulo.pos, self._rotulo.size = self.pos, self.size
        self.canvas.after.clear()
        with self.canvas.after:
            if self.elegida:
                Color(0.96, 0.78, 0.15, 1)
                Line(rounded_rectangle=(self.x + dp(1), self.y + dp(1), self.width - dp(2), self.height - dp(2), dp(5)), width=dp(2.6))
            else:
                Color(0, 0, 0, 0.30)
                Rectangle(pos=self.pos, size=self.size)


class FotoRedonda(Widget):
    """Recorte circular (con aro dorado) de la cara en una ilustración. Dibuja directo en su canvas, sin hijos."""
    def __init__(self, tex, cx, cy, lado, diametro=48, gris=False, **kwargs):
        super().__init__(size_hint=(None, None), size=(dp(diametro), dp(diametro)), **kwargs)
        self.tex, self.cx, self.cy, self.lado = tex, cx, cy, lado
        self.gris = gris   # True: se ve apagada, en gris (poder ya usado)
        self.bind(pos=self._dibujar, size=self._dibujar)
        self._dibujar()

    def _dibujar(self, *_):
        self.canvas.clear()
        d = min(self.width, self.height)
        if d < 4:
            return
        k = d / float(self.lado)
        w, h = self.tex.width * k, self.tex.height * k
        x, y = self.x + (self.width - d) / 2.0, self.y + (self.height - d) / 2.0
        mx, my = x + d / 2.0 - self.cx * k, y + d / 2.0 - (self.tex.height - self.cy) * k
        with self.canvas:
            StencilPush()
            Color(1, 1, 1, 1)
            Ellipse(pos=(x, y), size=(d, d))
            StencilUse()
            Color(1, 1, 1, 1)
            Rectangle(texture=self.tex, pos=(mx, my), size=(w, h))
            StencilUnUse()
            Color(1, 1, 1, 1)
            Ellipse(pos=(x, y), size=(d, d))
            StencilPop()
            if self.gris:
                Color(0.28, 0.28, 0.28, 0.82)
                Ellipse(pos=(x, y), size=(d, d))
                Color(0.50, 0.50, 0.50, 1)
            else:
                Color(0.85, 0.66, 0.20, 1)
            Line(circle=(x + d / 2.0, y + d / 2.0, d / 2.0 - dp(0.8)), width=dp(1.6))


# Recorte de la cara en las ilustraciones: (centro x, centro y desde arriba, lado del recorte) en píxeles de la imagen.
CARA_FOTO = {"halcon": (282, 170, 270), "comodin": (282, 170, 270), "pase": (278, 185, 215), "baqueano": (280, 135, 190), "chaleco": (280, 172, 270), "silencio": (282, 150, 210), "ancho": (280, 170, 230), "soplon": (280, 160, 240), "espia": (280, 150, 210), "escudo": (280, 170, 300), "fenix": (280, 170, 290), "detective": (292, 100, 135), "eliseo": (298, 108, 145), "mabel": (360, 140, 270), "nahuel": (335, 100, 270), "marconi": (150, 70, 190), "anibal": (282, 105, 215), "chiqui": (292, 150, 230), "ramirez": (278, 135, 215), "guadalupe": (285, 145, 250), "tolaba": (283, 175, 240), "cayetana": (285, 152, 230), "rosa": (280, 160, 230), "antonio": (280, 140, 250), "cientifico": (275, 180, 260)}


def cara_rival(ch):
    """Circulito con la cara del personaje contra el que jugás (Desafío, Familia, mago, encuentros del camino, Truco del día).
    Devuelve (widget, retrato_animado_o_None), o (None, None) si no hay cara para ese rival."""
    cid = ch.get("id", "")
    if ch.get("tipo") == "personaje" and ch.get("pid") in PERSONAJE_FOTO_B64:
        tex = textura_embebida("pers_" + ch["pid"], PERSONAJE_FOTO_B64[ch["pid"]], "jpg")
        cx, cy, lado = PERSONAJE_CARA[ch["pid"]]
        return FotoRedonda(tex, cx, cy, lado), None
    if cid in CARA_FOTO:
        b64 = MAFIA_JEFE_B64 if cid == "marconi" else DESAFIO_FOTO_B64[cid]
        tex = textura_embebida("mafia_jefe" if cid == "marconi" else "desafio_" + cid, b64, "jpg")
        cx, cy, lado = CARA_FOTO[cid]
        return FotoRedonda(tex, cx, cy, lado), None
    look = None
    if cid in DESAFIO_LOOK:
        look = DESAFIO_LOOK[cid]
    elif ch.get("tipo") == "evento":
        look = next((e["look"] for e in VIAJE_EVENTOS if "ev_" + e["id"] == cid), None)
    elif ch.get("tipo") == "diario":
        look = DIARIO_LOOKS.get(ch.get("nombre"))
    elif ch.get("tipo") == "personaje":
        look = ch.get("look")
    elif ch.get("tipo") == "mago":
        look = MAGO_LOOK
    if look is None:
        return None, None
    retrato = RetratoPersonaje(look, circular=True)
    retrato.size_hint = (None, None)
    retrato.size = (dp(48), dp(48))
    return retrato, retrato


class TilePoder(ButtonBehavior, BoxLayout):
    """Logo de un poder (la carita del personaje) con su nombre. Al tocarlo se abre su ficha."""
    ALTO = 112   # en dp

    def __init__(self, p, gris=False, **kwargs):
        super().__init__(orientation="vertical", size_hint_y=None, height=dp(self.ALTO), spacing=dp(2), **kwargs)
        tex = textura_embebida("desafio_" + p["foto"], DESAFIO_FOTO_B64[p["foto"]], "jpg")
        cx, cy, lado = CARA_FOTO[p["foto"]]
        fila = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(74))
        fila.add_widget(Widget())
        fila.add_widget(FotoRedonda(tex, cx, cy, lado, diametro=70, gris=gris))
        fila.add_widget(Widget())
        self.add_widget(fila)
        nombre = Label(text=p["nombre"], font_size="12sp", bold=True, halign="center", valign="top",
                       color=((0.55, 0.55, 0.55, 1) if gris else (p["color"][0], p["color"][1], p["color"][2], 1)))
        nombre.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, None)))
        self.add_widget(nombre)


class CartaTocable(ButtonBehavior, Image):
    """Imagen de una carta que se puede tocar (para elegirla en un cartel)."""


class TileFalta(BoxLayout):
    """Casillero vacío (por defecto con un «?»): un lugar donde todavía no hay un poder."""
    def __init__(self, color, texto="?", tam="30sp", **kwargs):
        super().__init__(orientation="vertical", size_hint_y=None, height=dp(TilePoder.ALTO), spacing=dp(2), **kwargs)
        fila = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(74))
        fila.add_widget(Widget())
        d = dp(70)
        cuadro = Label(text=texto, font_size=tam, bold=True, halign="center", valign="middle", size_hint=(None, None), size=(d, d),
                       color=(color[0], color[1], color[2], 0.55))
        cuadro.bind(size=lambda w, *_: setattr(w, "text_size", w.size))
        with cuadro.canvas.before:
            Color(color[0], color[1], color[2], 0.06)
            self._fondo = RoundedRectangle(pos=cuadro.pos, size=cuadro.size, radius=[dp(14)])
            Color(color[0], color[1], color[2], 0.40)
            self._borde = Line(rounded_rectangle=(cuadro.x, cuadro.y, d, d, dp(14)), width=dp(1.2))

        def _dibujar(w, *_):
            self._fondo.pos, self._fondo.size = w.pos, w.size
            self._borde.rounded_rectangle = (w.x, w.y, w.width, w.height, dp(14))
        cuadro.bind(pos=_dibujar, size=_dibujar)
        fila.add_widget(cuadro)
        fila.add_widget(Widget())
        self.add_widget(fila)
        self.add_widget(Widget())   # el lugar del nombre, vacío


class SeccionPoder(BoxLayout):
    """Una franja horizontal de la cuadrícula de Poderes: el título y sus casilleros, de a 3 por fila."""
    def __init__(self, titulo, color, filas=1, **kwargs):
        alto_cuerpo = TilePoder.ALTO * filas + 6 * (filas - 1)
        super().__init__(orientation="vertical", padding=[dp(6), dp(6)], spacing=dp(4), size_hint_y=None,
                         height=dp(26 + 12 + 4 + alto_cuerpo), **kwargs)
        with self.canvas.before:
            Color(color[0], color[1], color[2], 0.10)
            self._r_fondo = RoundedRectangle(pos=self.pos, size=self.size, radius=[dp(12)])
            Color(color[0], color[1], color[2], 0.85)
            self._l_borde = Line(rounded_rectangle=(self.x, self.y, self.width, self.height, dp(12)), width=dp(1.2))
        self.bind(pos=self._dibujar, size=self._dibujar)
        self.add_widget(Label(text=titulo, font_size="14sp", bold=True, size_hint_y=None, height=dp(26),
                              color=(color[0], color[1], color[2], 1)))
        self.fila = GridLayout(cols=3, spacing=dp(6), size_hint_y=None, height=dp(alto_cuerpo))
        self.add_widget(self.fila)

    def poner(self, widget):
        self.fila.add_widget(widget)

    def _dibujar(self, *_):
        self._r_fondo.pos, self._r_fondo.size = self.pos, self.size
        self._l_borde.rounded_rectangle = (self.x, self.y, self.width, self.height, dp(12))


class ConversacionMafia(BoxLayout):
    """El mafioso hablándote: la escena del callejón (o su ficha con retrato) y debajo su globito de diálogo."""
    def __init__(self, frase, modo="escena", **kwargs):
        super().__init__(orientation="vertical", size_hint_y=None, spacing=dp(2), **kwargs)
        self._modo = modo
        if modo == "escena":
            tex = textura_embebida("mafia_escena", MAFIA_ESCENA_B64, "jpg")
            self._img = Image(texture=tex, size_hint_y=None, fit_mode="fill")
            self._img.height = dp(150)
            self.add_widget(self._img)
            self._globo_alto = dp(116)
            self.bind(width=self._ajustar)
        else:
            self.add_widget(FichaMafia())
            self._globo_alto = dp(104)
        self.add_widget(GlobitoDialogo(frase, size_hint_y=None, height=self._globo_alto))
        self._ajustar()

    def _ajustar(self, *_):
        if self._modo == "escena":
            tex = self._img.texture
            self._img.height = max(dp(90), self.width * tex.height / float(tex.width)) if self.width > 10 else dp(150)
            self.height = self._img.height + self._globo_alto + self.spacing
        else:
            self.height = dp(182) + self._globo_alto + self.spacing


