class TarjetaMafia(Widget):
    """Tarjeta de la Familia (la aprobación del campeón del año pasado). Se dibuja por código y guarda a quién se la dieron."""
    def __init__(self, nombre="", aprobada_el=0, favor=None, **kwargs):
        kwargs.setdefault("size_hint_y", None)
        kwargs.setdefault("height", dp(176))
        super().__init__(**kwargs)
        self.favor = favor
        fecha = time.strftime("%d/%m/%Y", time.localtime(aprobada_el)) if aprobada_el else "—"
        def et(texto, tam, color, negrita=False):
            l = Label(text=texto, font_size=tam, bold=negrita, color=color, halign="left", valign="middle", markup=True)
            l.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
            self.add_widget(l)
            return l
        ORO, BLANCO, GRIS = (0.96, 0.78, 0.15, 1), (1, 1, 1, 1), (0.70, 0.68, 0.64, 1)
        self.l_firma = et("Aprobada por Don Nicola «El Tano» Marconi", "10sp", GRIS)
        self.l_banda = et("LA FAMILIA  ·  SOCIO APROBADO", "13sp", ORO, True)
        self.l_nombre = et((nombre or "Socio honorario").upper()[:22], "15sp", BLANCO, True)
        self.l_fecha = et("Desde %s" % fecha, "10sp", GRIS)
        self.l_favor = et("" if favor is None else ("FAVOR DISPONIBLE" if favor else "Favor usado"), "10sp",
                          (0.55, 0.85, 0.35, 1) if favor else GRIS, True)
        self.bind(pos=self._dibujar, size=self._dibujar)
        self._dibujar()

    def _dibujar(self, *_):
        self.canvas.before.clear()
        if self.width < 20 or self.height < 20:
            return
        cw = min(self.width - dp(8), (self.height - dp(8)) * 1.586)
        ch = cw / 1.586
        x0, y0 = self.center_x - cw / 2.0, self.center_y - ch / 2.0
        tex = textura_embebida("mafia_jefe", MAFIA_JEFE_B64, "jpg")
        with self.canvas.before:
            Color(0, 0, 0, 0.45)
            RoundedRectangle(pos=(x0 + dp(3), y0 - dp(3)), size=(cw, ch), radius=[dp(12)])
            Color(0.07, 0.06, 0.08, 1)
            RoundedRectangle(pos=(x0, y0), size=(cw, ch), radius=[dp(12)])
            Color(1, 1, 1, 0.04)
            RoundedRectangle(pos=(x0, y0 + ch * 0.5), size=(cw, ch * 0.5), radius=[dp(12), dp(12), 0, 0])
            Color(0.45, 0.07, 0.10, 1)
            Rectangle(pos=(x0, y0 + ch * 0.62), size=(cw, ch * 0.15))
            Color(0.85, 0.66, 0.20, 1)
            Line(rounded_rectangle=(x0, y0, cw, ch, dp(12)), width=max(1.0, dp(1.4)))
            Color(0.85, 0.66, 0.20, 0.45)
            Line(rounded_rectangle=(x0 + dp(5), y0 + dp(5), cw - dp(10), ch - dp(10), dp(9)), width=max(0.8, dp(0.8)))
            # chip dorado
            Color(0.88, 0.72, 0.32, 1)
            RoundedRectangle(pos=(x0 + cw * 0.07, y0 + ch * 0.36), size=(cw * 0.15, ch * 0.17), radius=[dp(3)])
            Color(0.55, 0.42, 0.12, 1)
            Line(points=[x0 + cw * 0.07, y0 + ch * 0.445, x0 + cw * 0.22, y0 + ch * 0.445], width=1)
            Line(points=[x0 + cw * 0.145, y0 + ch * 0.36, x0 + cw * 0.145, y0 + ch * 0.53], width=1)
            # retrato del campeón
            rw = cw * 0.19
            rh = rw * tex.height / float(tex.width)
            rx, ry = x0 + cw * 0.74, y0 + ch * 0.08
            Color(0.85, 0.66, 0.20, 1)
            Rectangle(pos=(rx - dp(1.5), ry - dp(1.5)), size=(rw + dp(3), rh + dp(3)))
            Color(1, 1, 1, 1)
            Rectangle(texture=tex, pos=(rx, ry), size=(rw, rh))
        self.l_firma.pos, self.l_firma.size = (x0 + cw * 0.07, y0 + ch * 0.80), (cw * 0.86, ch * 0.14)
        self.l_banda.pos, self.l_banda.size = (x0 + cw * 0.07, y0 + ch * 0.62), (cw * 0.86, ch * 0.15)
        self.l_nombre.pos, self.l_nombre.size = (x0 + cw * 0.07, y0 + ch * 0.14), (cw * 0.64, ch * 0.18)
        self.l_fecha.pos, self.l_fecha.size = (x0 + cw * 0.07, y0 + ch * 0.03), (cw * 0.64, ch * 0.12)
        self.l_favor.pos, self.l_favor.size = (x0 + cw * 0.26, y0 + ch * 0.37), (cw * 0.46, ch * 0.16)


class VoucherPapel(Widget):
    """Voucher de papel (hotel o pasaje de colectivo) dibujado por código: talón de color, línea de corte, sello y número."""
    def __init__(self, tipo, region, lugar, quien, **kwargs):
        kwargs.setdefault("size_hint_y", None)
        kwargs.setdefault("height", dp(104))
        super().__init__(**kwargs)
        self.hotel = tipo == "hotel"
        serie = sum(ord(ch) * (i + 3) for i, ch in enumerate(tipo + region)) % 10000
        TINTA, GRIS = (0.24, 0.15, 0.08, 1), (0.45, 0.36, 0.26, 1)
        def et(texto, tam, color, negrita=False, alin="left"):
            l = Label(text=texto, font_size=tam, bold=negrita, color=color, halign=alin, valign="middle", markup=True)
            l.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
            self.add_widget(l)
            return l
        self.l_tipo = et("VOUCHER DE HOTEL" if self.hotel else "PASAJE EN COLECTIVO", "11sp", GRIS, True)
        self.l_lugar = et(lugar, "15sp", TINTA, True)
        self.l_region = et("Destino: [b]%s[/b]" % region, "12sp", TINTA)
        self.l_pie = et("N° %04d  ·  1 persona  ·  %s" % (serie, quien), "9sp", GRIS)
        self.l_sello = et("CANJEABLE", "10sp", (0.72, 0.12, 0.12, 1), True, "center")
        self.bind(pos=self._dibujar, size=self._dibujar)
        self._dibujar()

    def _dibujar(self, *_):
        self.canvas.before.clear()
        if self.width < 40 or self.height < 30:
            return
        x0, y0 = self.x + dp(3), self.y + dp(4)
        cw, ch = self.width - dp(6), self.height - dp(8)
        talon = cw * 0.25
        col = (0.16, 0.52, 0.52) if self.hotel else (0.88, 0.48, 0.12)
        with self.canvas.before:
            Color(0, 0, 0, 0.35)
            RoundedRectangle(pos=(x0 + dp(2), y0 - dp(2)), size=(cw, ch), radius=[dp(7)])
            Color(0.97, 0.93, 0.82, 1)
            RoundedRectangle(pos=(x0, y0), size=(cw, ch), radius=[dp(7)])
            Color(0.86, 0.78, 0.60, 0.35)   # papel envejecido hacia los bordes
            RoundedRectangle(pos=(x0, y0), size=(cw, ch * 0.18), radius=[0, 0, dp(7), dp(7)])
            Color(*col, 1)
            RoundedRectangle(pos=(x0, y0), size=(talon, ch), radius=[dp(7), 0, 0, dp(7)])
            Color(1, 1, 1, 0.10)
            Rectangle(pos=(x0, y0 + ch * 0.5), size=(talon, ch * 0.5))
            # línea de corte punteada
            Color(0.40, 0.30, 0.20, 0.85)
            Line(points=[x0 + talon, y0 + dp(4), x0 + talon, y0 + ch - dp(4)], width=max(1.0, dp(1.1)), dash_length=dp(3), dash_offset=dp(3))
            # ícono blanco en el talón
            cx, cy = x0 + talon / 2.0, y0 + ch / 2.0
            Color(1, 1, 1, 1)
            if self.hotel:   # edificio con ventanas
                Rectangle(pos=(cx - talon * 0.22, cy - ch * 0.26), size=(talon * 0.44, ch * 0.52))
                Color(*col, 1)
                for fx in (-0.13, 0.03):
                    for fy in (-0.14, 0.0, 0.14):
                        Rectangle(pos=(cx + talon * fx, cy + ch * fy), size=(talon * 0.09, ch * 0.08))
            else:            # colectivo con ventanas y ruedas
                RoundedRectangle(pos=(cx - talon * 0.30, cy - ch * 0.14), size=(talon * 0.60, ch * 0.34), radius=[dp(4)])
                Color(*col, 1)
                for fx in (-0.24, -0.08, 0.08):
                    Rectangle(pos=(cx + talon * fx, cy + ch * 0.06), size=(talon * 0.13, ch * 0.10))
                Color(0.15, 0.15, 0.15, 1)
                for fx in (-0.20, 0.10):
                    Ellipse(pos=(cx + talon * fx, cy - ch * 0.22), size=(talon * 0.14, talon * 0.14))
            # sello rojo
            sx, sy, sw, sh = x0 + cw - cw * 0.25, y0 + ch * 0.58, cw * 0.21, ch * 0.24
            Color(0.72, 0.12, 0.12, 0.85)
            Line(rounded_rectangle=(sx, sy, sw, sh, dp(4)), width=max(1.2, dp(1.5)))
            # borde fino
            Color(0.55, 0.42, 0.25, 0.6)
            Line(rounded_rectangle=(x0, y0, cw, ch, dp(7)), width=max(0.8, dp(0.9)))
        tx = x0 + talon + cw * 0.04
        ancho = cw - talon - cw * 0.08
        self.l_tipo.pos, self.l_tipo.size = (tx, y0 + ch * 0.72), (ancho * 0.70, ch * 0.20)
        self.l_lugar.pos, self.l_lugar.size = (tx, y0 + ch * 0.42), (ancho, ch * 0.28)
        self.l_region.pos, self.l_region.size = (tx, y0 + ch * 0.22), (ancho, ch * 0.20)
        self.l_pie.pos, self.l_pie.size = (tx, y0 + ch * 0.04), (ancho, ch * 0.18)
        self.l_sello.pos, self.l_sello.size = (sx, sy), (sw, sh)


class Figurita(Widget):
    """Figurita del álbum: se consigue ganándole al rival del Desafío. Sin ganar, se ve una silueta con '?'."""
    COLORES = {"hotel": (0.16, 0.52, 0.52), "colectivo": (0.88, 0.48, 0.12), "mafia": (0.55, 0.10, 0.14), "personaje": (0.42, 0.28, 0.62)}

    def __init__(self, ch, tiene, numero, total, **kwargs):
        kwargs.setdefault("size_hint_y", None)
        kwargs.setdefault("height", dp(160))
        super().__init__(**kwargs)
        self.ch, self.tiene = ch, tiene
        self._tex = None
        self._retrato = None
        self._region = {}
        if tiene:
            if ch["id"] in DESAFIO_FOTO_B64:
                self._tex = textura_embebida("desafio_" + ch["id"], DESAFIO_FOTO_B64[ch["id"]], "jpg")
            elif ch["id"] == MAFIA_JEFE["id"]:
                self._tex = textura_embebida("mafia_jefe", MAFIA_JEFE_B64, "jpg")
            elif ch["tipo"] == "personaje":
                self._tex = textura_embebida("pers_" + ch["pid"], PERSONAJE_FOTO_B64[ch["pid"]], "jpg")
            else:
                self._retrato = RetratoPersonaje(DESAFIO_LOOK[ch["id"]])
                self._retrato.size_hint = (None, None)   # el constructor ya fija su size_hint: se cambia después
                self.add_widget(self._retrato)
        def et(texto, tam, color, negrita=False, alin="center"):
            l = Label(text=texto, font_size=tam, bold=negrita, color=color, halign=alin, valign="middle")
            l.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
            self.add_widget(l)
            return l
        BLANCO, GRIS = (1, 1, 1, 1), (0.72, 0.70, 0.66, 1)
        tipo = ch["tipo"]
        sub = "Personaje del día" if tipo == "personaje" else "Campeón · Buenos Aires" if tipo == "mafia" else "%s · %s" % ("Hotel" if tipo == "hotel" else "Colectivo", DESAFIO_NOMBRE_REGION.get(ch["region"], ch["region"]).title())
        self.l_num = et("N° %02d/%02d" % (numero, total), "8sp", (1, 0.92, 0.65, 1) if tiene else GRIS, True, "left")
        self.l_nombre = et(ch["nombre"] if tiene else "???", "10sp", BLANCO if tiene else GRIS, True)
        self.l_sub = et(sub if tiene else "Ganale en Desafíos", "8sp", (1, 0.92, 0.75, 1) if tiene else GRIS)
        self.l_q = et("" if tiene else "?", "46sp", (0.55, 0.53, 0.50, 1), True)
        self.bind(pos=self._dibujar, size=self._dibujar)
        self._dibujar()

    def _subtextura(self, ww, wh):
        """Recorte de la ilustración que llena la ventana (centrado a lo ancho y alineado arriba, donde está la cara)."""
        clave = (int(ww), int(wh))
        if clave not in self._region:
            tw, th = self._tex.size
            a = ww / float(wh)
            if tw / float(th) > a:
                w = th * a
                self._region[clave] = self._tex.get_region((tw - w) / 2.0, 0, w, th)
            else:
                h = tw / a
                self._region[clave] = self._tex.get_region(0, th - h, tw, h)
        return self._region[clave]

    def _dibujar(self, *_):
        self.canvas.before.clear()
        if self.width < 30 or self.height < 30:
            return
        x0, y0, cw, ch = self.x + dp(2), self.y + dp(2), self.width - dp(4), self.height - dp(4)
        col = self.COLORES.get(self.ch["tipo"], (0.3, 0.3, 0.3)) if self.tiene else (0.22, 0.22, 0.24)
        wx, wy, ww, wh = x0 + cw * 0.07, y0 + ch * 0.31, cw * 0.86, ch * 0.62
        with self.canvas.before:
            Color(0, 0, 0, 0.40)
            RoundedRectangle(pos=(x0 + dp(2), y0 - dp(2)), size=(cw, ch), radius=[dp(8)])
            Color(0.90, 0.72, 0.25, 1) if self.tiene else Color(0.40, 0.40, 0.42, 1)
            RoundedRectangle(pos=(x0, y0), size=(cw, ch), radius=[dp(8)])
            Color(*col, 1)
            RoundedRectangle(pos=(x0 + dp(2.5), y0 + dp(2.5)), size=(cw - dp(5), ch - dp(5)), radius=[dp(6)])
            Color(0.07, 0.06, 0.06, 1)
            Rectangle(pos=(wx, wy), size=(ww, wh))
            if self._tex is not None:
                Color(1, 1, 1, 1)
                Rectangle(texture=self._subtextura(ww, wh), pos=(wx, wy), size=(ww, wh))
            Color(0.90, 0.72, 0.25, 1) if self.tiene else Color(0.40, 0.40, 0.42, 1)
            Line(rectangle=(wx, wy, ww, wh), width=max(1.0, dp(1.2)))
            # chapita del nombre
            Color(0, 0, 0, 0.45)
            RoundedRectangle(pos=(x0 + cw * 0.07, y0 + ch * 0.05), size=(cw * 0.86, ch * 0.22), radius=[dp(4)])
            if self.tiene:   # brillo de figurita holográfica
                Color(1, 1, 1, 0.10)
                Quad(points=(wx + ww * 0.15, wy, wx + ww * 0.40, wy, wx + ww * 0.85, wy + wh, wx + ww * 0.60, wy + wh))
        if self._retrato is not None:
            self._retrato.pos, self._retrato.size = (wx, wy), (ww, wh)
        self.l_num.pos, self.l_num.size = (wx + dp(2), wy + wh - ch * 0.12), (ww * 0.7, ch * 0.12)
        self.l_nombre.pos, self.l_nombre.size = (x0 + cw * 0.09, y0 + ch * 0.14), (cw * 0.82, ch * 0.12)
        self.l_sub.pos, self.l_sub.size = (x0 + cw * 0.09, y0 + ch * 0.06), (cw * 0.82, ch * 0.09)
        self.l_q.pos, self.l_q.size = (wx, wy), (ww, wh)


def dibujar_escena_postal(clave, x, y, w, h):
    """Dibuja (con formas) el paisaje de una postal dentro del rectángulo x, y, w, h. Se llama dentro de un canvas."""
    def rect(c, fx, fy, fw, fh):
        Color(*c)
        Rectangle(pos=(x + fx * w, y + fy * h), size=(fw * w, fh * h))

    def tri(c, ax, ay, bx, by, cx, cy):
        Color(*c)
        Triangle(points=(x + ax * w, y + ay * h, x + bx * w, y + by * h, x + cx * w, y + cy * h))

    def ell(c, fx, fy, fw, fh):
        Color(*c)
        Ellipse(pos=(x + fx * w, y + fy * h), size=(fw * w, fh * h))

    def cielo(arriba, abajo, desde=0.0, n=12):
        for i in range(n):
            t = i / float(n - 1)
            c = tuple(abajo[k] + (arriba[k] - abajo[k]) * t for k in range(3))
            rect(c, 0, desde + (1 - desde) * i / float(n), 1, (1 - desde) / float(n) + 0.01)

    def estrellas(cuantas, desde):
        for i in range(cuantas):
            sx, sy = (i * 0.137 + 0.05) % 1.0, desde + ((i * 0.291) % 1.0) * (1 - desde)
            rect((1, 1, 0.92, 0.55 + 0.4 * ((i * 7) % 3) / 2.0), sx, sy, 0.013, 0.02)

    if clave == "buenos_aires":
        cielo((0.35, 0.25, 0.55), (0.99, 0.72, 0.42))
        ell((1, 0.92, 0.55), 0.64, 0.30, 0.22, 0.30)
        for i, alto in enumerate((0.30, 0.42, 0.25, 0.50, 0.35, 0.28, 0.45, 0.33, 0.40, 0.27)):
            rect((0.18, 0.14, 0.25), i * 0.1, 0.0, 0.1, alto)
            rect((1, 0.9, 0.5), i * 0.1 + 0.03, alto * 0.55, 0.02, 0.04)
        tri((0.88, 0.88, 0.92), 0.47, 0.0, 0.53, 0.0, 0.50, 0.84)
        rect((0.70, 0.70, 0.75), 0.46, 0.0, 0.08, 0.04)
    elif clave == "patagonia":
        cielo((0.45, 0.68, 0.92), (0.85, 0.93, 1.0))
        tri((0.55, 0.62, 0.78), 0.0, 0.30, 0.38, 0.30, 0.19, 0.78)
        tri((0.50, 0.58, 0.75), 0.30, 0.30, 0.78, 0.30, 0.54, 0.92)
        tri((0.58, 0.65, 0.80), 0.62, 0.30, 1.0, 0.30, 0.82, 0.70)
        tri((1, 1, 1), 0.14, 0.66, 0.24, 0.66, 0.19, 0.78)
        tri((1, 1, 1), 0.46, 0.74, 0.62, 0.74, 0.54, 0.92)
        tri((1, 1, 1), 0.77, 0.60, 0.87, 0.60, 0.82, 0.70)
        rect((0.40, 0.75, 0.82), 0, 0, 1, 0.30)
        tri((0.88, 0.96, 1.0), 0.18, 0.05, 0.55, 0.05, 0.36, 0.30)
        tri((0.75, 0.90, 0.98), 0.50, 0.0, 0.92, 0.0, 0.70, 0.26)
    elif clave == "cuyo":
        cielo((0.38, 0.25, 0.52), (0.99, 0.66, 0.40))
        ell((1, 0.85, 0.5), 0.68, 0.40, 0.18, 0.24)
        tri((0.28, 0.20, 0.38), 0.0, 0.28, 0.42, 0.28, 0.22, 0.80)
        tri((0.24, 0.17, 0.34), 0.30, 0.28, 0.80, 0.28, 0.55, 0.90)
        tri((0.30, 0.22, 0.40), 0.65, 0.28, 1.0, 0.28, 0.85, 0.66)
        tri((1, 1, 1), 0.18, 0.68, 0.26, 0.68, 0.22, 0.80)
        tri((1, 1, 1), 0.48, 0.76, 0.62, 0.76, 0.55, 0.90)
        rect((0.33, 0.50, 0.22), 0, 0, 1, 0.28)
        for i in range(7):
            rect((0.20, 0.36, 0.14), i * 0.15 + 0.04, 0.0, 0.05, 0.28)
    elif clave == "mesopotamia":
        cielo((0.55, 0.82, 0.95), (0.85, 0.95, 0.90))
        rect((0.12, 0.38, 0.18), 0.0, 0.0, 0.38, 0.80)
        rect((0.12, 0.38, 0.18), 0.62, 0.0, 0.38, 0.80)
        ell((0.18, 0.52, 0.24), -0.08, 0.58, 0.55, 0.40)
        ell((0.18, 0.52, 0.24), 0.54, 0.58, 0.55, 0.40)
        rect((0.90, 0.97, 1.0), 0.38, 0.12, 0.24, 0.68)
        for fx in (0.43, 0.50, 0.56):
            rect((0.70, 0.88, 0.97), fx, 0.12, 0.025, 0.68)
        ell((1, 1, 1, 0.9), 0.28, 0.02, 0.44, 0.24)
        rect((0.30, 0.62, 0.78), 0, 0, 1, 0.08)
    elif clave == "norte":
        cielo((0.25, 0.52, 0.88), (0.65, 0.82, 0.95))
        tri((0.78, 0.30, 0.22), 0.0, 0.0, 0.50, 0.0, 0.18, 0.60)
        tri((0.92, 0.62, 0.25), 0.15, 0.0, 0.65, 0.0, 0.38, 0.52)
        tri((0.60, 0.35, 0.55), 0.45, 0.0, 1.0, 0.0, 0.75, 0.68)
        tri((0.35, 0.62, 0.40), 0.30, 0.0, 0.80, 0.0, 0.55, 0.38)
        rect((0.85, 0.65, 0.40), 0, 0, 1, 0.12)
        rect((0.20, 0.50, 0.25), 0.84, 0.10, 0.04, 0.32)
        rect((0.20, 0.50, 0.25), 0.78, 0.22, 0.06, 0.04)
        rect((0.20, 0.50, 0.25), 0.78, 0.22, 0.03, 0.12)
    elif clave == "malvinas":
        cielo((0.60, 0.68, 0.75), (0.82, 0.87, 0.90))
        rect((0.14, 0.38, 0.50), 0, 0, 1, 0.38)
        for i in range(4):
            rect((1, 1, 1, 0.55), 0.05 + i * 0.22, 0.10 + (i % 2) * 0.09, 0.16, 0.02)
        tri((0.30, 0.30, 0.32), 0.55, 0.0, 1.0, 0.0, 0.82, 0.42)
        rect((0.95, 0.95, 0.95), 0.77, 0.34, 0.08, 0.36)
        rect((0.80, 0.15, 0.15), 0.77, 0.44, 0.08, 0.07)
        rect((0.80, 0.15, 0.15), 0.77, 0.58, 0.08, 0.07)
        tri((0.80, 0.15, 0.15), 0.75, 0.70, 0.87, 0.70, 0.81, 0.82)
        ell((1, 0.95, 0.5), 0.795, 0.66, 0.03, 0.05)
    elif clave == "tropilla":
        cielo((0.95, 0.55, 0.30), (0.99, 0.85, 0.55))
        ell((1, 0.95, 0.7), 0.38, 0.34, 0.22, 0.32)
        rect((0.25, 0.22, 0.15), 0, 0, 1, 0.30)
        for i in range(5):
            fx = 0.08 + i * 0.17
            ell((0.12, 0.08, 0.06), fx, 0.20, 0.13, 0.10)
            ell((0.12, 0.08, 0.06), fx + 0.10, 0.27, 0.05, 0.07)
            rect((0.12, 0.08, 0.06), fx + 0.02, 0.10, 0.015, 0.12)
            rect((0.12, 0.08, 0.06), fx + 0.09, 0.10, 0.015, 0.12)
        ell((0.95, 0.75, 0.55, 0.35), 0.0, 0.15, 0.55, 0.12)
    elif clave == "ruta":
        cielo((0.40, 0.60, 0.90), (0.95, 0.85, 0.65))
        ell((1, 0.95, 0.7), 0.66, 0.40, 0.14, 0.22)
        rect((0.45, 0.55, 0.25), 0, 0, 1, 0.40)
        Color(0.25, 0.25, 0.28)
        Quad(points=(x + 0.44 * w, y + 0.40 * h, x + 0.56 * w, y + 0.40 * h, x + 0.96 * w, y, x + 0.04 * w, y))
        for i in range(5):
            ancho = 0.020 * (1.0 - i * 0.15)
            rect((0.95, 0.85, 0.30), 0.5 - ancho / 2.0, 0.02 + i * 0.072, ancho, 0.04)
    elif clave == "fogon":
        cielo((0.04, 0.06, 0.16), (0.14, 0.12, 0.28))
        estrellas(16, 0.35)
        rect((0.10, 0.07, 0.05), 0, 0, 1, 0.28)
        ell((1.0, 0.50, 0.10, 0.20), 0.22, 0.0, 0.56, 0.62)
        tri((0.95, 0.40, 0.10), 0.40, 0.10, 0.60, 0.10, 0.50, 0.52)
        tri((1.0, 0.78, 0.20), 0.44, 0.10, 0.56, 0.10, 0.50, 0.38)
        rect((0.35, 0.20, 0.10), 0.35, 0.07, 0.30, 0.05)
    elif clave == "estrellas":
        cielo((0.02, 0.03, 0.10), (0.14, 0.14, 0.32))
        estrellas(30, 0.30)
        ell((0.98, 0.97, 0.85), 0.68, 0.60, 0.17, 0.28)
        ell((0.06, 0.06, 0.18), 0.74, 0.64, 0.16, 0.26)
        ell((0.10, 0.07, 0.10), -0.1, -0.30, 0.85, 0.58)
        ell((0.13, 0.09, 0.12), 0.30, -0.32, 0.95, 0.52)
        tri((0.55, 0.55, 0.60), 0.17, 0.0, 0.31, 0.0, 0.24, 0.20)
        rect((0.70, 0.70, 0.75), 0.20, 0.17, 0.10, 0.04)
    elif clave == "terminal":
        cielo((0.70, 0.85, 0.97), (0.92, 0.95, 0.98))
        rect((0.85, 0.78, 0.65), 0.0, 0.25, 1.0, 0.50)
        rect((0.20, 0.35, 0.55), 0.30, 0.62, 0.40, 0.10)
        for i in range(5):
            rect((0.30, 0.50, 0.58), 0.06 + i * 0.19, 0.50, 0.12, 0.10)
        rect((0.45, 0.45, 0.48), 0, 0, 1, 0.14)
        rect((0.90, 0.30, 0.20), 0.12, 0.08, 0.64, 0.32)
        for i in range(5):
            rect((0.75, 0.90, 0.97), 0.16 + i * 0.12, 0.26, 0.09, 0.08)
        ell((0.12, 0.12, 0.14), 0.20, 0.03, 0.10, 0.12)
        ell((0.12, 0.12, 0.14), 0.58, 0.03, 0.10, 0.12)
    else:
        cielo((0.45, 0.68, 0.92), (0.85, 0.93, 1.0))
        rect((0.35, 0.55, 0.30), 0, 0, 1, 0.30)


class PostalCard(Widget):
    """Postal ilustrada del álbum: sin conseguir se ve oscura con un '?'."""
    def __init__(self, postal, tiene, numero, total, **kwargs):
        kwargs.setdefault("size_hint_y", None)
        kwargs.setdefault("height", dp(120))
        super().__init__(**kwargs)
        self.postal, self.tiene = postal, tiene
        def et(texto, tam, color, negrita=False, alin="left"):
            l = Label(text=texto, font_size=tam, bold=negrita, color=color, halign=alin, valign="middle")
            l.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
            self.add_widget(l)
            return l
        if tiene:
            titulo = postal["titulo"]
        elif postal.get("region"):
            titulo = "Conquistá " + postal["region"].replace("_", " ").title()
        else:
            titulo = "Aparece en el camino"
        TINTA, GRIS = (0.25, 0.17, 0.10, 1), (0.60, 0.57, 0.52, 1)
        self.l_tit = et(titulo, "10sp", TINTA if tiene else GRIS, True)
        self.l_num = et("N° %02d/%02d" % (numero, total), "8sp", (0.45, 0.35, 0.25, 1) if tiene else GRIS, False, "right")
        self.l_q = et("" if tiene else "?", "34sp", (0.55, 0.53, 0.50, 1), True, "center")
        # Se redibuja ya y de nuevo en el próximo cuadro: dentro de un cartel (Popup) el tamaño y la posición
        # llegan en momentos distintos y la postal quedaba dibujada corrida a la izquierda.
        self._redibujar = Clock.create_trigger(self._dibujar, -1)
        self.bind(pos=self._dibujar, size=self._dibujar)
        self.bind(pos=self._redibujar, size=self._redibujar)
        self._dibujar()
        self._redibujar()

    def _dibujar(self, *_):
        self.canvas.before.clear()
        if self.width < 40 or self.height < 30:
            return
        cw = min(self.width - dp(4), (self.height - dp(4)) * 1.55)
        ch = cw / 1.55
        x0, y0 = self.center_x - cw / 2.0, self.center_y - ch / 2.0
        wx, wy, ww, wh = x0 + cw * 0.04, y0 + ch * 0.22, cw * 0.92, ch * 0.74
        with self.canvas.before:
            Color(0, 0, 0, 0.35)
            RoundedRectangle(pos=(x0 + dp(2), y0 - dp(2)), size=(cw, ch), radius=[dp(5)])
            Color(0.97, 0.94, 0.86, 1) if self.tiene else Color(0.20, 0.19, 0.18, 1)
            RoundedRectangle(pos=(x0, y0), size=(cw, ch), radius=[dp(5)])
            if self.tiene:
                dibujar_escena_postal(self.postal["escena"], wx, wy, ww, wh)
                # sello postal
                sx, sy, sw, sh = wx + ww * 0.82, wy + wh * 0.68, ww * 0.14, wh * 0.28
                Color(1, 0.97, 0.88, 1)
                Rectangle(pos=(sx, sy), size=(sw, sh))
                Color(0.80, 0.25, 0.22, 1)
                Rectangle(pos=(sx + sw * 0.12, sy + sh * 0.12), size=(sw * 0.76, sh * 0.76))
                Color(1, 0.9, 0.5, 1)
                Ellipse(pos=(sx + sw * 0.30, sy + sh * 0.30), size=(sw * 0.40, sh * 0.40))
                Color(0.30, 0.20, 0.12, 0.55)
                Line(circle=(sx - sw * 0.2, sy + sh * 0.3, sh * 0.34), width=max(0.8, dp(0.8)))
            else:
                Color(0.10, 0.10, 0.11, 1)
                Rectangle(pos=(wx, wy), size=(ww, wh))
            Color(0.35, 0.28, 0.20, 0.9) if self.tiene else Color(0.40, 0.40, 0.42, 1)
            Line(rectangle=(wx, wy, ww, wh), width=max(0.8, dp(0.9)))
        self.l_tit.pos, self.l_tit.size = (x0 + cw * 0.05, y0 + ch * 0.02), (cw * 0.66, ch * 0.19)
        self.l_num.pos, self.l_num.size = (x0 + cw * 0.70, y0 + ch * 0.02), (cw * 0.25, ch * 0.19)
        self.l_q.pos, self.l_q.size = (wx, wy), (ww, wh)


class Moneda(Widget):
    """Monedita dorada con el signo $ (se dibuja, no depende de la fuente de emojis del celular)."""
    def __init__(self, lado=26, **kwargs):
        super().__init__(size_hint=(None, None), size=(dp(lado), dp(lado)), **kwargs)
        self.signo = Label(text="$", bold=True, font_size="%dsp" % max(10, int(lado * 0.55)), color=(0.35, 0.22, 0.03, 1))
        self.add_widget(self.signo)
        self.bind(pos=self._dibujar, size=self._dibujar)
        self._dibujar()

    def _dibujar(self, *_):
        self.canvas.before.clear()
        with self.canvas.before:
            Color(0, 0, 0, 0.35)
            Ellipse(pos=(self.x + 1, self.y - 1), size=self.size)
            Color(0.62, 0.42, 0.06, 1)
            Ellipse(pos=self.pos, size=self.size)
            Color(0.98, 0.80, 0.22, 1)
            Ellipse(pos=(self.x + dp(2), self.y + dp(2)), size=(self.width - dp(4), self.height - dp(4)))
            Color(1, 0.93, 0.55, 1)
            Line(circle=(self.x + self.width / 2.0, self.y + self.height / 2.0, self.width / 2.0 - dp(4.5)), width=1.0)
        self.signo.size = self.size
        self.signo.pos = self.pos


class IconoPuesto(Widget):
    """Medalla dibujada: oro/plata/bronce para el podio, azul para el resto, gris si todavía no hay puesto."""
    def __init__(self, lado=30, **kwargs):
        super().__init__(size_hint=(None, None), size=(dp(lado), dp(lado)), **kwargs)
        self.puesto = None
        self.numero = Label(text="", bold=True, font_size="%dsp" % max(9, int(lado * 0.42)), color=(0.12, 0.08, 0.02, 1))
        self.add_widget(self.numero)
        self.bind(pos=self._dibujar, size=self._dibujar)
        self._dibujar()

    def fijar(self, puesto):
        self.puesto = puesto
        self.numero.text = str(puesto) if puesto else "?"
        self._dibujar()

    def _dibujar(self, *_):
        colores = {1: (0.98, 0.80, 0.22), 2: (0.80, 0.82, 0.86), 3: (0.80, 0.50, 0.25)}
        c = colores.get(self.puesto, (0.45, 0.62, 0.85) if self.puesto else (0.45, 0.45, 0.45))
        x, y, w, h = self.x, self.y, self.width, self.height
        self.canvas.before.clear()
        with self.canvas.before:
            Color(0.80, 0.18, 0.18, 1)   # cinta
            Triangle(points=[x + w * 0.22, y + h * 0.40, x + w * 0.46, y + h * 0.40, x + w * 0.30, y])
            Triangle(points=[x + w * 0.54, y + h * 0.40, x + w * 0.78, y + h * 0.40, x + w * 0.70, y])
            Color(0, 0, 0, 0.35)
            Ellipse(pos=(x + w * 0.10 + 1, y + h * 0.22 - 1), size=(w * 0.80, h * 0.80))
            Color(*c, 1)
            Ellipse(pos=(x + w * 0.10, y + h * 0.22), size=(w * 0.80, h * 0.80))
            Color(1, 1, 1, 0.55)
            Line(circle=(x + w * 0.50, y + h * 0.62, w * 0.34), width=1.0)
        self.numero.size = (w, h * 0.80)
        self.numero.pos = (x, y + h * 0.22)


class FilaGiraMenu(BoxLayout):
    """Debajo del nombre: puntos de la Gira + medalla con tu puesto en el ranking online."""
    def __init__(self, **kwargs):
        super().__init__(orientation="horizontal", size_hint_y=None, height=dp(38),
                         padding=[dp(10), dp(2)], spacing=dp(8), **kwargs)
        self.puntos = Label(text="", markup=True, font_size="13sp", halign="left", valign="middle")
        self.puntos.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        self.icono = IconoPuesto(30)
        self.texto = Label(text="", markup=True, font_size="12sp", halign="right", valign="middle",
                           size_hint_x=None, width=dp(130))
        self.texto.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        for w in (self.puntos, self.icono, self.texto):
            self.add_widget(w)
        self.bind(pos=self._fondo, size=self._fondo)
        self._fondo()

    def _fondo(self, *_):
        self.canvas.before.clear()
        with self.canvas.before:
            Color(0, 0, 0, 0.22)
            RoundedRectangle(pos=self.pos, size=self.size, radius=[dp(6)])

    def actualizar(self, puntos, conquistadas, estado, cargando=False, error=None):
        self.puntos.text = "Puntos de gira: [b]%d[/b]" % puntos
        if conquistadas < 1:
            self.icono.fijar(None)
            self.texto.text = "[size=11sp]Sin ranking aún\nconquistá 1 región[/size]"
        elif estado and estado.get("clasificado") and estado.get("puesto"):
            self.icono.fijar(int(estado["puesto"]))
            self.texto.text = "Puesto [b]%s°[/b] de %s" % (estado["puesto"], estado.get("total", "?"))
        elif cargando:
            self.icono.fijar(None)
            self.texto.text = "[size=11sp]Ranking:\ncargando...[/size]"
        elif estado:   # el servidor contestó, pero todavía no figurás en el ranking
            self.icono.fijar(None)
            self.texto.text = "[size=11sp]Todavía sin puesto\nen el ranking[/size]"
        elif error and error[0] is not None:   # el servidor contestó con un error (no es falta de internet)
            self.icono.fijar(None)
            self.texto.text = "[size=11sp]Ranking: error %s\ndel servidor[/size]" % error[0]
        else:          # no hubo respuesta del servidor
            self.icono.fijar(None)
            self.texto.text = "[size=11sp]Ranking: sin conexión[/size]"


class FilaClub(BoxLayout):
    """Fila con fondo: [escudo] texto. `clubes` = lista de nombres (1 o 2 equipos)."""
    def __init__(self, clubes, textos, fondo=(0, 0, 0, 0.28), borde=None, alto=40, tam="11sp", extra=(), **kwargs):
        super().__init__(orientation="horizontal", size_hint_y=None, height=dp(alto),
                         padding=[dp(8), dp(3)], spacing=dp(8), **kwargs)
        self.fondo, self.borde = fondo, borde
        lado = max(18, alto - 10)
        if len(clubes) == 1:
            self.add_widget(Escudo(clubes[0], lado))
            self.add_widget(self._etiqueta(textos[0], "left", tam))
        else:
            self.add_widget(Escudo(clubes[0], lado))
            self.add_widget(self._etiqueta(textos[0], "left", tam))
            self.add_widget(self._etiqueta(textos[1], "right", tam))
            self.add_widget(Escudo(clubes[1], lado))
        for w in extra:
            self.add_widget(w)
        self.bind(pos=self._dibujar, size=self._dibujar)
        self._dibujar()

    def _etiqueta(self, texto, alinear, tam):
        et = Label(text=texto, markup=True, font_size=tam, halign=alinear, valign="middle")
        et.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        return et

    def _dibujar(self, *_):
        self.canvas.before.clear()
        with self.canvas.before:
            if self.borde:
                Color(*self.borde)
                RoundedRectangle(pos=(self.x - 1, self.y - 1), size=(self.width + 2, self.height + 2), radius=[dp(7)])
            Color(*self.fondo)
            RoundedRectangle(pos=self.pos, size=self.size, radius=[dp(6)])


class OpcionClub(SpinnerOption):
    """Opción del desplegable de clubes: escudo a la izquierda y nombre."""
    def __init__(self, **kwargs):
        kwargs.setdefault("halign", "left")
        kwargs.setdefault("valign", "middle")
        super().__init__(**kwargs)
        self.escudo = Escudo(self.text, 34)
        self.add_widget(self.escudo)
        self.bind(pos=self._acomodar, size=self._acomodar)
        self._acomodar()

    def _acomodar(self, *_):
        self.padding_x = dp(56)
        self.text_size = (self.width - dp(60), self.height)
        self.escudo.pos = (self.x + dp(10), self.y + (self.height - self.escudo.height) / 2.0)


def selector_club(club_inicial, alto=52, tam="16sp", valores=None):
    """Fila [escudo del club elegido][desplegable con escudos]. Devuelve (fila, spinner)."""
    fila = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(alto), spacing=dp(8))
    spinner = Spinner(text=club_inicial, values=valores or CLUBES_ARGENTINOS, font_size=tam,
                      background_color=(0.20, 0.30, 0.22, 1), option_cls=OpcionClub)
    estado = {"escudo": None}

    def poner_escudo(*_):
        if estado["escudo"] is not None:
            fila.remove_widget(estado["escudo"])
        estado["escudo"] = Escudo(spinner.text, max(24, alto - 8))
        fila.add_widget(estado["escudo"], index=len(fila.children))
    spinner.bind(text=poner_escudo)
    fila.add_widget(spinner)
    poner_escudo()
    return fila, spinner


class CartelFondo(BoxLayout):
    """Fondo del cartel: negro con borde dorado y adornos finos."""
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.bind(pos=self._dibujar, size=self._dibujar)
        self._dibujar()

    def _dibujar(self, *_):
        self.canvas.before.clear()
        with self.canvas.before:
            Color(0.80, 0.62, 0.30, 1)
            RoundedRectangle(pos=(self.x - 2, self.y - 2), size=(self.width + 4, self.height + 4), radius=[dp(20)])
            Color(0.06, 0.04, 0.02, 1)
            RoundedRectangle(pos=self.pos, size=self.size, radius=[dp(18)])


class Adorno(Widget):
    """Línea dorada fina con rombo central (separador del cartel)."""
    def __init__(self, **kwargs):
        super().__init__(size_hint_y=None, height=dp(18), **kwargs)
        self.bind(pos=self._dibujar, size=self._dibujar)
        self._dibujar()

    def _dibujar(self, *_):
        self.canvas.before.clear()
        with self.canvas.before:
            Color(0.80, 0.62, 0.30, 1)
            cx, cy = self.x + self.width / 2.0, self.y + self.height / 2.0
            largo = self.width * 0.22
            Rectangle(pos=(cx - dp(10) - largo, cy - 0.5), size=(largo, max(1.0, dp(1))))
            Rectangle(pos=(cx + dp(10), cy - 0.5), size=(largo, max(1.0, dp(1))))
            RoundedRectangle(pos=(cx - dp(5), cy - dp(5)), size=(dp(10), dp(10)), radius=[dp(3)])


