EXT_FOTOS_GIRA = (".jpg", ".jpeg", ".png", ".webp")


def fotos_info_gira(nombre):
    """Rutas de las fotos de una región: subcarpeta <nombre>/ o archivos <nombre>*.ext dentro de las carpetas de mapas."""
    for carpeta in carpeta_mapas():
        rutas = []
        try:
            entradas = sorted(os.listdir(carpeta))
        except OSError:
            continue
        for entrada in entradas:
            baja = entrada.lower()
            ruta = os.path.join(carpeta, entrada)
            if os.path.isdir(ruta) and normalizar(entrada) == normalizar(nombre):
                try:
                    rutas += [os.path.join(ruta, a) for a in sorted(os.listdir(ruta)) if a.lower().endswith(EXT_FOTOS_GIRA)]
                except OSError:
                    pass
            elif os.path.isfile(ruta) and baja.startswith(nombre) and baja.endswith(EXT_FOTOS_GIRA):
                rutas.append(ruta)
        if rutas:
            return rutas
    return []


def audio_info_gira(nombre):
    """Ruta del audio de presentación de una región: <carpeta>/<nombre>/<nombre>.mp3 (ej. Patagonia/Patagonia.mp3),
    buscando sin importar mayúsculas. Si no está ahí, prueba en la carpeta 'audio' del juego."""
    clave = normalizar(nombre)
    for carpeta in carpeta_mapas():
        try:
            entradas = sorted(os.listdir(carpeta))
        except OSError:
            continue
        for entrada in entradas:
            sub = os.path.join(carpeta, entrada)
            if not (os.path.isdir(sub) and normalizar(entrada) == clave):
                continue
            try:
                archivos = sorted(os.listdir(sub))
            except OSError:
                continue
            for archivo in archivos:
                nombre_sin_ext, ext = os.path.splitext(archivo)
                if ext.lower() in EXTENSIONES_AUDIO and normalizar(nombre_sin_ext) == clave:
                    return os.path.join(sub, archivo)
            for archivo in archivos:  # cualquier audio dentro de esa carpeta
                if archivo.lower().endswith(EXTENSIONES_AUDIO):
                    return os.path.join(sub, archivo)
    return buscar_audio(nombre)


class CarruselFotos(StencilView):
    """Fotos que pasan solas: cada una entra con fundido y se acerca despacio mientras se desplaza (efecto 'documental')."""
    SEG = 3.8    # segundos que dura cada foto
    FADE = 0.9   # segundos del fundido entre fotos

    def __init__(self, rutas, **kwargs):
        super().__init__(**kwargs)
        self.rutas = list(rutas)
        self.texturas = {}
        self.t = 0.0
        self.evento = None
        self.bind(pos=self._dibujar, size=self._dibujar)

    def iniciar(self):
        if self.evento is None and len(self.rutas) > 0:
            self.evento = Clock.schedule_interval(self._paso, 1 / 30.0)

    def detener(self):
        if self.evento is not None:
            self.evento.cancel()
            self.evento = None

    def _textura(self, ruta):
        if ruta not in self.texturas:
            try:
                self.texturas[ruta] = CoreImage(ruta).texture
            except Exception as error:
                print("No se pudo cargar la foto:", ruta, error)
                self.texturas[ruta] = None
        return self.texturas[ruta]

    def _paso(self, dt):
        self.t += min(dt, 0.1)
        self._dibujar()

    def _capa(self, i, alfa, edad):
        ruta = self.rutas[i % len(self.rutas)]
        tex = self._textura(ruta)
        if tex is None:
            return
        iw, ih = tex.size
        progreso = max(0.0, min(1.0, edad / (self.SEG + self.FADE)))
        esc = max(self.width / float(iw), self.height / float(ih)) * (1.0 + 0.14 * progreso)
        rw, rh = iw * esc, ih * esc
        sentido = 1 if i % 2 == 0 else -1
        x = self.x + (self.width - rw) / 2.0 + sentido * (progreso - 0.5) * (rw - self.width) * 0.8
        y = self.y + (self.height - rh) / 2.0
        Color(1, 1, 1, alfa)
        Rectangle(texture=tex, pos=(x, y), size=(rw, rh))

    def _dibujar(self, *_):
        if self.width <= 0 or self.height <= 0 or not self.rutas:
            return
        k = int(self.t // self.SEG)
        edad = self.t - k * self.SEG
        self.canvas.clear()
        with self.canvas:
            Color(0.08, 0.06, 0.04, 1)
            Rectangle(pos=self.pos, size=self.size)
            if k >= 1 and edad < self.FADE and len(self.rutas) > 1:
                self._capa(k - 1, 1.0, edad + self.SEG)          # la que se va queda debajo
                self._capa(k, edad / self.FADE, edad)            # la nueva aparece encima
            else:
                self._capa(k, 1.0, edad)
            n = len(self.rutas)
            if n > 1:                                             # puntitos de posición
                for j in range(n):
                    Color(1, 1, 1, 0.95 if j == k % n else 0.35)
                    Ellipse(pos=(self.center_x - n * dp(5) + j * dp(10), self.y + dp(6)), size=(dp(6), dp(6)))


class InfoRegionGira(BoxLayout):
    """Título + fotos animadas + texto cortito. Se arma con los datos de GIRA_INFO_REGION."""

    def __init__(self, info, **kwargs):
        super().__init__(orientation="vertical", spacing=dp(4), size_hint_y=None, **kwargs)
        self.carrusel = None
        self.audio_nombre = info.get("audio", "")
        self.sonido = None
        self._musica_pausada_por_mi = False
        alto = dp(22) + dp(78)
        self.add_widget(Label(text=info["titulo"], font_size="14sp", bold=True, color=(0.96, 0.78, 0.30, 1),
                              size_hint_y=None, height=dp(22)))
        fotos = fotos_info_gira(info.get("fotos", ""))
        if fotos:
            self.carrusel = CarruselFotos(fotos, size_hint_y=None, height=dp(130))
            self.add_widget(self.carrusel)
            alto += dp(134)
        texto = Label(text=info["texto"], markup=True, font_size="12sp", halign="left", valign="top",
                      color=(0.88, 0.85, 0.80, 1), size_hint_y=None, height=dp(78))
        texto.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, None)))
        self.add_widget(texto)
        self.height = alto

    def iniciar(self):
        if self.carrusel is not None:
            self.carrusel.iniciar()
        self._iniciar_audio()

    def detener(self):
        if self.carrusel is not None:
            self.carrusel.detener()
        self._detener_audio()

    def _iniciar_audio(self):
        """Suena <región>/<región>.mp3 mientras pasan las fotos (respeta el botón de silencio)."""
        if not self.audio_nombre or self.sonido is not None:
            return
        app = App.get_running_app()
        try:
            if app is None or not app.audio_permitido():
                return
            ruta = audio_info_gira(self.audio_nombre)
            if not ruta:
                print("No se encontró el audio de la región:", self.audio_nombre)
                return
            sonido = SoundLoader.load(ruta)
            if sonido is None:
                print("No se pudo cargar el audio de la región:", ruta)
                return
            if not getattr(app, "musica_menu_pausada", False):   # baja la música del menú mientras dura la presentación
                app.musica_menu_pausar()
                self._musica_pausada_por_mi = True
            self.sonido = sonido
            _SONIDOS_VIVOS.append(sonido)
            del _SONIDOS_VIVOS[:-6]
            app.sonido_region = sonido   # así el botón de silencio también lo corta
            sonido.play()
        except Exception as error:
            print("Error audio de la región:", error)

    def _detener_audio(self):
        sonido, self.sonido = self.sonido, None
        if sonido is not None:
            try:
                if getattr(sonido, "state", "stop") == "play":
                    sonido.stop()
            except Exception:
                pass
            try: sonido.unload()
            except Exception: pass
            if sonido in _SONIDOS_VIVOS:
                _SONIDOS_VIVOS.remove(sonido)
        if self._musica_pausada_por_mi:
            self._musica_pausada_por_mi = False
            app = App.get_running_app()
            try:
                if app is not None:
                    app.musica_menu_reanudar()
            except Exception:
                pass


def gira_info_widget(pais, region):
    info = GIRA_INFO_REGION.get("%s.%s" % (pais["id"], region["id"]))
    return InfoRegionGira(info) if info else None


class DiapositivaGira(Widget):
    """Zona animada de la presentación de la Gira."""
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.n = 0
        self.tema = "gira"
        self.t = 0.0
        self.evento = None
        self.bind(pos=self.dibujar, size=self.dibujar)

    def iniciar(self):
        self.evento = Clock.schedule_interval(self.paso, 1 / 20.0)

    def detener(self):
        if self.evento is not None:
            self.evento.cancel()
            self.evento = None

    def paso(self, dt):
        self.t += dt
        self.dibujar()

    def dibujar(self, *_):
        if self.width > 0 and self.height > 0:
            escena = escena_presentacion_copa if self.tema == "copa" else escena_presentacion
            pintar_figuras(self, escena(self.n, self.width, self.height, self.t))


class EscudosPasan(FloatLayout):
    """Primera diapositiva de la Copa: tres filas de escudos que pasan solas, en sentidos opuestos."""
    FILAS = 3

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.n = 0
        self.evento = None
        self.desfase = 0.0
        clubes = list(CLUBES_ARGENTINOS)
        random.shuffle(clubes)
        self.lado = 56
        self.paso_x = dp(self.lado + 18)
        self.filas = []
        por_fila = max(6, len(clubes) // self.FILAS + 1)
        for i in range(self.FILAS):
            grupo = [clubes[(i * por_fila + k) % len(clubes)] for k in range(por_fila)]
            escudos = [Escudo(c, self.lado) for c in grupo]
            for e in escudos:
                self.add_widget(e)
            self.filas.append(escudos)
        self.bind(pos=self.acomodar, size=self.acomodar)

    def iniciar(self):
        self.evento = Clock.schedule_interval(self.mover, 1 / 30.0)

    def detener(self):
        if self.evento is not None:
            self.evento.cancel()
            self.evento = None

    def mover(self, dt):
        self.desfase += dt * dp(55)
        self.acomodar()

    def acomodar(self, *_):
        if self.width <= 0 or self.height <= 0:
            return
        largo = self.paso_x * len(self.filas[0])
        alto_fila = self.height / float(self.FILAS)
        for i, escudos in enumerate(self.filas):
            sentido = 1 if i % 2 == 0 else -1
            y = self.y + self.height - (i + 0.5) * alto_fila - dp(self.lado) / 2.0
            for k, e in enumerate(escudos):
                x = (k * self.paso_x + sentido * self.desfase + i * dp(30)) % largo
                e.pos = (self.x + x - self.paso_x, y)


class CartaBoton(ButtonBehavior, Image):
    def on_press(self): self.opacity = 0.65
    def on_release(self): self.opacity = 1.0


def _sombra_en(widget, desvio=2.5, alfa=0.38):
    """Sombra suave con la forma de la carta. Se llama dentro de `with widget.canvas.before:`."""
    widget._sombra_color = Color(0, 0, 0, alfa)
    widget._sombra_rect = RoundedRectangle(pos=widget.pos, size=widget.size, radius=[dp(4)])
    widget._sombra_desvio = dp(desvio)

    def actualizar(*_):
        try:
            ancho, alto = widget.norm_image_size
        except Exception:
            ancho, alto = widget.size
        if not ancho or not alto:
            ancho, alto = widget.size
        d = widget._sombra_desvio
        cx, cy = widget.center
        widget._sombra_rect.size = (ancho, alto)
        widget._sombra_rect.pos = (cx - ancho / 2.0 + d, cy - alto / 2.0 - d * 1.4)
    widget._sombra_actualizar = actualizar
    widget.bind(pos=actualizar, size=actualizar, texture_size=actualizar)
    actualizar()


class CartaMesa(Image):
    """Carta jugada sobre el paño: sombra, leve giro natural y caída con rebote al soltarla."""
    caida = NumericProperty(1.0)   # no llamarla `t`: en Animation(t=...) significa transición

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self._giro = 0.0
        self._desde_y = 0.0
        self._corr_x = 0.0   # corrimiento al azar: nadie apoya la carta en el centro exacto
        self._corr_y = 0.0
        with self.canvas.before:
            PushMatrix()
            self._tr = Translate(0, 0)
            self._sc = Scale(1, 1, 1)
            self._rot = Rotate(angle=0, origin=self.center)
            _sombra_en(self, desvio=3.5, alfa=0.44)
        with self.canvas.after:
            PopMatrix()
        self.bind(pos=self._centrar, size=self._centrar, caida=self._aplicar)
        self._centrar()

    def _centrar(self, *_):
        try: self._sc.origin = self.center
        except Exception: pass
        self._rot.origin = self.center

    def _aplicar(self, *_):
        k = 1.0 - self.caida
        self._tr.x = self._corr_x
        self._tr.y = self._desde_y * k + self._corr_y
        esc = 1.0 + 0.32 * k
        self._sc.x = self._sc.y = esc
        self._rot.angle = self._giro + 14.0 * k * (1 if self._giro >= 0 else -1)
        self._sombra_desvio = dp(3) + dp(14) * max(0.0, k)
        self._sombra_actualizar()

    def soltar(self, desde_y=0):
        """La carta cae sobre el paño desde `desde_y` (px) con un rebote corto."""
        Animation.cancel_all(self, "caida")
        self._giro = random.choice((-1, 1)) * random.uniform(2.0, 8.0)
        self._corr_x = random.uniform(-dp(6), dp(6))
        self._corr_y = random.uniform(-dp(5), dp(5))
        self._desde_y = desde_y
        self.caida = 0.0
        Animation(caida=1.0, duration=0.32, transition="out_back").start(self)

    def limpiar(self):
        Animation.cancel_all(self, "caida")
        self._giro = 0.0
        self._corr_x = self._corr_y = 0.0
        self.caida = 1.0
        self._aplicar()


class VueloCarta:
    """Mixin: la carta vuela desde un punto (el mazo) hasta su lugar SIN tocar `pos`.
    El vuelo es solo un desplazamiento dibujado: el acomodo de la mano manda siempre, así la carta
    termina donde corresponde aunque la pantalla todavía se esté acomodando."""

    def _vuelo_instrucciones(self):
        self._vuelo_tr = Translate(0, 0)
        self._vuelo_sc = Scale(1, 1, 1)
        self._vuelo_dx = self._vuelo_dy = 0.0

    def _vuelo_centrar(self):
        try: self._vuelo_sc.origin = self.center
        except Exception: pass

    def _aplicar_vuelo(self, *_):
        k = 1.0 - self.vuelo
        self._vuelo_tr.x = self._vuelo_dx * k
        self._vuelo_tr.y = self._vuelo_dy * k
        self._vuelo_sc.x = self._vuelo_sc.y = 1.0 - 0.45 * k

    def volar_desde(self, x, y, demora, duracion):
        """Después de `demora` segundos la carta sale de (x, y) y viaja hasta su lugar en `duracion` segundos."""
        def lanzar(_dt):
            cx, cy = self.center
            self._vuelo_dx, self._vuelo_dy = x - cx, y - cy
            self.vuelo = 0.0
            self.opacity = 1
            Animation(vuelo=1.0, duration=duracion, transition="out_cubic").start(self)
        Clock.schedule_once(lanzar, demora)


class DorsoRotado(VueloCarta, Image):
    """Dorso de una carta del rival con la misma inclinación de abanico que la mano propia."""
    vuelo = NumericProperty(1.0)

    def __init__(self, angulo=0, **kwargs):
        super().__init__(**kwargs)
        with self.canvas.before:
            PushMatrix()
            self._vuelo_instrucciones()
            self.rotacion_mano = Rotate(angle=angulo, origin=self.center)
            _sombra_en(self, desvio=2, alfa=0.34)
        with self.canvas.after:
            PopMatrix()
        self.bind(pos=self._actualizar_rotacion, size=self._actualizar_rotacion, vuelo=self._aplicar_vuelo)
        self._vuelo_centrar()

    def _actualizar_rotacion(self, *_):
        self.rotacion_mano.origin = self.center
        self._vuelo_centrar()


class CartaManoRotada(VueloCarta, CartaBoton):
    """Carta interactiva con una inclinación suave para formar un abanico."""
    vuelo = NumericProperty(1.0)

    def __init__(self, angulo=0, **kwargs):
        super().__init__(**kwargs)
        self.angulo_mano = angulo
        with self.canvas.before:
            PushMatrix()
            self._vuelo_instrucciones()
            self.rotacion_mano = Rotate(angle=angulo, origin=self.center)
            _sombra_en(self, desvio=2.5, alfa=0.38)
        with self.canvas.after:
            PopMatrix()
        self.bind(pos=self._actualizar_rotacion, size=self._actualizar_rotacion, vuelo=self._aplicar_vuelo)
        self._vuelo_centrar()

    def _actualizar_rotacion(self, *_):
        self.rotacion_mano.origin = self.center
        self._vuelo_centrar()


class MesaJuego(GridLayout):
    """Paño de juego: tres columnas de bazas en el centro y, a los costados, la taza de café y el mazo.

    Los laterales quedan libres de cartas, así que ninguna baza tapa la taza ni el mazo.
    El mazo usa el mismo dorso que las cartas y se apoya a la derecha de quien reparte.
    """
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.dorso = None
        self.repartidor = 1          # 0 = jugador (abajo), 1 = rival (arriba)
        self._ruta_textura = None
        self._textura_dorso = None
        self._mazo_centro = None
        self._humo = InstructionGroup()
        self._humo_base = None
        self._humo_t = 0.0
        self._humo_evento = None
        self._humo_ausente = 0
        self.bind(pos=self._dibujar_accesorios, size=self._dibujar_accesorios)
        self.bind(parent=self._al_cambiar_parent)
        self._dibujar_accesorios()

    def centro_mazo(self):
        """Centro del mazo en coordenadas de ventana (de ahí salen las cartas al repartir)."""
        return self._mazo_centro or (self.center_x, self.center_y)

    def _al_cambiar_parent(self, *_):
        if self.parent is not None and self._humo_evento is None:
            self._humo_ausente = 0
            self._humo_evento = Clock.schedule_interval(self._animar_humo, 1 / 24.0)

    def _animar_humo(self, dt):
        """Vapor del café: bocanadas que suben, se ensanchan, se mecen y se desvanecen."""
        if self.get_root_window() is None:
            self._humo_ausente += 1
            if self._humo_ausente > 72:   # la pantalla ya no está: se corta el reloj
                self._humo_evento = None
                return False
            return True
        self._humo_ausente = 0
        base = self._humo_base
        if base is None:
            return True
        self._humo_t += dt
        bx, by, u = base
        g = self._humo
        g.clear()
        # Tres hilos finos de vapor que suben ondulando y se desvanecen.
        for k in range(3):
            fase = (self._humo_t * 0.22 + k / 3.0) % 1.0
            env = math.sin(math.pi * fase)
            x0 = bx + (k - 1) * u * 0.07
            tramos = 12
            xa, ya = x0, by
            for j in range(1, tramos + 1):
                sj = j / float(tramos)
                xb = x0 + math.sin(sj * 5.0 + fase * 6.0 + k * 2.1) * u * (0.03 + 0.05 * sj)
                yb = by + sj * u * 0.50 * (0.55 + 0.45 * fase)
                g.add(Color(0.95, 0.95, 0.91, 0.30 * env * math.sin(math.pi * (1 - sj * 0.9))))
                g.add(Line(points=[xa, ya, xb, yb], width=max(1.0, dp(1.3))))
                xa, ya = xb, yb
        return True

    def configurar_mazo(self, dorso, repartidor):
        if dorso == self.dorso and repartidor == self.repartidor:
            return
        self.dorso = dorso
        self.repartidor = repartidor
        self._dibujar_accesorios()

    def _textura(self):
        if not self.dorso or not os.path.isfile(self.dorso):
            return None
        if self._ruta_textura != self.dorso:
            self._ruta_textura = self.dorso
            try:
                self._textura_dorso = CoreImage(self.dorso).texture
            except Exception:
                self._textura_dorso = None
        return self._textura_dorso

    def _dibujar_accesorios(self, *_):
        canvas = self.canvas.before
        canvas.clear()
        x, y, w, h = self.x, self.y, self.width, self.height
        if w < 10 or h < 10:
            return
        # Franja lateral reservada para la taza y el mazo; las bazas ocupan el centro.
        lado = w * 0.17
        if abs(self.padding[0] - lado) > 0.5 or abs(self.padding[2] - lado) > 0.5:
            self.padding = [lado, 0, lado, 0]
        # Cada objeto tiene su franja vertical y su tamaño depende también del ALTO de la mesa: si la mesa
        # es baja, los objetos se achican en vez de pisarse.
        #   Izquierda (de abajo hacia arriba): taza, palillero + monedas, mazo (si reparte el rival).
        #   Derecha (de abajo hacia arriba):   mazo (si repartís vos), sobres de azúcar, vaso de soda.
        with canvas:
            u_taza = min(lado * 0.70, h * 0.40)
            self._dibujar_taza(x + (lado - u_taza) / 2.0, y + h * 0.03, u_taza)
            u_pal = min(lado * 0.46, h * 0.15)
            self._dibujar_palillero(x + lado * 0.10, y + h * 0.38, u_pal)
            u_mon = min(lado * 0.22, h * 0.09)
            self._dibujar_monedas(x + lado * 0.70, y + h * 0.39, u_mon)
            self._dibujar_mazo(x, y, w, h, lado)
            u_vaso = min(lado * 0.78, h * 0.27)
            self._dibujar_vaso(x + w - lado + (lado - u_vaso) / 2.0, y + h - u_vaso * 1.10 - h * 0.03, u_vaso)
            self._dibujar_sobres(x + w - lado / 2.0, y + h * 0.47, min(lado * 0.80, h * 0.30))
        canvas.add(self._humo)

    def _dibujar_mazo(self, x, y, w, h, lado):
        tex = self._textura()
        proporcion = (tex.width / float(tex.height)) if tex is not None and tex.height else 0.68
        dw_max = lado * 0.84
        dh = min(h * 0.30, dw_max / proporcion)
        dw = dh * proporcion
        margen = h * 0.04
        if self.repartidor == 1:
            # Reparte el rival (arriba): su derecha cae a la izquierda de la pantalla.
            dx = x + (lado - dw) / 2.0
            dy = y + h - dh - margen
        else:
            # Repartís vos (abajo): tu derecha es la derecha de la pantalla.
            dx = x + w - lado + (lado - dw) / 2.0
            dy = y + margen
        self._mazo_centro = (dx + dw / 2.0, dy + dh / 2.0)
        grosor = max(1.0, dp(1.3))
        capas = 4
        # Sombra del mazo.
        Color(0, 0, 0, 0.35)
        RoundedRectangle(pos=(dx + dp(3), dy - dp(3) - grosor * capas), size=(dw, dh), radius=[dp(3)])
        # Pila: capas con el mismo dorso, apenas desplazadas, para dar espesor.
        for i in range(capas):
            ox = dx - grosor * (capas - 1 - i) * 0.6
            oy = dy - grosor * (capas - 1 - i)
            if tex is not None:
                Color(0.72, 0.72, 0.72, 1) if i < capas - 1 else Color(1, 1, 1, 1)
                Rectangle(texture=tex, pos=(ox, oy), size=(dw, dh))
            else:
                Color(0.88, 0.82, 0.68, 1) if i < capas - 1 else Color(0.38, 0.055, 0.06, 1)
                RoundedRectangle(pos=(ox, oy), size=(dw, dh), radius=[dp(3)])
        # Filo fino alrededor de la carta de arriba.
        Color(0, 0, 0, 0.45)
        Line(rectangle=(dx, dy - 0, dw, dh), width=max(0.6, dp(0.5)))

    def _dibujar_taza(self, px, py, u):
        """Taza con plato; u es el ancho del plato."""
        # Plato con sombra suave.
        Color(0, 0, 0, .24)
        Ellipse(pos=(px + u * .04, py - u * .03), size=(u, u * .50))
        Color(.79, .77, .69, 1)
        Ellipse(pos=(px, py), size=(u, u * .50))
        Color(.96, .94, .86, 1)
        Ellipse(pos=(px + u * .09, py + u * .07), size=(u * .82, u * .36))
        # Cucharita apoyada en el plato.
        Color(0, 0, 0, .18)
        Line(points=[px + u * .10, py + u * .11, px + u * .30, py + u * .09], width=max(1, dp(1.6)))
        Color(.82, .82, .85, 1)
        Line(points=[px + u * .10, py + u * .13, px + u * .30, py + u * .11], width=max(1, dp(1.4)))
        Ellipse(pos=(px + u * .06, py + u * .105), size=(u * .09, u * .06))
        # Asa detrás de la taza.
        Color(.77, .75, .66, 1)
        Ellipse(pos=(px + u * .64, py + u * .30), size=(u * .30, u * .36))
        Color(*PAÑO)
        Ellipse(pos=(px + u * .72, py + u * .38), size=(u * .14, u * .20))
        # Cuerpo de la taza.
        cx, cy, cw, ch = px + u * .20, py + u * .20, u * .56, u * .62
        Color(0, 0, 0, .2)
        RoundedRectangle(pos=(cx + u * .03, cy - u * .02), size=(cw, ch), radius=[dp(8)])
        Color(.91, .89, .80, 1)
        RoundedRectangle(pos=(cx, cy), size=(cw, ch), radius=[dp(8)])
        Color(.99, .97, .89, 1)
        Ellipse(pos=(cx, cy + ch - u * .10), size=(cw, u * .20))
        Color(.17, .12, .075, 1)
        Ellipse(pos=(cx + cw * .10, cy + ch - u * .065), size=(cw * .80, u * .12))
        # Reflejo (el vapor se anima aparte, en _animar_humo).
        Color(1, .98, .88, .55)
        Line(points=[cx + cw * .12, cy + ch * .18, cx + cw * .12, cy + ch * .70], width=max(1, dp(1.1)))
        self._humo_base = (cx + cw * .5, cy + ch + u * .04, u)

    def _dibujar_palillero(self, px, py, u):
        """Palillero de metal con palillos asomando; u = ancho aproximado."""
        bw, bh = u * 0.62, u * 0.86
        bx = px
        Color(0, 0, 0, .25)
        Ellipse(pos=(bx - bw * .05, py - u * .06), size=(bw * 1.25, u * .20))
        Color(.60, .62, .66, 1)
        RoundedRectangle(pos=(bx, py), size=(bw, bh), radius=[dp(3)])
        Color(.82, .84, .88, .55)
        Rectangle(pos=(bx + bw * .14, py + bh * .08), size=(bw * .16, bh * .80))
        Color(.20, .20, .24, .35)
        Rectangle(pos=(bx + bw * .78, py + bh * .06), size=(bw * .14, bh * .84))
        Color(.30, .30, .34, 1)
        Ellipse(pos=(bx, py + bh - u * .09), size=(bw, u * .18))
        Color(.86, .74, .50, 1)
        for dx, alto in ((.22, .30), (.40, .38), (.58, .26), (.70, .34)):
            Rectangle(pos=(bx + bw * dx, py + bh), size=(max(1.0, dp(1.4)), u * alto))

    def _dibujar_monedas(self, cx, cy, u):
        """Tres monedas apiladas y una suelta; u = diámetro."""
        alto = u * .22
        for i in range(3):
            y0 = cy + i * alto * .55
            Color(0, 0, 0, .24 if i == 0 else 0)
            Ellipse(pos=(cx - u / 2 + dp(1.5), y0 - dp(1.5)), size=(u, alto))
            Color(.62, .47, .12, 1)
            Ellipse(pos=(cx - u / 2, y0), size=(u, alto))
            Color(.86, .70, .24, 1)
            Ellipse(pos=(cx - u / 2, y0 + alto * .22), size=(u, alto))
            Color(1, .90, .55, .55)
            Line(ellipse=(cx - u * .36, y0 + alto * .30, u * .72, alto * .62), width=max(.8, dp(.8)))
        Color(.62, .47, .12, 1)
        Ellipse(pos=(cx + u * .62, cy - alto * .35), size=(u * .90, alto * .90))
        Color(.86, .70, .24, 1)
        Ellipse(pos=(cx + u * .62, cy - alto * .15), size=(u * .90, alto * .90))

    def _dibujar_vaso(self, px, py, u):
        """Vaso de soda sobre un posavasos de cartón; u = ancho del posavasos."""
        Color(0, 0, 0, .25)
        Ellipse(pos=(px + u * .03, py - u * .02), size=(u, u * .42))
        Color(.80, .66, .42, 1)
        Ellipse(pos=(px, py), size=(u, u * .42))
        Color(.62, .47, .26, 1)
        Line(ellipse=(px + u * .07, py + u * .035, u * .86, u * .35), width=max(1, dp(1)))
        vw, vh = u * .56, u * .95
        vx, vy = px + (u - vw) / 2.0, py + u * .12
        Color(0, 0, 0, .22)
        Ellipse(pos=(vx + vw * .12, vy - u * .03), size=(vw * 1.0, u * .18))
        Color(.80, .92, .95, .30)
        Quad(points=(vx + vw * .06, vy + u * .06, vx + vw * .94, vy + u * .06, vx + vw * 1.04, vy + vh, vx - vw * .04, vy + vh))
        Color(.62, .84, .92, .40)
        Quad(points=(vx + vw * .08, vy + u * .08, vx + vw * .92, vy + u * .08, vx + vw * 1.0, vy + vh * .72, vx, vy + vh * .72))
        Color(.92, .98, 1, .50)
        Line(ellipse=(vx - vw * .04, vy + vh - u * .05, vw * 1.08, u * .10), width=max(1, dp(1)))
        Color(1, 1, 1, .55)
        Line(points=[vx + vw * .18, vy + vh * .12, vx + vw * .14, vy + vh * .62], width=max(1, dp(1.2)))
        Color(1, 1, 1, .50)
        for bx, by in ((.35, .30), (.55, .45), (.42, .58)):
            Ellipse(pos=(vx + vw * bx, vy + vh * by), size=(dp(2.2), dp(2.2)))

    def _dibujar_sobres(self, cx, cy, u):
        """Dos sobrecitos de azúcar tirados sobre el paño."""
        for dx, dy, ang, col in ((-u * .10, 0, 14, (0.95, 0.95, 0.92)), (u * .08, -u * .06, -9, (0.92, 0.90, 0.86))):
            ox, oy = cx + dx, cy + dy
            PushMatrix()
            Rotate(angle=ang, origin=(ox, oy))
            Color(0, 0, 0, .24)
            RoundedRectangle(pos=(ox - u * .30 + dp(1.5), oy - u * .11 - dp(1.5)), size=(u * .60, u * .22), radius=[dp(2)])
            Color(col[0], col[1], col[2], 1)
            RoundedRectangle(pos=(ox - u * .30, oy - u * .11), size=(u * .60, u * .22), radius=[dp(2)])
            Color(.25, .45, .75, 1)
            Rectangle(pos=(ox - u * .30, oy - u * .02), size=(u * .60, u * .04))
            PopMatrix()


def valor_envido(numero):
    return 0 if numero >= 10 else numero


def puntos_envido(mano):
    mejor = 0
    for palo in PALOS:
        valores = [valor_envido(c[0]) for c in mano if c[1] == palo]
        if len(valores) >= 2:
            valores.sort(reverse=True)
            mejor = max(mejor, 20 + valores[0] + valores[1])
    if mejor: return mejor
    return max(valor_envido(c[0]) for c in mano)


def apuesta_falta_envido(puntos_jugador, puntos_ia):
    # Falta envido: lo que le falta al que va ganando para llegar al final.
    return max(1, PUNTOS_PARTIDA - max(puntos_jugador, puntos_ia))


