def libertadores_participantes(usuario):
    """32 equipos: los 32 de la lista, con tu club en lugar de un argentino (o sin cambios si ya estaba)."""
    todos = [c for _pais, clubes in LIBERTADORES_EQUIPOS for c in clubes]
    if usuario in todos:
        return todos
    argentinos = list(LIBERTADORES_EQUIPOS[0][1])
    sale = random.choice(argentinos)
    return [usuario if c == sale else c for c in todos]


