def escena_presentacion_copa(n, ancho, alto, t):
    """Diapositivas de la presentación de la Copa Argentina (sin imágenes)."""
    U = min(ancho, alto)
    if n == 1:
        return escena_presentacion(1, ancho, alto, t)
    if n == 2:
        return escena_presentacion(2, ancho, alto, t)
    f = [("c", 0.10, 0.07, 0.04, 1), ("rect", 0, 0, ancho, alto)]
    if n == 0:  # 8 zonas que se van iluminando
        activo = int(t * 2.0) % 9
        cw, ch = ancho * 0.19, alto * 0.30
        for i in range(8):
            col, fila = i % 4, i // 4
            x = ancho * 0.07 + col * (cw + ancho * 0.026)
            y = alto * 0.58 - fila * (ch + alto * 0.08)
            f += [("c", 0.95, 0.76, 0.20, 1) if i < activo else ("c", 0.32, 0.25, 0.18, 1), ("rect", x, y, cw, ch),
                  ("c", 0.10, 0.07, 0.04, 1) if i < activo else ("c", 0.75, 0.65, 0.45, 1),
                  ("circ", x + cw / 2.0, y + ch / 2.0, min(cw, ch) * 0.22)]
    else:  # boleto dorado hacia la Libertadores
        cx, cy = ancho / 2.0, alto * 0.52
        pulso = 1.0 + 0.06 * math.sin(t * 4.0)
        w, h = ancho * 0.70 * pulso, alto * 0.36 * pulso
        f += [("c", 0.62, 0.42, 0.06, 1), ("rect", cx - w / 2.0 - 3, cy - h / 2.0 - 3, w + 6, h + 6),
              ("c", 0.95, 0.76, 0.20, 1), ("rect", cx - w / 2.0, cy - h / 2.0, w, h),
              ("c", 0.35, 0.22, 0.05, 1), ("rect", cx - w * 0.40, cy - h * 0.06, w * 0.80, h * 0.12),
              ("rect", cx - w * 0.28, cy + h * 0.22, w * 0.56, h * 0.10),
              ("c", 0.10, 0.07, 0.04, 1), ("circ", cx - w / 2.0, cy, h * 0.12), ("circ", cx + w / 2.0, cy, h * 0.12)]
        for i in range(8):
            a = t * 0.8 + i * math.pi / 4
            f += [("c", 1, 0.95, 0.6, 0.9), ("circ", cx + math.cos(a) * U * 0.55, cy + math.sin(a) * U * 0.32, U * 0.018)]
    return f


