_AMA, _AZU, _ROJ, _VER, _BLA = (0.99, 0.82, 0.09), (0.0, 0.20, 0.60), (0.80, 0.10, 0.15), (0.0, 0.52, 0.25), (1.0, 1.0, 1.0)
BANDERAS_FRANJAS = {
    "bol": ("h", [(_ROJ, 1), ((0.98, 0.84, 0.10), 1), (_VER, 1)]),
    "col": ("h", [(_AMA, 2), (_AZU, 1), (_ROJ, 1)]),
    "ecu": ("h", [(_AMA, 2), (_AZU, 1), (_ROJ, 1)]),
    "par": ("h", [(_ROJ, 1), (_BLA, 1), (_AZU, 1)]),
    "per": ("v", [(_ROJ, 1), (_BLA, 1), (_ROJ, 1)]),
    "ven": ("h", [(_AMA, 1), (_AZU, 1), (_ROJ, 1)]),
}
BANDERA_DE_PAIS = {"Argentina": "arg", "Bolivia": "bol", "Brasil": "bra", "Chile": "chi", "Colombia": "col",
                   "Ecuador": "ecu", "Paraguay": "par", "Perú": "per", "Uruguay": "uru", "Venezuela": "ven"}


class Bandera(Widget):
    """Banderita dibujada de un país (código: arg, bol, bra, chi, col, ecu, par, per, uru, ven)."""
    def __init__(self, codigo, ancho=34, **kwargs):
        super().__init__(size_hint=(None, None), size=(dp(ancho), dp(ancho * 0.66)), **kwargs)
        self.codigo = codigo
        self.bind(pos=self._dibujar, size=self._dibujar)
        self._dibujar()

    def _dibujar(self, *_):
        if self.width <= 0 or self.height <= 0:
            return
        f = []
        _bandera(f, self.codigo, 0, 0, self.width, self.height)
        pintar_figuras(self, f)


def _bandera(f, tipo, x, y, w, h):
    if tipo == "arg":
        f += [("c", 0.46, 0.70, 0.88, 1), ("rect", x, y, w, h), ("c", 1, 1, 1, 1), ("rect", x, y + h / 3.0, w, h / 3.0),
              ("c", 0.96, 0.75, 0.20, 1), ("circ", x + w / 2.0, y + h / 2.0, h * 0.11)]
    elif tipo == "chi":
        f += [("c", 1, 1, 1, 1), ("rect", x, y + h / 2.0, w, h / 2.0), ("c", 0.85, 0.16, 0.18, 1), ("rect", x, y, w, h / 2.0),
              ("c", 0.0, 0.22, 0.60, 1), ("rect", x, y + h / 2.0, w * 0.33, h / 2.0),
              ("c", 1, 1, 1, 1), ("circ", x + w * 0.165, y + h * 0.75, h * 0.09)]
    elif tipo in BANDERAS_FRANJAS:
        direccion, colores = BANDERAS_FRANJAS[tipo]
        n = sum(p for _c, p in colores)
        acum = 0.0
        for color, partes in colores:
            if direccion == "h":   # franjas horizontales, de arriba hacia abajo
                alto = h * partes / n
                f += [("c",) + color + (1,), ("rect", x, y + h - acum - alto, w, alto)]
            else:                  # franjas verticales, de izquierda a derecha
                ancho = w * partes / n
                f += [("c",) + color + (1,), ("rect", x + acum, y, ancho, h)]
            acum += alto if direccion == "h" else ancho
    elif tipo == "bra":
        f += [("c", 0.0, 0.60, 0.22, 1), ("rect", x, y, w, h), ("c", 1.0, 0.85, 0.0, 1),
              ("quad", [x + w / 2.0, y + h * 0.92, x + w * 0.92, y + h / 2.0, x + w / 2.0, y + h * 0.08, x + w * 0.08, y + h / 2.0]),
              ("c", 0.0, 0.15, 0.55, 1), ("circ", x + w / 2.0, y + h / 2.0, h * 0.26)]
    else:
        f += [("c", 1, 1, 1, 1), ("rect", x, y, w, h)]
        for i in range(4):
            f += [("c", 0.05, 0.25, 0.60, 1), ("rect", x, y + h - (2 * i + 2) * h / 9.0, w, h / 9.0)]
        f += [("c", 1, 1, 1, 1), ("rect", x, y + h * 5 / 9.0, w * 0.40, h * 4 / 9.0), ("c", 0.96, 0.75, 0.20, 1),
              ("circ", x + w * 0.20, y + h * 7 / 9.0, h * 0.11)]
    f += [("c", 0.2, 0.15, 0.08, 1), ("line", [x, y, x + w, y, x + w, y + h, x, y + h, x, y], 1.5)]


def escena_presentacion(n, ancho, alto, t):
    """Dibujo de cada diapositiva de la presentación de la Gira (sin imágenes)."""
    f = [("c", 0.10, 0.07, 0.04, 1), ("rect", 0, 0, ancho, alto)]
    U = min(ancho, alto)
    if n == 0:  # mapa que se va conquistando
        k = int(t * 0.9) % 7
        demo = {"regiones": {"arg.%s" % r["id"]: GIRA_VICTORIAS_REGION for r in GIRA_PAISES[0]["regiones"][:k]}}
        f += escena_mapa_gira(ancho, alto, GIRA_PAISES[0], demo)[0]
    elif n == 1:  # cuadro de 16 equipos
        colw = ancho * 0.88 / 5.0
        activo = int(t * 1.4) % 6
        centros = {}
        for col in range(5):
            cantidad = 16 >> col
            for i in range(cantidad):
                yc = alto * 0.10 + (i + 0.5) * (alto * 0.80 / cantidad)
                x = ancho * 0.06 + col * colw
                w, h = colw * 0.74, min(alto * 0.80 / cantidad * 0.68, 24)
                oro = (i == 0 and col <= activo)
                f += [("c", 0.95, 0.76, 0.20, 1) if oro else ("c", 0.32, 0.25, 0.18, 1), ("rect", x, yc - h / 2.0, w, h)]
                centros[(col, i)] = (x, w, yc)
        for col in range(4):
            for k in range(16 >> (col + 1)):
                xa, wa, ya = centros[(col, 2 * k)]
                _, _, yb = centros[(col, 2 * k + 1)]
                xn, _, yn = centros[(col + 1, k)]
                xm = xa + wa + (xn - xa - wa) / 2.0
                oro = (k == 0 and col < activo)
                f += [("c", 0.95, 0.76, 0.20, 1) if oro else ("c", 0.55, 0.45, 0.30, 1),
                      ("line", [xa + wa, ya, xm, ya, xm, yb, xa + wa, yb], 1.4), ("line", [xm, yn, xn, yn], 1.4)]
    elif n == 2:  # copa de la región
        f += escena_campeon(1.4 + t * 0.4, ancho, alto, False)[2:]
    elif n == 3:  # candado y monedas
        cx, cy = ancho / 2.0, alto * 0.52
        for i in range(10):
            a = t * 1.1 + i * 2 * math.pi / 10
            rx, ry = cx + math.cos(a) * U * 0.34, cy + math.sin(a) * U * 0.22
            f += [("c", 0.62, 0.42, 0.06, 1), ("circ", rx, ry, U * 0.055), ("c", 0.98, 0.80, 0.22, 1), ("circ", rx, ry, U * 0.045)]
        abre = (math.sin(t * 2.0) + 1) / 2.0
        f += [("c", 0.85, 0.85, 0.88, 1),
              ("line", [cx - U * 0.09, cy + U * 0.02, cx - U * 0.09, cy + U * (0.12 + 0.05 * abre), cx - U * 0.04, cy + U * (0.17 + 0.05 * abre),
                        cx + U * 0.04, cy + U * (0.17 + 0.05 * abre), cx + U * 0.09, cy + U * (0.12 + 0.05 * abre), cx + U * 0.09, cy + U * 0.02], 5),
              ("c", 0.93, 0.74, 0.20, 1), ("rect", cx - U * 0.15, cy - U * 0.15, U * 0.30, U * 0.18),
              ("c", 0.35, 0.22, 0.05, 1), ("circ", cx, cy - U * 0.07, U * 0.03), ("rect", cx - U * 0.008, cy - U * 0.14, U * 0.016, U * 0.07)]
    else:  # banderas de los países
        for i, tipo in enumerate(("arg", "chi", "uru")):
            w, h = ancho * 0.62, alto * 0.17
            x = (ancho - w) / 2.0
            y = alto * (0.64 - 0.24 * i) + math.sin(t * 2 + i) * 4
            _bandera(f, tipo, x, y, w, h)
    return f


def duracion_audio(ruta):
    """Duración en segundos de un WAV (exacta) o MP3 (estimada por el bitrate); 0 si no se sabe."""
    try:
        if ruta.lower().endswith(".wav"):
            with wave.open(ruta, "rb") as w:
                return w.getnframes() / float(w.getframerate())
        if ruta.lower().endswith(".mp3"):
            tam = os.path.getsize(ruta)
            with open(ruta, "rb") as f:
                cab = f.read(65536)
            ini = 0
            if cab[:3] == b"ID3" and len(cab) >= 10:
                ini = 10 + ((cab[6] & 127) << 21 | (cab[7] & 127) << 14 | (cab[8] & 127) << 7 | (cab[9] & 127))
                with open(ruta, "rb") as f:
                    f.seek(ini)
                    cab = f.read(65536)
            for i in range(len(cab) - 4):
                if cab[i] == 0xFF and (cab[i + 1] & 0xE0) == 0xE0:
                    version = (cab[i + 1] >> 3) & 3
                    capa = (cab[i + 1] >> 1) & 3
                    idx = (cab[i + 2] >> 4) & 15
                    if version == 1 or capa != 1 or idx in (0, 15):
                        continue
                    tabla = ([0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320] if version == 3
                             else [0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160])
                    return max(0, tam - ini) * 8.0 / (tabla[idx] * 1000.0)
    except Exception:
        pass
    return 0.0


def generar_efecto(ruta, tipo, tasa=22050):
    """Sintetiza 'gana' (aplausos + cornetas de fiesta) o 'pierde' (trompetas tristes) como WAV."""
    dur = {"gana": 3.8, "reparto": 2.4}.get(tipo, 3.0)
    n = int(dur * tasa)
    datos = [0.0] * n

    def nota(frec, ini, largo, amp, armonicos, vib=0.004, baja=0.0, cola=0.15):
        i0, i1 = int(ini * tasa), min(n, int((ini + largo + cola) * tasa))
        for i in range(i0, i1):
            tt = (i - i0) / tasa
            if tt < 0.04: env = tt / 0.04
            elif tt < largo: env = 1.0 - 0.2 * (tt / largo)
            else: env = max(0.0, 0.8 * (1 - (tt - largo) / cola))
            f = frec * (1 - baja * min(1.0, tt / largo)) * (1 + vib * math.sin(2 * math.pi * 5.5 * tt))
            v = sum(a * math.sin(2 * math.pi * f * h * tt) for h, a in armonicos)
            datos[i] += amp * env * v

    TROMPETA = ((1, 1.0), (2, 0.55), (3, 0.35), (4, 0.2), (5, 0.1))
    if tipo == "gana":
        for frec, ini, largo in ((523.25, 0.0, 0.14), (659.25, 0.16, 0.14), (783.99, 0.32, 0.14), (1046.5, 0.5, 0.6)):
            nota(frec, ini, largo, 0.06, TROMPETA)
        # cornetas de fiesta: ráfagas con subida de tono
        for ini in (0.25, 0.95, 1.7):
            for i in range(int(ini * tasa), min(n, int((ini + 0.45) * tasa))):
                tt = (i / tasa) - ini
                f = 520 + 380 * min(1.0, tt / 0.12) - 40 * tt
                env = min(1.0, tt / 0.02) * max(0.0, 1 - (tt / 0.45) ** 3)
                v = sum((1.0 / h) * math.sin(2 * math.pi * f * h * tt) for h in range(1, 7))
                datos[i] += 0.05 * env * v
        rnd = random.Random(4)
        suave, gan = 0.0, 0.0
        for i in range(int(0.1 * tasa), n):
            tt = i / tasa
            if i % 650 == 0: gan = rnd.uniform(0.25, 1.0)
            env = min(1.0, (tt - 0.1) / 0.5) * max(0.0, min(1.0, (dur - tt) / 0.9))
            suave += 0.55 * (rnd.uniform(-1, 1) - suave)
            pico = rnd.uniform(-1, 1) if rnd.random() < 0.012 else 0.0
            datos[i] += 0.2 * env * gan * (suave + pico)
    elif tipo == "reparto":
        # 6 cartas, una cada 0,30 s (igual que la animación): un "flap" de papel al salir del mazo y un golpecito al caer.
        rnd = random.Random(21)
        for j in range(6):
            ini = 0.15 + j * 0.30
            fuerza = rnd.uniform(0.75, 1.0)
            i0, suave = int(ini * tasa), 0.0
            for i in range(i0, min(n, i0 + int(0.22 * tasa))):
                tt = (i - i0) / tasa
                env = min(1.0, tt / 0.010) * math.exp(-tt * 20.0)
                r = rnd.uniform(-1, 1)
                suave += 0.30 * (r - suave)
                datos[i] += 0.60 * fuerza * env * (r - suave)       # ruido pasa-altos: el "thwip"
            i1 = int((ini + 0.42) * tasa)
            for i in range(i1, min(n, i1 + int(0.07 * tasa))):
                tt = (i - i1) / tasa
                env = math.exp(-tt * 60.0)
                datos[i] += 0.30 * fuerza * env * (math.sin(2 * math.pi * 150 * tt) + 0.5 * rnd.uniform(-1, 1))
    else:
        for frec, ini, largo, baja in ((466.16, 0.0, 0.45, 0.0), (440.0, 0.5, 0.45, 0.0),
                                       (415.3, 1.0, 0.45, 0.0), (392.0, 1.5, 1.3, 0.07)):
            nota(frec, ini, largo, 0.09, ((1, 1.0), (2, 0.6), (3, 0.4), (4, 0.18)), vib=0.012 if baja else 0.006,
                 baja=baja, cola=0.25)
    pico = max(abs(x) for x in datos) or 1.0
    datos = [x * (0.85 / pico) for x in datos]
    with wave.open(ruta, "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(tasa)
        w.writeframes(b"".join(struct.pack("<h", int(max(-1.0, min(1.0, x)) * 32000)) for x in datos))


def ruta_efecto(nombre, tipo):
    """audio/<nombre>.* si existe; si no, un efecto generado ('gana' o 'pierde') guardado en WAV."""
    propio = buscar_audio(nombre)
    if propio:
        return propio
    for carpeta in (os.path.dirname(os.path.abspath(__file__)), tempfile.gettempdir()):
        ruta = os.path.join(carpeta, "truco_efecto_%s.wav" % tipo)
        try:
            if not os.path.isfile(ruta) or os.path.getsize(ruta) < 1000:
                generar_efecto(ruta, tipo)
            return ruta
        except OSError:
            continue
    return None


def ruta_fanfarria():
    """Audio de celebración: audio/campeon.* si existe; si no, una fanfarria generada."""
    for nombre in ("campeon", "campeón", "celebracion"):
        propio = buscar_audio(nombre)
        if propio:
            return propio
    for carpeta in (os.path.dirname(os.path.abspath(__file__)), tempfile.gettempdir()):
        ruta = os.path.join(carpeta, "truco_campeon.wav")
        try:
            if not os.path.isfile(ruta) or os.path.getsize(ruta) < 1000:
                generar_fanfarria(ruta)
            return ruta
        except OSError:
            continue
    return None


