def desafio_clave_voucher(ch):
    """Clave del voucher que da ganarle a este rival: 'hotel_<region>' o 'viaje_<region>'."""
    return ("hotel_" if ch["tipo"] == "hotel" else "viaje_") + ch["region"]


def desafio_ganado(datos, ch):
    """True si le ganaste a ese rival del Desafío: por su contador de victorias o, en partidas viejas, porque tenés su voucher
    sin haberlo comprado (los vouchers comprados con monedas no cuentan)."""
    if int((datos.get("desafios") or {}).get(ch["id"], 0)) > 0:
        return True
    if desafio_clave_voucher(ch) in (datos.get("compradas") or {}):
        return False
    return gira_tiene_voucher(datos, "hotel" if ch["tipo"] == "hotel" else "viaje", ch["region"])


def gira_tiene_postal(datos, pais, postal):
    """Las postales de región se tienen al conquistar esa región; las del camino, al conseguirlas en un encuentro."""
    if postal.get("region"):
        reg = next((r for r in pais["regiones"] if r["id"] == postal["region"]), None)
        return bool(reg) and gira_region_conquistada(datos, pais, reg)
    return postal["id"] in (datos.get("postales") or {})


def gira_viaje_pendiente(datos, pais, conquistadas):
    """Hay un encuentro en el camino cuando ya conquistaste alguna región y todavía no tuviste el de esa conquista."""
    return pais.get("id") == "arg" and conquistadas >= 1 and int((datos.get("viaje") or {}).get("hechos", 0)) < conquistadas


def gira_tiene_tarjeta_mafia(datos):
    """True si ya ganaste la aprobación de la Familia (la tarjeta se puede usar más adelante para lo que se decida)."""
    return bool((datos.get("mafia") or {}).get("aprobado"))


def gira_mafia_pendiente(datos, pais):
    """El campeón del año pasado te para cuando ya conquistaste Buenos Aires, todavía no la Patagonia y no tenés su tarjeta."""
    if pais.get("id") != "arg" or gira_tiene_tarjeta_mafia(datos):
        return False
    est = [e for _r, e, _v in gira_estados(datos, pais)]
    return len(est) > 1 and est[0] == "conquistada" and est[1] != "conquistada"


def gira_tiene_voucher(datos, tipo, rid):
    """tipo: 'hotel' o 'viaje'. Los vouchers viejos (un solo voucher por región) valen para los dos."""
    vouchers = datos.get("vouchers") or {}
    return (tipo + "_" + rid) in vouchers or rid in vouchers


