def ruleta_disponible(datos):
    """True si todavía no giraste hoy."""
    return (datos.get("ruleta") or {}).get("fecha") != diario_fecha(0)


def ruleta_poderes_libres(datos, nivel):
    """Poderes de esa sección (débil, medio, poderoso) que todavía no tenés sin usar."""
    return [p for p in PODERES if p.get("nivel") == nivel and not poder_sin_gastar(datos, p)]


def ruleta_sortear(datos):
    """Índice del casillero que sale. Un casillero de poder solo puede salir si todavía hay un poder de esa sección que no tengas."""
    indices, pesos = [], []
    for i, (tipo, valor, _etiqueta, _color, peso) in enumerate(RULETA_PREMIOS):
        if tipo == "poder" and not ruleta_poderes_libres(datos, valor):
            continue
        indices.append(i)
        pesos.append(peso)
    return random.choices(indices, weights=pesos)[0]


def diario_fecha(desfase_dias=0):
    """Fecha local 'AAAA-MM-DD' (hoy, o hoy + desfase_dias)."""
    return time.strftime("%Y-%m-%d", time.localtime(time.time() + 86400 * desfase_dias))


def diario_rival():
    """El rival del día (cambia cada día; es el mismo para todos los jugadores)."""
    nombre, frase = DIARIO_RIVALES[time.localtime().tm_yday % len(DIARIO_RIVALES)]
    return {"id": "truco_dia", "tipo": "diario", "region": "buenos_aires", "nombre": nombre, "perfil": "Implacable",
            "lugar": "Mesa del café", "frase": frase}


def diario_racha_vigente(d):
    """Días seguidos ganados que siguen vivos (si ayer o hoy ganaste; si no, la racha se cortó)."""
    return int(d.get("racha", 0)) if d.get("ultima") in (diario_fecha(0), diario_fecha(-1)) else 0

