def gira_tiene_lentes(datos):
    """True si ya le ganaste al Científico y todavía tenés sus lentes sin gastar (se usan UNA sola vez, en un Desafío)."""
    c = datos.get("cientifico") or {}
    return bool(c.get("lentes")) and not c.get("usado")


def gira_aprendio_lentes(datos):
    """True si alguna vez le ganaste al Científico (aunque ya hayas gastado los lentes): no te vuelve a frenar."""
    return bool((datos.get("cientifico") or {}).get("lentes"))


def gira_cientifico_pendiente(datos, pais):
    """El Científico te frena (entre Cuyo y Mesopotamia) cuando ya conquistaste Cuyo, todavía no Mesopotamia y no tenés sus lentes."""
    if pais.get("id") != "arg" or gira_aprendio_lentes(datos):
        return False
    est = [e for _r, e, _v in gira_estados(datos, pais)]
    return len(est) > 3 and est[2] == "conquistada" and est[3] != "conquistada"


def gira_tiene_poder_mago(datos):
    """True si ya le ganaste al Mago Eliseo y todavía tenés su poder sin gastar (se usa UNA sola vez en toda la Gira)."""
