def gira_aprendio_poder_mago(datos):
    """True si alguna vez le ganaste al mago (aunque ya hayas gastado el poder): el mago no te vuelve a frenar."""
    return bool((datos.get("mago") or {}).get("poder"))


def gira_mago_pendiente(datos, pais):
    """El mago te frena (entre la Patagonia y Cuyo) cuando ya conquistaste la Patagonia, todavía no Cuyo y no tenés su poder.
    El campeón de la Familia sigue donde estaba: entre Buenos Aires y la Patagonia."""
    if pais.get("id") != "arg" or gira_aprendio_poder_mago(datos):
        return False
    est = [e for _r, e, _v in gira_estados(datos, pais)]
    return len(est) > 2 and est[1] == "conquistada" and est[2] != "conquistada"


