NIVELES_PODER = (("debil", "DÉBIL", (0.45, 0.85, 0.55)),
                 ("medio", "MEDIO", (0.96, 0.78, 0.15)),
                 ("poderoso", "PODEROSO", (0.95, 0.45, 0.40)))


OFERTA_DESCUENTO = 50   # % de descuento de la oferta del día


def _hoy_argentina():
    """Número de día (ordinal) en Argentina, UTC-3: igual que el servidor, sin importar la zona horaria del celular."""
    import datetime
    return datetime.datetime.fromtimestamp(time.time() - 3 * 3600, datetime.timezone.utc).date().toordinal()


def oferta_poder_id():
    """Id del poder en oferta hoy. Se elige por la fecha de Argentina (igual para todos y para el servidor) y cambia a las 00:00."""
    return random.Random(_hoy_argentina()).choice(PODERES)["id"]


def oferta_segundos_restantes():
    """Segundos que faltan para que termine la oferta de hoy (medianoche de Argentina)."""
    return max(0, int(86400 - ((time.time() - 3 * 3600) % 86400)))


def oferta_texto_tiempo():
    s = oferta_segundos_restantes()
    return "%dh %02dmin" % (s // 3600, (s % 3600) // 60)


def oferta_2x1_id():
    """Id del poder en 2x1 hoy (distinto al del descuento): comprás uno y te regalan un poder débil al azar."""
    hoy = _hoy_argentina()
    otros = [p for p in PODERES if p["id"] != oferta_poder_id()]
    return random.Random(hoy * 7919 + 1).choice(otros)["id"]


def poder_en_oferta(p):
    return p["id"] == oferta_poder_id()


def poder_en_2x1(p):
    return p["id"] == oferta_2x1_id()


def poder_regalo_2x1(datos, comprado):
    """Poder débil que se regala con el 2x1 (al azar entre los que no tenés sin usar), o None si ya tenés todos."""
    libres = [q for q in PODERES if q.get("nivel") == "debil" and q["id"] != comprado["id"] and not poder_sin_gastar(datos, q)]
    return random.choice(libres) if libres else None


def precio_poder(p):
    """Precio actual del poder: con descuento si es la oferta del día."""
    if poder_en_oferta(p):
        return max(1, p["precio"] * (100 - OFERTA_DESCUENTO) // 100)
    return p["precio"]


def poder_sin_gastar(datos, p):
    """True si tenés ese poder y todavía no lo usaste."""
    d = datos.get(p["clave"]) or {}
    return bool(d.get(p["campo"])) and not d.get("usado")


def poder_gastado(datos, p):
    """True si alguna vez tuviste ese poder y ya lo gastaste (podés conseguir otro)."""
    d = datos.get(p["clave"]) or {}
    return bool(d.get(p["campo"])) and bool(d.get("usado"))


