def personaje_ficha(p):
    """Un personaje del día armado como los rivales del Desafío (sirve para jugar contra él y para su figurita)."""
    return {"id": "pers_" + p["id"], "pid": p["id"], "tipo": "personaje", "region": "buenos_aires", "nombre": p["nombre"],
            "perfil": p["perfil"], "lugar": p["titulo"], "frase": p["frase"], "gana": p["gana"], "pierde": p["pierde"],
            "look": p["look"], "premio": p["premio"]}


def figurita_conseguida(datos, d):
    """¿Ya tenés la figurita de ese rival? (Desafío: ganarle una vez; campeón: ganarle; personaje del día: ganarle una vez)."""
    if d["tipo"] == "mafia":
        return bool(int((datos.get("mafia") or {}).get("ganadas", 0)))
    if d["tipo"] == "personaje":
        return d["pid"] in datos["personaje"]["figuritas"]
    return desafio_ganado(datos, d)


def personaje_del_dia():
    """El personaje del día (cambia cada día; es el mismo para todos los jugadores). Se arma como los rivales del Desafío."""
    return personaje_ficha(PERSONAJES_DIA[time.localtime().tm_yday % len(PERSONAJES_DIA)])


def premio_texto(premio):
    """'+50 puntos para el ranking online' o 'un poder débil al azar'."""
    tipo, valor = premio
    return "+%d puntos para el ranking online" % valor if tipo == "puntos" else "un poder %s al azar" % NIVEL_PODER_TXT[valor]


