def semana_clave():
    """Semana de hoy como 'AAAA-Wss' (la semana va de lunes a domingo)."""
    import datetime as _dt
    f = time.localtime()
    anio, semana, _dia = _dt.date(f.tm_year, f.tm_mon, f.tm_mday).isocalendar()
    return "%d-W%02d" % (anio, semana)


def semanal_progreso(sem, s):
    """Cuánto llevás de ese desafío semanal."""
    return len(sem["personajes"]) if s["campo"] == "personajes" else int(sem.get(s["campo"], 0))


