def gira_recortar_banda(poli, lat_min, lat_max):
    """Recorta un polígono a la franja lat_min <= lat <= lat_max (Sutherland-Hodgman)."""
    def recortar(pts, dentro, cruce):
        salida = []
        for i in range(len(pts)):
            a, b = pts[i - 1], pts[i]
            da, db = dentro(a), dentro(b)
            if db:
                if not da:
                    salida.append(cruce(a, b))
                salida.append(b)
            elif da:
                salida.append(cruce(a, b))
        return salida

    def cruce_lat(lat):
        return lambda a, b: (a[0] + (b[0] - a[0]) * (lat - a[1]) / ((b[1] - a[1]) or 1e-9), lat)

    pts = recortar(list(poli), lambda p: p[1] >= lat_min, cruce_lat(lat_min))
    if pts:
        pts = recortar(pts, lambda p: p[1] <= lat_max, cruce_lat(lat_max))
    return pts


