def _regiones_por_bandas(contorno, bandas):
    regiones = []
    for rid, nombre, pt, lat_a, lat_b in bandas:
        poli = _banda(contorno, min(lat_a, lat_b), max(lat_a, lat_b))
        if not poli:
            continue
        cx = sum(p[0] for p in poli) / len(poli)
        cy = sum(p[1] for p in poli) / len(poli)
        regiones.append({"id": rid, "nombre": nombre, "pt": pt, "centro": (cx, cy), "poligonos": [poli]})
    return regiones


