def gira_clave(pais, region):
    return "%s.%s" % (pais["id"], region["id"])


def gira_victorias(datos, pais, region):
    return min(GIRA_VICTORIAS_REGION, int((datos.get("regiones") or {}).get(gira_clave(pais, region), 0)))


def gira_region_conquistada(datos, pais, region):
    return gira_victorias(datos, pais, region) >= GIRA_VICTORIAS_REGION


def gira_region_exige_apuesta(pais, region):
    """Desde la tercera región se alterna: con apuesta de 100 (3.ª, 5.ª...) y sin apuesta (4.ª, 6.ª...)."""
    i = pais["regiones"].index(region)
    return i >= GIRA_REGION_CON_APUESTA_DESDE and (i - GIRA_REGION_CON_APUESTA_DESDE) % 2 == 0


def gira_pais_completo(datos, pais):
    return all(gira_region_conquistada(datos, pais, r) for r in pais["regiones"])


def gira_pais_desbloqueado(datos, indice):
    return indice == 0 or gira_pais_completo(datos, GIRA_PAISES[indice - 1])


def gira_contadores(datos):
    """Contadores del jugador que miden requisitos y logros."""
    prog = datos.get("prog") or {}
    regs = datos.get("regiones") or {}
    conquistadas = [k for k, v in regs.items() if int(v or 0) >= GIRA_VICTORIAS_REGION]
    en_chile = int(datos.get("pais", 0) or 0) >= 1 or any(str(k).startswith("chi.") for k in conquistadas)
    cont = {"victorias": int(prog.get("victorias", 0)), "seguidas": int(prog.get("seguidas", 0)),
            "mejor": int(prog.get("mejor", 0)), "apuestas": int(prog.get("apuestas", 0)),
            "margen": int(prog.get("margen", 0)), "apuesta100": int(prog.get("apuesta100", 0)),
            "online": int(prog.get("online", 0)), "ia50": int(prog.get("ia50", 0)),
            "regiones": len(conquistadas), "chile": 1 if en_chile else 0}
    vouchers = datos.get("vouchers") or {}
    for rid in DESAFIO_REGIONES:   # con voucher, o si ya habías empezado a jugar esa región antes de existir el Desafío
        ya_jugada = any(str(k).startswith("arg." + rid) and int(v or 0) > 0 for k, v in regs.items())
        for _tipo in ("hotel", "viaje"):
            cont["voucher_%s_%s" % (_tipo, rid)] = 1 if (gira_tiene_voucher(datos, _tipo, rid) or ya_jugada) else 0
    return cont


def gira_progreso(datos, item, prefijo):
    """(actual, meta, cumplido) de un requisito o logro. Lo ya cumplido queda cumplido para siempre."""
    meta = item["meta"]
    if (prefijo + item["id"]) in (datos.get("hechas") or {}):
        return meta, meta, True
    actual = min(gira_contadores(datos).get(item["cuenta"], 0), meta)
    return actual, meta, actual >= meta


def gira_requisitos_region(datos, pais, region):
    """[(texto, actual, meta, cumplido)] de los requisitos extra de la región ([] si no tiene o es un progreso de prueba)."""
    if "prog" not in datos:
        return []
    salida = []
    for req in GIRA_REQUISITOS.get(gira_clave(pais, region), []):
        actual, meta, ok = gira_progreso(datos, req, "req.")
        salida.append((req["texto"], actual, meta, ok))
    return salida


def gira_faltan_vouchers(datos, pais, region):
    """True si la región pide vouchers del Desafío (colectivo y hotel) y todavía te falta alguno."""
    if pais["id"] != "arg" or region["id"] not in DESAFIO_REGIONES:
        return False
    cont = gira_contadores(datos)
    return not (cont.get("voucher_hotel_" + region["id"]) and cont.get("voucher_viaje_" + region["id"]))


def gira_ya_viajo(datos, pais, region):
    """True si el muñequito ya llegó a esa región (arrancó su torneo): si perdés, se queda ahí y no vuelve a Buenos Aires."""
    return gira_clave(pais, region) in (datos.get("viajadas") or {})


def gira_sin_estadia(datos, pais, region):
    """Ya estuviste en la región (perdiste y se usó el hotel) y todavía no conseguiste otro voucher de hotel para la revancha."""
    return (pais["id"] == "arg" and region["id"] in DESAFIO_REGIONES and gira_ya_viajo(datos, pais, region)
            and not gira_region_conquistada(datos, pais, region) and not gira_tiene_voucher(datos, "hotel", region["id"]))


def gira_gastar_hotel(datos, pais, region):
    """Perder (o abandonar) el torneo de una región usa el voucher de hotel: para la revancha hace falta otro. True si lo gastó."""
    rid = region["id"]
    if pais["id"] != "arg" or rid not in DESAFIO_REGIONES:
        return False
    v = datos.setdefault("vouchers", {})
    if ("hotel_" + rid) in v:
        del v["hotel_" + rid]
        return True
    if rid in v:   # voucher viejo (uno solo por región, valía para los dos): se queda el de viaje
        v["viaje_" + rid] = v.pop(rid)
        return True
    return False


def gira_requisitos_ok(datos, pais, region):
    """Misiones para desbloquear la región. Los vouchers (pasajes) no cuentan acá: traban el viaje, no el desbloqueo."""
    defs = GIRA_REQUISITOS.get(gira_clave(pais, region), [])
    return all(ok for (_t, _a, _m, ok), d in zip(gira_requisitos_region(datos, pais, region), defs)
               if not str(d["cuenta"]).startswith("voucher_"))


class TarjetaToque(ButtonBehavior, TarjetaFondo):
    """TarjetaFondo que se puede tocar."""


def gira_misiones_widget(region, previa, reqs, acciones=None, con_titulo=True, con_pie=True, previa_ok=True, accion_previa=None, pie_texto=None):
    """Lista cálida de misiones para el cartel 'Faltan misiones': una tarjeta de color por misión (verde = hecha, naranja = falta)."""
    VERDE, NARANJA = (0.35, 0.85, 0.45), (0.95, 0.55, 0.15)
    filas = []
    if previa:
        filas.append(("Ganar el campeonato de %s" % previa, previa_ok, "HECHO" if previa_ok else "0/1"))
    for texto, actual, meta, ok in reqs:
        filas.append((texto, ok, "HECHO" if ok else "%d/%d" % (actual, meta)))
    acciones = list(acciones or [])
    alto_fila, sep = dp(60), dp(6)
    caja = BoxLayout(orientation="vertical", size_hint_y=None, spacing=sep,
                     height=(dp(24) if con_titulo else 0) + (dp(30) if con_pie else 0) + len(filas) * (alto_fila + sep))
    titulo = Label(text="Para abrir [b]%s[/b]:" % region["nombre"].title(), markup=True, font_size="15sp",
                   color=(0.96, 0.78, 0.15, 1), size_hint_y=None, height=dp(24))
    if con_titulo:
        caja.add_widget(titulo)
    desfase = len(filas) - len(reqs)  # la fila del campeonato anterior no tiene acción
    for i, (texto, ok, chip) in enumerate(filas):
        col = VERDE if ok else NARANJA
        accion = acciones[i - desfase] if (not ok and 0 <= i - desfase < len(acciones)) else None
        if previa and i == 0 and not ok and accion_previa:
            accion = accion_previa   # la fila del campeonato de la región donde estás: toca y juega
        clase = TarjetaToque if accion else TarjetaFondo
        tarjeta = clase(color=col, demora=0.08 * i, orientation="horizontal", size_hint_y=None, height=alto_fila,
                        padding=[dp(12), dp(4), dp(8), dp(4)], spacing=dp(8))
        if accion:
            texto += "\n[size=11sp][color=f5c726]Tocá para jugar >[/color][/size]"
        et = Label(text=texto, markup=True, font_size="14sp", halign="left", valign="middle", color=(1.0, 0.95, 0.85, 1))
        et.bind(size=lambda w, sz: setattr(w, "text_size", (sz[0], sz[1])))
        tarjeta.add_widget(et)
        boton = BotonColor("JUGAR" if accion else chip, col, ancho=70, font_size="13sp")
        tarjeta.add_widget(boton)
        if accion:
            tarjeta.bind(on_release=lambda *_, f=accion: f())
            boton.bind(on_release=lambda *_, f=accion: f())
        caja.add_widget(tarjeta)
    pie = Label(text=pie_texto or "Valen las partidas individuales y online (no las de torneo).", font_size="12sp", halign="center",
                valign="middle", color=(0.95, 0.85, 0.65, 1), size_hint_y=None, height=dp(30))
    pie.bind(size=lambda w, sz: setattr(w, "text_size", (sz[0], sz[1])))
    if con_pie:
        caja.add_widget(pie)
    return caja


def gira_estados(datos, pais):
    """[(region, estado, victorias)] con estado: 'conquistada', 'disponible' o 'bloqueada'."""
    salida = []
    anterior_ok = True
    for r in pais["regiones"]:
        v = gira_victorias(datos, pais, r)
        if v >= GIRA_VICTORIAS_REGION:
            est = "conquistada"
        elif anterior_ok and gira_requisitos_ok(datos, pais, r):
            est = "disponible"
        else:
            est = "bloqueada"
        salida.append((r, est, v))
        anterior_ok = anterior_ok and v >= GIRA_VICTORIAS_REGION
    return salida


def gira_aduana_estado(datos, pais, ahora=None):
    """Papel aduanero para entrar a un país: ('libre'|'aprobado'|'espera'|'pendiente', segundos que faltan)."""
    if pais["id"] not in GIRA_ADUANA:
        return "libre", 0
    ahora = time.time() if ahora is None else ahora
    prefijo = pais["id"] + "."
    if any(int(v or 0) > 0 for k, v in (datos.get("regiones") or {}).items() if str(k).startswith(prefijo)):
        return "aprobado", 0  # ya jugaba ahí antes de que existiera la aduana
    papel = (datos.get("aduana") or {}).get(pais["id"]) or {}
    if papel.get("ok"):
        return "aprobado", 0
    hasta = int(papel.get("hasta", 0) or 0)
    if hasta > 0:
        return ("aprobado", 0) if ahora >= hasta else ("espera", int(hasta - ahora))
    return "pendiente", 0


def gira_texto_tiempo(segundos):
    d, r = divmod(max(0, int(segundos)), 86400)
    h, r = divmod(r, 3600)
    m = r // 60
    if d:
        return "%d d %d h" % (d, h)
    if h:
        return "%d h %d min" % (h, m)
    return "%d min" % max(1, m)


def gira_proyectar(lon, lat, ancho, alto, pais, margen=0.0):
    """lon/lat -> pixeles del widget (origen abajo-izquierda), manteniendo proporciones."""
    k = math.cos(math.radians((pais["lat"][0] + pais["lat"][1]) / 2.0))
    mundo_w = (pais["lon"][1] - pais["lon"][0]) * k
    mundo_h = pais["lat"][1] - pais["lat"][0]
    escala = min(ancho / mundo_w, alto / mundo_h) * (1 - margen)
    ox = (ancho - mundo_w * escala) / 2.0
    oy = (alto - mundo_h * escala) / 2.0
    return (ox + (lon - pais["lon"][0]) * k * escala, oy + (lat - pais["lat"][0]) * escala)


def gira_triangular(poligono):
    """Triangula un polígono simple (corte de orejas). Devuelve lista de triángulos."""
    pts = list(poligono)
    area = sum(pts[i][0] * pts[(i + 1) % len(pts)][1] - pts[(i + 1) % len(pts)][0] * pts[i][1] for i in range(len(pts)))
    if area < 0:
        pts.reverse()

    def cruz(a, b, c):
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

    def dentro(p, a, b, c):
        return cruz(a, b, p) >= 0 and cruz(b, c, p) >= 0 and cruz(c, a, p) >= 0

    tris = []
    guardia = 0
    while len(pts) > 3 and guardia < 5000:
        guardia += 1
        for i in range(len(pts)):
            a, b, c = pts[i - 1], pts[i], pts[(i + 1) % len(pts)]
            if cruz(a, b, c) <= 0:
                continue
            if any(dentro(p, a, b, c) for p in pts if p not in (a, b, c)):
                continue
            tris.append((a, b, c))
            del pts[i]
            break
        else:
            break
    if len(pts) == 3:
        tris.append(tuple(pts))
    return tris


def gira_punto_en_poligono(x, y, poligono):
    dentro = False
    j = len(poligono) - 1
    for i in range(len(poligono)):
        xi, yi = poligono[i]
        xj, yj = poligono[j]
        if (yi > y) != (yj > y) and x < (xj - xi) * (y - yi) / ((yj - yi) or 1e-9) + xi:
            dentro = not dentro
        j = i
    return dentro


def escena_mapa_gira(ancho, alto, pais, datos):
    """Primitivas del mapa de un país de la Gira. Devuelve (figuras, etiquetas, poligonos_por_region).
    Lo dibuja Kivy en el juego y PIL en la vista previa."""
    f, etiquetas, polis = [], [], {}
    P = lambda lon, lat: gira_proyectar(lon, lat, ancho, alto, pais, 0.02)
    x0, y0 = P(pais["lon"][0], pais["lat"][0])
    x1, y1 = P(pais["lon"][1], pais["lat"][1])
    f += [("c", 0.13, 0.09, 0.05, 1), ("rect", 0, 0, ancho, alto),
          ("c", 0.66, 0.78, 0.74, 1), ("rect", x0, y0, x1 - x0, y1 - y0)]
    rnd = random.Random(2)
    for _ in range(int((x1 - x0) * (y1 - y0) / 700)):  # grano de pergamino
        f += [("c", 1, 1, 1, 0.10) if rnd.random() < 0.5 else ("c", 0.2, 0.15, 0.05, 0.07),
              ("rect", rnd.uniform(x0, x1 - 2), rnd.uniform(y0, y1 - 2), 2, 2)]
    for i in range(7):  # viñeta en los bordes de la hoja
        m = (7 - i) * 4
        f += [("c", 0.25, 0.20, 0.10, 0.045), ("rect", x0, y0, x1 - x0, m), ("rect", x0, y1 - m, x1 - x0, m),
              ("rect", x0, y0, m, y1 - y0), ("rect", x1 - m, y0, m, y1 - y0)]

    def borde(pts):
        # recorta a la hoja del mapa para que nada se salga del marco
        return [(min(max(x, x0), x1), min(max(y, y0), y1)) for x, y in pts]

    for poli in pais["vecinos"]:
        pix = borde([P(*p) for p in poli])
        for a, b, c in gira_triangular(pix):
            f += [("c", 0.91, 0.87, 0.76, 1), ("tri", [a[0], a[1], b[0], b[1], c[0], c[1]])]
    for reg, estado, vic in gira_estados(datos, pais):
        relleno = {"conquistada": (0.45, 0.63, 0.25), "disponible": (0.90, 0.80, 0.38), "bloqueada": (0.96, 0.93, 0.84)}[estado]
        polis[reg["id"]] = []
        for poli in reg["poligonos"]:
            pix = [P(*p) for p in poli]
            polis[reg["id"]].append(pix)
            for a, b, c in gira_triangular(pix):
                f += [("c", relleno[0], relleno[1], relleno[2], 1), ("tri", [a[0], a[1], b[0], b[1], c[0], c[1]])]
            pts = [v for p in pix for v in p]
            f += [("c", 0.30, 0.20, 0.10, 1), ("line", pts + pts[:2], 1.8)]
        cx, cy = P(*reg["centro"])
        etiquetas.append((cx, cy, reg["nombre"], "nombre"))
        if estado == "bloqueada":
            f += [("c", 0.18, 0.18, 0.20, 0.92), ("circ", cx, cy + 26, 14),
                  ("c", 0.85, 0.85, 0.88, 1), ("rect", cx - 6, cy + 19, 12, 9),
                  ("line", [cx - 4, cy + 28, cx - 4, cy + 33, cx + 4, cy + 33, cx + 4, cy + 28], 1.6)]
            etiquetas.append((cx, cy - 24, "Bloqueada", "bloqueada"))
        elif estado == "disponible":
            etiquetas.append((cx, cy - 24, "JUGAR · APUESTA" if gira_region_exige_apuesta(pais, reg) else "JUGAR", "jugar"))
        else:
            etiquetas.append((cx, cy - 24, "CONQUISTADA", "conquistada"))
    # rosa de los vientos
    rx, ry, rr = x1 - 36, y0 + 44, 24
    f += [("c", 0.30, 0.20, 0.10, 0.9)]
    for k in range(32):
        a0, a1 = 2 * math.pi * k / 32, 2 * math.pi * (k + 1) / 32
        f += [("line", [rx + math.cos(a0) * rr, ry + math.sin(a0) * rr, rx + math.cos(a1) * rr, ry + math.sin(a1) * rr], 1.2)]
    f += [("quad", [rx, ry + rr * 1.15, rx + rr * 0.18, ry, rx, ry - rr * 1.15, rx - rr * 0.18, ry]),
          ("quad", [rx - rr * 1.15, ry, rx, ry + rr * 0.18, rx + rr * 1.15, ry, rx, ry - rr * 0.18])]
    etiquetas.append((rx, ry + rr + 10, "N", "norte"))
    f += [("c", 0.80, 0.62, 0.30, 1), ("line", [x0, y0, x1, y0, x1, y1, x0, y1, x0, y0], 2.5)]
    return f, etiquetas, polis


