class TrucoApp(App):

    def probar_voz(self, genero):
        """Suena una frase de la voz elegida (carpeta de audios Hombre o Mujer) para escucharla al registrarte."""
        ruta = os.path.join(CARPETA_AUDIOS, genero, "Truco.mp3")
        if not self.audio_permitido() or not os.path.isfile(ruta):
            return
        self.musica_menu_pausar()                 # se corta la música del menú mientras escuchás la voz
        try:
            previo = getattr(self, "sonido_prueba", None)
            if previo is not None:
                previo.stop()
                previo.unload()
            self.sonido_prueba = SoundLoader.load(ruta)
            if self.sonido_prueba is not None:
                self.sonido_prueba.play()
        except Exception as error:
            print("Error voz de prueba:", error)

    def configurar_audios(self):
        genero = (getattr(self, "perfil_usuario", None) or {}).get("genero")
        propia = os.path.join(CARPETA_AUDIOS, genero) if genero in ("Hombre", "Mujer") else ""
        if propia and os.path.isdir(propia):
            self.carpeta_yo = propia                                   # mi voz: la que elegí en el perfil
            self.voz_ia = "Mujer" if genero == "Hombre" else "Hombre"  # el rival suena distinto a mí
        else:                                                          # perfil viejo sin voz elegida
            self.carpeta_yo = os.path.join(CARPETA_AUDIOS, "Yo")
            self.voz_ia = random.choice(["Hombre", "Mujer"])
        self.carpeta_ia = os.path.join(CARPETA_AUDIOS, self.voz_ia)
        self.sonido_actual = None

    def reproducir_audio(self, quien, nombre):
        carpeta = self.carpeta_yo if quien == "yo" else self.carpeta_ia
        ruta = os.path.join(carpeta, nombre + ".mp3")

        if not self.audio_permitido() or not os.path.isfile(ruta): return
        self.musica_menu_pausar()

        try:
            if self.sonido_actual is not None:
                self.sonido_actual.stop()
                self.sonido_actual.unload()
                self.sonido_actual = None

            sonido = SoundLoader.load(ruta)
            if sonido is None: return
            self.sonido_actual = sonido
            sonido.play()
        except Exception as error:
            print("Error audio:", error)

    def audio_canto_envido(self, quien, nivel):
        """Reproduce el canto que corresponde al nivel: 4 falta, 3 real, 2 re-envido, 1 envido."""
        carpeta = self.carpeta_yo if quien == "yo" else self.carpeta_ia
        candidatos = {4: ["Falta envido"], 3: ["Real envido"],
                      2: ["Re-envido", "Envido"]}.get(nivel, ["Envido"])
        for nombre in candidatos:
            if os.path.isfile(os.path.join(carpeta, nombre + ".mp3")):
                self.reproducir_audio(quien, nombre)
                return
        self.reproducir_audio(quien, "Envido")

    def audio_canto_truco(self, valor, quien):
        archivo = "Truco" if valor == 2 else "Quiero retruco" if valor == 3 else "Quiero vale cuatro"
        self.reproducir_audio(quien, archivo)

    # --- Menú inicial y campeonato de 32 participantes ---
    def nombre_equipo(self, nombre):
        return self.equipo_usuario if nombre == "VOS" else nombre

    def ruta_perfil(self):
        nombre = "perfil_truco.json"
        try:
            from kivy.utils import platform
            if platform == "android":
                # La carpeta del código se borra al instalar una versión nueva del APK;
                # user_data_dir se conserva, así el perfil y el progreso no se pierden.
                carpeta = self.user_data_dir
                os.makedirs(carpeta, exist_ok=True)
                return os.path.join(carpeta, nombre)
        except Exception:
            pass
        return os.path.join(os.path.dirname(os.path.abspath(__file__)), nombre)

    def cargar_perfil(self):
        try:
            with open(self.ruta_perfil(), "r", encoding="utf-8") as archivo:
                perfil = json.load(archivo)
            nombre = str(perfil.get("nombre", "")).strip()
            apellido = str(perfil.get("apellido", "")).strip()
            club = perfil.get("club", "Boca Juniors")
            if nombre and apellido and club in CLUBES_ARGENTINOS:
                self.perfil_usuario = {"nombre": nombre, "apellido": apellido, "club": club,
                                       "genero": perfil.get("genero") if perfil.get("genero") in ("Hombre", "Mujer") else "",
                                       "id": str(perfil.get("id", "")).strip(),
                                       "token": str(perfil.get("token", "")).strip(),
                                       "pendientes": [p for p in perfil.get("pendientes", [])
                                                      if isinstance(p, dict) and p.get("ticket") and p.get("evento")],
                                       "gira": self.gira_normalizar(perfil.get("gira")),
                                       "copa": self.copa_normalizar(perfil.get("copa")),
                                       "ia_memoria": perfil.get("ia_memoria") if isinstance(perfil.get("ia_memoria"), dict) else {},
                                       "silenciado": bool(perfil.get("silenciado", False))}
                self.silenciado = self.perfil_usuario["silenciado"]
                self.equipo_usuario = club
                return True
        except (OSError, ValueError, TypeError):
            pass
        self.perfil_usuario = None
        self.equipo_usuario = "Boca Juniors"
        return False

    def persistir_perfil(self):
        try:
            with open(self.ruta_perfil(), "w", encoding="utf-8") as archivo:
                json.dump(self.perfil_usuario, archivo, ensure_ascii=False, indent=2)
        except OSError as error:
            print("No se pudo guardar el perfil:", error)
            return False
        return True

    def guardar_perfil(self, nombre, apellido, club, genero=None):
        previo = getattr(self, "perfil_usuario", None) or {}
        if genero not in ("Hombre", "Mujer"):
            genero = previo.get("genero", "")          # si no se eligió, queda el que ya tenía
        perfil = {"nombre": nombre.strip(), "apellido": apellido.strip(), "club": club, "genero": genero,
                  "id": previo.get("id", ""), "token": previo.get("token", ""),
                  "pendientes": list(previo.get("pendientes", [])),
                  "gira": self.gira_normalizar(previo.get("gira")),
                  "copa": self.copa_normalizar(previo.get("copa")),
                  "ia_memoria": dict(previo.get("ia_memoria") or {}),
                  "silenciado": bool(previo.get("silenciado", getattr(self, "silenciado", False)))}
        anterior = getattr(self, "perfil_usuario", None)
        self.perfil_usuario = perfil
        if not self.persistir_perfil():
            self.perfil_usuario = anterior
            return False
        self.equipo_usuario = club
        self.sincronizar_perfil_servidor()
        return True

    # ---------------- Cuenta y monedas (el saldo vive en el servidor) ----------------
    def api(self, ruta, datos=None, metodo="POST", ok=None, fallo=None):
        """Llamada HTTP al servidor en un hilo; los callbacks vuelven al hilo de Kivy."""
        def trabajo():
            try:
                cuerpo = json.dumps(datos).encode("utf-8") if datos is not None else None
                req = urllib.request.Request(HTTP_BASE + ruta, data=cuerpo, method=metodo,
                                             headers={"Content-Type": "application/json"})
                with urllib.request.urlopen(req, timeout=75) as resp:
                    respuesta = json.loads(resp.read().decode("utf-8"))
            except urllib.error.HTTPError as error:
                try: detalle = json.loads(error.read().decode("utf-8")).get("error", str(error))
                except Exception: detalle = str(error)
                if fallo:
                    Clock.schedule_once(lambda _dt, d=detalle, c=error.code: fallo(d, c), 0)
                return
            except Exception as error:
                self.ultimo_error_red = (type(error).__name__ + ": " + str(error))[:140]
                if fallo:
                    Clock.schedule_once(lambda _dt, d=str(error): fallo(d, None), 0)
                return
            if ok:
                Clock.schedule_once(lambda _dt: ok(self.gira_ajustar_estado(ruta, respuesta)), 0)
        threading.Thread(target=trabajo, daemon=True).start()

    def gira_conciliar_puntos(self, r):
        """La fama (puntos de gira de este celular) y el ranking online tienen que ser el mismo número. Si no queda nada por
        informar al servidor y el servidor tiene otro total, el del servidor manda: así Mi carrera, tu puesto y el Top 10 coinciden
        (corrige diferencias viejas, por ejemplo puntos que se descontaron acá antes de que el servidor supiera informarlos)."""
        try:
            if not (r.get("registrado") and self.tiene_cuenta()):
                return False
            datos = self.gira_datos()
            if not datos.get("sync") or any(datos.get(k) for k in ("pend", "pend_logros", "pend_diario", "pend_periodico", "pend_desafio")):
                return False   # todavía hay cosas sin informar: el total del servidor está desactualizado
            servidor = max(0, int(r["puntos"]))
            if servidor == int(datos["puntos"]):
                return False
            datos["puntos"] = servidor
            self.gira_guardar()
            return True
        except (TypeError, ValueError, KeyError, AttributeError):
            return False

    def gira_ajustar_estado(self, ruta, r):
        """Tus puntos del ranking online = los del servidor menos los descuentos de Desafío que el servidor todavía no registró,
        así el puntaje es el mismo en el menú de la Gira, el Top 10 y los logros."""
        if str(ruta).startswith("/gira/mi_estado") and isinstance(r, dict) and "puntos" in r:
            self.gira_conciliar_puntos(r)
            try:
                pend = sum(int(p.get("puntos", 0)) for p in self.gira_datos().get("pend_desafio", []))
                if pend:
                    r = dict(r, puntos=max(0, int(r["puntos"]) - pend))
            except (TypeError, ValueError, AttributeError):
                pass
        return r

    # ---------------- Actualizaciones de la app ----------------
    def revisar_actualizacion(self):
        """Pregunta al servidor la última versión: avisa si hay una nueva o si esta ya no puede jugar online."""
        if getattr(self, "_version_revisada", False) or getattr(self, "_version_revisando", False):
            return
        self._version_revisando = True

        def ok(r):
            self._version_revisando = False
            try:
                ultima, minima = int(r.get("ultima", 0)), int(r.get("minima", 0))
            except (TypeError, ValueError, AttributeError):
                return
            self._version_revisada = True
            url = str(r.get("url") or "")
            novedades = str(r.get("novedades") or "").replace("[", "(").replace("]", ")")[:300]
            if minima > VERSION_APP:
                self.cartel_actualizar(url, novedades, obligatoria=True)
            elif ultima > VERSION_APP:
                self.cartel_actualizar(url, novedades, obligatoria=False)

        def fallo(*_):
            self._version_revisando = False  # sin conexión: se reintenta la próxima vez que se abra el menú
        self.api("/version", None, metodo="GET", ok=ok, fallo=fallo)

    def abrir_enlace(self, url):
        if not str(url).startswith(("https://", "http://")):
            return
        try:
            webbrowser.open(url)
        except Exception:
            try:
                from jnius import autoclass
                Intent = autoclass("android.content.Intent")
                Uri = autoclass("android.net.Uri")
                actividad = autoclass("org.kivy.android.PythonActivity").mActivity
                actividad.startActivity(Intent(Intent.ACTION_VIEW, Uri.parse(url)))
            except Exception as error:
                print("No se pudo abrir el enlace:", error)

    def cartel_actualizar(self, url, novedades, obligatoria):
        if getattr(self, "_popup_actualizar", None) is not None:
            return
        contenido = MesaBox(orientation="vertical", padding=dp(12), spacing=dp(8))
        titulo = "Tenés que actualizar para seguir jugando online" if obligatoria else "¡Hay una versión nueva del juego!"
        texto = "[b]%s[/b]\nTu versión: %s" % (titulo, VERSION_TEXTO)
        if novedades:
            texto += "\n\n" + novedades
        if not url:
            texto += "\n\nPedí el enlace de la versión nueva a quien te pasó el juego."
        etiqueta = Label(text=texto, markup=True, font_size="15sp", halign="center", valign="middle")
        etiqueta.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        contenido.add_widget(etiqueta)
        popup = Popup(title="Actualización", content=contenido, auto_dismiss=False,
                      size_hint=(0.9, None), height=dp(330 if novedades else 260))
        self._popup_actualizar = popup

        def cerrar(*_):
            popup.dismiss()
            self._popup_actualizar = None
        if url:
            b = boton_oscuro("ACTUALIZAR", "16sp")
            b.size_hint_y = None
            b.height = dp(48)
            b.bind(on_release=lambda *_: self.abrir_enlace(url))
            contenido.add_widget(b)
        if not obligatoria:
            m = boton_oscuro("MÁS TARDE", "14sp")
            m.size_hint_y = None
            m.height = dp(44)
            m.bind(on_release=cerrar)
            contenido.add_widget(m)
        popup.open()

    def tiene_cuenta(self):
        perfil = getattr(self, "perfil_usuario", None) or {}
        return bool(perfil.get("id") and perfil.get("token"))

    def texto_saldo(self):
        saldo = getattr(self, "saldo", None)
        perfil = getattr(self, "perfil_usuario", None) or {}
        texto = f"Monedas: {saldo if saldo is not None else '—'}"
        if perfil.get("id"):
            texto += f"   ·   ID: {perfil['id']}"
        aviso = getattr(self, "aviso_cuenta", "")
        return texto + ("\n" + aviso if aviso else "")

    def texto_saldo_corto(self):
        saldo = getattr(self, "saldo", None)
        return "[b]%s[/b]" % (saldo if saldo is not None else "—")

    def refrescar_label_saldo(self):
        etiqueta = getattr(self, "lbl_saldo", None)
        if etiqueta is not None:
            etiqueta.text = self.texto_saldo()
        corta = getattr(self, "lbl_saldo_menu", None)
        if corta is not None:
            corta.text = self.texto_saldo_corto()

    def apuesta_desde_texto(self, texto):
        try:
            return int(str(texto).split()[0])
        except (ValueError, IndexError):
            return 0

    def refrescar_selector_apuesta(self):
        selector = getattr(self, "sel_apuesta", None)
        if selector is None:
            return
        saldo = getattr(self, "saldo", None) or 0
        valores = ["Sin apuesta"] + [f"{v} monedas" for v in OPCIONES_APUESTA if v <= saldo]
        selector.values = valores
        actual = int(getattr(self, "apuesta_elegida", 0))
        texto = f"{actual} monedas" if f"{actual} monedas" in valores else "Sin apuesta"
        selector.text = texto
        self.apuesta_elegida = self.apuesta_desde_texto(texto)

    def fijar_saldo(self, monedas):
        try:
            self.saldo = int(monedas)
        except (TypeError, ValueError):
            return
        self.aviso_cuenta = ""
        self.cuenta_invalida = False
        self.refrescar_label_saldo()
        self.refrescar_selector_apuesta()

    def actualizar_saldo(self, *_):
        """Pide el saldo; si todavía no hay cuenta en el servidor, la crea."""
        perfil = getattr(self, "perfil_usuario", None)
        if not perfil:
            return
        self.reintentar_pendientes()
        if not self.tiene_cuenta():
            if getattr(self, "_registrando", False):
                return
            self._registrando = True
            # El token se genera y se guarda ANTES de registrar: si la respuesta se pierde y se
            # reintenta, el servidor devuelve la misma cuenta en vez de crear otra.
            if not perfil.get("token"):
                perfil["token"] = secrets.token_urlsafe(24)
                self.persistir_perfil()
            self.api("/register", {"name": self.online_nombre(), "token": perfil["token"], "club": perfil.get("club", "")},
                     ok=self._cuenta_creada, fallo=self._fallo_cuenta)
            return
        self.api("/wallet", {"id": perfil["id"], "token": perfil["token"]},
                 ok=lambda r: self.fijar_saldo(r.get("coins")), fallo=self._fallo_cuenta)

    def sincronizar_perfil_servidor(self):
        """Informa nombre y club al servidor: así tus amigos ven tu escudo y podés aparecer en la búsqueda."""
        perfil = getattr(self, "perfil_usuario", None) or {}
        if not self.tiene_cuenta() or not perfil.get("club"):
            return
        self.api("/cuenta/perfil", dict(self.amigos_credenciales(), nombre=self.online_nombre(), club=perfil["club"]),
                 ok=lambda r: None, fallo=lambda *a: None)

    def _cuenta_creada(self, resp):
        self._registrando = False
        self.perfil_usuario["id"] = str(resp.get("id", ""))
        self.perfil_usuario["token"] = str(resp.get("token", ""))
        self.persistir_perfil()
        self.fijar_saldo(resp.get("coins", 0))

    def _fallo_cuenta(self, mensaje, codigo=None):
        self._registrando = False
        if codigo == 401 and self.tiene_cuenta():
            # El servidor no reconoce la cuenta (por ejemplo, base reiniciada). NO se cambia el ID
            # en silencio: se conservan los datos y el jugador decide desde MI SALDO / ID.
            self.cuenta_invalida = True
            self.aviso_cuenta = "El servidor no reconoce tu cuenta. Tocá MI SALDO / ID."
            self.refrescar_label_saldo()
            return
        self.aviso_cuenta = "Sin conexión con el servidor (el saldo se actualiza al reintentar)."
        self.refrescar_label_saldo()

    def cerrar_aviso(self):
        popup = getattr(self, "online_popup_actual", None)
        if popup is not None:
            try: popup.dismiss()
            except Exception: pass

    def _cartel_online(self, titulo):
        """Fondo negro con borde dorado y título, igual que los carteles del juego."""
        fondo = CartelFondo(orientation="vertical", padding=[dp(18), dp(14)], spacing=dp(8))
        fondo.add_widget(Label(text=titulo, font_size="24sp", bold=True, color=(0.93, 0.74, 0.22, 1),
                               size_hint_y=None, height=dp(40)))
        fondo.add_widget(Adorno())
        return fondo

    def _popup_cartel(self, fondo, ancho=0.88, alto=None, alto_rel=0.4, auto_dismiss=False):
        datos = dict(title="", separator_height=0, background="", background_color=(0, 0, 0, 0),
                     content=fondo, auto_dismiss=auto_dismiss)
        if alto is None:
            datos["size_hint"] = (ancho, alto_rel)
        else:
            datos["size_hint"] = (ancho, None)
            datos["height"] = dp(alto)
        return Popup(**datos)

    # ---------------- Pantalla de carga al arrancar ----------------
    def on_start(self):
        Clock.schedule_once(self.arranque_cargar, 0.3)
        # Aviso de "hay una versión nueva" (consulta en segundo plano; si falla, el juego sigue igual)
        try:
            if AVISO_VERSION_GITHUB:
                from cartel_actualizacion import chequear_al_iniciar
                chequear_al_iniciar()
        except Exception as error:
            print("No se pudo chequear la versión:", error)

    def arranque_cargar(self, *_, reintento=False):
        """Cartel 'Cargando' que bloquea todo (es modal) hasta tener monedas, logros y ranking,
        o hasta saber que no hay conexión; en ese caso avisa qué cosas no se van a ver."""
        if not getattr(self, "perfil_usuario", None) or getattr(self, "_arranque_popup", None) is not None:
            return
        estado = {"cuenta": "esperando", "logros": "esperando", "podio": "esperando", "punto": 0,
                  "inicio": time.time(), "logros_pedido": False}
        if reintento:
            if getattr(self, "saldo", None) is None:
                self.aviso_cuenta = ""
                self.cuenta_invalida = False
            self.actualizar_saldo()
        fondo = self._cartel_online("Cargando")
        msg = Label(markup=True, font_size="15sp", halign="center", valign="middle", color=(0.93, 0.90, 0.85, 1))
        msg.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        fondo.add_widget(msg)
        popup = self._popup_cartel(fondo, alto=290)
        self._arranque_popup = popup

        def red_o_error(codigo):
            return "fallo" if codigo is None else "error"

        def podio_ok(r):
            estado["podio"] = "ok"
            self.podio_cache = r.get("podio", [])

        def podio_fallo(detalle="", codigo=None):
            estado["podio"] = red_o_error(codigo)
        self.api("/gira/podio?limite=10", None, metodo="GET", ok=podio_ok, fallo=podio_fallo)

        def pedir_logros():
            estado["logros_pedido"] = True
            perfil = self.perfil_usuario

            def ok(r):
                self.gira_estado_cache = r
                self.gira_estado_error = None
                estado["logros"] = "ok"

            def fallo(detalle="", codigo=None):
                self.gira_estado_error = (codigo, str(detalle)[:120])
                print("Arranque: fallo /gira/mi_estado ->", codigo, detalle)
                estado["logros"] = red_o_error(codigo)
            self.api("/gira/mi_estado", {"id": perfil["id"], "token": perfil["token"]}, ok=ok, fallo=fallo)

        def estado_cuenta():
            if getattr(self, "saldo", None) is not None:
                return "ok"
            if getattr(self, "cuenta_invalida", False):
                return "error"
            if getattr(self, "aviso_cuenta", ""):
                return "fallo"
            return "esperando"

        def marca(v, codigo=None):
            return {"ok": "[color=8fcc3f][b]listo[/b][/color]",
                    "fallo": "[color=ee8026][b]sin conexión[/b][/color]",
                    "error": "[color=ee8026][b]error del servidor%s[/b][/color]" % (
                        (" (%s)" % codigo) if codigo else "")}.get(v, "[color=b8b8b8]...[/color]")

        def pintar(puntos):
            msg.text = ("[b]Conectando con el servidor%s[/b]\n[size=12sp][color=c8c0b0]Si estaba dormido puede tardar un rato.[/color][/size]\n\n"
                        "Monedas y cuenta:  %s\nLogros y ranking:  %s\nPodio y Top 10:  %s") % (
                puntos, marca(estado["cuenta"]), marca(estado["logros"], (getattr(self, "gira_estado_error", None) or (None,))[0]),
                marca(estado["podio"]))
            if getattr(self, "ultimo_error_red", None):
                from kivy.utils import escape_markup
                msg.text += "\n\n[size=10sp][color=a09080]%s[/color][/size]" % escape_markup(self.ultimo_error_red)

        def terminar(vencio=False):
            ev.cancel()
            if getattr(self, "_arranque_popup", None) is popup:
                self._arranque_popup = None
            popup.dismiss()
            if vencio:
                for clave in ("cuenta", "logros", "podio"):
                    if estado[clave] in ("esperando",):
                        estado[clave] = "fallo"
            try:
                fila = getattr(self, "fila_gira_menu", None)
                if fila is not None:
                    fila.actualizar(self.gira_datos()["puntos"], self.gira_conquistadas(),
                                    getattr(self, "gira_estado_cache", None),
                                    error=getattr(self, "gira_estado_error", None))
            except Exception as error:
                print("No se pudo refrescar el menú:", error)
            self.sin_conexion = any(estado[k] == "fallo" for k in ("cuenta", "logros", "podio"))
            if self.sin_conexion:
                self.arranque_cartel_sin_conexion()

        def tick(_dt):
            estado["punto"] += 1
            estado["cuenta"] = estado_cuenta()
            if estado["cuenta"] == "ok" and not estado["logros_pedido"]:
                if self.tiene_cuenta():
                    self.sincronizar_perfil_servidor()
                    pedir_logros()
                else:
                    estado["logros"] = "error"
            elif estado["cuenta"] in ("fallo", "error") and estado["logros"] == "esperando":
                estado["logros"] = estado["cuenta"]
            pintar("." * (1 + estado["punto"] % 3))
            if all(estado[k] != "esperando" for k in ("cuenta", "logros", "podio")):
                if time.time() - estado["inicio"] >= ARRANQUE_ESPERA_MIN:
                    terminar()
            elif time.time() - estado["inicio"] > ARRANQUE_ESPERA_MAX:
                terminar(vencio=True)
        pintar(".")
        ev = Clock.schedule_interval(tick, 0.25)
        popup.open()

    def arranque_cartel_sin_conexion(self):
        self.mostrar_cartel(
            "AVISO", "Sin conexión", False,
            detalle=("No se pudo conectar con el servidor. Revisá tu internet.\n\n"
                     "Mientras no haya conexión no vas a ver tus monedas, tus logros en el ranking, "
                     "el podio ni el Top 10 online, y no se puede jugar online, con amigos ni por apuesta.\n\n"
                     "Podés seguir jugando contra la IA."),
            botones=[("REINTENTAR", lambda: self.arranque_cargar(reintento=True)), ("SEGUIR SIN CONEXIÓN", None)],
            alto=0.72, apilados=True)

    def preguntar_apuesta(self, titulo, continuar, maximo=None):
        """Antes de empezar: ¿sin apuesta o por cuántas monedas? Deja el monto en self.apuesta_elegida."""
        saldo = getattr(self, "saldo", None)
        saldo = saldo if (self.tiene_cuenta() and saldo is not None) else 0
        VERDE, DORADO, GRIS = (0.55, 0.80, 0.25), (0.96, 0.78, 0.15), (0.70, 0.67, 0.62)
        contenido = self._cartel_online(titulo)
        et = Label(text="[b]¿Jugás por apuesta?[/b]\n[size=13sp][color=f5c518]Tu saldo: %s[/color][/size]" % (
                       saldo if self.tiene_cuenta() else "—"),
                   markup=True, halign="center", valign="middle", font_size="17sp", size_hint_y=None, height=dp(56))
        et.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        contenido.add_widget(et)
        montos = [v for v in OPCIONES_APUESTA if v <= saldo and (maximo is None or v <= maximo)]
        alto = 28 + 40 + 18 + 56 + 8 * (3 + len(montos)) + 66 * (2 + len(montos)) + (30 if not montos else 0)
        popup = self._popup_cartel(contenido, alto=alto)

        def elegir(monto):
            popup.dismiss()
            self.apuesta_elegida = monto
            continuar()
        sin = boton_cartel("SIN APUESTA", VERDE, "16sp")
        sin.bind(on_release=lambda *_: elegir(0))
        contenido.add_widget(sin)
        for valor in montos:
            b = boton_cartel("APOSTAR %d" % valor, DORADO, "16sp")
            b.bind(on_release=lambda *_, v=valor: elegir(v))
            contenido.add_widget(b)
        if not montos:
            aviso = Label(text="[i]No tenés saldo para apostar todavía.[/i]", markup=True, font_size="12sp",
                          color=(0.93, 0.90, 0.85, 0.85), size_hint_y=None, height=dp(22))
            contenido.add_widget(aviso)
        cancelar = boton_cartel("CANCELAR", GRIS, "14sp", 52)
        cancelar.bind(on_release=popup.dismiss)
        contenido.add_widget(cancelar)
        popup.open()

    def preguntar_poderes(self, titulo, continuar):
        """Online: ¿con poderes o sin poderes? Valen solo si los dos dicen que sí. Deja la respuesta en self.online_poderes_pref."""
        VERDE, DORADO, GRIS = (0.55, 0.80, 0.25), (0.96, 0.78, 0.15), (0.70, 0.67, 0.62)
        contenido = self._cartel_online(titulo)
        et = Label(text="[b]¿Jugás con poderes?[/b]\n[size=12sp]Solo valen si los dos dicen que sí.\n"
                        "Online funcionan casi todos (no el Poder del mago, el baqueano ni los de la Gira).[/size]",
                   markup=True, halign="center", valign="middle", font_size="17sp", size_hint_y=None, height=dp(110))
        et.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        contenido.add_widget(et)
        popup = self._popup_cartel(contenido, alto=28 + 40 + 18 + 110 + 8 * 5 + 66 * 2 + 52)

        def elegir(si):
            popup.dismiss()
            self.online_poderes_pref = bool(si)
            continuar()
        con = boton_cartel("CON PODERES", DORADO, "16sp")
        con.bind(on_release=lambda *_: elegir(True))
        contenido.add_widget(con)
        sin = boton_cartel("SIN PODERES", VERDE, "16sp")
        sin.bind(on_release=lambda *_: elegir(False))
        contenido.add_widget(sin)
        cancelar = boton_cartel("CANCELAR", GRIS, "14sp", 52)
        cancelar.bind(on_release=popup.dismiss)
        contenido.add_widget(cancelar)
        popup.open()

    def abrir_apuesta(self, tipo, monto, siguiente):
        """Retiene la apuesta en el servidor y recién después arranca la partida."""
        if not self.tiene_cuenta() or (getattr(self, "saldo", None) or 0) < monto:
            self.online_aviso("No tenés saldo suficiente para esa apuesta.", "Apuesta")
            return
        if getattr(self, "_abriendo_apuesta", False):
            return
        self._abriendo_apuesta = True
        self.online_aviso("Reteniendo tu apuesta…\n(si el servidor estaba dormido puede tardar hasta un minuto)", "Apuesta")
        perfil = self.perfil_usuario

        def ok(resp):
            self._abriendo_apuesta = False
            self.cerrar_aviso()
            self.apuesta_ticket = resp.get("ticket")
            self.apuesta_tipo = tipo
            self.apuesta_monto = int(monto)
            self.fijar_saldo(resp.get("coins"))
            siguiente()

        def fallo(mensaje, _codigo=None):
            self._abriendo_apuesta = False
            self.online_aviso("No se pudo retener la apuesta: " + mensaje, "Apuesta")
        self.api("/apuesta/abrir", {"id": perfil["id"], "token": perfil["token"],
                                    "tipo": tipo, "bet": int(monto)}, ok=ok, fallo=fallo)

    def guardar_pendiente(self, ticket, evento):
        perfil = self.perfil_usuario
        perfil.setdefault("pendientes", []).append({"ticket": ticket, "evento": evento})
        self.persistir_perfil()

    def quitar_pendiente(self, ticket, evento):
        perfil = self.perfil_usuario
        perfil["pendientes"] = [p for p in perfil.get("pendientes", [])
                                if not (p.get("ticket") == ticket and p.get("evento") == evento)]
        self.persistir_perfil()

    def reintentar_pendientes(self):
        """Reenvía de a uno (en orden) los resultados que no pudieron informarse."""
        perfil = getattr(self, "perfil_usuario", None) or {}
        if not self.tiene_cuenta() or getattr(self, "_reintentando", False):
            return
        pendientes = perfil.get("pendientes", [])
        if pendientes:
            self._reintentando = True
            self._enviar_reclamo(pendientes[0]["ticket"], pendientes[0]["evento"], pendiente=True)

    def reclamar_apuesta(self, evento, silencioso=False):
        ticket = getattr(self, "apuesta_ticket", None)
        if not ticket or not self.tiene_cuenta():
            return
        if evento in ("perder", "final") or getattr(self, "apuesta_tipo", "") == "ia":
            self.apuesta_ticket = None  # el ticket queda cerrado con este resultado
        self._enviar_reclamo(ticket, evento, silencioso=silencioso)

    def _enviar_reclamo(self, ticket, evento, silencioso=False, pendiente=False):
        perfil = self.perfil_usuario
        datos = {"id": perfil["id"], "token": perfil["token"], "ticket": ticket, "evento": evento}

        def siguiente():
            if pendiente:
                self._reintentando = False
                self.reintentar_pendientes()

        def ok(resp):
            if pendiente:
                self.quitar_pendiente(ticket, evento)
            self.fijar_saldo(resp.get("coins"))
            pago = int(resp.get("pago", 0))
            callar = silencioso
            if evento in ("clasificar", "octavos", "cuartos", "semifinal", "final") and getattr(self, "modo_torneo", False):
                self.torneo_premio_acum = int(getattr(self, "torneo_premio_acum", 0)) + pago
            if evento == "final" and getattr(self, "celebracion_pendiente", False):
                self.celebracion_pendiente = False
                self.mostrar_animacion_campeon(premio=int(getattr(self, "torneo_premio_acum", 0)))
                callar = True  # el premio ya se ve en la celebración
            if not callar and evento != "perder":
                nombre = {"ganar": "¡Ganaste la apuesta!", "clasificar": "¡Clasificaste!", "octavos": "¡Ganaste octavos!",
                          "cuartos": "¡Ganaste cuartos!", "semifinal": "¡Ganaste la semifinal!",
                          "final": "¡CAMPEÓN!"}.get(evento, "Apuesta")
                self.online_aviso(f"{nombre} Cobrás {pago} monedas.\nSaldo: {getattr(self, 'saldo', '—')}", "Apuesta")
            elif not callar:
                self.online_aviso(f"Perdiste la apuesta.\nSaldo: {getattr(self, 'saldo', '—')}", "Apuesta")
            siguiente()

        def fallo(mensaje, codigo=None):
            rechazado = codigo in (400, 401, 404)  # el servidor lo rechazó: no se reintenta
            if rechazado:
                if pendiente:
                    self.quitar_pendiente(ticket, evento)
                elif not silencioso:
                    self.online_aviso("El servidor no aceptó el resultado: " + mensaje, "Apuesta")
            elif not pendiente:
                self.guardar_pendiente(ticket, evento)
                if not silencioso:
                    self.online_aviso("Sin conexión: tu resultado se enviará cuando vuelvas al menú con internet.", "Apuesta")
            if pendiente:
                if rechazado:
                    siguiente()
                else:
                    self._reintentando = False
        self.api("/apuesta/reclamar", datos, ok=ok, fallo=fallo)

    def mostrar_cuenta_monedas(self):
        panel = MesaBox(orientation="vertical", padding=dp(12), spacing=dp(8))
        etiqueta = Label(text="", halign="center", valign="middle")
        etiqueta.bind(size=lambda inst, size: setattr(inst, "text_size", size))
        panel.add_widget(etiqueta)

        def pintar():
            perfil = getattr(self, "perfil_usuario", None) or {}
            saldo = getattr(self, "saldo", None)
            etiqueta.text = (f"Saldo: {saldo if saldo is not None else '—'} monedas\n"
                             f"Tu ID: {perfil.get('id') or '(sin cuenta todavía)'}\n\n"
                             "Para recargar, pasale tu ID a quien administra el juego.")
        pintar()
        copiar = boton_oscuro("Copiar ID")
        actualizar = boton_oscuro("Actualizar saldo")
        cerrar = boton_oscuro("Cerrar")
        nueva = None
        if getattr(self, "cuenta_invalida", False):
            nueva = boton_oscuro("Crear cuenta nueva (pierde acceso al saldo anterior)", "12sp")
        for b in (copiar, actualizar, cerrar) + ((nueva,) if nueva else ()):
            b.size_hint_y = None
            b.height = dp(42)
            panel.add_widget(b)
        popup = Popup(title="Mis monedas", content=panel, size_hint=(0.9, 0.55))

        def copiar_id(*_):
            try: Clipboard.copy((getattr(self, "perfil_usuario", None) or {}).get("id", ""))
            except Exception: pass
        def refrescar(*_):
            self.actualizar_saldo()
            Clock.schedule_once(lambda _dt: pintar(), 2.5)
        def cuenta_nueva(*_):
            self.perfil_usuario["id"] = self.perfil_usuario["token"] = ""
            self.persistir_perfil()
            self.cuenta_invalida = False
            self.saldo = None
            self.aviso_cuenta = ""
            popup.dismiss()
            self.actualizar_saldo()
        if nueva:
            nueva.bind(on_release=cuenta_nueva)
        copiar.bind(on_release=copiar_id)
        actualizar.bind(on_release=refrescar)
        cerrar.bind(on_release=popup.dismiss)
        popup.open()

    def confirmar_apuesta(self, apuesta, al_aceptar):
        panel = MesaBox(orientation="vertical", padding=dp(12), spacing=dp(8))
        panel.add_widget(Label(text=f"Esta sala apuesta {apuesta} monedas.\nSi perdés o abandonás, las perdés.",
                               halign="center"))
        entrar = boton_oscuro(f"ENTRAR (apuesto {apuesta})")
        cancelar = boton_oscuro("Cancelar")
        for b in (entrar, cancelar):
            b.size_hint_y = None
            b.height = dp(44)
            panel.add_widget(b)
        popup = Popup(title="Confirmar apuesta", content=panel, size_hint=(0.88, 0.42), auto_dismiss=False)
        cancelar.bind(on_release=popup.dismiss)
        entrar.bind(on_release=lambda *_: (popup.dismiss(), al_aceptar()))
        popup.open()

    # ---------- música del menú principal ----------
    def reproducir_inicio(self, *_):
        """Arranca la música del menú (audio/inicio.*) en bucle y la mantiene viva."""
        self.musica_menu_pausada = False
        self._musica_fallos = 0
        if getattr(self, "_musica_vigia", None) is None:
            self._musica_vigia = Clock.schedule_interval(self._musica_menu_vigilar, 1.0)
        self._musica_menu_tocar()

    def _musica_menu_vigilar(self, _dt):
        """Si el sistema cortó la música y debería sonar, la vuelve a cargar."""
        try:
            self._musica_menu_tocar()
        except Exception as error:
            print("Error vigilando música:", error)

    def _musica_menu_tocar(self):
        if getattr(self, "musica_menu_pausada", False) or not self.audio_permitido():
            return
        if getattr(self, "_musica_fallos", 0) >= 5:
            return
        sonido = getattr(self, "sonido_inicio", None)
        if sonido is not None:
            try:
                if getattr(sonido, "state", "stop") == "play":
                    return
            except Exception:
                pass
            try: sonido.stop()
            except Exception: pass
            try: sonido.unload()
            except Exception: pass
            if sonido in _SONIDOS_VIVOS:
                _SONIDOS_VIVOS.remove(sonido)
            self.sonido_inicio = None
        ruta = buscar_audio("inicio")
        if not ruta:
            return
        try:
            sonido = SoundLoader.load(ruta)
            if sonido is None:
                self._musica_fallos = getattr(self, "_musica_fallos", 0) + 1
                print("No se pudo cargar la música del menú:", ruta)
                return
            sonido.loop = True  # música de fondo: no se corta al terminar
            self.sonido_inicio = sonido
            _SONIDOS_VIVOS.append(sonido)  # referencia fuerte: evita que el recolector lo corte
            sonido.play()
            self._musica_fallos = 0
        except Exception as error:
            self._musica_fallos = getattr(self, "_musica_fallos", 0) + 1
            print("Error música del menú:", error)

    def musica_menu_pausar(self):
        """Corta la música del menú (presentaciones, cantos, efectos). No suena hasta reanudarla."""
        if getattr(self, "musica_menu_pausada", False):
            return
        self.musica_menu_pausada = True
        sonido = getattr(self, "sonido_inicio", None)
        if sonido is not None:
            try: sonido.stop()
            except Exception: pass

    def musica_menu_reanudar(self, *_):
        """Vuelve a sonar la música al regresar a un menú."""
        if not getattr(self, "musica_menu_pausada", False):
            return
        self.musica_menu_pausada = False
        self._musica_fallos = 0
        Clock.schedule_once(lambda _dt: self._musica_menu_tocar(), 0.3)

    @staticmethod
    def _parar_si_suena(sonido):
        """stop() solo si realmente está sonando: en algunos backends frena el canal de música global."""
        try:
            if sonido is not None and getattr(sonido, "state", "stop") == "play":
                sonido.stop()
        except Exception:
            pass

    def build(self):
        self.title = "Truco Argentino"
        Clock.schedule_once(self.reproducir_inicio, 1.2)
        if not self.cargar_perfil():
            return self.build_registro()
        return self.build_menu()

    def build_registro(self, edicion=False):
        pantalla = MesaBox(orientation="vertical", padding=dp(18), spacing=dp(9))
        pantalla.add_widget(TituloTruco("MI PERFIL" if edicion else "TRUCO", 40 if edicion else 56, 66 if edicion else 80))
        pantalla.add_widget(Label(text="[i]%s[/i]" % ("Editá tus datos" if edicion else "¡Bienvenido! Completá tus datos para guardar tu cuenta"),
                                  markup=True, font_size="14sp", color=(0.96, 0.82, 0.40, 1), size_hint_y=None, height=dp(30)))
        perfil = getattr(self, "perfil_usuario", None) or {}
        nombre = TextInput(text=perfil.get("nombre", ""), hint_text="Nombre",
                           multiline=False, size_hint_y=None, height=dp(48), font_size="16sp")
        apellido = TextInput(text=perfil.get("apellido", ""), hint_text="Apellido",
                              multiline=False, size_hint_y=None, height=dp(48), font_size="16sp")
        pantalla.add_widget(nombre)
        pantalla.add_widget(apellido)
        pantalla.add_widget(Label(text="Tu club favorito", size_hint_y=None, height=dp(28)))
        club_inicial = perfil.get("club", getattr(self, "equipo_usuario", "Boca Juniors"))
        if club_inicial not in CLUBES_ARGENTINOS:
            club_inicial = "Boca Juniors"
        fila_club, club = selector_club(club_inicial, 50, "15sp")
        pantalla.add_widget(fila_club)
        # Voz propia: Hombre o Mujer. Al tocar se elige y suena una frase de esa voz.
        genero_elegido = {"v": perfil.get("genero", "")}
        fila_voz = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(46), spacing=dp(6))
        fila_voz.add_widget(Label(text="Mi voz:", size_hint_x=None, width=dp(72), font_size="14sp", color=(0.96, 0.82, 0.40, 1)))
        botones_voz = {}

        def pintar_voz():
            for g, b in botones_voz.items():
                b.background_color = (0.55, 0.42, 0.10, 1) if genero_elegido["v"] == g else COLOR_BOTON

        def elegir_voz(g, *_):
            genero_elegido["v"] = g
            pintar_voz()
            aviso.text = ""
            self.probar_voz(g)
        for g in ("Hombre", "Mujer"):
            b = boton_oscuro(g, "15sp")
            b.bind(on_release=lambda _b, g=g: elegir_voz(g))
            botones_voz[g] = b
            fila_voz.add_widget(b)
        pantalla.add_widget(fila_voz)
        aviso = Label(text="", size_hint_y=None, height=dp(35), color=(1,0.65,0.45,1))
        pantalla.add_widget(aviso)
        pintar_voz()
        guardar = ItemMenuColor("perfil", "Guardar perfil", "Tu nombre, tu club y tu voz quedan en tu cuenta.", (0.96, 0.78, 0.15), 0.05)
        def confirmar(*_):
            n, a = nombre.text.strip(), apellido.text.strip()
            if not n or not a:
                aviso.text = "Ingresá nombre y apellido."
                return
            if genero_elegido["v"] not in ("Hombre", "Mujer"):
                aviso.text = "Elegí tu voz: Hombre o Mujer."
                return
            if not self.guardar_perfil(n, a, club.text, genero_elegido["v"]):
                aviso.text = "No se pudo guardar. Revisá permisos de la carpeta."
                return
            self.cambiar_pantalla(self.build_menu())
        guardar.bind(on_release=confirmar)
        pantalla.add_widget(guardar)
        if edicion:
            volver = boton_oscuro("CANCELAR", "13sp")
            volver.size_hint_y = None
            volver.height = dp(42)
            volver.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_menu()))
            pantalla.add_widget(volver)
        return pantalla

