    # ---------- pantallas secundarias ----------
    def _pantalla_con_volver(self, titulo, volver, texto_volver="< Volver", titulo_truco=True, tam_truco=None):
        """Devuelve (scroll, contenido) con encabezado dorado y botón de volver."""
        contenido = MesaBox(orientation="vertical", padding=dp(16), spacing=dp(8), size_hint_y=None)
        contenido.bind(minimum_height=contenido.setter("height"))
        atras = boton_oscuro(texto_volver, "14sp")
        atras.size_hint_x = 0.4
        atras.bind(on_release=lambda *_: volver())
        encabezado = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(42), spacing=dp(8))
        encabezado.add_widget(atras)
        encabezado.add_widget(Widget())
        encabezado.add_widget(self.nuevo_boton_sonido(40))
        contenido.add_widget(encabezado)
        if titulo_truco:   # mismo título con relieve que el menú principal
            titulo = str(titulo).upper()
            if tam_truco is None:   # el tamaño se ajusta al largo para que entre en el ancho de la pantalla
                tam = max(24, min(52, int(300 / (0.7 * max(1, len(titulo))))))
                tam_truco = (tam, max(52, int(tam * 1.55)))
            contenido.add_widget(TituloTruco(titulo, tam_truco[0], tam_truco[1]))
        else:
            contenido.add_widget(Label(text=titulo, font_size="26sp", bold=True, color=(0.93, 0.74, 0.22, 1),
                                       size_hint_y=None, height=dp(52)))
        contenido.add_widget(Adorno())
        scroll = ScrollView(do_scroll_x=False, bar_width=dp(4))
        scroll.add_widget(contenido)
        return scroll, contenido

    # ---------------- Amigos ----------------
    def amigos_credenciales(self):
        perfil = getattr(self, "perfil_usuario", None) or {}
        return {"id": perfil.get("id", ""), "token": perfil.get("token", "")}

    def amigos_latido_iniciar(self):
        """Mientras la app está abierta, avisa al servidor cada tanto para figurar 'en línea'."""
        if getattr(self, "_amigos_latido_ev", None) is not None:
            return
        def guardar(r):
            try: self.chats_sin_leer = int(r.get("sin_leer", 0))
            except (TypeError, ValueError): pass
            self.invitaciones_recibidas = r.get("invitaciones") or []
            self.invitaciones_avisar()
        def latir(_dt):
            if self.tiene_cuenta():
                self.api("/amigos/latido", self.amigos_credenciales(), ok=guardar)
        self._amigos_latido_ev = Clock.schedule_interval(latir, AMIGOS_LATIDO_SEG)
        Clock.schedule_once(latir, 2)

    # ---------------- Invitaciones a jugar ----------------
    def invitaciones_avisar(self):
        """Si un amigo te invitó a jugar y no estás en una sala o partida, muestra el cartel."""
        if getattr(self, "online_ws", None) is not None or getattr(self, "modo_online", False):
            return
        if getattr(self, "_invitacion_popup", None) is not None:
            return
        vistas = self.__dict__.setdefault("_invitaciones_vistas", set())
        for inv in getattr(self, "invitaciones_recibidas", []):
            # Si ya tenés abierto el chat con quien invita, la tarjeta del chat ya tiene los botones.
            if inv.get("id") in vistas or inv.get("de") == getattr(self, "_chat_abierto", None):
                continue
            vistas.add(inv["id"])
            self.mostrar_invitacion(inv)
            break

    def mostrar_invitacion(self, inv):
        apuesta = int(inv.get("apuesta", 0) or 0)
        nombre = str(inv.get("nombre", "Un amigo")).replace("&", "&amp;").replace("[", "&bl;").replace("]", "&br;")
        contenido = MesaBox(orientation="vertical", padding=dp(12), spacing=dp(8))
        et = Label(text="[b]%s[/b] te invita a jugar al truco.\n%s" % (
                       nombre, ("Apuesta: %d monedas" % apuesta) if apuesta > 0 else "Sin apuesta"),
                   markup=True, halign="center", valign="middle")
        et.bind(size=lambda w, tam: setattr(w, "text_size", tam))
        contenido.add_widget(et)
        b_si = boton_oscuro("ACEPTAR", "15sp")
        b_no = boton_oscuro("RECHAZAR", "14sp")
        for b in (b_si, b_no):
            b.size_hint_y = None
            b.height = dp(44)
            contenido.add_widget(b)
        popup = Popup(title="Invitación a jugar", content=contenido, size_hint=(0.88, 0.45), auto_dismiss=False)
        self._invitacion_popup = popup

        def responder(aceptar):
            popup.dismiss()
            self._invitacion_popup = None
            self.invitacion_responder(inv["id"], aceptar, apuesta)
        b_si.bind(on_release=lambda *_: responder(True))
        b_no.bind(on_release=lambda *_: responder(False))

        def vencida(_dt):   # la invitación vence a los 90 s: el cartel se cierra solo
            if getattr(self, "_invitacion_popup", None) is popup:
                popup.dismiss()
                self._invitacion_popup = None
        Clock.schedule_once(vencida, 90)
        popup.open()

    def invitacion_responder(self, inv_id, aceptar, apuesta=0, despues=None):
        """Acepta o rechaza una invitación. Si acepta, entra a la sala con el flujo de siempre."""
        if aceptar:
            if getattr(self, "online_ws", None) is not None or getattr(self, "modo_online", False):
                self.online_aviso("Ya estás en una sala o en una partida.", "Invitación")
                return
            saldo = getattr(self, "saldo", None) or 0
            if apuesta > 0 and (not self.tiene_cuenta() or saldo < apuesta):
                self.online_aviso("Esa partida apuesta %d monedas y tu saldo es %s." % (apuesta, saldo), "Invitación")
                return
        def ok(r):
            if aceptar and r.get("sala"):
                self.online_unirse_con_codigo(str(r["sala"]))
            if despues:
                despues()
        def fallo(mensaje, codigo=None):
            self.online_aviso(mensaje if codigo else "No se pudo responder. Revisá tu internet.", "Invitación")
            if despues:
                despues()
        self.api("/chat/invitacion", dict(self.amigos_credenciales(), invitacion=inv_id, aceptar=bool(aceptar)),
                 ok=ok, fallo=fallo)

    def invitacion_enviar(self, inv, sala):
        """Ya creada la sala, avisa al amigo por el chat (queda como tarjeta de invitación)."""
        def fallo(mensaje, codigo=None):
            self.online_aviso("No se pudo avisar a %s por el chat: %s\n\nPasale este código: %s" % (
                inv["nombre"], mensaje if codigo else "sin conexión", sala), "Invitación")
        self.api("/chat/invitar", dict(self.amigos_credenciales(), otro=inv["id"], sala=sala), fallo=fallo)

    def build_amigos(self):
        pantalla, c = self._pantalla_con_volver("Amigos", lambda: self.cambiar_pantalla(self.build_menu()))

        def etiqueta(texto, tam="13sp", alto=30, color=(0.93, 0.90, 0.85, 1), negrita=False):
            et = Label(text=texto, font_size=tam, color=color, bold=negrita, halign="center", valign="middle",
                       markup=True, size_hint_y=None, height=dp(alto))
            et.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
            return et

        if not self.tiene_cuenta():
            c.add_widget(etiqueta("Todavía no tenés cuenta online.\nVolvé al menú, esperá unos segundos y entrá de nuevo.",
                                  alto=70))
            return pantalla

        cred = self.amigos_credenciales()
        mi_id = cred["id"]

        DORADO, VERDE = (0.96, 0.78, 0.15), (0.55, 0.80, 0.25)
        # --- tu ID ---
        tarjeta_id = TarjetaFondo(DORADO, 0.05, orientation="horizontal", size_hint_y=None, height=dp(72),
                                  padding=[dp(14), dp(8), dp(10), dp(8)], spacing=dp(8))
        col_id = BoxLayout(orientation="vertical")
        col_id.add_widget(_etiqueta_logro("[b]TU ID[/b]", "11sp", (0.96, 0.82, 0.40, 1), size_hint_y=None, height=dp(16)))
        col_id.add_widget(_etiqueta_logro("[b][size=24sp]%s[/size][/b]" % mi_id, "24sp", (0.98, 0.80, 0.22, 1)))
        tarjeta_id.add_widget(col_id)
        b_copiar = BotonColor("Copiar", DORADO, 86)
        tarjeta_id.add_widget(b_copiar)
        c.add_widget(tarjeta_id)
        c.add_widget(etiqueta("Pasale tu ID a tus amigos para que te agreguen.", "12sp", 24))
        b_buscar = ItemMenuColor("buscar", "Buscar jugador", "Por nombre, apellido y club.", (0.35, 0.80, 0.75), 0.1)
        b_buscar.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_buscar_amigos()))
        c.add_widget(b_buscar)

        # --- agregar por ID ---
        fila_add = TarjetaFondo(VERDE, 0.15, orientation="horizontal", size_hint_y=None, height=dp(62),
                                padding=[dp(10), dp(7), dp(8), dp(7)], spacing=dp(8))
        campo = TextInput(hint_text="ID de tu amigo", multiline=False, font_size="16sp", write_tab=False)
        b_add = BotonColor("Agregar", VERDE, 92)
        fila_add.add_widget(campo)
        fila_add.add_widget(b_add)
        c.add_widget(fila_add)
        estado = etiqueta("", "13sp", 36)
        c.add_widget(estado)

        lista = MesaBox(orientation="vertical", spacing=dp(6), size_hint_y=None)
        lista.bind(minimum_height=lista.setter("height"))
        c.add_widget(lista)

        def decir(texto, error=False):
            estado.text = texto
            estado.color = (1, 0.45, 0.40, 1) if error else (0.55, 0.90, 0.60, 1)

        def fallo_red(mensaje, codigo=None):
            decir(mensaje if codigo else "No se pudo conectar. Revisá tu internet.", True)

        primera = [True]   # solo la primera vez entran con fundido: los refrescos automáticos no parpadean
        orden = [0]

        def demora():
            if not primera[0]:
                return None
            orden[0] += 1
            return 0.25 + 0.07 * orden[0]

        def grupo(texto, color):
            lista.add_widget(etiqueta("[b]%s[/b]" % texto, "17sp", 36, (color[0], color[1], color[2], 1), True))

        def fila(nombre, en_linea, botones, tipo="amigo", estado_texto="", club=""):
            seguro = str(nombre).replace("&", "&amp;").replace("[", "&bl;").replace("]", "&br;")  # el nombre lo eligió otro jugador
            if not estado_texto:
                estado_texto = "en línea" if en_linea else "desconectado"
            if club:
                estado_texto = str(club).replace("&", "&amp;").replace("[", "&bl;").replace("]", "&br;") + "  ·  " + estado_texto
            lista.add_widget(TarjetaAmigo(nombre, seguro, estado_texto, tipo, en_linea, botones, demora(), club=club))

        def responder(otro, aceptar):
            self.api("/amigos/responder", dict(cred, otro=otro, aceptar=aceptar),
                     ok=lambda r: (decir("¡Listo! Ahora son amigos." if aceptar else "Solicitud rechazada."), refrescar()),
                     fallo=lambda m, c=None: (decir(m, True), refrescar()))

        def eliminar(otro, mensaje_ok):
            self.api("/amigos/eliminar", dict(cred, otro=otro),
                     ok=lambda r: (decir(mensaje_ok), refrescar()), fallo=fallo_red)

        def confirmar_eliminar(otro, nombre):
            def hacer():
                try: self.online_popup_actual.dismiss()
                except Exception: pass
                eliminar(otro, "Amigo eliminado.")
            self.online_aviso("¿Eliminar a %s de tus amigos?" % nombre, "Eliminar amigo", [("Eliminar", hacer)])

        def pintar(datos):
            if pantalla.parent is None:
                return
            lista.clear_widgets()
            orden[0] = 0
            NARANJA, TURQUESA, VIOLETA = (0.95, 0.60, 0.15), (0.35, 0.80, 0.75), (0.72, 0.58, 0.96)
            VERDE_, CORAL = (0.55, 0.80, 0.25), (0.93, 0.42, 0.40)
            amigos, recibidas, enviadas = datos.get("amigos", []), datos.get("recibidas", []), datos.get("enviadas", [])
            if recibidas:
                grupo("Solicitudes recibidas (%d)" % len(recibidas), NARANJA)
                for x in recibidas:
                    fila(x["nombre"], None, [("Aceptar", lambda i=x["id"]: responder(i, True), VERDE_),
                                              ("Rechazar", lambda i=x["id"]: responder(i, False), CORAL)],
                         "recibida", "quiere ser tu amigo", club=x.get("club", ""))
            conectados = sum(1 for x in amigos if x.get("en_linea"))
            grupo("Mis amigos (%d)%s" % (len(amigos), ("  ·  %d en línea" % conectados) if conectados else ""), TURQUESA)
            if not amigos:
                lista.add_widget(etiqueta("Todavía no tenés amigos agregados.\nPasales tu ID o agregá el de ellos arriba.", "13sp", 48,
                                          (0.85, 0.85, 0.85, 1)))
            for x in sorted(amigos, key=lambda a: not a.get("en_linea")):   # los que están en línea, primero
                n_sin = int(x.get("sin_leer", 0) or 0)
                fila(x["nombre"], bool(x.get("en_linea")),
                     [("Chat (%d)" % n_sin if n_sin else "Chat",
                       lambda i=x["id"], n=x["nombre"]: self.cambiar_pantalla(self.build_chat(i, n)), TURQUESA),
                      ("Eliminar", lambda i=x["id"], n=x["nombre"]: confirmar_eliminar(i, n), CORAL)],
                     club=x.get("club", ""))
            if enviadas:
                grupo("Solicitudes enviadas (%d)" % len(enviadas), VIOLETA)
                for x in enviadas:
                    fila(x["nombre"], None, [("Cancelar", lambda i=x["id"]: eliminar(i, "Solicitud cancelada."), CORAL)],
                         "enviada", "esperando respuesta", club=x.get("club", ""))
            primera[0] = False

        def refrescar(*_):
            self.api("/amigos/listar", cred, ok=pintar, fallo=fallo_red)

        def agregar(*_):
            otro = campo.text.strip().upper()
            if not otro:
                decir("Escribí el ID de tu amigo.", True)
                return
            def listo(r):
                campo.text = ""
                if r.get("estado") == "aceptada":
                    decir("¡Ya sos amigo de %s!" % r.get("nombre", ""))
                else:
                    decir("Solicitud enviada a %s." % r.get("nombre", ""))
                refrescar()
            self.api("/amigos/pedir", dict(cred, otro=otro), ok=listo, fallo=fallo_red)

        def copiar_id(*_):
            try: Clipboard.copy(mi_id)
            except Exception: pass
            decir("ID copiado.")

        b_add.bind(on_release=agregar)
        campo.bind(on_text_validate=agregar)
        b_copiar.bind(on_release=copiar_id)

        def auto(_dt):
            if pantalla.parent is None:   # salió de la pantalla: deja de consultar
                return False
            refrescar()
        Clock.schedule_once(refrescar, 0)
        Clock.schedule_interval(auto, AMIGOS_REFRESCO_SEG)
        return pantalla

    def build_buscar_amigos(self):
        """Amigos > Buscar jugador: por nombre, apellido y club; con botón para mandar la solicitud."""
        pantalla, c = self._pantalla_con_volver("Buscar jugador", lambda: self.cambiar_pantalla(self.build_amigos()),
                                                "< Amigos")
        TURQUESA, VERDE = (0.35, 0.80, 0.75), (0.55, 0.80, 0.25)
        CORAL = (0.93, 0.42, 0.40)

        def etiqueta(texto, tam="13sp", alto=30, color=(0.93, 0.90, 0.85, 1)):
            et = Label(text=texto, font_size=tam, color=color, halign="center", valign="middle", markup=True,
                       size_hint_y=None, height=dp(alto))
            et.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
            return et

        if not self.tiene_cuenta():
            c.add_widget(etiqueta("Todavía no tenés cuenta online.\nVolvé al menú, esperá unos segundos y entrá de nuevo.",
                                  alto=70))
            return pantalla
        cred = self.amigos_credenciales()
        tarjeta = TarjetaFondo(TURQUESA, 0.05, orientation="vertical", size_hint_y=None, height=dp(250),
                               padding=[dp(12), dp(12)], spacing=dp(8))
        estilo = dict(multiline=False, font_size="16sp", write_tab=False, size_hint_y=None, height=dp(44),
                      padding=[dp(10), dp(11)])
        campo_nombre = TextInput(hint_text="Nombre", **estilo)
        campo_apellido = TextInput(hint_text="Apellido", **estilo)
        fila_club, sel_club = selector_club("Cualquier club", 46, "15sp", ["Cualquier club"] + CLUBES_ARGENTINOS)
        b_buscar = boton_cartel("BUSCAR", VERDE, "16sp")
        for w in (campo_nombre, campo_apellido, fila_club, b_buscar):
            tarjeta.add_widget(w)
        c.add_widget(tarjeta)
        estado = etiqueta("Escribí al menos 2 letras del nombre o apellido, o elegí un club.", "12sp", 36)
        c.add_widget(estado)
        lista = MesaBox(orientation="vertical", spacing=dp(6), size_hint_y=None)
        lista.bind(minimum_height=lista.setter("height"))
        c.add_widget(lista)

        def decir(texto, error=False):
            estado.text = texto
            estado.color = (1, 0.45, 0.40, 1) if error else (0.55, 0.90, 0.60, 1)

        def fallo(mensaje, codigo=None):
            decir(mensaje if codigo else "No se pudo conectar. Revisá tu internet.", True)

        def seguro(t):
            return str(t).replace("&", "&amp;").replace("[", "&bl;").replace("]", "&br;")

        def pedir(otro):
            def listo(r):
                decir("¡Ya sos amigo de %s!" % seguro(r.get("nombre", "")) if r.get("estado") == "aceptada"
                      else "Solicitud enviada a %s." % seguro(r.get("nombre", "")))
                buscar(mantener_mensaje=True)
            self.api("/amigos/pedir", dict(cred, otro=otro), ok=listo, fallo=fallo)

        def aceptar(otro):
            self.api("/amigos/responder", dict(cred, otro=otro, aceptar=True),
                     ok=lambda r: (decir("¡Listo! Ahora son amigos."), buscar(mantener_mensaje=True)), fallo=fallo)

        def pintar(r, mantener_mensaje=False):
            if pantalla.parent is None:
                return
            lista.clear_widgets()
            resultados = r.get("resultados", [])
            if not resultados:
                decir("No encontramos a nadie con esos datos.\nProbá con menos letras o sin elegir club.", True)
                return
            if not mantener_mensaje:
                decir("%d jugador%s encontrado%s." % (len(resultados), "" if len(resultados) == 1 else "es",
                                                    "" if len(resultados) == 1 else "s"))
            for i, x in enumerate(resultados):
                rel = x.get("relacion", "")
                if rel == "amigo":
                    botones, texto = [], "ya son amigos"
                elif rel == "enviada":
                    botones, texto = [], "solicitud enviada"
                elif rel == "recibida":
                    botones, texto = [("Aceptar", lambda o=x["id"]: aceptar(o), VERDE)], "quiere ser tu amigo"
                else:
                    botones, texto = [("Agregar", lambda o=x["id"]: pedir(o), VERDE)], "jugador"
                club = x.get("club", "")
                if club:
                    texto = seguro(club) + "  ·  " + texto
                lista.add_widget(TarjetaAmigo(x["nombre"], seguro(x["nombre"]), texto, "resultado", None, botones,
                                              0.05 * i, club=club))

        def buscar(*_, mantener_mensaje=False):
            club = "" if sel_club.text == "Cualquier club" else sel_club.text
            nombre, apellido = campo_nombre.text.strip(), campo_apellido.text.strip()
            if not club and len(nombre) < 2 and len(apellido) < 2:
                decir("Escribí al menos 2 letras del nombre o apellido, o elegí un club.", True)
                return
            if not mantener_mensaje:
                decir("Buscando...")
            self.api("/amigos/buscar", dict(cred, nombre=nombre, apellido=apellido, club=club),
                     ok=lambda r: pintar(r, mantener_mensaje), fallo=fallo)

        b_buscar.bind(on_release=lambda *_: buscar())
        campo_nombre.bind(on_text_validate=lambda *_: buscar())
        campo_apellido.bind(on_text_validate=lambda *_: buscar())
        return pantalla

    def build_chat(self, otro, nombre):
        """Chat directo con un amigo. Busca mensajes nuevos cada CHAT_REFRESCO_SEG mientras está abierto."""
        cred = self.amigos_credenciales()
        self._chat_abierto = otro
        previo_teclado = Window.softinput_mode
        Window.softinput_mode = "resize"   # que el teclado no tape la caja de texto

        raiz = MesaBox(orientation="vertical", padding=dp(8), spacing=dp(6))

        def salir(*_):
            Window.softinput_mode = previo_teclado
            self._chat_abierto = None
            self.cambiar_pantalla(self.build_amigos())

        encabezado = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(46), spacing=dp(8))
        b_volver = boton_oscuro("< Amigos", "14sp")
        b_volver.size_hint_x = 0.30
        b_volver.bind(on_release=salir)
        b_invitar = boton_oscuro("Invitar", "14sp")
        b_invitar.size_hint_x = 0.26
        titulo = Label(text=str(nombre), font_size="20sp", bold=True, color=(0.93, 0.74, 0.22, 1),
                       halign="left", valign="middle", shorten=True, shorten_from="right")
        titulo.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        encabezado.add_widget(b_volver)
        encabezado.add_widget(titulo)
        encabezado.add_widget(b_invitar)
        raiz.add_widget(encabezado)

        scroll = ScrollView(do_scroll_x=False, bar_width=dp(4))
        contenido = BoxLayout(orientation="vertical", spacing=dp(6), size_hint_y=None, padding=[0, dp(4)])
        contenido.bind(minimum_height=contenido.setter("height"))
        scroll.add_widget(contenido)
        raiz.add_widget(scroll)

        fila_envio = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(48), spacing=dp(8))
        campo = TextInput(hint_text="Escribí un mensaje", multiline=False, font_size="16sp", write_tab=False)
        b_enviar = boton_oscuro("Enviar", "15sp")
        b_enviar.size_hint_x = 0.28
        fila_envio.add_widget(campo)
        fila_envio.add_widget(b_enviar)
        raiz.add_widget(fila_envio)

        estado = {"ultimo": 0, "pidiendo": False, "enviando": False, "vistos": set(), "cerrado": False}
        estados = {}     # id de invitación -> {"mio", "estado", "apuesta"} (lo informa el servidor)
        tarjetas = {}    # id de invitación -> widgets de su tarjeta en pantalla

        def escapar(texto):
            return str(texto).replace("&", "&amp;").replace("[", "&bl;").replace("]", "&br;")

        def burbuja(texto, mio, fecha=None, color_texto=None):
            hora = ""
            if fecha:
                try: hora = "\n[size=10sp][color=bbbbbb]%s[/color][/size]" % time.strftime("%H:%M", time.localtime(fecha))
                except Exception: hora = ""
            et = Label(text=escapar(texto) + (hora if not mio else hora.replace("bbbbbb", "5a4a2a")), markup=True,
                       font_size="15sp", halign="left", valign="middle", size_hint=(None, None),
                       color=color_texto or ((0.10, 0.07, 0.02, 1) if mio else (1, 1, 1, 1)))
            et.text_size = (Window.width * 0.70, None)
            def medir(w, ts):
                w.size = (min(ts[0], Window.width * 0.70) + dp(22), ts[1] + dp(14))
            et.bind(texture_size=medir)
            def fondo(w, *_):
                w.canvas.before.clear()
                with w.canvas.before:
                    Color(*((0.85, 0.66, 0.28, 0.95) if mio else (0, 0, 0, 0.45)))
                    RoundedRectangle(pos=w.pos, size=w.size, radius=[dp(12)])
            et.bind(pos=fondo, size=fondo)
            fila = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(44))
            if mio:
                fila.add_widget(Widget())
                fila.add_widget(et)
            else:
                fila.add_widget(et)
                fila.add_widget(Widget())
            et.bind(height=lambda w, h: setattr(fila, "height", h + dp(2)))
            return fila

        ETIQUETA_INV = {"aceptada": "Aceptada", "rechazada": "Rechazada",
                        "expirada": "Expirada", "cancelada": "Cancelada"}

        def tarjeta(inv_id, mio):
            caja = BoxLayout(orientation="vertical", size_hint=(None, None), width=Window.width * 0.74,
                             height=dp(86), padding=dp(10), spacing=dp(6))
            lbl = Label(markup=True, font_size="14sp", halign="left", valign="top", size_hint_y=None, height=dp(66))
            lbl.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
            botones = BoxLayout(orientation="horizontal", spacing=dp(8), size_hint_y=None, height=0)
            caja.add_widget(lbl)
            caja.add_widget(botones)
            def fondo(w, *_):
                w.canvas.before.clear()
                with w.canvas.before:
                    Color(0.12, 0.32, 0.18, 0.92)
                    RoundedRectangle(pos=w.pos, size=w.size, radius=[dp(12)])
                    Color(0.85, 0.66, 0.28, 1)
                    Line(rounded_rectangle=(w.x, w.y, w.width, w.height, dp(12)), width=1.1)
            caja.bind(pos=fondo, size=fondo)
            fila = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(90))
            if mio:
                fila.add_widget(Widget())
                fila.add_widget(caja)
            else:
                fila.add_widget(caja)
                fila.add_widget(Widget())
            tarjetas[inv_id] = {"caja": caja, "lbl": lbl, "botones": botones, "fila": fila,
                                "mio": mio, "con_botones": False}
            return fila

        def actualizar_tarjeta(inv_id):
            t = tarjetas[inv_id]
            e = estados.get(inv_id) or {"estado": "expirada", "apuesta": 0}   # el servidor ya no la recuerda
            ap = int(e.get("apuesta", 0) or 0)
            est = e.get("estado", "expirada")
            pendiente_mia = est == "pendiente" and not t["mio"]
            if est == "pendiente":
                linea = "Esperando respuesta…" if t["mio"] else "¿Querés jugar?"
            else:
                linea = ETIQUETA_INV.get(est, est)
            t["lbl"].text = "[b]%s[/b]\n%s\n%s" % ("Invitaste a jugar" if t["mio"] else "Te invitó a jugar",
                                                  ("Apuesta: %d monedas" % ap) if ap > 0 else "Sin apuesta", linea)
            if pendiente_mia and not t["con_botones"]:
                b_si = boton_oscuro("Aceptar", "14sp")
                b_no = boton_oscuro("Rechazar", "14sp")
                b_si.bind(on_release=lambda *_: self.invitacion_responder(inv_id, True, ap, lambda: leer(forzar=True)))
                b_no.bind(on_release=lambda *_: self.invitacion_responder(inv_id, False, ap, lambda: leer(forzar=True)))
                t["botones"].add_widget(b_si)
                t["botones"].add_widget(b_no)
                t["botones"].height = dp(40)
                t["caja"].height = dp(132)
                t["fila"].height = dp(136)
                t["con_botones"] = True
            elif not pendiente_mia and t["con_botones"]:
                t["botones"].clear_widgets()
                t["botones"].height = 0
                t["caja"].height = dp(86)
                t["fila"].height = dp(90)
                t["con_botones"] = False

        def agregar(mensajes):
            nuevos = False
            for m in mensajes:
                if m["id"] in estado["vistos"]:
                    continue
                estado["vistos"].add(m["id"])
                estado["ultimo"] = max(estado["ultimo"], m["id"])
                if str(m["texto"]).startswith("@@INV:"):
                    contenido.add_widget(tarjeta(str(m["texto"])[6:], bool(m.get("mio"))))
                else:
                    contenido.add_widget(burbuja(m["texto"], bool(m.get("mio")), m.get("fecha")))
                nuevos = True
            for inv_id in list(tarjetas):
                actualizar_tarjeta(inv_id)
            if nuevos:
                Clock.schedule_once(lambda _dt: setattr(scroll, "scroll_y", 0), 0.2)

        def leer(forzar=False):
            if estado["cerrado"] or raiz.parent is None:
                return
            if estado["pidiendo"] and not forzar:
                return
            estado["pidiendo"] = True
            def ok(r):
                estado["pidiendo"] = False
                if not estado["cerrado"]:
                    estados.clear()
                    estados.update(r.get("invitaciones") or {})
                    agregar(r.get("mensajes", []))
            def fallo(mensaje, codigo=None):
                estado["pidiendo"] = False
                if codigo == 400 and not estado["cerrado"]:   # ya no son amigos
                    estado["cerrado"] = True
                    contenido.add_widget(burbuja("Ya no podés chatear con esta persona.", False,
                                                 color_texto=(1, 0.75, 0.70, 1)))
            self.api("/chat/leer", dict(cred, otro=otro, desde=estado["ultimo"]), ok=ok, fallo=fallo)

        def enviar(*_):
            texto = campo.text.strip()
            if not texto or estado["enviando"] or estado["cerrado"]:
                return
            estado["enviando"] = True
            def ok(r):
                estado["enviando"] = False
                campo.text = ""
                leer(forzar=True)
            def fallo(mensaje, codigo=None):
                estado["enviando"] = False
                self.online_aviso(mensaje if codigo else "No se pudo enviar. Revisá tu internet.", "Chat")
            self.api("/chat/enviar", dict(cred, otro=otro, texto=texto), ok=ok, fallo=fallo)
            Clock.schedule_once(lambda _dt: setattr(campo, "focus", True), 0.1)

        def invitar(*_):
            if getattr(self, "online_ws", None) is not None or getattr(self, "modo_online", False):
                self.online_aviso("Ya estás en una sala o en una partida.", "Invitar")
                return
            _tit = "Invitar a %s" % nombre
            self.preguntar_apuesta(_tit, lambda: self.preguntar_poderes(
                _tit, lambda: self.online_conectar("create", invitar={"id": otro, "nombre": nombre})))

        b_enviar.bind(on_release=enviar)
        b_invitar.bind(on_release=invitar)
        campo.bind(on_text_validate=enviar)

        def auto(_dt):
            if raiz.parent is None:   # salió del chat (o de la pantalla): deja de consultar
                estado["cerrado"] = True
                if getattr(self, "_chat_abierto", None) == otro:
                    self._chat_abierto = None
                if Window.softinput_mode == "resize":
                    Window.softinput_mode = previo_teclado
                return False
            leer()
        Clock.schedule_once(lambda _dt: leer(), 0)
        Clock.schedule_interval(auto, CHAT_REFRESCO_SEG)
        return raiz

    def build_online_menu(self):
        pantalla, c = self._pantalla_con_volver("ONLINE", lambda: self.cambiar_pantalla(self.build_menu()),
                                                titulo_truco=True)
        perfil = getattr(self, "perfil_usuario", {}) or {}
        club = getattr(self, "equipo_usuario", "Boca Juniors")
        nombre = (perfil.get("nombre", "") + " " + perfil.get("apellido", "")).strip() or "Jugador"
        c.add_widget(Label(text="[i]Elegí cómo querés jugar[/i]", markup=True, font_size="14sp",
                           color=(0.96, 0.82, 0.40, 1), size_hint_y=None, height=dp(22)))
        self.lbl_saldo_menu = Label(text=self.texto_saldo_corto(), markup=True, font_size="16sp", halign="right",
                                    valign="middle", color=(0.98, 0.80, 0.22, 1), size_hint_x=None, width=dp(64))
        self.lbl_saldo_menu.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        c.add_widget(FilaClub([club], [f"[b]{nombre}[/b]\n[size=11sp]{club}[/size]"],
                              fondo=(0.45, 0.33, 0.10, 0.40), borde=(0.96, 0.78, 0.15, 1), alto=52, tam="14sp",
                              extra=[Moneda(26), self.lbl_saldo_menu]))
        self.actualizar_saldo()
        CORAL, CELESTE, DORADO = (0.93, 0.42, 0.40), (0.45, 0.72, 0.95), (0.96, 0.78, 0.15)
        b_crear = ItemMenuColor("sala", "Crear sala online", "Armá una sala e invitá a un rival.", CORAL, 0.05)
        b_buscar = ItemMenuColor("buscar", "Buscar rival online", "Desafiá a truqueros de todo el país.", CELESTE, 0.12)
        b_codigo = ItemMenuColor("codigo", "Entrar con código", "Sumate a la sala de un amigo.", DORADO, 0.19)
        b_crear.bind(on_release=lambda *_: self.preguntar_apuesta(
            "Crear sala", lambda: self.preguntar_poderes("Crear sala", lambda: self.online_conectar("create"))))
        b_buscar.bind(on_release=lambda *_: self.preguntar_apuesta(
            "Buscar rival", lambda: self.preguntar_poderes("Buscar rival", lambda: self.online_conectar("search"))))
        b_codigo.bind(on_release=lambda *_: self.online_pedir_codigo())
        b_priv = ItemMenuColor("copa", "Torneo privado", "De 4 a 16 jugadores con tus amigos; los lugares libres, con bots.",
                               (0.55, 0.80, 0.25), 0.26)
        b_priv.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_tp_config()))
        for b in (b_crear, b_buscar, b_codigo, b_priv):
            c.add_widget(b)
        nota = Label(text="[i]Antes de crear una sala o buscar rival te preguntamos si es por apuesta.[/i]", markup=True,
                     font_size="12sp", halign="center", valign="middle", color=(0.93, 0.90, 0.85, 0.85),
                     size_hint_y=None, height=dp(40))
        nota.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        c.add_widget(nota)
        c.add_widget(Adorno())
        return pantalla

    # ================= Torneo privado online (amigos + bots) =================
    # Pantallas: config -> lobby -> cuadro. El servidor (/ws_torneo) arma y avanza el cuadro; los partidos
    # entre humanos usan la sala 1 a 1 de siempre y los partidos contra bots se juegan contra tu IA.
    @staticmethod
    def _tp_esc(texto):
        return str(texto).replace("&", "&amp;").replace("[", "&bl;").replace("]", "&br;")

    def tp_cfg(self):
        cfg = getattr(self, "_tp_cfg", None)
        if cfg is None:
            cfg = self._tp_cfg = {"size": 8, "apuesta": 0, "poderes": False}
        return cfg

    def tp_montos(self):
        saldo = (getattr(self, "saldo", None) or 0) if self.tiene_cuenta() else 0
        return [0] + [v for v in OPCIONES_APUESTA if v <= saldo]

    def online_nombre_partida(self):
        """Nombre con el que entrás a una sala: en el torneo, el que te asignó el servidor (es único)."""
        t = getattr(self, "tpriv", None)
        if getattr(self, "modo_torneo_priv", False) and t and t.get("nombre"):
            return t["nombre"]
        return self.online_nombre()

    # ---------- pantalla 1: configuración ----------
    def build_tp_config(self):
        pantalla, c = self._pantalla_con_volver("TORNEO PRIVADO", lambda: self.cambiar_pantalla(self.build_online_menu()))
        cfg = self.tp_cfg()
        if cfg["apuesta"] not in self.tp_montos():
            cfg["apuesta"] = 0
        VERDE, DORADO, CELESTE, GRIS = (0.55, 0.80, 0.25), (0.96, 0.78, 0.15), (0.45, 0.72, 0.95), (0.70, 0.67, 0.62)
        c.add_widget(Label(text="[i]Armá tu torneo y pasales el código a tus amigos.[/i]", markup=True,
                           font_size="14sp", color=(0.96, 0.82, 0.40, 1), size_hint_y=None, height=dp(22)))
        lbl_tam = Label(markup=True, font_size="22sp", color=(1, 1, 1, 1))
        lbl_ap = Label(markup=True, font_size="19sp", color=(0.98, 0.80, 0.22, 1))
        resumen = Label(markup=True, font_size="13sp", halign="center", valign="middle",
                        color=(0.93, 0.90, 0.85, 0.9), size_hint_y=None, height=dp(100))
        resumen.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        b_pod = boton_cartel("", DORADO, "16sp", 54)

        def refrescar(*_):
            tam, ap = cfg["size"], cfg["apuesta"]
            lbl_tam.text = "[b]%d[/b] jugadores" % tam
            lbl_ap.text = "[b]Sin apuesta[/b]" if ap == 0 else "[b]%d[/b] monedas c/u" % ap
            b_pod.text = "CON PODERES" if cfg["poderes"] else "SIN PODERES"
            b_pod.fondo = DORADO if cfg["poderes"] else GRIS
            b_pod._dibujar()
            lineas = ["Los lugares que no ocupen tus amigos los completan bots. Eliminación directa."]
            if ap > 0:
                lineas.append("Cada jugador paga %d y el campeón se lleva el pozo. Si gana un bot, todos pierden la inscripción." % ap)
            elif len(self.tp_montos()) == 1:
                lineas.append("Para apostar necesitás una cuenta con saldo.")
            if cfg["poderes"]:
                lineas.append("Cada uno usa los poderes que ya tiene.")
            resumen.text = "\n".join(lineas)

        def cambiar_tam(d):
            cfg["size"] = max(TORNEO_TAM_MIN, min(TORNEO_TAM_MAX, cfg["size"] + d))
            refrescar()

        def cambiar_ap(d):
            montos = self.tp_montos()
            i = montos.index(cfg["apuesta"]) if cfg["apuesta"] in montos else 0
            cfg["apuesta"] = montos[max(0, min(len(montos) - 1, i + d))]
            refrescar()

        def alternar_poderes(*_):
            cfg["poderes"] = not cfg["poderes"]
            refrescar()

        def fila_ajuste(titulo, etiqueta, menos, mas):
            caja = TarjetaFondo(DORADO, orientation="vertical", padding=dp(8), spacing=dp(4),
                                size_hint_y=None, height=dp(100))
            caja.add_widget(Label(text=titulo, font_size="12sp", bold=True, color=(0.96, 0.82, 0.40, 1),
                                  size_hint_y=None, height=dp(20)))
            fila = BoxLayout(orientation="horizontal", spacing=dp(8))
            b_menos = boton_oscuro("-", "28sp")
            b_mas = boton_oscuro("+", "28sp")
            for b in (b_menos, b_mas):
                b.size_hint_x = None
                b.width = dp(70)
            b_menos.bind(on_release=lambda *_: menos())
            b_mas.bind(on_release=lambda *_: mas())
            fila.add_widget(b_menos)
            fila.add_widget(etiqueta)
            fila.add_widget(b_mas)
            caja.add_widget(fila)
            return caja

        c.add_widget(fila_ajuste("CUÁNTOS JUEGAN (4 A 16)", lbl_tam, lambda: cambiar_tam(-1), lambda: cambiar_tam(1)))
        c.add_widget(fila_ajuste("INSCRIPCIÓN POR JUGADOR", lbl_ap, lambda: cambiar_ap(-1), lambda: cambiar_ap(1)))
        b_pod.bind(on_release=alternar_poderes)
        c.add_widget(b_pod)
        c.add_widget(resumen)
        refrescar()
        crear = boton_cartel("CREAR TORNEO", VERDE, "18sp", 62)
        crear.bind(on_release=lambda *_: self.tp_crear())
        entrar = boton_cartel("ENTRAR CON CÓDIGO", CELESTE, "15sp", 52)
        entrar.bind(on_release=lambda *_: self.online_pedir_codigo())
        c.add_widget(crear)
        c.add_widget(entrar)
        c.add_widget(Adorno())
        return pantalla

    def tp_crear(self):
        cfg = self.tp_cfg()
        saldo = getattr(self, "saldo", None) or 0
        if cfg["apuesta"] > 0 and (not self.tiene_cuenta() or saldo < cfg["apuesta"]):
            self.online_aviso("No tenés saldo suficiente para esa inscripción.", "Torneo privado")
            return
        self.tp_conectar({"action": "crear", "name": self.online_nombre(), "size": cfg["size"],
                          "bet": cfg["apuesta"], "powers": bool(cfg["poderes"])})

    def tp_unirse(self, codigo, info):
        """Llega desde 'Entrar con código' (o una invitación) cuando el código es de un torneo."""
        bet = int(info.get("bet", 0) or 0)
        saldo = getattr(self, "saldo", None) or 0
        if bet > 0 and (not self.tiene_cuenta() or saldo < bet):
            self.online_aviso("Este torneo tiene una inscripción de %d monedas y tu saldo es %s." % (
                bet, saldo if self.tiene_cuenta() else "—"), "Torneo privado")
            return

        def entrar():
            self.tp_conectar({"action": "unirse", "name": self.online_nombre(), "room": codigo})
        if bet > 0:
            self.online_aviso("Torneo privado de %d jugadores.\nInscripción: %d monedas (si no sos el campeón, o si gana un bot, las perdés).%s" % (
                int(info.get("size", 0) or 0), bet, "\nSe juega con poderes." if info.get("powers") else ""),
                "Torneo privado", botones=[("ENTRAR (pago %d)" % bet, entrar)])
        else:
            entrar()

    # ---------- conexión con el torneo ----------
    def tp_conectar(self, payload):
        if websocket is None:
            self.online_aviso("Falta instalar websocket-client en Pydroid 3. Abrí Pip e instalá: websocket-client")
            return
        self.tp_cerrar_ws(avisar=False)
        self.tpriv = {"room": None, "pid": None, "nombre": "", "estado": "conectando", "players": [], "host": None,
                      "size": 0, "bet": 0, "poderes": False, "cuadro": [], "jugadores": [], "partido": None,
                      "jugando": None, "resultado_enviado": False, "fin": None, "rival_pid": None}
        self.online_aviso("Conectando al torneo…\nSi el servidor estaba dormido puede tardar hasta un minuto.",
                          "Torneo privado")
        perfil = getattr(self, "perfil_usuario", None) or {}
        if perfil.get("id") and perfil.get("token"):
            payload["account"] = {"id": perfil["id"], "token": perfil["token"]}
        self._tp_abrir_ws(payload)

    def _tp_abrir_ws(self, payload):
        token = object()
        self.tp_ws_token = token

        def vivo():
            return self.tp_ws_token is token

        def on_open(ws):
            if vivo():
                ws.send(json.dumps(payload, ensure_ascii=False))

        def on_message(ws, raw):
            if not vivo():
                return
            try: msg = json.loads(raw)
            except Exception: return
            Clock.schedule_once(lambda _dt, m=msg: vivo() and self.tp_procesar(m), 0)

        def on_error(ws, error):
            if not vivo():
                return
            Clock.schedule_once(lambda _dt, e=error: vivo() and self.tp_procesar(
                {"type": "torneo_cerrado", "message": str(e)}), 0)

        def on_close(ws, code, reason):
            if not vivo():
                return
            Clock.schedule_once(lambda _dt: vivo() and self.tp_procesar(
                {"type": "torneo_cerrado", "message": "Se cerró la conexión con el torneo."}), 0)
        ws = websocket.WebSocketApp(TORNEO_SERVER_URL, on_open=on_open, on_message=on_message,
                                    on_error=on_error, on_close=on_close)
        self.tp_ws = ws
        threading.Thread(
            target=lambda: ws.run_forever(ping_interval=ONLINE_PING_INTERVALO, ping_timeout=ONLINE_PING_TIMEOUT,
                                          **({"sslopt": {"ca_certs": SSL_CAFILE}} if SSL_CAFILE else {})),
            daemon=True).start()

    def tp_enviar(self, accion):
        ws = getattr(self, "tp_ws", None)
        if ws is None:
            return False
        try:
            ws.send(json.dumps(accion, ensure_ascii=False))
            return True
        except Exception:
            return False

    def tp_cerrar_ws(self, avisar=True):
        """Sale del torneo (el servidor devuelve la inscripción en el lobby o da por perdidos los partidos)."""
        ws = getattr(self, "tp_ws", None)
        if ws is not None and avisar:
            try: ws.send(json.dumps({"action": "salir"}))
            except Exception: pass
        self.tp_ws_token = None
        self.tp_ws = None
        if ws is not None:
            try: ws.close()
            except Exception: pass
        self.tpriv = None
        self.modo_torneo_priv = False

    def tp_procesar(self, msg):
        t = getattr(self, "tpriv", None)
        tipo = msg.get("type")
        if t is None:
            return
        if tipo in ("torneo_creado", "torneo_unido"):
            t.update(room=msg.get("room"), pid=msg.get("pid"), nombre=msg.get("name", ""),
                     size=int(msg.get("size") or 0), bet=int(msg.get("bet") or 0),
                     poderes=bool(msg.get("powers")), estado="lobby")
            self.cerrar_aviso()
            self.cambiar_pantalla(self.build_tp_lobby())
        elif tipo == "wallet":
            self.fijar_saldo(msg.get("coins"))
        elif tipo == "torneo_lobby":
            t["players"] = msg.get("players", [])
            t["host"] = msg.get("host")
            t["size"] = int(msg.get("size") or t.get("size") or 0)
            if t["estado"] == "lobby":
                self.tp_refrescar_lobby()
        elif tipo in ("torneo_inicio", "torneo_cuadro"):
            era_lobby = t["estado"] == "lobby"
            t["estado"] = "juego"
            t["cuadro"] = msg.get("cuadro", [])
            t["jugadores"] = msg.get("jugadores", t.get("jugadores", []))
            if era_lobby and not getattr(self, "modo_torneo_priv", False):
                self.cerrar_aviso()
                self.cambiar_pantalla(self.build_tp_cuadro())
            else:
                self.tp_refrescar_cuadro()
            if (tipo == "torneo_cuadro" and msg.get("match") and msg.get("match") == t.get("jugando")
                    and not t.get("resultado_enviado")):
                self.tp_partido_resuelto_por_servidor(msg)
        elif tipo == "torneo_partido":
            t["partido"] = msg
            self.tp_refrescar_cuadro()
            self.tp_avisar_partido(msg)
        elif tipo == "torneo_fin":
            t["fin"] = msg
            t["estado"] = "fin"
            if msg.get("coins") is not None:
                self.fijar_saldo(msg.get("coins"))
            if not getattr(self, "modo_torneo_priv", False):
                self.tp_mostrar_fin()
        elif tipo == "torneo_aviso":
            self.online_aviso(msg.get("message", ""), "Torneo")
        elif tipo in ("torneo_error", "error"):
            self.cerrar_aviso()
            texto = msg.get("message", "Error en el torneo.")
            if not t.get("room"):          # no se pudo ni crear ni entrar
                self.tp_cerrar_ws()
            self.online_aviso(texto, "Torneo privado")
        elif tipo == "torneo_cerrado":
            en_partida = bool(getattr(self, "modo_torneo_priv", False))
            conectado = t.get("estado") != "conectando"
            terminado = t.get("estado") == "fin"
            self.cerrar_aviso()
            self.tp_cerrar_ws(avisar=False)
            if en_partida:
                self.salir_al_menu(destino=self.build_online_menu)
            else:
                self.cambiar_pantalla(self.build_online_menu())
            if not terminado:
                self.online_aviso(("Se perdió la conexión con el torneo.\nSi estabas jugando, el servidor te da por ausente."
                                   if conectado else "No se pudo conectar con el servidor. Probá de nuevo."),
                                  "Torneo privado")

    # ---------- pantalla 2: lobby ----------
    def build_tp_lobby(self):
        t = self.tpriv
        pantalla, c = self._pantalla_con_volver("TORNEO", self.tp_pedir_salir, texto_volver="< Salir")
        VERDE, CELESTE, GRIS = (0.55, 0.80, 0.25), (0.45, 0.72, 0.95), (0.70, 0.67, 0.62)
        cod = Label(text="[size=13sp]Código del torneo[/size]\n[b][size=36sp]%s[/size][/b]" % t["room"], markup=True,
                    halign="center", valign="middle", color=(0.96, 0.82, 0.40, 1), size_hint_y=None, height=dp(84))
        cod.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        c.add_widget(cod)
        info = Label(text="%d jugadores  ·  %s  ·  %s" % (
            t["size"], ("inscripción %d" % t["bet"]) if t["bet"] else "sin apuesta",
            "con poderes" if t["poderes"] else "sin poderes"),
            font_size="13sp", color=(0.93, 0.90, 0.85, 0.9), size_hint_y=None, height=dp(24))
        c.add_widget(info)
        for texto, color, fn in (("INVITAR AMIGOS (CHAT)", (0.96, 0.78, 0.15), lambda: self.tp_invitar_amigos()),
                                 ("INVITAR POR WHATSAPP", VERDE, lambda: self.invitar_whatsapp(t["room"])),
                                 ("COMPARTIR INVITACIÓN", CELESTE, lambda: self.compartir_invitacion(t["room"])),
                                 ("COPIAR CÓDIGO", GRIS, lambda: Clipboard.copy(t["room"]))):
            b = boton_cartel(texto, color, "14sp", 46)
            b.bind(on_release=lambda *_, f=fn: f())
            c.add_widget(b)
        self.tp_caja_jugadores = BoxLayout(orientation="vertical", spacing=dp(4), size_hint_y=None)
        self.tp_caja_jugadores.bind(minimum_height=self.tp_caja_jugadores.setter("height"))
        c.add_widget(self.tp_caja_jugadores)
        self.tp_btn_empezar = boton_cartel("", VERDE, "17sp", 62)
        self.tp_btn_empezar.bind(on_release=lambda *_: self.tp_empezar())
        c.add_widget(self.tp_btn_empezar)
        c.add_widget(Adorno())
        self.tp_refrescar_lobby()
        return pantalla

    def tp_refrescar_lobby(self):
        t = getattr(self, "tpriv", None)
        caja = getattr(self, "tp_caja_jugadores", None)
        if not t or caja is None or caja.parent is None:
            return
        caja.clear_widgets()
        jugadores = t.get("players", [])
        size = int(t.get("size") or 0)
        for i in range(size):
            if i < len(jugadores):
                j = jugadores[i]
                yo = j.get("pid") == t.get("pid")
                org = j.get("pid") == t.get("host")
                texto = "%d.  [b]%s[/b]%s%s" % (i + 1, self._tp_esc(j.get("name", "")), "  (vos)" if yo else "",
                                                "   [color=f5c518]organizador[/color]" if org else "")
                fila = FilaPanel(fondo=(0.45, 0.33, 0.10, 0.40), borde=(0.96, 0.78, 0.15, 1) if yo else None,
                                 text=texto, markup=True, font_size="14sp", size_hint_y=None, height=dp(38))
            else:
                fila = FilaPanel(text="%d.  [i]lugar libre: lo completa un bot[/i]" % (i + 1), markup=True,
                                 font_size="13sp", color=(0.75, 0.72, 0.66, 1), size_hint_y=None, height=dp(34))
            caja.add_widget(fila)
        libres = max(0, size - len(jugadores))
        b = self.tp_btn_empezar
        if t.get("host") == t.get("pid"):
            b.text = ("EMPEZAR (completan %d bot%s)" % (libres, "" if libres == 1 else "s")) if libres else "EMPEZAR TORNEO"
            b.disabled = False
        else:
            b.text = "Esperando al organizador…"
            b.disabled = True

    def tp_invitar_amigos(self):
        """Elegís amigos de tu lista y les llega la invitación por el chat."""
        t = getattr(self, "tpriv", None)
        if not t or not t.get("room"):
            return
        if not self.tiene_cuenta():
            self.online_aviso("Necesitás una cuenta para invitar amigos por el chat.", "Invitar")
            return
        cred = self.amigos_credenciales()
        self.online_aviso("Buscando tus amigos…", "Invitar")

        def ok(datos):
            amigos = sorted(datos.get("amigos", []), key=lambda a: not a.get("en_linea"))
            if not amigos:
                self.online_aviso("Todavía no tenés amigos agregados.", "Invitar")
                return
            panel = self._cartel_online("Invitar amigos")
            lista = BoxLayout(orientation="vertical", spacing=dp(6), size_hint_y=None)
            lista.bind(minimum_height=lista.setter("height"))
            for x in amigos[:40]:
                nombre = str(x.get("nombre", "Amigo"))
                b = boton_cartel(nombre + ("  (en línea)" if x.get("en_linea") else ""),
                                 (0.55, 0.80, 0.25) if x.get("en_linea") else (0.70, 0.67, 0.62), "14sp", 48)

                def enviar(*_, x=x, b=b, nombre=nombre):
                    self.invitacion_enviar(x, t["room"])
                    b.text = "Invitado: " + nombre
                    b.disabled = True
                b.bind(on_release=enviar)
                lista.add_widget(b)
            scroll = ScrollView(do_scroll_x=False, bar_width=dp(4))
            scroll.add_widget(lista)
            panel.add_widget(scroll)
            listo = boton_cartel("LISTO", (0.70, 0.67, 0.62), "15sp", 52)
            panel.add_widget(listo)
            self.cerrar_aviso()
            popup = self._popup_cartel(panel, alto_rel=0.78, auto_dismiss=True)
            listo.bind(on_release=popup.dismiss)
            popup.open()
        self.api("/amigos/listar", cred, ok=ok,
                 fallo=lambda m, c=None: self.online_aviso(m if c else "No se pudo cargar tu lista de amigos.", "Invitar"))

    def tp_empezar(self):
        self.tp_enviar({"action": "empezar"})

    def tp_pedir_salir(self, *_):
        t = getattr(self, "tpriv", None)
        if not t:
            self.cambiar_pantalla(self.build_online_menu())
            return
        if t.get("estado") == "fin":
            self.tp_salir()
            return
        if t.get("estado") == "lobby":
            texto = "¿Salir del torneo?" + ("\nSe te devuelve la inscripción." if t.get("bet") else "")
        else:
            texto = "¿Abandonar el torneo?\nPerdés los partidos que te falten."
        self.online_aviso(texto, "Torneo", botones=[("SALIR", self.tp_salir)])

    def tp_salir(self):
        self.cerrar_aviso()
        self.tp_cerrar_ws()
        self.cambiar_pantalla(self.build_online_menu())

    # ---------- pantalla 3: cuadro ----------
    def build_tp_cuadro(self):
        pantalla, c = self._pantalla_con_volver("CUADRO", self.tp_pedir_salir, texto_volver="< Salir")
        self.tp_lbl_estado = Label(markup=True, font_size="15sp", halign="center", valign="middle",
                                   color=(0.96, 0.82, 0.40, 1), size_hint_y=None, height=dp(64))
        self.tp_lbl_estado.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        c.add_widget(self.tp_lbl_estado)
        self.tp_btn_jugar = boton_cartel("JUGAR MI PARTIDO", (0.96, 0.78, 0.15), "18sp", 62)
        self.tp_btn_jugar.bind(on_release=self.tp_jugar_partido)
        c.add_widget(self.tp_btn_jugar)
        self.tp_caja_cuadro = BoxLayout(orientation="vertical", spacing=dp(4), size_hint_y=None)
        self.tp_caja_cuadro.bind(minimum_height=self.tp_caja_cuadro.setter("height"))
        c.add_widget(self.tp_caja_cuadro)
        c.add_widget(Adorno())
        self.tp_refrescar_cuadro()
        return pantalla

    def tp_mi_situacion(self):
        t = self.tpriv
        yo = t.get("pid")
        ultimo = None
        for ronda in t.get("cuadro", []):
            for p in ronda["partidos"]:
                if yo in (p["a_pid"], p["b_pid"]):
                    ultimo = (ronda is t["cuadro"][-1], p)
        if ultimo is None:
            return "espera"
        es_final, p = ultimo
        if p["estado"] == "fin":
            if p["w"] == yo:
                return "campeon" if es_final else "avanzo"
            return "eliminado"
        return "juega"

    def tp_refrescar_cuadro(self):
        t = getattr(self, "tpriv", None)
        caja = getattr(self, "tp_caja_cuadro", None)
        if not t or caja is None or caja.parent is None:
            return
        yo = t.get("pid")
        humanos = {j["pid"]: j.get("humano") for j in t.get("jugadores", [])}

        def etiqueta(nombre, pid, ganador):
            if not pid:
                return "[color=8a8478]por definir[/color]"
            texto = self._tp_esc(nombre)
            if humanos.get(pid) is False:
                texto += " [size=11sp](bot)[/size]"
            if pid == yo:
                texto = "[b]%s (vos)[/b]" % texto
            if ganador and ganador == pid:
                return "[color=8cd34a]%s[/color]" % texto
            if ganador and ganador != pid:
                return "[color=8a8478]%s[/color]" % texto
            return texto
        caja.clear_widgets()
        for ronda in t.get("cuadro", []):
            caja.add_widget(Label(text=ronda["nombre"].upper(), bold=True, font_size="15sp",
                                  color=(0.93, 0.74, 0.22, 1), size_hint_y=None, height=dp(30)))
            for p in ronda["partidos"]:
                mio = yo in (p["a_pid"], p["b_pid"])
                if p.get("pase"):
                    texto = "%s   [i]pasa directo[/i]" % etiqueta(p["a"], p["a_pid"], p["w"])
                else:
                    texto = "%s   vs   %s" % (etiqueta(p["a"], p["a_pid"], p["w"]), etiqueta(p["b"], p["b_pid"], p["w"]))
                caja.add_widget(FilaPanel(fondo=(0.45, 0.33, 0.10, 0.40) if mio else (0, 0, 0, 0.28),
                                          borde=(0.96, 0.78, 0.15, 1) if mio else None,
                                          text=texto, markup=True, font_size="13sp", size_hint_y=None, height=dp(44)))
        sit = self.tp_mi_situacion()
        partido = t.get("partido")
        fin = t.get("estado") == "fin"
        if fin:
            texto = "[b]Torneo terminado[/b]"
        elif partido:
            texto = "[b]¡Te toca![/b]\n%s contra %s" % (partido.get("ronda", ""), self._tp_esc(partido.get("rival", "")))
        elif sit == "eliminado":
            texto = "Quedaste eliminado.\nPodés seguir el torneo desde acá."
        elif sit == "campeon":
            texto = "[b]¡Sos el campeón![/b]"
        elif sit == "avanzo":
            texto = "¡Pasaste de ronda!\nEsperando que terminen los otros partidos…"
        else:
            texto = "Esperando que arranque tu partido…"
        self.tp_lbl_estado.text = texto
        b = self.tp_btn_jugar
        hay = bool(partido) and not fin
        b.height = dp(62) if hay else 0
        b.opacity = 1 if hay else 0
        b.disabled = not hay

    # ---------- jugar un partido del torneo ----------
    def tp_avisar_partido(self, msg):
        texto = "%s\n\nTe toca contra %s." % (msg.get("ronda", ""), msg.get("rival", ""))
        self.online_aviso(texto, "¡Tu partido!", botones=[("JUGAR AHORA", self.tp_jugar_partido)])

    def tp_jugar_partido(self, *_):
        t = getattr(self, "tpriv", None)
        p = t.get("partido") if t else None
        if not p:
            return
        self.cerrar_aviso()
        t["jugando"] = p["match"]
        t["resultado_enviado"] = False
        t["rival_pid"] = p.get("rival_pid")
        t["partido"] = None
        self.reloj_turno_detener()
        self.cancelar_timers()
        self.modo_online = False
        self.modo_torneo_priv = True
        self.online_poderes_pref = bool(p.get("powers"))
        if p.get("modo") == "sala":
            self.online_conectar("join", p.get("room"))
        else:
            self._tp_arrancar_ia(p.get("rival", "Bot"))

    def _tp_arrancar_ia(self, rival):
        """Partido contra un bot del torneo: tu IA de siempre."""
        self.mision_gira_activa = None
        self.desafio_activo = None
        self.apuesta_ticket = None
        self.modo_gira = False
        self.modo_gira_torneo = False
        self.cancelar_timers()
        self.online_cerrar_ws()
        self.modo_online = False
        self.modo_torneo = False
        perfil = getattr(self, "perfil_usuario", None) or {}
        if perfil.get("club") in CLUBES_ARGENTINOS:
            self.equipo_usuario = perfil["club"]
        self.equipo_ia = rival
        estilo = random.choice(["Prudente", "Equilibrado", "Farolero"])
        self.perfiles_mentira = {rival: estilo}
        self.estadisticas_farol = {rival: {"cantados": 0, "descubiertos": 0}}
        self.factor_farol_ia = FACTOR_FAROL[estilo]
        self.goles_farol_jugador = self.goles_farol_ia = 0
        self.puntos_jugador = self.puntos_ia = self.numero_mano = 0
        self.cambiar_pantalla(self.build_partida())
        self.nueva_mano()

    def tp_fin_partido(self, gane):
        """Terminó mi partido del torneo: se lo informo al servidor y vuelvo al cuadro."""
        t = getattr(self, "tpriv", None)
        if not t or t.get("resultado_enviado") or not t.get("jugando"):
            return
        t["resultado_enviado"] = True
        ganador = t.get("pid") if gane else t.get("rival_pid")
        self.tp_enviar({"action": "resultado", "match": t["jugando"], "winner": ganador})
        self.estado.text = ("¡Ganaste el partido! Volvemos al cuadro…" if gane
                            else "Perdiste el partido. Volvemos al cuadro…")
        self.tp_programar_vuelta(4.0)

    def tp_programar_vuelta(self, seg):
        t = getattr(self, "tpriv", None)
        m = t.get("jugando") if t else None
        self.programar(lambda _dt, m=m: self.tp_volver_cuadro(m), seg)

    def _tp_congelar_partida(self):
        self.cancelar_timers()
        self.mano_terminada = True
        self.esperando_ia = False
        self.canto_en_curso = False
        self.ia_canto = None
        try: self.actualizar_botones()
        except Exception: pass

    def tp_rival_se_fue(self):
        """El rival cerró su conexión con la sala en plena partida: paso de ronda."""
        t = getattr(self, "tpriv", None)
        if not t or t.get("resultado_enviado") or not t.get("jugando"):
            return
        self._tp_congelar_partida()
        self.tp_fin_partido(True)
        self.estado.text = "Tu rival abandonó el partido. ¡Pasás de ronda!"

    def tp_partido_resuelto_por_servidor(self, msg):
        """El servidor cerró mi partido por su cuenta (p. ej. el rival no apareció)."""
        t = self.tpriv
        t["resultado_enviado"] = True
        gane = msg.get("winner") == t.get("pid")
        self._tp_congelar_partida()
        try:
            self.estado.text = ("Tu rival no apareció: ¡pasás de ronda!" if gane
                                else "El torneo te dio el partido por perdido.")
        except Exception:
            pass
        self.tp_programar_vuelta(3.5)

    def tp_volver_cuadro(self, partido=None):
        t = getattr(self, "tpriv", None)
        if not t:
            return
        if partido is not None and t.get("jugando") != partido:
            return          # ya empezó otro partido: este aviso quedó viejo
        self.reloj_turno_detener()
        self.cancelar_timers()
        self.online_cerrar_ws()
        self.modo_online = False
        self.modo_torneo_priv = False
        self.online_desconectado = False
        self.canto_en_curso = False
        self.detener_voz()
        self._parar_si_suena(getattr(self, "sonido_actual", None))
        perfil = getattr(self, "perfil_usuario", None) or {}
        if perfil.get("club") in CLUBES_ARGENTINOS:
            self.equipo_usuario = perfil["club"]
        t["jugando"] = None
        self.cambiar_pantalla(self.build_tp_cuadro())
        if t.get("partido"):
            self.tp_avisar_partido(t["partido"])
        if t.get("fin"):
            self.tp_mostrar_fin()

    def tp_mostrar_fin(self):
        t = getattr(self, "tpriv", None)
        fin = t.get("fin") if t else None
        if not fin:
            return
        t["fin"] = None
        gane = fin.get("campeon_pid") == t.get("pid")
        res = fin.get("result", "")
        pozo = int(fin.get("pot") or 0)
        perfil = getattr(self, "perfil_usuario", None) or {}
        club = perfil.get("club") if perfil.get("club") in CLUBES_ARGENTINOS else None
        if gane:
            self.mostrar_animacion_campeon(
                equipo=club, premio=pozo if res == "win" else 0, titulo="¡CAMPEÓN!", unidad="monedas",
                lineas=[("Torneo privado", "18sp", (0.96, 0.82, 0.40, 1))], al_terminar=self.tp_salir)
            return
        texto = "El campeón es %s." % fin.get("campeon", "")
        if res == "lose":
            texto += "\nPerdiste tu inscripción de %d monedas." % int(t.get("bet") or 0)
        elif res == "refund":
            texto += "\nSe te devolvió la inscripción."
        self.online_aviso(texto, "Torneo terminado", botones=[("VOLVER AL MENÚ", self.tp_salir)])

    def build_perfil(self):
        pantalla, c = self._pantalla_con_volver("Perfil", lambda: self.cambiar_pantalla(self.build_menu()))
        perfil = getattr(self, "perfil_usuario", {}) or {}
        nombre = (perfil.get("nombre", "") + " " + perfil.get("apellido", "")).strip() or "Jugador"
        club = getattr(self, "equipo_usuario", "Boca Juniors")
        VERDE, DORADO, CELESTE = (0.55, 0.80, 0.25, 1), (0.96, 0.78, 0.15, 1), (0.45, 0.72, 0.95, 1)
        tarjeta = TarjetaPerfil(club, nombre)
        c.add_widget(tarjeta)
        datos_g = self.gira_datos()
        hechos = sum(1 for lg in GIRA_LOGROS if ("logro." + lg["id"]) in (datos_g.get("hechas") or {}))
        chips = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(70), spacing=dp(8))
        chips.add_widget(ChipPuntos("LOGROS", "[b][size=22sp]%d[/size][/b][size=14sp] / " + str(len(GIRA_LOGROS)) + "[/size]",
                                    hechos, VERDE, 0.15))
        chips.add_widget(ChipPuntos("PUNTOS DE GIRA", "[b][size=22sp]%d[/size][/b]", datos_g.get("puntos", 0), DORADO, 0.3))
        chips.add_widget(ChipPuntos("REGIONES", "[b][size=22sp]%d[/size][/b]", self.gira_conquistadas(), CELESTE, 0.45))
        c.add_widget(chips)
        c.add_widget(Label(text="[b]Tu club[/b]", markup=True, font_size="14sp", color=DORADO, size_hint_y=None, height=dp(26)))
        fila_selector, selector = selector_club(club, 52, "16sp")
        selector.bind(text=self.seleccionar_equipo)
        selector.bind(text=lambda _sp, t: tarjeta.cambiar_club(t))
        c.add_widget(fila_selector)
        self.lbl_saldo = EtiquetaSaldo(text=self.texto_saldo())
        c.add_widget(self.lbl_saldo)
        self.actualizar_saldo()
        b_datos = ItemPerfil("perfil", "Editar mis datos", "Tu nombre y tu club.", 0.35)
        b_cuenta = ItemPerfil("codigo", "Mi saldo / ID de cuenta", "Tus monedas y tu ID para amigos.", 0.5)
        for b in (b_datos, b_cuenta):
            c.add_widget(b)
        b_datos.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_registro(edicion=True)))
        b_cuenta.bind(on_release=lambda *_: self.mostrar_cuenta_monedas())
        c.add_widget(Label(text="Versión %s" % VERSION_TEXTO, font_size="12sp", color=(0.85, 0.82, 0.78, 0.8),
                           size_hint_y=None, height=dp(30)))
        return pantalla

    def build_gira_menu(self):
        """Menú de la Gira Nacional: el mapa de la gira, Mi carrera y Mis pertenencias."""
        pantalla, c = self._pantalla_con_volver("Gira Nacional", lambda: self.cambiar_pantalla(self.build_menu()))
        NARANJA, DORADO, TURQUESA = (0.95, 0.55, 0.15), (0.96, 0.78, 0.15), (0.35, 0.80, 0.75)
        self.gira_revisar_categoria()   # si subiste de categoría, festeja
        c.add_widget(Adorno())
        b_gira = ItemMenuColor("mapa", "Gira Nacional", "Mini campeonatos: conquistá regiones y países.", NARANJA, 0.05)
        b_des = ItemMenuColor("persona", "Desafíos", "Desafíos diarios (ruleta, Truco del día, personaje del día) y semanales, y el Desafío de vouchers.", (0.93, 0.42, 0.40), 0.09)
        b_pod = ItemMenuColor("persona", "Poderes", "Poderes débiles, medios y poderosos: conseguilos con misiones o comprarlos por 50, 100 o 150 monedas. Se usan una sola vez.",
                              (0.60, 0.55, 0.98), 0.11)
        b_logros = ItemMenuColor("copa", "Mi carrera", "Tu categoría, fama, logros, misiones y Top 10 online.", DORADO, 0.14)
        b_pert = ItemMenuColor("codigo", "Mis pertenencias", "Tus monedas, vouchers, tarjetas y papeles aduaneros.", TURQUESA, 0.20)
        b_gira.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_gira()))
        b_logros.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_logros()))
        b_pod.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_poderes()))
        b_pert.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_pertenencias()))
        b_des.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_desafios_menu()))
        for b in (b_gira, b_des, b_pod, b_logros, b_pert):
            c.add_widget(b)
        b_reset = boton_oscuro("Reiniciar mi Gira Nacional", "13sp")
        b_reset.size_hint_y = None
        b_reset.height = dp(40)
        b_reset.bind(on_release=self.gira_pedir_reinicio)
        c.add_widget(b_reset)
        c.add_widget(Adorno())
        return pantalla

    def build_pertenencias(self):
        """Gira Nacional > Mis pertenencias: lo que tenés (monedas, papeles aduaneros) y lo que conquistaste."""
        pantalla, c = self._pantalla_con_volver("Mis pertenencias", lambda: self.cambiar_pantalla(self.build_gira_menu()))
        datos = self.gira_datos()
        DORADO, VERDE, CELESTE = (0.96, 0.78, 0.15), (0.55, 0.80, 0.25), (0.45, 0.72, 0.95)
        club = getattr(self, "equipo_usuario", "Boca Juniors")
        saldo = getattr(self, "saldo", None)
        c.add_widget(TarjetaTexto("Monedas", "[b][size=22sp]%s[/size][/b]\nTu club: %s" % (saldo if saldo is not None else "—", club), DORADO))
        hechos = sum(1 for lg in GIRA_LOGROS if ("logro." + lg["id"]) in (datos.get("hechas") or {}))
        c.add_widget(TarjetaTexto("Gira", "Puntos de gira: [b]%d[/b]\nRegiones conquistadas: [b]%d[/b]\nLogros: [b]%d / %d[/b]" % (
            datos.get("puntos", 0), self.gira_conquistadas(), hechos, len(GIRA_LOGROS)), VERDE))
        quien = self.online_nombre() or "Viajero"
        for _tipo, _titulo, _tdes in (("hotel", "Vouchers de hotel (para quedarte)", "hotel"), ("viaje", "Pasajes de colectivo (para viajar)", "colectivo")):
            c.add_widget(Label(text="[b]%s[/b]" % _titulo, markup=True, font_size="15sp", color=(0.93, 0.62, 0.45, 1),
                               size_hint_y=None, height=dp(30)))
            _faltan = []
            _hay = False
            for r in DESAFIO_REGIONES:
                if gira_tiene_voucher(datos, _tipo, r):
                    ch = next((d for d in DESAFIOS if d["region"] == r and d["tipo"] == _tdes), None)
                    lugar = (ch["lugar"].split(" · ")[0] if ch else DESAFIO_NOMBRE_REGION[r])
                    c.add_widget(VoucherPapel(_tipo, DESAFIO_NOMBRE_REGION[r], lugar, quien))
                    _hay = True
                else:
                    _faltan.append(DESAFIO_NOMBRE_REGION[r])
            if _faltan:
                c.add_widget(Label(text=("Todavía sin conseguir: %s" if _hay else "Todavía no conseguiste ninguno: %s") % ", ".join(_faltan),
                                   font_size="12sp", color=(0.80, 0.76, 0.70, 1), halign="center", valign="middle",
                                   size_hint_y=None, height=dp(34)))
        if gira_aprendio_poder_mago(datos):
            _pm = datos.get("mago") or {}
            _gastado = bool(_pm.get("usado"))
            c.add_widget(TarjetaTexto("Poder del mago",
                                      ("Se lo ganaste al Mago Eliseo (%s).\n" % time.strftime("%d/%m/%Y", time.localtime(int(_pm.get("poder", 0)))))
                                      + ("Ya lo usaste: el poder se gasta una sola vez." if _gastado else
                                         "Lo podés usar UNA sola vez, en un campeonato de la Gira Nacional: al empezar una mano tocá «Poderes», elegí «Poder del mago» y elegí las 3 cartas que quieras."),
                                      (0.72, 0.58, 0.96)))
        if gira_aprendio_lentes(datos):
            _pc = datos.get("cientifico") or {}
            _gastado_c = bool(_pc.get("usado"))
            c.add_widget(TarjetaTexto("Lentes del científico",
                                      ("Se los ganaste al Científico (%s).\n" % time.strftime("%d/%m/%Y", time.localtime(int(_pc.get("lentes", 0)))))
                                      + ("Ya los usaste: se gastan una sola vez." if _gastado_c else
                                         "Los podés usar UNA sola vez, en cualquier lugar de la Gira Nacional: al empezar una mano tocá «Poderes», elegí «Lentes del científico» y mirá las cartas del rival. Podés usarlos en la misma mano que el Poder del mago."),
                                      (0.45, 0.80, 0.95)))
        _pd = datos.get("detective") or {}
        if _pd.get("poder"):
            c.add_widget(TarjetaTexto("Investigación del detective",
                                      ("Ya la usaste: se gasta una sola vez." if _pd.get("usado") else
                                       "La podés usar UNA sola vez, en cualquier lugar de la Gira Nacional: al empezar una mano tocá «Poderes» y elegí «Investigación del detective» para saber si la mano del rival es fuerte, media o débil."),
                                      (0.90, 0.68, 0.30)))
        for _pid in PODERES_NUEVOS:
            _pp = PODER_POR_ID[_pid]
            _dp = datos.get(_pp["clave"]) or {}
            if _dp.get("poder"):
                c.add_widget(TarjetaTexto(_pp["nombre"], ("Ya lo usaste: se gasta una sola vez." if _dp.get("usado") else _pp["uso"]),
                                          _pp["color"]))
        _pf = datos.get("fenix") or {}
        if _pf.get("poder"):
            c.add_widget(TarjetaTexto("Ave Fénix",
                                      ("Ya lo usaste: se gasta una sola vez." if _pf.get("usado") else
                                       "Lo podés usar UNA sola vez: si perdés un partido de un campeonato de la Gira Nacional (por ejemplo la final), aparece el botón «Revancha con el Ave Fénix» para volver a jugar ese partido y seguir en el campeonato."),
                                      (0.98, 0.58, 0.18)))
        if gira_tiene_tarjeta_mafia(datos):
            c.add_widget(Label(text="[b]Tarjeta de la Familia[/b]", markup=True, font_size="15sp", color=(0.96, 0.78, 0.15, 1),
                               size_hint_y=None, height=dp(30)))
            _mf = datos.get("mafia") or {}
            c.add_widget(TarjetaMafia(quien, int(_mf.get("aprobado", 0)), favor=int(_mf.get("favor", 0)), height=dp(196)))
            _ex = Label(text="Favor de la Familia: si perdés el torneo de una región, la tarjeta cubre tu voucher de hotel (una vez) "
                             "y podés jugar la revancha. Se recarga cada vez que conquistás una región.",
                        font_size="12sp", color=(0.80, 0.76, 0.70, 1), halign="center", valign="middle", size_hint_y=None, height=dp(62))
            _ex.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, None)))
            c.add_widget(_ex)
        # Álbum de figuritas: una por cada rival del Desafío, el campeón del año pasado y los 7 personajes del día.
        _album = list(DESAFIOS) + [MAFIA_JEFE] + [personaje_ficha(p) for p in PERSONAJES_DIA]
        _ganadas = [(d, figurita_conseguida(datos, d)) for d in _album]
        c.add_widget(Label(text="[b]Álbum de figuritas[/b]  ·  %d / %d" % (sum(1 for _d, t in _ganadas if t), len(_album)), markup=True,
                           font_size="15sp", color=(0.96, 0.78, 0.15, 1), size_hint_y=None, height=dp(30)))
        _filas = (len(_album) + 2) // 3
        _grilla = GridLayout(cols=3, spacing=dp(6), size_hint_y=None, height=_filas * dp(160) + (_filas - 1) * dp(6))
        for _n, (_d, _t) in enumerate(_ganadas, 1):
            _grilla.add_widget(Figurita(_d, _t, _n, len(_album)))
        c.add_widget(_grilla)
        c.add_widget(Label(text="Ganale a cada rival en Desafíos (y a los personajes del día) para sumar su figurita.", font_size="12sp",
                           color=(0.80, 0.76, 0.70, 1), size_hint_y=None, height=dp(30)))
        # Postales: una por región conquistada y una por cada encuentro del camino.
        _arg = next(p for p in GIRA_PAISES if p["id"] == "arg")
        _pos = [(po, gira_tiene_postal(datos, _arg, po)) for po in POSTALES]
        c.add_widget(Label(text="[b]Postales[/b]  ·  %d / %d" % (sum(1 for _p, t in _pos if t), len(POSTALES)), markup=True,
                           font_size="15sp", color=(0.96, 0.78, 0.15, 1), size_hint_y=None, height=dp(30)))
        _filas = (len(_pos) + 1) // 2
        _gp = GridLayout(cols=2, spacing=dp(6), size_hint_y=None, height=_filas * dp(124) + (_filas - 1) * dp(6))
        for _n, (_po, _t) in enumerate(_pos, 1):
            _gp.add_widget(PostalCard(_po, _t, _n, len(_pos)))
        c.add_widget(_gp)
        c.add_widget(Label(text="Conquistá cada región y frená a los viajeros del camino para completar la colección.", font_size="12sp",
                           color=(0.80, 0.76, 0.70, 1), size_hint_y=None, height=dp(30)))
        lineas = []
        for pais in GIRA_PAISES:
            if pais["id"] not in GIRA_ADUANA:
                continue
            estado, falta = gira_aduana_estado(datos, pais)
            if estado == "aprobado":
                txt = "[color=8ccc40]Aprobado[/color]"
            elif estado == "espera":
                txt = "En trámite: faltan %s" % gira_texto_tiempo(falta)
            else:
                txt = "Sin tramitar"
            lineas.append("%s: %s" % (pais["nombre"].title(), txt))
        c.add_widget(TarjetaTexto("Papeles aduaneros", "\n".join(lineas) if lineas else "Todavía no hay papeles.", CELESTE))
        return pantalla

    def build_desafios_menu(self):
        """Gira Nacional > Desafíos: diarios, semanales y el Desafío de vouchers (hoteles y colectivos)."""
        pantalla, c = self._pantalla_con_volver("Desafíos", lambda: self.cambiar_pantalla(self.build_gira_menu()))
        datos = self.gira_datos()
        sem = self.gira_semana(datos)
        cobrados = len([s for s in SEMANALES if s["id"] in sem["cobrados"]])
        c.add_widget(Adorno())
        b_dia = ItemMenuColor("pelota", "Desafíos diarios", "Ruleta, Truco del día y personaje del día. Se renuevan todos los días.",
                              (0.80, 0.35, 0.95), 0.05)
        b_sem = ItemMenuColor("copa", "Desafíos semanales", "Metas de la semana con puntos y poderes · Cobrados: %d de %d" % (cobrados, len(SEMANALES)),
                              (0.30, 0.72, 0.68), 0.09)
        b_des = ItemMenuColor("persona", "Desafío", "Jugá contra dueños de hoteles y colectivos: ganá tus vouchers de hotel y de viaje.",
                              (0.93, 0.42, 0.40), 0.13)
        b_dia.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_desafios_diarios()))
        b_sem.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_desafios_semanales()))
        b_des.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_desafios()))
        for b in (b_dia, b_sem, b_des):
            c.add_widget(b)
        c.add_widget(Adorno())
        return pantalla

    def build_desafios_diarios(self):
        """Desafíos > Diarios: la Ruleta, el Truco del día y el personaje del día."""
        pantalla, c = self._pantalla_con_volver("Desafíos diarios", lambda: self.cambiar_pantalla(self.build_desafios_menu()))
        pj = personaje_del_dia()
        c.add_widget(Adorno())
        b_rul = ItemMenuColor("pelota", "Ruleta", "%s · Puntos de ranking, poderes o nada." % self.ruleta_estado_texto(),
                              (0.95, 0.65, 0.20), 0.05)
        b_dia = ItemMenuColor("pelota", "Truco del día", "%s · IA extrema, una partida por día: ganá puntos para el ranking online." % self.truco_dia_estado_texto(),
                              (0.80, 0.35, 0.95), 0.09)
        b_per = ItemMenuColor("persona", "Personaje del día", "%s · %s · Premio: %s" % (pj["nombre"], self.personaje_estado_texto(), premio_texto(pj["premio"])),
                              (0.30, 0.72, 0.68), 0.13)
        b_rul.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_ruleta()))
        b_dia.bind(on_release=self.truco_dia_cartel)
        b_per.bind(on_release=self.personaje_dia_cartel)
        for b in (b_rul, b_dia, b_per):
            c.add_widget(b)
        c.add_widget(Adorno())
        return pantalla

    def build_desafios_semanales(self):
        """Desafíos > Semanales: metas de la semana. Cada una se cobra a mano cuando la cumplís."""
        pantalla, c = self._pantalla_con_volver("Desafíos semanales", lambda: self.cambiar_pantalla(self.build_desafios_menu()))
        datos = self.gira_datos()
        sem = self.gira_semana(datos)
        DORADO, VERDE, GRIS = (0.96, 0.78, 0.15), (0.55, 0.80, 0.25), (0.45, 0.45, 0.50)
        faltan = 7 - time.localtime().tm_wday   # la semana cierra el domingo (cuenta hoy)
        c.add_widget(TarjetaTexto("Esta semana",
                                  "Quedan %d día%s (hasta el domingo). El avance se reinicia el lunes. Cobrá cada desafío apenas lo cumplís." % (
                                      faltan, "" if faltan == 1 else "s"), DORADO))
        for s in SEMANALES:
            hecho = semanal_progreso(sem, s)
            cobrado = s["id"] in sem["cobrados"]
            c.add_widget(TarjetaTexto("%s%s" % (s["titulo"], " · COBRADO" if cobrado else ""),
                                      "%s\nAvance: %d de %d · Premio: %s" % (s["texto"], min(hecho, s["meta"]), s["meta"], premio_texto(s["premio"])),
                                      VERDE if cobrado else DORADO))
            if not cobrado and hecho >= s["meta"]:
                b = boton_cartel("COBRAR", VERDE, "16sp")
                b.bind(on_release=lambda *_, sid=s["id"]: self.semanal_cobrar(sid))
                c.add_widget(b)
        todos = all(s["id"] in sem["cobrados"] for s in SEMANALES)
        comp = SEMANAL_COMPLETA
        c.add_widget(TarjetaTexto("%s%s" % (comp["titulo"], " · COBRADO" if "completa" in sem["cobrados"] else ""),
                                  "%s\nPremio: %s" % (comp["texto"], premio_texto(comp["premio"])),
                                  VERDE if "completa" in sem["cobrados"] else (0.80, 0.35, 0.95)))
        if todos and "completa" not in sem["cobrados"]:
            b = boton_cartel("COBRAR", VERDE, "16sp")
            b.bind(on_release=lambda *_: self.semanal_cobrar("completa"))
            c.add_widget(b)
        if not self.tiene_cuenta():
            c.add_widget(Label(text="Necesitás una cuenta online para que los puntos entren al ranking.", font_size="12sp",
                               color=(0.95, 0.60, 0.40, 1), size_hint_y=None, height=dp(30)))
        c.add_widget(Adorno())
        return pantalla

    def gira_semana(self, datos):
        """Avance de la semana en curso; si cambió la semana, arranca de cero (el que llama guarda si hace falta)."""
        s = datos["semana"]
        if s["clave"] != semana_clave():
            s.update(clave=semana_clave(), ruleta=0, truco=0, personajes=[], cobrados=[])
        return s

    def gira_dar_poder(self, datos, nivel):
        """Entrega un poder al azar de esa categoría que no tengas sin usar. Devuelve el poder, o None si ya los tenés todos."""
        libres = ruleta_poderes_libres(datos, nivel)
        if not libres:
            return None
        p = random.choice(libres)
        m = datos.setdefault(p["clave"], {})
        m[p["campo"]] = int(time.time())
        m["usado"] = 0
        return p

    def semanal_cobrar(self, sid):
        """Entrega el premio de un desafío semanal cumplido (una sola vez por semana)."""
        datos = self.gira_datos()
        sem = self.gira_semana(datos)
        if sid in sem["cobrados"]:
            return
        if sid == "completa":
            if any(s["id"] not in sem["cobrados"] for s in SEMANALES):
                return
            titulo, premio, logro = SEMANAL_COMPLETA["titulo"], SEMANAL_COMPLETA["premio"], SEMANAL_COMPLETA["logro_respaldo"]
        else:
            s = next((x for x in SEMANALES if x["id"] == sid), None)
            if s is None or semanal_progreso(sem, s) < s["meta"]:
                return
            titulo, premio, logro = s["titulo"], s["premio"], s["logro"]
        avisos, puntos = [], 0
        if premio[0] == "poder":
            p = self.gira_dar_poder(datos, premio[1])
            if p:
                avisos.append("¡Ganaste el %s! Lo tenés en Poderes > Mis poderes." % p["nombre"])
            else:
                puntos, logro = SEMANAL_COMPLETA["puntos_respaldo"], SEMANAL_COMPLETA["logro_respaldo"]
                avisos.append("Ya tenías todos los poderes de esa categoría: te llevás puntos en su lugar.")
        else:
            puntos = premio[1]
        if puntos:
            datos["puntos"] += puntos
            self.gira_encolar_puntos(datos, logro)
            avisos.append("+%d puntos para el ranking online." % puntos)
        sem["cobrados"].append(sid)
        self.gira_historial(datos, "Desafío semanal «%s» cobrado" % titulo)
        avisos += self.gira_revisar_hechas(datos) or []
        self.gira_guardar()
        self.gira_enviar_pendientes()
        self.mostrar_cartel("DESAFÍO SEMANAL", titulo, True, detalle="\n".join(avisos),
                            botones=[("ACEPTAR", lambda: self.cambiar_pantalla(self.build_desafios_semanales()))], alto=0.45)

    # ---------- Personaje del día ----------
    def personaje_estado_texto(self):
        d = self.gira_datos()["personaje"]
        if d["fecha"] == diario_fecha(0) and d["estado"]:
            return {"ganado": "Ya lo ganaste hoy", "perdido": "Hoy ya lo jugaste", "jugando": "Lo dejaste a medias"}[d["estado"]]
        return "Disponible hoy"

    def personaje_dia_cartel(self, *_):
        d = self.gira_datos()["personaje"]
        ch = personaje_del_dia()
        jugado = d["fecha"] == diario_fecha(0) and bool(d["estado"])
        lineas = ["%s · Juega %s" % (ch["lugar"], ch["perfil"].lower()),
                  "Una sola partida por día · Sin apuesta",
                  "Premio si ganás: %s" % premio_texto(ch["premio"])]
        if ch["premio"][0] == "puntos" and not self.tiene_cuenta():
            lineas.append("Necesitás una cuenta online para que los puntos entren al ranking.")
        if jugado:
            lineas.append("%s. Volvé mañana: cambia el personaje." % self.personaje_estado_texto())
        botones = [] if jugado else [("JUGAR", lambda: self.personaje_arrancar())]
        botones.append(("CERRAR", None))
        pid = ch["pid"]
        conversacion = ConversacionFoto(pid, ch["frase"], tex=textura_embebida("pers_" + pid, PERSONAJE_FOTO_B64[pid], "jpg"),
                                        cara_y=PERSONAJE_CARA[pid][1] + {"comisario": 20, "domador": 10}.get(pid, 0))   # baja un poco el encuadre para que entre el mentón
        self.mostrar_cartel("PERSONAJE DEL DÍA", ch["nombre"], d["estado"] != "perdido", detalle="\n".join(lineas),
                            extra=conversacion, botones=botones, apilados=True, alto=0.66 + 0.085 * len(botones))

    def personaje_arrancar(self):
        """Gasta el intento de hoy apenas empieza (salirse a mitad de partida cuenta como perdida) y arranca el duelo."""
        datos = self.gira_datos()
        d = datos["personaje"]
        hoy = diario_fecha(0)
        if d["fecha"] == hoy and d["estado"]:
            self.personaje_dia_cartel()
            return
        d["fecha"], d["estado"] = hoy, "jugando"
        d["jugados"] += 1
        self.gira_historial(datos, "Empezaste el personaje del día")
        self.gira_guardar()
        self.desafio_arrancar(personaje_del_dia())

    def personaje_resolver(self, ch, gano):
        """Resultado del personaje del día: ganar da su premio (puntos para el ranking o un poder); perder no descuenta nada."""
        datos = self.gira_datos()
        d = datos["personaje"]
        d["fecha"] = diario_fecha(0)
        if not gano:
            d["estado"] = "perdido"
            self.gira_historial(datos, "Perdiste con %s (personaje del día)" % ch["nombre"])
            self.gira_guardar()
            return [ch["pierde"], "Mañana hay otro personaje y otra chance."]
        d["estado"] = "ganado"
        d["ganados"] += 1
        nueva = ch["pid"] not in d["figuritas"]
        if nueva:
            d["figuritas"].append(ch["pid"])   # la figurita queda para siempre en el álbum (Pertenencias)
        sem = self.gira_semana(datos)
        if ch["pid"] not in sem["personajes"]:
            sem["personajes"].append(ch["pid"])   # cuenta para el desafío semanal
        tipo, valor = ch["premio"]
        avisos = [ch["gana"]]
        if nueva:
            avisos.append("¡Nueva figurita en tu álbum: %s!" % ch["nombre"])
        if tipo == "poder":
            p = self.gira_dar_poder(datos, valor)
            if p:
                d["ultimo"] = p["nombre"]
                avisos.append("¡Ganaste el %s! Lo tenés en Poderes > Mis poderes." % p["nombre"])
                self.gira_historial(datos, "Le ganaste a %s: %s" % (ch["nombre"], p["nombre"]))
            else:
                tipo, valor = "puntos", PERSONAJE_PUNTOS_RESPALDO
                avisos.append("Ya tenías todos los poderes de esa categoría: te llevás puntos en su lugar.")
        if tipo == "puntos":
            datos["puntos"] += valor
            d["ultimo"] = "+%d puntos" % valor
            self.gira_encolar_puntos(datos, "personaje_%d" % valor)
            avisos.append("+%d puntos para el ranking online." % valor)
            self.gira_historial(datos, "Le ganaste a %s (+%d pts)" % (ch["nombre"], valor))
        avisos += self.gira_revisar_hechas(datos) or []
        self.gira_guardar()
        self.gira_enviar_pendientes()
        return avisos

    def ruleta_estado_texto(self):
        """Resumen corto para el menú."""
        return "Giro disponible hoy" if ruleta_disponible(self.gira_datos()) else "Hoy ya giraste"

    def build_ruleta(self):
        """Gira Nacional > Ruleta: un giro gratis por día. Puede salir un premio de puntos para el ranking, un poder o nada."""
        self._ruleta_girando = False
        pantalla, c = self._pantalla_con_volver("Ruleta", lambda: self.cambiar_pantalla(self.build_desafios_diarios()))
        datos = self.gira_datos()
        DORADO, VERDE = (0.96, 0.78, 0.15), (0.55, 0.80, 0.25)
        r = datos["ruleta"]
        c.add_widget(TarjetaTexto("¿Cómo funciona?",
                                  "Tenés un giro gratis por día. La ruleta puede darte +25, +50 o +100 puntos para el ranking online, "
                                  "un poder (débil, medio o fuerte) o nada. Los poderes se usan una sola vez.\n"
                                  "Giros: %d · Puntos ganados en la ruleta: %d" % (r["giros"], r["puntos"]), DORADO))
        rueda = RuletaRueda(RULETA_PREMIOS, size_hint_y=None, height=dp(330))
        c.add_widget(rueda)
        if ruleta_disponible(datos):
            girar = boton_cartel("GIRAR", VERDE, "18sp")
        else:
            girar = boton_cartel("HOY YA GIRASTE · VOLVÉ MAÑANA", (0.45, 0.45, 0.50), "14sp")
            girar.disabled = True
        girar.bind(on_release=lambda *_: self.ruleta_girar(rueda, girar))
        c.add_widget(girar)
        if r.get("ultimo"):
            c.add_widget(Label(text="Último premio: %s" % r["ultimo"], font_size="13sp", color=(0.85, 0.82, 0.78, 0.9),
                               size_hint_y=None, height=dp(28)))
        if not self.tiene_cuenta():
            c.add_widget(Label(text="Necesitás una cuenta online para que los puntos entren al ranking.", font_size="12sp",
                               color=(0.95, 0.60, 0.40, 1), size_hint_y=None, height=dp(30)))
        c.add_widget(Adorno())
        return pantalla

    def ruleta_girar(self, rueda, boton):
        """El premio se sortea y se entrega ya (así salirse a mitad del giro no lo pierde ni permite girar de nuevo); después la rueda lo muestra."""
        datos = self.gira_datos()
        if getattr(self, "_ruleta_girando", False) or not ruleta_disponible(datos):
            return
        self._ruleta_girando = True
        indice = ruleta_sortear(datos)
        titulo, detalle, gano = self.ruleta_entregar(datos, indice)
        boton.disabled = True
        boton.text = "GIRANDO..."

        def terminar():
            self._ruleta_girando = False
            self.mostrar_cartel("RULETA", titulo, gano, detalle=detalle,
                                botones=[("ACEPTAR", lambda: self.cambiar_pantalla(self.build_ruleta()))], alto=0.45)
        rueda.girar(indice, terminar)

    def ruleta_entregar(self, datos, indice):
        """Gasta el giro de hoy y entrega el premio del casillero. Devuelve (título, detalle, ¿ganó algo?)."""
        tipo, valor, _etiqueta, _color, _peso = RULETA_PREMIOS[indice]
        r = datos["ruleta"]
        r["fecha"] = diario_fecha(0)
        r["giros"] += 1
        self.gira_semana(datos)["ruleta"] += 1   # cuenta para el desafío semanal (hay un giro por día)
        if tipo == "puntos":
            datos["puntos"] += valor
            r["puntos"] += valor
            r["ultimo"] = "+%d puntos" % valor
            self.gira_encolar_puntos(datos, "%s%d" % (RULETA_LOGRO_PREFIJO, valor))
            self.gira_historial(datos, "Ruleta: +%d puntos" % valor)
            resultado = ("¡+%d PUNTOS!" % valor, "Suman a tu ranking online.", True)
        elif tipo == "poder":
            libres = ruleta_poderes_libres(datos, valor)
            p = random.choice(libres) if libres else None
            if p is None:   # no debería pasar (ruleta_sortear ya lo evita), pero por las dudas no se pierde el giro
                r["ultimo"] = "nada"
                resultado = ("NADA", "Esta vez no hubo premio. Mañana hay otro giro.", False)
            else:
                m = datos.setdefault(p["clave"], {})
                m[p["campo"]] = int(time.time())
                m["usado"] = 0
                r["ultimo"] = p["nombre"]
                self.gira_historial(datos, "Ruleta: ganaste el %s" % p["nombre"])
                self.gira_revisar_hechas(datos)
                resultado = ("¡%s!" % p["nombre"].upper(), "%s\nLo tenés en Poderes > Mis poderes." % p["uso"], True)
        else:
            r["ultimo"] = "nada"
            self.gira_historial(datos, "Ruleta: no hubo premio")
            resultado = ("NADA", "Esta vez no hubo premio. Mañana hay otro giro.", False)
        self.gira_guardar()
        self.gira_enviar_pendientes()
        return resultado

    def build_desafios(self):
        """Gira Nacional > Desafío: los dueños de hoteles dan el voucher de hotel y los de colectivos, el voucher de viaje."""
        pantalla, c = self._pantalla_con_volver("Desafío", lambda: self.cambiar_pantalla(self.build_desafios_menu()))
        datos = self.gira_datos()
        DORADO, HOTEL, COLECTIVO = (0.96, 0.78, 0.15), (0.35, 0.80, 0.75), (0.93, 0.50, 0.15)
        c.add_widget(TarjetaTexto("¿Cómo funciona?",
                                  "Cada región tiene dos vouchers. Ganale al dueño del hotel y conseguís el voucher de hotel (para quedarte). "
                                  "Ganale al dueño de los colectivos y conseguís el voucher de viaje (para viajar en colectivo a esa región). "
                                  "Sin los dos no podés jugar esa región en la Gira Nacional. Si perdés el torneo de la región (o lo abandonás) se usa tu voucher de hotel y para la revancha necesitás otro. Los desafíos se juegan en modo difícil (la IA calcula mejor y miente más) y sin apostar. "
                                  "Si ganás, el voucher es tuyo. Si perdés, te descuentan %d puntos de tu carrera online (los puntos de gira del ranking). "
                                  "Si no querés jugar, podés comprar cada voucher por %d monedas.\n"
                                  "Tus puntos de carrera online: %d" % (DESAFIO_PUNTOS_PIERDE, DESAFIO_PRECIO_VOUCHER, datos.get("puntos", 0)),
                                  DORADO))
        demora = 0.05
        # Cada grupo es (sede donde se juega, región a la que dan acceso los vouchers).
        grupos = [("buenos_aires", "patagonia")] + [(r, r) for r in DESAFIO_REGIONES if r != "patagonia"]
        for sede, rid in grupos:
            def _estado(tipo, rotulo, rid=rid):
                ok = gira_tiene_voucher(datos, tipo, rid)
                return "%s: %s" % (rotulo, "[color=8ccc40]conseguido[/color]" if ok else "pendiente")
            titulo = ("Buenos Aires → %s" % DESAFIO_NOMBRE_REGION[rid]) if sede != rid else DESAFIO_NOMBRE_REGION[rid]
            c.add_widget(Label(text="[b]%s[/b]  ·  %s  ·  %s" % (titulo, _estado("hotel", "Hotel"),
                                                                 _estado("viaje", "Viaje")),
                               markup=True, font_size="15sp", color=DORADO, size_hint_y=None, height=dp(30)))
            for ch in (d for d in DESAFIOS if d["region"] == rid and d.get("sede", d["region"]) == sede):
                hecho = desafio_ganado(datos, ch)
                tipo = "Duelo de colectivos" if ch["tipo"] == "colectivo" else "Hotel"
                desc = "%s · %s · Rival %s · Premio: voucher de %s%s" % (
                    tipo, ch["lugar"], ch["perfil"], "viaje" if ch["tipo"] == "colectivo" else "hotel", " · Ganado" if hecho else "")
                b = ItemMenuColor("grupo" if ch["tipo"] == "colectivo" else "persona", ch["nombre"], desc,
                                  COLECTIVO if ch["tipo"] == "colectivo" else HOTEL, demora, alto=88)
                b.bind(on_release=lambda *_, d=ch: self.desafio_cartel(d))
                c.add_widget(b)
                demora += 0.05
        return pantalla

    def build_poderes(self):
        """Gira Nacional > Poderes: arriba «Mis poderes» (los que ya tenés, listos para usar) y abajo, en 3 secciones
        (débil, medio, poderoso), los que podés conseguir o comprar. Al tocar uno se abre su ficha."""
        pantalla, c = self._pantalla_con_volver("Poderes", lambda: self.cambiar_pantalla(self.build_gira_menu()))
        c.add_widget(TarjetaTexto("¿Cómo funcionan?",
                                  "Arriba están los poderes que ya tenés. Abajo, todos los poderes por sección: en gris los que ya tenés en «Mis poderes», y en color los que podés conseguir con misiones o comprar (también los que ya usaste):"
                                  "los débiles cuestan %d monedas, los medios %d y los poderosos %d. Cada uno se usa UNA sola vez. "
                                  "Tocá uno para ver su ficha."
                                  % (PRECIO_NIVEL["debil"], PRECIO_NIVEL["medio"], PRECIO_NIVEL["poderoso"]),
                                  (0.96, 0.78, 0.15)))
        datos = self.gira_datos()
        mios = [p for p in PODERES if poder_sin_gastar(datos, p)]
        abrir = lambda p: self.cambiar_pantalla(self.build_poder_ficha(p))

        # --- Oferta del día (50% de descuento hasta medianoche) ---
        po = PODER_POR_ID[oferta_poder_id()]
        if not poder_sin_gastar(datos, po):
            bo = ItemMenuColor(po["icono"], "¡OFERTA DEL DÍA! %s" % po["nombre"],
                               "%d%% OFF · %d monedas (antes %d) · termina en %s" % (OFERTA_DESCUENTO, precio_poder(po), po["precio"], oferta_texto_tiempo()),
                               (0.95, 0.35, 0.30), 0.0, alto=88)
            bo.bind(on_release=lambda *_, p=po: abrir(p))
            c.add_widget(bo)
        p2 = PODER_POR_ID[oferta_2x1_id()]
        if not poder_sin_gastar(datos, p2):
            b2x = ItemMenuColor(p2["icono"], "¡2x1 DEL DÍA! %s" % p2["nombre"],
                                "Comprás este (%d monedas) y te regalamos un poder débil · termina en %s" % (precio_poder(p2), oferta_texto_tiempo()),
                                (0.90, 0.55, 0.15), 0.0, alto=88)
            b2x.bind(on_release=lambda *_, p=p2: abrir(p))
            c.add_widget(b2x)

        # --- Mis poderes ---
        TURQUESA = (0.35, 0.80, 0.75)
        lugares = max(PODERES_POR_SECCION, -(-len(mios) // 3) * 3)   # de a 3 por fila
        franja = SeccionPoder("MIS PODERES · %d" % len(mios), TURQUESA, filas=lugares // 3)
        for p in mios:
            t = TilePoder(p)
            t.bind(on_release=lambda *_, p=p: abrir(p))
            franja.poner(t)
        for _i in range(lugares - len(mios)):
            franja.poner(TileFalta(TURQUESA))
        c.add_widget(franja)

        # --- Los que se pueden conseguir, por sección ---
        for nid, titulo, color in NIVELES_PODER:
            lugares_n = max(PODERES_POR_SECCION, -(-sum(1 for p in PODERES if p.get("nivel") == nid) // 3) * 3)
            franja = SeccionPoder("%s · %d monedas" % (titulo, PRECIO_NIVEL[nid]), color, filas=lugares_n // 3)
            puestos = 0
            for p in PODERES:
                if p.get("nivel") != nid:
                    continue
                # el que tenés en «Mis poderes» sigue en su sección, pero en gris (el usado vuelve a color: se puede conseguir otro)
                t = TilePoder(p, gris=poder_sin_gastar(datos, p))
                t.bind(on_release=lambda *_, p=p: abrir(p))
                franja.poner(t)
                puestos += 1
            for _i in range(max(0, lugares_n - puestos)):
                franja.poner(TileFalta(color))   # lugares que todavía faltan
            c.add_widget(franja)
        return pantalla

    def build_poder_ficha(self, p):
        """La ficha de un poder: su ilustración, qué hace, cómo se consigue y el botón para comprarlo."""
        pantalla, c = self._pantalla_con_volver("Poderes", lambda: self.cambiar_pantalla(self.build_poderes()))
        datos = self.gira_datos()
        if poder_sin_gastar(datos, p):
            estado = "Lo tenés, listo para usar.\n" + p["uso"]
        elif poder_gastado(datos, p):
            estado = "Ya lo usaste. Podés comprar otro por %d monedas.\n%s" % (precio_poder(p), p["uso"])
        else:
            estado = ("Todavía no lo tenés.\nMisión: %s\nO comprarlo por %d monedas.\n%s" % (p["mision"], precio_poder(p), p["uso"])
                      if p.get("mision") else
                      "Todavía no lo tenés.\nPor ahora se consigue comprándolo: %d monedas.\n%s" % (precio_poder(p), p["uso"]))
        if poder_en_oferta(p) and not poder_sin_gastar(datos, p):
            estado = ("¡OFERTA DEL DÍA! %d%% de descuento (antes %d monedas). Termina en %s.\n" % (OFERTA_DESCUENTO, p["precio"], oferta_texto_tiempo())) + estado
        if poder_en_2x1(p) and not poder_sin_gastar(datos, p):
            estado = ("¡2x1 DEL DÍA! Comprás este y te regalamos un poder débil al azar. Termina en %s.\n" % oferta_texto_tiempo()) + estado
        if not poder_sin_gastar(datos, p):
            saldo = (getattr(self, "saldo", None) or 0) if self.tiene_cuenta() else None
            estado += "\n" + (("Tus monedas: %d" % saldo) if saldo is not None else "Para comprar necesitás una cuenta online.")
        c.add_widget(Image(texture=textura_embebida("desafio_" + p["foto"], DESAFIO_FOTO_B64[p["foto"]], "jpg"),
                           size_hint_y=None, height=dp(150), fit_mode="cover"))
        c.add_widget(TarjetaTexto(p["nombre"], p["desc"] + "\n" + estado, p["color"]))
        if not poder_sin_gastar(datos, p):
            b = ItemMenuColor(p["icono"], "Comprar · %d monedas" % precio_poder(p), p["nombre"], p["color"], 0.05, alto=88)
            b.bind(on_release=lambda *_: self.poder_cartel(p))
            c.add_widget(b)
        if p["id"] == "comodin" and poder_sin_gastar(datos, p):
            b2 = ItemMenuColor(p["icono"], "Usar el comodín", "Elegí qué voucher reemplaza", p["color"], 0.05, alto=88)
            b2.bind(on_release=lambda *_: self.comodin_abrir())
            c.add_widget(b2)
        return pantalla

    def comodin_abrir(self):
        """Lista los vouchers de hotel y de colectivo que te faltan (de regiones no conquistadas) para elegir cuál reemplaza."""
        datos = self.gira_datos()
        if not poder_sin_gastar(datos, PODER_POR_ID["comodin"]):
            return
        pais = next((p for p in GIRA_PAISES if p["id"] == "arg"), GIRA_PAISES[0])
        faltan = []
        for region in pais["regiones"]:
            rid = region["id"]
            if rid not in DESAFIO_REGIONES or gira_region_conquistada(datos, pais, region):
                continue
            for tipo, etiqueta in (("hotel", "Voucher de hotel"), ("viaje", "Voucher de colectivo")):
                if not gira_tiene_voucher(datos, tipo, rid):
                    faltan.append((tipo, rid, "%s · %s" % (etiqueta, DESAFIO_NOMBRE_REGION.get(rid, rid.title()))))
        if not faltan:
            self.online_aviso("No te falta ningún voucher de hotel ni de colectivo.", "Comodín")
            return
        fondo = CartelFondo(orientation="vertical", padding=[dp(12), dp(12)], spacing=dp(8))
        fondo.add_widget(Label(text="COMODÍN", font_size="20sp", bold=True, size_hint_y=None, height=dp(34),
                               color=PODER_POR_ID["comodin"]["color"] + (1,)))
        fondo.add_widget(Label(text="Elegí qué voucher reemplaza el comodín:", font_size="14sp", size_hint_y=None, height=dp(28),
                               color=(0.96, 0.90, 0.75, 1)))
        lista = GridLayout(cols=1, spacing=dp(6), size_hint_y=None)
        lista.bind(minimum_height=lista.setter("height"))
        popup = Popup(title="", separator_height=0, background="", background_color=(0, 0, 0, 0),
                      content=fondo, size_hint=(0.92, 0.8), auto_dismiss=False)

        def elegir(tipo, rid, texto):
            popup.dismiss()
            self.mostrar_cartel("COMODÍN", texto, True,
                                detalle="El comodín reemplaza este voucher. Se usa UNA sola vez.",
                                botones=[("USAR EL COMODÍN", lambda: self.comodin_usar(tipo, rid, texto)), ("CANCELAR", None)],
                                apilados=True, alto=0.5)
        for tipo, rid, texto in faltan:
            bt = boton_oscuro(texto, "15sp")
            bt.size_hint_y = None
            bt.height = dp(48)
            bt.bind(on_release=lambda _b, t=tipo, r=rid, x=texto: elegir(t, r, x))
            lista.add_widget(bt)
        sv = ScrollView()
        sv.add_widget(lista)
        fondo.add_widget(sv)
        cancelar = boton_oscuro("CANCELAR", "15sp")
        cancelar.size_hint_y = None
        cancelar.height = dp(50)
        cancelar.bind(on_release=lambda *_: popup.dismiss())
        fondo.add_widget(cancelar)
        popup.open()

    def comodin_usar(self, tipo, rid, texto):
        """Gasta el comodín y te da el voucher elegido (como los que se compran: no cuenta como victoria del Desafío)."""
        d = self.gira_datos()
        if not poder_sin_gastar(d, PODER_POR_ID["comodin"]):
            return
        d["comodin"]["usado"] = int(time.time())
        clave = ("hotel_" if tipo == "hotel" else "viaje_") + rid
        d.setdefault("vouchers", {})[clave] = int(time.time())
        d.setdefault("compradas", {})[clave] = 1
        self.gira_historial(d, "Usaste el Comodín: %s" % texto)
        self.gira_revisar_hechas(d)
        self.gira_guardar()
        self.mostrar_cartel("COMODÍN", "¡%s!" % texto, True, detalle="El comodín reemplazó el voucher. Ya lo tenés.",
                            botones=[("ACEPTAR", lambda: self.cambiar_pantalla(self.build_poder_ficha(PODER_POR_ID["comodin"])))], alto=0.42)

    def poder_cartel(self, p):
        """Pide confirmar la compra del poder."""
        self.mostrar_cartel("COMPRAR PODER", p["nombre"], True,
                            detalle="%s\n%s\nPrecio: %d monedas.%s" % (p["desc"], p["uso"], precio_poder(p), (" (¡oferta! antes %d)" % p["precio"]) if poder_en_oferta(p) else (" ¡2x1! Te regalamos un poder débil al azar." if poder_en_2x1(p) else "")),
                            botones=[("COMPRAR · %d MONEDAS" % precio_poder(p), lambda: self.poder_comprar(p)), ("CANCELAR", None)],
                            apilados=True, alto=0.62)

    def desafio_cartel(self, ch):
        datos = self.gira_datos()
        es_hotel = ch["tipo"] == "hotel"
        tengo = gira_tiene_voucher(datos, "hotel" if es_hotel else "viaje", ch["region"])
        region = DESAFIO_NOMBRE_REGION[ch["region"]]
        voucher = ("voucher de hotel de %s" if es_hotel else "voucher de viaje en colectivo a %s") % region
        premio = ("Ya tenés el %s." % voucher) if tengo else "Si ganás: %s." % voucher
        detalle = "%s\nSi perdés: -%d puntos de tu carrera online · Tenés %d\nRival: %s · Modo difícil · Sin apuesta" % (
            premio, DESAFIO_PUNTOS_PIERDE, datos.get("puntos", 0), ch["perfil"])
        botones = [("JUGAR", lambda d=ch: self.desafio_arrancar(d))]
        if not tengo:
            botones.append(("COMPRAR VOUCHER · %d MONEDAS" % DESAFIO_PRECIO_VOUCHER, lambda d=ch: self.desafio_comprar(d)))
        botones.append(("CERRAR", None))
        if ch["id"] in DESAFIO_FOTO_B64:
            conversacion = ConversacionFoto(ch["id"], ch["frase"])
        else:
            conversacion = ConversacionDesafio(DESAFIO_LOOK[ch["id"]], ch["frase"])
        self.mostrar_cartel("DESAFÍO", ch["nombre"], True, detalle=detalle, extra=conversacion, botones=botones,
                            apilados=True, alto=0.58 + 0.085 * len(botones))

    # ---------- Encuentros en el viaje ----------
    def viaje_evento(self):
        """Te para alguien en el camino (una vez por región conquistada) y te da a elegir qué hacer."""
        self._viaje_avisado = False
        if getattr(self, "cartel_actual", None) is not None:
            return   # hay otro cartel abierto: te para la próxima vez que abras el mapa
        datos = self.gira_datos()
        v = datos["viaje"]
        vistos = [i for i in v.get("vistos", []) if any(e["id"] == i for e in VIAJE_EVENTOS)]
        libres = [e for e in VIAJE_EVENTOS if e["id"] not in vistos]
        if not libres:
            vistos, libres = [], list(VIAJE_EVENTOS)
        e = random.choice(libres)
        v["hechos"] = self.gira_conquistadas()
        v["vistos"] = vistos + [e["id"]]
        self.gira_guardar()
        botones = [(o["texto"], lambda i=i: self.viaje_elegir(e, i)) for i, o in enumerate(e["opciones"])]
        self.mostrar_cartel("EN EL CAMINO", e["nombre"], True,
                            detalle="Un encuentro en la ruta...", extra=ConversacionDesafio(e["look"], e["frase"]),
                            botones=botones, apilados=True, alto=0.58 + 0.085 * len(botones))

    def viaje_elegir(self, e, i):
        o = e["opciones"][i]
        if o.get("duelo"):
            ch = {"id": "ev_" + e["id"], "tipo": "evento", "region": "patagonia", "evento": e["id"], "opcion": i,
                  "nombre": e["nombre"], "perfil": o["duelo"], "lugar": "En el camino", "frase": e["frase"]}
            self.desafio_arrancar(ch)
            return
        texto = self._viaje_premiar(e, o, o["res"]) if o.get("postal") else o["res"]
        self._viaje_cartel_resultado(e, texto, bool(o.get("postal")))

    def _viaje_premiar(self, e, o, texto):
        """Entrega la postal del encuentro (y recarga el favor de la Familia si hay tarjeta); devuelve el texto completo."""
        datos = self.gira_datos()
        nueva = e["id"] not in datos["postales"]
        if nueva:
            datos["postales"][e["id"]] = int(time.time())
            self.gira_historial(datos, "Encuentro en el camino: %s (postal nueva)" % e["nombre"])
            texto += "\n\n¡Postal nueva! La ves en Gira > Mis pertenencias."
        else:
            texto += "\n\nEsa postal ya la tenías."
        if o.get("favor") and gira_tiene_tarjeta_mafia(datos):
            datos["mafia"]["favor"] = 1
            texto += "\nEl favor de la Familia se recargó."
        self.gira_guardar()
        return texto

    def _viaje_cartel_resultado(self, e, texto, con_postal):
        po = next((p for p in POSTALES if p["id"] == e["id"]), None)
        extra = PostalCard(po, True, POSTALES.index(po) + 1, len(POSTALES), height=dp(132)) if (con_postal and po) else None
        self.mostrar_cartel("EN EL CAMINO", e["nombre"], con_postal, detalle=texto, extra=extra,
                            botones=[("SEGUIR VIAJE", None)], alto=0.74 if extra else 0.52)

    def viaje_resolver(self, ch, gano):
        """Resultado del duelo de un encuentro del camino: ganar da la postal; perder no cuesta nada."""
        e = next((x for x in VIAJE_EVENTOS if x["id"] == ch["evento"]), None)
        if e is None:
            return []
        o = e["opciones"][ch["opcion"]]
        if not gano:
            return [o["pierde"]]
        return [self._viaje_premiar(e, o, o["gana"])]

    # ---------- La Familia: el campeón del año pasado ----------
    def mafia_encuentro(self):
        """Emboscada en Buenos Aires: el campeón del año pasado te frena antes de salir hacia la Patagonia."""
        if getattr(self, "cartel_actual", None) is not None:
            self._mafia_avisado = False   # hay otro cartel abierto: te para la próxima vez que abras el mapa
            return
        self.mafia_cartel(emboscada=True)

    def mafia_cartel(self, emboscada=False):
        ch = MAFIA_JEFE
        datos = self.gira_datos()
        tiene = gira_tiene_tarjeta_mafia(datos)
        if emboscada:
            conversacion = ConversacionMafia(ch["frase"], "escena")
            detalle = "Si ganás: la aprobación de la Familia y su tarjeta.\nModo difícil. Si no jugás... sos boleta."
            botones = [("JUGAR", lambda: self.mafia_arrancar()), ("ME VOY", None)]
            titulo, resultado = "¡ALTO AHÍ!", ch["nombre"]
        else:
            conversacion = ConversacionMafia(ch["frase_ficha"], "ficha")
            detalle = ("Ya tenés la aprobación de la Familia." if tiene else "Si ganás: la aprobación de la Familia y su tarjeta.\nSi perdés, no pasa nada: podés reintentar.")
            botones = [("JUGAR DE NUEVO" if tiene else "JUGAR", lambda: self.mafia_arrancar()), ("CERRAR", None)]
            titulo, resultado = "LA FAMILIA", ch["titulo"]
        self.mostrar_cartel(titulo, resultado, tiene, detalle=detalle, extra=conversacion, botones=botones, apilados=True, alto=0.95)

    # ---------- El Mago del Camino ----------
    def mago_encuentro(self):
        """Entre la Patagonia y Cuyo aparece el mago y te desafía."""
        if getattr(self, "cartel_actual", None) is not None:
            self._mago_avisado = False   # hay otro cartel abierto: te para la próxima vez que abras el mapa
            return
        ch = MAGO
        conversacion = ConversacionFoto("eliseo", ch["frase"])
        detalle = ("Si ganás una partida: aprendés el Poder del mago, elegir las 3 cartas de una mano. "
                   "Se usa UNA sola vez y solo en un campeonato de la Gira Nacional.\n"
                   "Modo difícil. Si perdés no pasa nada: podés reintentar.")
        self.mostrar_cartel("UN MAGO EN EL CAMINO", ch["nombre"], True, detalle=detalle, extra=conversacion,
                            botones=[("JUGAR", lambda: self.desafio_arrancar(MAGO)), ("ME VOY", None)],
                            apilados=True, alto=0.82)

    def mago_resolver(self, ch, gano):
        """Ganarle al mago enseña el poder (una vez); perder no cuesta nada."""
        datos = self.gira_datos()
        m = datos["mago"]
        if not gano:
            m["perdidas"] += 1
            self.gira_guardar()
            return [ch["pierde"]]
        m["ganadas"] += 1
        if not m["poder"]:
            m["poder"] = int(time.time())
            self.gira_historial(datos, "Aprendiste el Poder del mago (elegir tus 3 cartas)")
            avisos = [ch["gana"], "¡Aprendiste el Poder del mago! Lo podés usar UNA sola vez, en un campeonato de la Gira Nacional: vas a ver el botón «Poderes» al empezar una mano."]
        else:
            avisos = ["Le volviste a ganar al mago. Ya tenías su poder."]
        avisos += self.gira_revisar_hechas(datos) or []
        self.gira_guardar()
        return avisos

    # ---------- El Científico del Camino ----------
    def cientifico_encuentro(self):
        """Entre Cuyo y Mesopotamia aparece el científico y te desafía."""
        if getattr(self, "cartel_actual", None) is not None:
            self._cientifico_avisado = False   # hay otro cartel abierto: te para la próxima vez que abras el mapa
            return
        ch = CIENTIFICO
        conversacion = ConversacionFoto("cientifico", ch["frase"])
        detalle = ("Si ganás una partida: te regala los Lentes del científico, para ver las cartas del rival. "
                   "Se usan UNA sola vez, en cualquier lugar de la Gira Nacional.\n"
                   "Modo difícil. Si perdés no pasa nada: podés reintentar.")
        self.mostrar_cartel("UN CIENTÍFICO EN EL CAMINO", ch["nombre"], True, detalle=detalle, extra=conversacion,
                            botones=[("JUGAR", lambda: self.desafio_arrancar(CIENTIFICO)), ("ME VOY", None)],
                            apilados=True, alto=0.82)

    def cientifico_resolver(self, ch, gano):
        """Ganarle al científico te da los lentes (una vez); perder no cuesta nada."""
        datos = self.gira_datos()
        c = datos["cientifico"]
        if not gano:
            c["perdidas"] += 1
            self.gira_guardar()
            return [ch["pierde"]]
        c["ganadas"] += 1
        if not c["lentes"]:
            c["lentes"] = int(time.time())
            self.gira_historial(datos, "Ganaste los Lentes del científico (ver las cartas del rival)")
            avisos = [ch["gana"], "¡Tenés los Lentes del científico! Los podés usar UNA sola vez, en cualquier lugar de la Gira Nacional: vas a ver el botón «Poderes» al empezar una mano."]
        else:
            avisos = ["Le volviste a ganar al científico. Ya tenías sus lentes."]
        avisos += self.gira_revisar_hechas(datos) or []
        self.gira_guardar()
        return avisos

    # ---------- Lentes del científico: ver las cartas del rival (una vez, solo en Desafíos) ----------
    # Dónde valen los Lentes: en cualquier lugar de la Gira Nacional (campeonatos, misiones y Desafíos del camino).
    LENTES_TIPOS_DESAFIO = ("hotel", "colectivo", "mafia", "mago", "cientifico", "evento")

    def en_gira_nacional(self):
        """True si la partida es de la Gira Nacional: campeonato, misión o Desafío del camino (nunca online)."""
        if getattr(self, "modo_online", False):
            return False
        if getattr(self, "modo_torneo_priv", False):   # torneo privado con poderes: también contra los bots
            return bool((getattr(self, "tpriv", None) or {}).get("poderes"))
        if getattr(self, "modo_gira_torneo", False) or getattr(self, "mision_gira_activa", None):
            return True
        _da = getattr(self, "desafio_activo", None)
        return bool(_da) and _da.get("tipo") in self.LENTES_TIPOS_DESAFIO

    def lentes_permitidos(self):
        """Los lentes se usan UNA sola vez en toda la Gira y en cualquier lugar de la Gira Nacional (online: si los dos aceptaron poderes)."""
        if getattr(self, "modo_online", False):
            return self.online_poderes_activos() and gira_tiene_lentes(self.gira_datos())
        if getattr(self, "_lentes_prueba", False):   # partida de prueba del menú Pruebas (no gasta los lentes)
            return True
        return self.en_gira_nacional() and gira_tiene_lentes(self.gira_datos())

    def lentes_disponibles(self):
        """Se pueden usar al empezar una mano (antes de jugar o cantar nada); una vez usados se gastan para siempre."""
        if not self.lentes_permitidos() or getattr(self, "_lentes_usado", False):
            return False
        return (not self.mano_terminada and len(self.mano_jugador) == 3 and len(self.mano_ia) == 3
                and not self.bazas and self.carta_actual_jugador is None and self.carta_actual_ia is None
                and self.ia_canto is None and not self.canto_en_curso and self.envido_nivel == 0 and self.truco_valor == 1
                and self.puntos_jugador < PUNTOS_PARTIDA and self.puntos_ia < PUNTOS_PARTIDA)

    def _lentes_vigentes(self):
        """True si ya viste las cartas del rival con los lentes en ESTA mano (la IA conserva esas cartas)."""
        vistas = getattr(self, "_lentes_cartas", None)
        return bool(vistas) and len(self.mano_ia) == 3 and sorted(vistas) == sorted(self.mano_ia)

    def lentes_abrir(self, *_):
        """Pide confirmación (los lentes se gastan para siempre) y después muestra las cartas del rival."""
        if not self.lentes_disponibles():
            return
        self._pausar_ia_poder()   # la IA espera mientras decidís
        fondo = CartelFondo(orientation="vertical", padding=[dp(14), dp(14)], spacing=dp(10))
        fondo.add_widget(Label(text="LENTES DEL CIENTÍFICO", font_size="20sp", bold=True, size_hint_y=None, height=dp(34),
                               color=(0.55, 0.85, 0.98, 1)))
        fondo.add_widget(Label(text="Te dejan ver las cartas del rival en esta mano.\nSe usan UNA sola vez: después se gastan para siempre.",
                               font_size="15sp", halign="center", valign="middle", color=(0.96, 0.90, 0.75, 1)))
        fila = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(50), spacing=dp(10))
        boton_no = boton_oscuro("CANCELAR", "15sp")
        boton_ok = boton_oscuro("PONERME LOS LENTES", "15sp")
        fila.add_widget(boton_no)
        fila.add_widget(boton_ok)
        fondo.add_widget(fila)
        popup = Popup(title="", separator_height=0, background="", background_color=(0, 0, 0, 0),
                      content=fondo, size_hint=(0.92, 0.42), auto_dismiss=False)

        def cancelar(*_):
            popup.dismiss()
            self._poder_mago_reanudar()

        def confirmar(*_):
            popup.dismiss()
            self.lentes_aplicar()
        boton_no.bind(on_release=cancelar)
        boton_ok.bind(on_release=confirmar)
        popup.open()

    def lentes_aplicar(self):
        """Gasta los lentes y muestra las cartas que tiene el rival (online: se las pide al anfitrión)."""
        self.info_rival("lentes", self._lentes_resultado)

    def _lentes_resultado(self, info):
        cartas = [tuple(c) for c in info["cartas"]]
        self._lentes_usado = True
        self._lentes_cartas = list(cartas)   # si después usás el Poder del mago, la IA conserva estas cartas
        if not getattr(self, "_lentes_prueba", False):   # en el Desafío de verdad los lentes se gastan para siempre
            datos = self.gira_datos()
            datos["cientifico"]["usado"] = int(time.time())
            self.gira_historial(datos, "Usaste los Lentes del científico (viste las cartas del rival)")
            self.gira_guardar()
        self.actualizar_boton_poder()
        fondo = CartelFondo(orientation="vertical", padding=[dp(12), dp(12)], spacing=dp(8))
        fondo.add_widget(Label(text="LAS CARTAS DEL RIVAL", font_size="20sp", bold=True, size_hint_y=None, height=dp(34),
                               color=(0.55, 0.85, 0.98, 1)))
        cartas_fila = BoxLayout(orientation="horizontal", spacing=dp(8))
        for carta in cartas:
            ruta = self.imagenes.get(carta)
            if ruta and os.path.isfile(ruta):
                cartas_fila.add_widget(Image(source=ruta, fit_mode="contain"))
            else:
                cartas_fila.add_widget(Label(text=nombre_carta(carta).replace(" de ", "\nde\n"), font_size="16sp",
                                             halign="center", valign="middle", color=(1, 1, 1, 1)))
        fondo.add_widget(cartas_fila)
        cerrar = boton_oscuro("CERRAR LOS LENTES", "15sp")
        cerrar.size_hint_y = None
        cerrar.height = dp(50)
        fondo.add_widget(cerrar)
        popup = Popup(title="", separator_height=0, background="", background_color=(0, 0, 0, 0),
                      content=fondo, size_hint=(0.96, 0.6), auto_dismiss=False)

        def cerrar_lentes(*_):
            popup.dismiss()
            self._poder_mago_reanudar()
        cerrar.bind(on_release=cerrar_lentes)
        popup.open()

    # ---------- Investigación del detective: una pista sobre la fuerza de la mano rival (una vez; no ves las cartas) ----------
    def investigacion_permitido(self):
        """Se usa UNA sola vez en toda la Gira y en cualquier lugar de la Gira Nacional (online: si los dos aceptaron poderes)."""
        if getattr(self, "modo_online", False):
            return self.online_poderes_activos() and gira_tiene_investigacion(self.gira_datos())
        if getattr(self, "_invest_prueba", False):
            return True
        return self.en_gira_nacional() and gira_tiene_investigacion(self.gira_datos())

    def investigacion_disponible(self):
        """Se puede usar al empezar una mano (antes de jugar o cantar nada); una vez usada se gasta para siempre."""
        if not self.investigacion_permitido() or getattr(self, "_invest_usado", False):
            return False
        return (not self.mano_terminada and len(self.mano_jugador) == 3 and len(self.mano_ia) == 3
                and not self.bazas and self.carta_actual_jugador is None and self.carta_actual_ia is None
                and self.ia_canto is None and not self.canto_en_curso and self.envido_nivel == 0 and self.truco_valor == 1
                and self.puntos_jugador < PUNTOS_PARTIDA and self.puntos_ia < PUNTOS_PARTIDA)

    def investigacion_abrir(self, *_):
        """Pide confirmación (se gasta para siempre) y después da la pista."""
        if not self.investigacion_disponible():
            return
        self._pausar_ia_poder()   # la IA espera mientras decidís
        fondo = CartelFondo(orientation="vertical", padding=[dp(14), dp(14)], spacing=dp(10))
        fondo.add_widget(Label(text="INVESTIGACIÓN DEL DETECTIVE", font_size="20sp", bold=True, size_hint_y=None, height=dp(34),
                               color=(0.90, 0.68, 0.30, 1)))
        fondo.add_widget(Label(text="Te dice si la mano del rival es fuerte, media o débil. No ves sus cartas.\nSe usa UNA sola vez: después se gasta para siempre.",
                               font_size="15sp", halign="center", valign="middle", color=(0.96, 0.90, 0.75, 1)))
        fila = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(50), spacing=dp(10))
        boton_no = boton_oscuro("CANCELAR", "15sp")
        boton_ok = boton_oscuro("INVESTIGAR", "15sp")
        fila.add_widget(boton_no)
        fila.add_widget(boton_ok)
        fondo.add_widget(fila)
        popup = Popup(title="", separator_height=0, background="", background_color=(0, 0, 0, 0),
                      content=fondo, size_hint=(0.92, 0.42), auto_dismiss=False)

        def cancelar(*_):
            popup.dismiss()
            self._poder_mago_reanudar()

        def confirmar(*_):
            popup.dismiss()
            self.investigacion_aplicar()
        boton_no.bind(on_release=cancelar)
        boton_ok.bind(on_release=confirmar)
        popup.open()

    def investigacion_aplicar(self):
        """Gasta la investigación y muestra la pista sobre la mano del rival (online: se la pide al anfitrión)."""
        self.info_rival("investigacion", lambda info: self._investigacion_resultado(info["nivel"]))

    def _investigacion_resultado(self, nivel):
        self._invest_usado = True
        if not getattr(self, "_invest_prueba", False):
            datos = self.gira_datos()
            datos["detective"]["usado"] = int(time.time())
            self.gira_historial(datos, "Usaste la Investigación del detective (pista sobre la mano del rival)")
            self.gira_guardar()
        self.actualizar_boton_poder()
        detalle = {"fuerte": "Trae cartas de mucho peso.", "media": "Trae una mano pareja, con algo de peso.",
                   "débil": "Trae cartas bajas."}[nivel]
        color = {"fuerte": (0.95, 0.45, 0.40, 1), "media": (0.96, 0.78, 0.15, 1), "débil": (0.45, 0.85, 0.55, 1)}[nivel]
        fondo = CartelFondo(orientation="vertical", padding=[dp(14), dp(14)], spacing=dp(8))
        fondo.add_widget(Label(text="LA MANO DEL RIVAL", font_size="20sp", bold=True, size_hint_y=None, height=dp(34),
                               color=(0.90, 0.68, 0.30, 1)))
        fondo.add_widget(Label(text=nivel.upper(), font_size="34sp", bold=True, color=color))
        fondo.add_widget(Label(text=detalle, font_size="15sp", halign="center", valign="middle", size_hint_y=None, height=dp(40),
                               color=(0.96, 0.90, 0.75, 1)))
        cerrar = boton_oscuro("CERRAR", "15sp")
        cerrar.size_hint_y = None
        cerrar.height = dp(50)
        fondo.add_widget(cerrar)
        popup = Popup(title="", separator_height=0, background="", background_color=(0, 0, 0, 0),
                      content=fondo, size_hint=(0.92, 0.45), auto_dismiss=False)

        def cerrar_pista(*_):
            popup.dismiss()
            self._poder_mago_reanudar()
        cerrar.bind(on_release=cerrar_pista)
        popup.open()

    # ---------- Soplón, Espía y Escudo de envido ----------
    def online_poderes_activos(self):
        """Online: los poderes valen solo si LOS DOS jugadores dijeron que sí."""
        return bool(getattr(self, "modo_online", False) and getattr(self, "online_poderes_pref", False)
                    and getattr(self, "_rival_poderes", False))

    def online_tengo_poderes(self):
        """True si tenés algún poder que se pueda usar online y todavía no gastaste."""
        datos = self.gira_datos()
        return (any(poder_sin_gastar(datos, PODER_POR_ID[pid]) for pid in PODERES_ONLINE)
                or gira_tiene_investigacion(datos) or gira_tiene_lentes(datos))

    def online_enviar_pref_poderes(self):
        """Le avisa al rival si querés jugar con poderes y si tenés alguno para usar (se reenvía en cada mano)."""
        if getattr(self, "modo_online", False):
            pref = bool(getattr(self, "online_poderes_pref", False))
            self.online_enviar_evento("powers_pref", {"on": pref, "tiene": bool(pref and self.online_tengo_poderes())})

    def _ventana_hace_falta(self):
        return bool(self.online_poderes_activos()
                    and (self.online_tengo_poderes() or getattr(self, "_rival_tiene", False)))

    def online_extender_ventana(self, seg):
        """El rival abrió su menú de poderes: se alarga un poco la pausa para que no te adelantes."""
        if getattr(self, "_ventana_poderes", False):
            self._ventana_fin = max(self._ventana_fin, time.time() + seg)

    def online_iniciar_ventana_poderes(self):
        """Online con poderes: al empezar cada mano hay unos segundos en los que nadie canta ni juega, para que nadie se
        adelante al poder del otro. Si a los 0,8 s resulta que nadie tiene poderes para usar, se corta enseguida."""
        ev = getattr(self, "_ventana_ev", None)
        if ev is not None:
            ev.cancel()
        self._ventana_ev = None
        if not getattr(self, "modo_online", False) or not getattr(self, "online_poderes_pref", False):
            self._ventana_poderes = False
            return
        inicio = time.time()
        self._ventana_poderes = True
        self._ventana_fin = inicio + VENTANA_PODERES_SEG

        def cerrar():
            self._ventana_poderes = False
            e = getattr(self, "_ventana_ev", None)
            if e is not None:
                e.cancel()
            self._ventana_ev = None
            if str(self.estado.text).startswith("Poderes:"):
                self.estado.text = "Sos mano. Elegí carta." if self.turno == 0 else "El rival es mano; esperá su carta."
            self.actualizar_botones()

        def tick(_dt):
            if not getattr(self, "_ventana_poderes", False):
                return False
            ahora = time.time()
            if ahora >= self._ventana_fin or (ahora - inicio >= 0.8 and not self._ventana_hace_falta()):
                cerrar()
                return False
            self.estado.text = "Poderes: tenés %d s para usar uno antes de empezar la mano." % int(self._ventana_fin - ahora + 0.99)
        self._ventana_ev = Clock.schedule_interval(tick, 0.4)
        self.actualizar_botones()

    def canto_bloqueado(self, clase):
        """Online: Escudo de envido / Silencio del RIVAL. clase: 'envido' o 'truco'."""
        if not getattr(self, "modo_online", False):
            return False
        if getattr(self, "_ventana_poderes", False) or getattr(self, "_bloqueo_todo_rival", False):
            return True
        return clase == "envido" and getattr(self, "_bloqueo_envido_rival", False)

    def _pausar_ia_poder(self):
        """Contra la IA se frena su turno mientras elegís; online no se toca el reloj de la partida."""
        if not getattr(self, "modo_online", False):
            self.cancelar_timers()

    def info_calcular(self, kind, cartas):
        """Dato sobre la mano (de 3 cartas) del rival para los poderes de información."""
        if kind == "investigacion":
            return {"nivel": pista_fuerza_mano(cartas)}
        if kind == "soplon":
            return {"tiene": puntos_envido(cartas) >= 27}
        if kind == "espia":
            c = random.choice(cartas)
            return {"carta": [c[0], c[1]]}
        if kind == "halcon":
            c = max(cartas, key=fuerza)
            return {"carta": [c[0], c[1]]}
        if kind == "lentes":
            return {"cartas": [[c[0], c[1]] for c in cartas]}
        return None

    def info_rival(self, kind, listo):
        """Pide un dato de la mano del rival y llama a listo(dato). Contra la IA sale de sus cartas; online, el anfitrión
        lo calcula con las cartas que repartió y el invitado se lo pide por mensaje."""
        if getattr(self, "modo_online", False):
            self.online_pedir_info(kind, listo)
        else:
            listo(self.info_calcular(kind, [c for c in self.mano_ia if c]))

    def online_cartas_del_rival(self):
        """Anfitrión: las cartas del rival, mientras todavía no jugó ninguna."""
        c = getattr(self, "online_cartas_rival", None)
        if (int(getattr(self, "online_slot", 0) or 0) == 0 and c and len(c) == 3
                and int(getattr(self, "online_remote_cards_left", 0) or 0) == 3):
            return list(c)
        return None

    def online_pedir_info(self, kind, listo):
        if int(getattr(self, "online_slot", 0) or 0) == 0:
            cartas = self.online_cartas_del_rival()
            if not cartas:
                self.estado.text = "No se pudo consultar la mano del rival."
                self._poder_mago_reanudar()
                return
            listo(self.info_calcular(kind, cartas))
            return
        hand_id = int(self.online_hand_id)
        self._info_pendiente = {"kind": kind, "hand_id": hand_id, "listo": listo}
        self.estado.text = "Consultando…"
        self.online_enviar_evento("info_req", {"hand_id": hand_id, "kind": kind})

        def sin_respuesta(_dt):
            p = getattr(self, "_info_pendiente", None)
            if p and p["kind"] == kind and p["hand_id"] == hand_id:
                self._info_pendiente = None
                self.estado.text = "El rival no respondió. Probá de nuevo."
                self._poder_mago_reanudar()
        Clock.schedule_once(sin_respuesta, 8)

    def online_responder_info(self, datos):
        """Anfitrión: el invitado usó un poder de información. Su rival soy yo, así que el dato sale de MIS cartas.
        (Cuando el poder lo usa el anfitrión, el dato sale de las cartas que le repartió al invitado.)"""
        if int(getattr(self, "online_slot", 0) or 0) != 0 or not self.online_poderes_activos():
            return
        kind = str(datos.get("kind", ""))
        if kind not in ("investigacion", "soplon", "espia", "halcon", "lentes"):
            return
        cartas = list(self.mano_jugador_inicial or [])
        if len(cartas) != 3 or len(self.mano_jugador) != 3:
            return   # el anfitrión ya jugó una carta: el dato ya no vale
        self.online_enviar_evento("info_res", {"hand_id": int(self.online_hand_id), "kind": kind,
                                               "data": self.info_calcular(kind, cartas)})

    def online_recibir_info(self, datos):
        p = getattr(self, "_info_pendiente", None)
        if not p or p["kind"] != datos.get("kind") or p["hand_id"] != int(self.online_hand_id):
            return
        self._info_pendiente = None
        info = datos.get("data")
        if isinstance(info, dict):
            p["listo"](info)

    def online_recibir_poder(self, datos):
        """El rival usó un poder online: acá se aplica lo que nos afecta."""
        nombre = str(datos.get("name", ""))
        if nombre == "escudo":
            self._bloqueo_envido_rival = True
            self.estado.text = "El rival usó el Escudo de envido: en esta mano no podés cantar envido."
        elif nombre == "silencio":
            self._bloqueo_todo_rival = True
            self.estado.text = "El rival usó Silencio: en esta mano no podés cantar nada (solo aceptar o rechazar)."
        elif nombre == "chaleco":
            self._chaleco_rival = True
            self.estado.text = "El rival usó el Chaleco antibalas: si pierde esta mano, solo te da 1 punto."
        elif nombre == "ancho":
            self._ancho_hand = True
            self.estado.text = "El rival usó el Ancho de bolsillo: una de sus cartas vale como el 1 de espada."
        self.actualizar_botones()

    def poder_simple_permitido(self, pid):
        """Se usan UNA sola vez en toda la Gira. Contra la IA: en cualquier lugar de la Gira Nacional. Online: solo los
        de PODERES_ONLINE y solo si los dos jugadores aceptaron jugar con poderes."""
        if getattr(self, "modo_online", False):
            return (pid in PODERES_ONLINE and self.online_poderes_activos()
                    and poder_sin_gastar(self.gira_datos(), PODER_POR_ID[pid]))
        return self.en_gira_nacional() and poder_sin_gastar(self.gira_datos(), PODER_POR_ID[pid])

    def poder_simple_disponible(self, pid):
        """Se pueden usar al empezar una mano (antes de jugar o cantar nada)."""
        if not self.poder_simple_permitido(pid) or pid in getattr(self, "_poderes_simples_usados", set()):
            return False
        if pid == "chaleco":
            return self._poder_turno_ok()
        if pid == "baqueano" and self.turno != 1:
            return False   # el baqueano solo sirve cuando arranca el rival (es mano)
        return (not self.mano_terminada and len(self.mano_jugador) == 3 and len(self.mano_ia) == 3
                and not self.bazas and self.carta_actual_jugador is None and self.carta_actual_ia is None
                and self.ia_canto is None and not self.canto_en_curso and self.envido_nivel == 0 and self.truco_valor == 1
                and self.puntos_jugador < PUNTOS_PARTIDA and self.puntos_ia < PUNTOS_PARTIDA)

    def _poder_turno_ok(self):
        """Poderes de «tu turno»: antes de tirar tu carta y sin canto pendiente."""
        return (not self.mano_terminada and self.turno == 0 and self.carta_actual_jugador is None
                and not getattr(self, "canto_en_curso", False) and self.ia_canto is None and len(self.mano_jugador) >= 1
                and self.puntos_jugador < PUNTOS_PARTIDA and self.puntos_ia < PUNTOS_PARTIDA)

    def _carta_baqueano(self):
        """La carta que el baqueano dijo que el rival iba a tirar primero (la IA la juega de verdad)."""
        c = getattr(self, "_baqueano_carta", None)
        self._baqueano_carta = None
        if c and len(self.mano_ia) == 3 and c in self.mano_ia and not self.bazas:
            return c
        return None

    def _poder_visor_carta(self, carta):
        ruta = self.imagenes.get(carta)
        if ruta and os.path.isfile(ruta):
            return Image(source=ruta, fit_mode="contain")
        return Label(text=nombre_carta(carta).replace(" de ", "\nde\n"), font_size="22sp", halign="center",
                     valign="middle", color=(1, 1, 1, 1))

    def _poder_cartel(self, titulo, color, widgets, cerrar_texto="CERRAR", alto=0.45):
        """Cartel de un poder: título, el contenido y un botón para cerrar (después la partida sigue)."""
        fondo = CartelFondo(orientation="vertical", padding=[dp(14), dp(14)], spacing=dp(8))
        fondo.add_widget(Label(text=titulo, font_size="20sp", bold=True, size_hint_y=None, height=dp(34), color=color))
        for w in widgets:
            fondo.add_widget(w)
        cerrar = boton_oscuro(cerrar_texto, "15sp")
        cerrar.size_hint_y = None
        cerrar.height = dp(50)
        fondo.add_widget(cerrar)
        popup = Popup(title="", separator_height=0, background="", background_color=(0, 0, 0, 0),
                      content=fondo, size_hint=(0.92, alto), auto_dismiss=False)

        def cerrar_popup(*_):
            popup.dismiss()
            self._poder_mago_reanudar()
        cerrar.bind(on_release=cerrar_popup)
        popup.open()

    def poder_simple_abrir(self, pid):
        """Pide confirmación (el poder se gasta para siempre) y después lo aplica."""
        if not self.poder_simple_disponible(pid):
            return
        p = PODER_POR_ID[pid]
        self._pausar_ia_poder()   # la IA espera mientras decidís
        fondo = CartelFondo(orientation="vertical", padding=[dp(14), dp(14)], spacing=dp(10))
        fondo.add_widget(Label(text=p["nombre"].upper(), font_size="20sp", bold=True, size_hint_y=None, height=dp(34),
                               color=p["color"] + (1,)))
        fondo.add_widget(Label(text=p["desc"] + "\nSe usa UNA sola vez: después se gasta para siempre.",
                               font_size="15sp", halign="center", valign="middle", color=(0.96, 0.90, 0.75, 1)))
        fila = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(50), spacing=dp(10))
        boton_no = boton_oscuro("CANCELAR", "15sp")
        boton_ok = boton_oscuro("USARLO", "15sp")
        fila.add_widget(boton_no)
        fila.add_widget(boton_ok)
        fondo.add_widget(fila)
        popup = Popup(title="", separator_height=0, background="", background_color=(0, 0, 0, 0),
                      content=fondo, size_hint=(0.92, 0.42), auto_dismiss=False)

        def cancelar(*_):
            popup.dismiss()
            self._poder_mago_reanudar()

        def confirmar(*_):
            popup.dismiss()
            self.poder_simple_aplicar(pid)
        boton_no.bind(on_release=cancelar)
        boton_ok.bind(on_release=confirmar)
        popup.open()

    def poder_simple_aplicar(self, pid):
        """Soplón, espía y ojo de halcón necesitan un dato de la mano del rival: contra la IA sale de sus cartas y online se lo
        pide al otro celular (el poder se gasta recién cuando llega la respuesta). Los demás se aplican directo."""
        if pid in ("soplon", "espia", "halcon"):
            self.info_rival(pid, lambda info: self._poder_simple_aplicar_ya(pid, info))
        else:
            self._poder_simple_aplicar_ya(pid, None)

    def _poder_simple_aplicar_ya(self, pid, info=None):
        """Gasta el poder y aplica su efecto: soplón (avisa del envido), espía (una carta) o escudo (sin envido del rival)."""
        p = PODER_POR_ID[pid]
        self._poderes_simples_usados = set(getattr(self, "_poderes_simples_usados", set())) | {pid}
        datos = self.gira_datos()
        datos[p["clave"]]["usado"] = int(time.time())
        self.gira_historial(datos, "Usaste: %s" % p["nombre"])
        self.gira_guardar()
        self.actualizar_boton_poder()
        col = p["color"] + (1,)
        crema = (0.96, 0.90, 0.75, 1)
        if pid == "soplon":
            tiene = bool(info.get("tiene"))
            self._poder_cartel("EL SOPLÓN", col, [
                Label(text="¡TIENE ENVIDO!" if tiene else "NO TIENE ENVIDO", font_size="28sp", bold=True,
                      color=(0.95, 0.45, 0.40, 1) if tiene else (0.45, 0.85, 0.55, 1)),
                Label(text="Tiene 27 o más tantos. Ojo con el envido." if tiene else "No pasa de 26 tantos. Tranquilo con el envido.",
                      font_size="15sp", halign="center", valign="middle", size_hint_y=None, height=dp(44), color=crema)])
        elif pid == "espia":
            carta = tuple(info["carta"])
            ruta = self.imagenes.get(carta)
            if ruta and os.path.isfile(ruta):
                visor = Image(source=ruta, fit_mode="contain")
            else:
                visor = Label(text=nombre_carta(carta).replace(" de ", "\nde\n"), font_size="22sp", halign="center",
                              valign="middle", color=(1, 1, 1, 1))
            self._poder_cartel("EL ESPÍA", col, [
                Label(text="Una carta del rival:", font_size="15sp", size_hint_y=None, height=dp(26), color=crema),
                visor,
                Label(text=nombre_carta(carta), font_size="16sp", bold=True, size_hint_y=None, height=dp(30), color=crema)],
                alto=0.7)
        elif pid == "halcon":
            carta = tuple(info["carta"])
            self._poder_cartel("OJO DE HALCÓN", col, [
                Label(text="La carta más fuerte del rival:", font_size="15sp", size_hint_y=None, height=dp(26), color=crema),
                self._poder_visor_carta(carta),
                Label(text=nombre_carta(carta), font_size="16sp", bold=True, size_hint_y=None, height=dp(30), color=crema)],
                alto=0.7)
        elif pid == "baqueano":
            carta = self.elegir_carta_ia()
            self._baqueano_carta = carta   # la IA va a arrancar con esta carta
            self._poder_cartel("EL BAQUEANO", col, [
                Label(text="El rival va a arrancar con:", font_size="15sp", size_hint_y=None, height=dp(26), color=crema),
                self._poder_visor_carta(carta),
                Label(text=nombre_carta(carta), font_size="16sp", bold=True, size_hint_y=None, height=dp(30), color=crema)],
                alto=0.7)
        elif pid == "chaleco":
            self._chaleco = True   # vale hasta que termine esta mano
            self._poder_cartel("CHALECO ANTIBALAS", col, [
                Label(text="Si perdés esta mano jugando, el rival suma solo 1 punto,\naunque se haya cantado retruco o vale cuatro.\n"
                           "(El envido y el «no quiero» no cambian.)", font_size="15sp",
                      halign="center", valign="middle", color=crema)], alto=0.5)
        elif pid == "silencio":
            self._silencio = True   # la IA no puede cantar ni subir nada hasta la próxima mano
            self._poder_cartel("SILENCIO", col, [
                Label(text="El rival no podrá cantar nada en esta mano:\nni envido, ni truco, ni subir una apuesta.\n"
                           "Solo puede aceptar o rechazar lo que cantes vos.", font_size="16sp",
                      halign="center", valign="middle", color=crema)], alto=0.5)
        elif pid == "escudo":
            self._escudo_envido = True   # la IA no abre envido hasta la próxima mano
            self._poder_cartel("ESCUDO DE ENVIDO", col, [
                Label(text="El rival no podrá cantar envido en esta mano.\nVos sí podés cantarlo.", font_size="16sp",
                      halign="center", valign="middle", color=crema)])

        if getattr(self, "modo_online", False) and pid in ("escudo", "silencio", "chaleco"):
            self.online_enviar_evento("power", {"hand_id": int(self.online_hand_id), "name": pid})

    # ---------- Ancho de bolsillo: una carta tuya pasa a valer como el 1 de espada ----------
    def ancho_permitido(self):
        """Se usa UNA sola vez en toda la Gira y en cualquier lugar de la Gira Nacional (nunca online)."""
        return self.poder_simple_permitido("ancho")

    def ancho_cartas(self):
        """Cartas de tu mano que pueden pasar a valer como el 1 de espada (todas menos el 1 de espada de verdad)."""
        return [c for c in self.mano_jugador if c != (1, "espada")]

    def ancho_disponible(self):
        """Se usa en tu turno, antes de tirar la carta: esa carta vale como el 1 de espada en esa baza."""
        if not self.ancho_permitido() or "ancho" in getattr(self, "_poderes_simples_usados", set()):
            return False
        return (not self.mano_terminada and self.turno == 0 and self.carta_actual_jugador is None
                and not getattr(self, "canto_en_curso", False) and self.ia_canto is None
                and bool(self.ancho_cartas())
                and self.puntos_jugador < PUNTOS_PARTIDA and self.puntos_ia < PUNTOS_PARTIDA)

    def ancho_abrir(self, *_):
        """Muestra tus cartas para elegir cuál pasa a valer como el 1 de espada."""
        if not self.ancho_disponible():
            return
        self._pausar_ia_poder()
        fondo = CartelFondo(orientation="vertical", padding=[dp(14), dp(14)], spacing=dp(8))
        fondo.add_widget(Label(text="ANCHO DE BOLSILLO", font_size="20sp", bold=True, size_hint_y=None, height=dp(34),
                               color=PODER_POR_ID["ancho"]["color"] + (1,)))
        fondo.add_widget(Label(text="Elegí la carta que pasa a valer como el 1 de espada.\nSe usa UNA sola vez.",
                               font_size="14sp", halign="center", valign="middle", size_hint_y=None, height=dp(44),
                               color=(0.96, 0.90, 0.75, 1)))
        fila = BoxLayout(orientation="horizontal", spacing=dp(8))
        popup = Popup(title="", separator_height=0, background="", background_color=(0, 0, 0, 0),
                      content=fondo, size_hint=(0.96, 0.62), auto_dismiss=False)

        def elegir(carta):
            popup.dismiss()
            self.ancho_aplicar(carta)
        for carta in self.ancho_cartas():
            ruta = self.imagenes.get(carta)
            if ruta and os.path.isfile(ruta):
                t = CartaTocable(source=ruta, fit_mode="contain")
            else:
                t = Button(text=nombre_carta(carta).replace(" de ", "\nde\n"), font_size="16sp", background_color=COLOR_BOTON,
                           color=(1, 1, 1, 1))
            t.bind(on_release=lambda _w, c=carta: elegir(c))
            fila.add_widget(t)
        fondo.add_widget(fila)
        boton_no = boton_oscuro("CANCELAR", "15sp")
        boton_no.size_hint_y = None
        boton_no.height = dp(50)

        def cancelar(*_):
            popup.dismiss()
            self._poder_mago_reanudar()
        boton_no.bind(on_release=cancelar)
        fondo.add_widget(boton_no)
        popup.open()

    def ancho_aplicar(self, carta):
        """Esa carta pasa a ser el 1 de espada (solo para ganar la baza; los tantos del envido no cambian)."""
        if carta not in self.mano_jugador:
            return
        i = self.mano_jugador.index(carta)
        self.mano_jugador[i] = (1, "espada")
        self._prob_cache = None
        self._ancho_hand = True   # online: en esta mano el 1 de espada puede repetirse (el del rival y el tuyo)
        if getattr(self, "modo_online", False):
            self.online_enviar_evento("power", {"hand_id": int(self.online_hand_id), "name": "ancho"})
        self._poderes_simples_usados = set(getattr(self, "_poderes_simples_usados", set())) | {"ancho"}
        datos = self.gira_datos()
        datos["ancho"]["usado"] = int(time.time())
        self.gira_historial(datos, "Usaste el Ancho de bolsillo (%s pasó a valer como el 1 de espada)" % nombre_carta(carta))
        self.gira_guardar()
        self.mostrar_mano()
        self.actualizar_boton_poder()
        self.actualizar_botones()
        self.estado.text = "Ancho de bolsillo: tu %s ahora vale como el 1 de espada. ¡Tirala!" % nombre_carta(carta)

    # ---------- Poder del mago: elegir las 3 cartas de una mano ----------
    def poder_mago_permitido(self):
        """El poder se usa UNA sola vez en toda la Gira y solo en un campeonato de la Gira Nacional (nunca online)."""
        if getattr(self, "modo_online", False):
            return False
        if getattr(self, "_poder_prueba", False):   # partida de prueba del menú Pruebas (no gasta el poder)
            return True
        return bool(getattr(self, "modo_gira_torneo", False)) and gira_tiene_poder_mago(self.gira_datos())

    def poder_mago_disponible(self):
        """Se puede usar al empezar una mano (antes de jugar o cantar nada); una vez usado se gasta para siempre."""
        if not self.poder_mago_permitido() or getattr(self, "_poder_mago_usado", False):
            return False
        return (not self.mano_terminada and len(self.mano_jugador) == 3 and len(self.mano_ia) == 3
                and not self.bazas and self.carta_actual_jugador is None and self.carta_actual_ia is None
                and self.ia_canto is None and not self.canto_en_curso and self.envido_nivel == 0 and self.truco_valor == 1
                and self.puntos_jugador < PUNTOS_PARTIDA and self.puntos_ia < PUNTOS_PARTIDA)

    def poderes_lista(self):
        """Poderes que tenés en esta partida y todavía no gastaste: [(clave, título, ¿se puede usar ahora?)]."""
        lista = []
        if self.poder_mago_permitido() and not getattr(self, "_poder_mago_usado", False):
            lista.append(("mago", "Poder del mago: elegir mis 3 cartas", self.poder_mago_disponible()))
        if self.lentes_permitidos() and not getattr(self, "_lentes_usado", False):
            lista.append(("lentes", "Lentes del científico: ver las cartas del rival", self.lentes_disponibles()))
        if self.investigacion_permitido() and not getattr(self, "_invest_usado", False):
            lista.append(("investigacion", "Investigación del detective: pista sobre su mano", self.investigacion_disponible()))
        for _pid, _titulo in (("soplon", "El soplón: ¿tiene envido?"), ("espia", "El espía: ver 1 carta del rival"),
                              ("escudo", "Escudo de envido: el rival no lo canta"), ("silencio", "Silencio: el rival no puede cantar"),
                              ("halcon", "Ojo de halcón: su carta más fuerte"), ("baqueano", "El baqueano: su primera carta"),
                              ("chaleco", "Chaleco antibalas: perder cuesta 1 punto")):
            if self.poder_simple_permitido(_pid) and _pid not in getattr(self, "_poderes_simples_usados", set()):
                lista.append((_pid, _titulo, self.poder_simple_disponible(_pid)))
        if self.ancho_permitido() and "ancho" not in getattr(self, "_poderes_simples_usados", set()):
            lista.append(("ancho", "Ancho de bolsillo: una carta vale como el 1 de espada", self.ancho_disponible()))
        return lista

    def poderes_disponibles(self):
        return [p for p in self.poderes_lista() if p[2]]

    def actualizar_boton_poder(self):
        b = getattr(self, "btn_poder", None)
        if b is None:
            return
        lista = self.poderes_lista()
        b.height = dp(36) if lista else 0
        b.opacity = 1 if lista else 0
        b.disabled = not any(p[2] for p in lista)
        b.text = "Poderes"

    def poderes_abrir(self, *_):
        """Menú para elegir qué poder usar. Se pueden usar los dos en la misma mano (mejor primero el mago y después los lentes)."""
        disponibles = self.poderes_disponibles()
        if not disponibles:
            return
        self._pausar_ia_poder()   # la IA espera mientras elegís
        if getattr(self, "modo_online", False):
            self.online_extender_ventana(4)   # yo también tengo más tiempo mientras elijo
            self.online_enviar_evento("power_hold", {"hand_id": int(self.online_hand_id)})   # y le pido al rival que espere
        fondo = CartelFondo(orientation="vertical", padding=[dp(14), dp(14)], spacing=dp(10))
        fondo.add_widget(Label(text="PODERES", font_size="22sp", bold=True, size_hint_y=None, height=dp(34),
                               color=(0.96, 0.78, 0.15, 1)))
        pista = Label(text="Cada poder se usa UNA sola vez.\nPodés usar más de uno en la misma mano.",
                      font_size="13sp", halign="center", valign="middle", size_hint_y=None, height=dp(44),
                      color=(0.96, 0.90, 0.75, 1))
        pista.bind(size=lambda w, s: setattr(w, "text_size", (s[0], None)))
        fondo.add_widget(pista)
        popup = Popup(title="", separator_height=0, background="", background_color=(0, 0, 0, 0),
                      content=fondo, size_hint=(0.92, None), auto_dismiss=False,
                      height=dp(28 + 34 + 44 + 50 * (len(disponibles) + 1) + 10 * (len(disponibles) + 3)))

        def elegir(clave):
            popup.dismiss()
            if clave == "mago":
                self.poder_mago_abrir()
            elif clave == "investigacion":
                self.investigacion_abrir()
            elif clave in ("soplon", "espia", "escudo", "silencio", "halcon", "baqueano", "chaleco"):
                self.poder_simple_abrir(clave)
            elif clave == "ancho":
                self.ancho_abrir()
            else:
                self.lentes_abrir()

        for clave, titulo, _ok in disponibles:
            b = boton_oscuro(titulo, "15sp")
            b.size_hint_y = None
            b.height = dp(50)
            b.bind(on_release=lambda _b, c=clave: elegir(c))
            fondo.add_widget(b)
        boton_no = boton_oscuro("CANCELAR", "15sp")
        boton_no.size_hint_y = None
        boton_no.height = dp(50)

        def cancelar(*_):
            popup.dismiss()
            self._poder_mago_reanudar()
        boton_no.bind(on_release=cancelar)
        fondo.add_widget(boton_no)
        popup.open()

    def poder_mago_abrir(self, *_):
        if not self.poder_mago_disponible():
            return
        self.cancelar_timers()   # la IA espera mientras elegís
        elegidas = []
        celdas = {}
        # Si ya viste las cartas del rival con los lentes en esta mano, esas cartas no se pueden elegir (la IA las conserva).
        bloqueadas = set(self.mano_ia) if self._lentes_vigentes() else set()
        fondo = CartelFondo(orientation="vertical", padding=[dp(10), dp(10)], spacing=dp(6))
        fondo.add_widget(Label(text="PODER DEL MAGO", font_size="22sp", bold=True, size_hint_y=None, height=dp(32),
                               color=(0.80, 0.66, 0.98, 1)))
        contador = Label(text="", font_size="14sp", size_hint_y=None, height=dp(40), halign="center", valign="middle",
                         color=(0.96, 0.90, 0.75, 1))
        fondo.add_widget(contador)
        cuadro = GridLayout(cols=5, spacing=dp(4), size_hint_y=None)
        boton_ok = boton_oscuro("USAR EL PODER", "15sp")
        boton_no = boton_oscuro("CANCELAR", "15sp")

        def refrescar():
            for carta, w in celdas.items():
                w.poner(carta in elegidas)
            contador.text = ("Tocá 3 cartas para tu mano (%d/3)" % len(elegidas)
                             + ("\nLas apagadas son las del rival" if bloqueadas else ""))
            boton_ok.disabled = len(elegidas) != 3

        def tocar(carta):
            if carta in bloqueadas:
                return
            if carta in elegidas:
                elegidas.remove(carta)
            elif len(elegidas) < 3:
                elegidas.append(carta)
            refrescar()

        for palo in PALOS:
            for n in NUMEROS:
                carta = (n, palo)
                ruta = self.imagenes.get(carta)
                w = CartaElegible(carta, source=ruta if ruta and os.path.isfile(ruta) else "")
                w.bind(on_release=lambda _w, c=carta: tocar(c))
                if carta in bloqueadas:
                    w.opacity = 0.3
                celdas[carta] = w
                cuadro.add_widget(w)

        def ajustar(*_):
            ancho = max(1.0, (cuadro.width - cuadro.spacing[0] * 4) / 5.0)
            alto = ancho * 1.47
            cuadro.row_force_default = True
            cuadro.row_default_height = alto
            cuadro.height = alto * 8 + cuadro.spacing[1] * 7
        cuadro.bind(width=ajustar)
        ajustar()
        scroll = ScrollView(do_scroll_x=False)
        scroll.add_widget(cuadro)
        fondo.add_widget(scroll)
        fila = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(50), spacing=dp(10))
        fila.add_widget(boton_no)
        fila.add_widget(boton_ok)
        fondo.add_widget(fila)
        popup = Popup(title="", separator_height=0, background="", background_color=(0, 0, 0, 0),
                      content=fondo, size_hint=(0.96, 0.92), auto_dismiss=False)

        def cancelar(*_):
            popup.dismiss()
            self._poder_mago_reanudar()

        def confirmar(*_):
            if len(elegidas) != 3:
                return
            popup.dismiss()
            self.poder_mago_aplicar(list(elegidas))
        boton_no.bind(on_release=cancelar)
        boton_ok.bind(on_release=confirmar)
        refrescar()
        popup.open()

    def _poder_mago_reanudar(self):
        """Si la IA era mano y todavía no jugó, retoma su turno después de elegir (o cancelar)."""
        if (not getattr(self, "modo_online", False) and not self.mano_terminada and self.turno == 1
                and self.carta_actual_ia is None and len(self.mano_ia) == 3 and self.ia_canto is None):
            self.esperando_ia = True
            _extra = 3.5 if self.poderes_disponibles() else 0.0   # si queda otro poder, la IA te da unos segundos más
            self.programar(self.jugar_ia, self.demora_ia("jugar") + _extra)
        self.actualizar_botones()

    def poder_mago_aplicar(self, cartas):
        """Tu mano pasa a ser las 3 cartas elegidas; la IA recibe 3 al azar de las que quedan."""
        self._poder_mago_usado = True
        if not getattr(self, "_poder_prueba", False):   # en el campeonato de verdad el poder se gasta para siempre
            datos = self.gira_datos()
            datos["mago"]["usado"] = int(time.time())
            self.gira_historial(datos, "Usaste el Poder del mago (elegiste tus 3 cartas)")
            self.gira_guardar()
        if self._lentes_vigentes():
            ia = list(self.mano_ia)   # ya le viste las cartas con los lentes: la IA las conserva
        else:
            resto = [(n, p) for p in PALOS for n in NUMEROS if (n, p) not in cartas]
            random.shuffle(resto)
            ia = resto[:3]
        self.mano_jugador = list(cartas)
        self.mano_ia = ia
        self.mano_jugador_inicial = list(self.mano_jugador)
        self.mano_ia_inicial = list(self.mano_ia)
        self._prob_cache = None
        self.mostrar_mano()
        self.mostrar_dorso()
        self.estado.text = "El mago te dio las cartas que elegiste. El poder se gastó. ¡A jugar!" if self.turno == 0 else "El mago te dio tus cartas. La computadora es mano."
        if self.lentes_disponibles():
            self.estado.text += " ¿Usás también los Lentes del científico?"
        self._poder_mago_reanudar()

    def mafia_arrancar(self):
        self.desafio_arrancar(MAFIA_JEFE)

    def mafia_resolver(self, ch, gano):
        """Ganarle al campeón da la aprobación de la Familia (una vez) y su tarjeta; perder no cuesta nada."""
        datos = self.gira_datos()
        m = datos.setdefault("mafia", {"aprobado": 0, "ganadas": 0, "perdidas": 0})
        if not gano:
            m["perdidas"] = int(m.get("perdidas", 0)) + 1
            self.gira_guardar()
            return [ch["pierde"]]
        m["ganadas"] = int(m.get("ganadas", 0)) + 1
        if not m.get("aprobado"):
            m["aprobado"] = int(time.time())
            m["favor"] = 1
            self.gira_historial(datos, "Ganaste la aprobación de la Familia (tarjeta de %s)" % ch["nombre"])
            avisos = [ch["gana"], "¡Conseguiste la tarjeta de la Familia! Tiene un favor: si perdés un torneo de región, cubre tu voucher de hotel. La ves en Gira > Mis pertenencias."]
        else:
            avisos = ["Le volviste a ganar a %s. Ya tenías la aprobación de la Familia." % ch["nombre"]]
        avisos += self.gira_revisar_hechas(datos) or []
        self.gira_guardar()
        return avisos

    def desafio_comprar(self, ch):
        """Compra el voucher (de hotel o de viaje, según el rival) sin jugar, por DESAFIO_PRECIO_VOUCHER monedas."""
        region = DESAFIO_NOMBRE_REGION[ch["region"]]
        es_hotel = ch["tipo"] == "hotel"
        clave = desafio_clave_voucher(ch)
        voucher = ("voucher de hotel de %s" if es_hotel else "voucher de viaje a %s") % region
        datos = self.gira_datos()
        if gira_tiene_voucher(datos, "hotel" if es_hotel else "viaje", ch["region"]):
            self.online_aviso("Ya tenés el %s." % voucher, "Desafío")
            return
        saldo = getattr(self, "saldo", None) or 0
        if not self.tiene_cuenta() or saldo < DESAFIO_PRECIO_VOUCHER:
            self.online_aviso("Para comprar el %s necesitás una cuenta online y %d monedas.\nTenés %d."
                              % (voucher, DESAFIO_PRECIO_VOUCHER, saldo), "Desafío")
            return

        def cobrado():
            self.reclamar_apuesta("perder", silencioso=True)   # las monedas retenidas quedan cobradas
            d = self.gira_datos()
            d.setdefault("vouchers", {})[clave] = int(time.time())
            d.setdefault("compradas", {})[clave] = 1   # comprado: no cuenta como victoria para el álbum
            self.gira_historial(d, "Compraste el %s" % voucher)
            self.gira_revisar_hechas(d)
            self.gira_guardar()
            self.mostrar_cartel("VOUCHER", "¡Voucher de %s!" % ("hotel" if es_hotel else "viaje"), True,
                                detalle="Pagaste %d monedas.\n%s" % (DESAFIO_PRECIO_VOUCHER, (
                                    "Ya tenés dónde quedarte en %s." % region) if es_hotel else
                                    "Ya podés viajar en colectivo a %s." % region),
                                botones=[("ACEPTAR", lambda: self.cambiar_pantalla(self.build_desafios()))], alto=0.42)
        self.abrir_apuesta("torneo", DESAFIO_PRECIO_VOUCHER, cobrado)

    def poder_comprar(self, p):
        """Compra un poder (50, 100 o 150 monedas según su sección; con la oferta del día). El servidor fija y cobra el precio.
        Se usa una sola vez; gastado, se puede comprar otro. No toca la apuesta de un campeonato abierto."""
        datos = self.gira_datos()
        if poder_sin_gastar(datos, p):
            self.online_aviso("Ya tenés el %s sin usar." % p["nombre"], "Poderes")
            return
        saldo = getattr(self, "saldo", None) or 0
        precio = precio_poder(p)
        if not self.tiene_cuenta() or saldo < precio:
            self.online_aviso("Para comprar el %s necesitás una cuenta online y %d monedas.\nTenés %d." % (p["nombre"], precio, saldo), "Poderes")
            return
        if getattr(self, "_comprando_poder", False):
            return
        self._comprando_poder = True
        self.online_aviso("Comprando…\n(si el servidor estaba dormido puede tardar hasta un minuto)", "Poderes")
        perfil = self.perfil_usuario

        def ok(resp):
            self._comprando_poder = False
            self.cerrar_aviso()
            self.fijar_saldo(resp.get("coins"))
            pagado = int(resp.get("pago", resp.get("precio", precio)))
            d = self.gira_datos()
            m = d.setdefault(p["clave"], {})
            m[p["campo"]] = int(time.time())
            m["usado"] = 0
            regalo = poder_regalo_2x1(d, p) if resp.get("regalo") else None
            if regalo:
                mr = d.setdefault(regalo["clave"], {})
                mr[regalo["campo"]] = int(time.time())
                mr["usado"] = 0
            self.gira_historial(d, "Compraste el %s" % p["nombre"] + ((" y te regalaron: %s" % regalo["nombre"]) if regalo else ""))
            self.gira_revisar_hechas(d)
            self.gira_guardar()
            self.mostrar_cartel("PODER", "¡%s!" % p["nombre"], True,
                                detalle="Pagaste %d monedas.\n%s%s" % (pagado, p["uso"], ("\n¡2x1! Te regalaron: %s." % regalo["nombre"]) if regalo else ""),
                                botones=[("ACEPTAR", lambda: self.cambiar_pantalla(self.build_poder_ficha(p)))], alto=0.5)

        def fallo(mensaje, _codigo=None):
            self._comprando_poder = False
            self.online_aviso("No se pudo comprar: " + mensaje, "Poderes")
        # el mismo `evento` en un reintento no vuelve a cobrar; el servidor ignora el precio del celular si no coincide con el suyo
        self.api("/poderes/comprar", {"id": perfil["id"], "token": perfil["token"], "poder": p["id"],
                                      "evento": secrets.token_hex(12), "precio": precio}, ok=ok, fallo=fallo)

    def desafio_arrancar(self, ch):
        """Arranca la partida contra el personaje elegido (sin apuesta)."""
        def ir(_dt):
            self._mision_pendiente = None
            self._desafio_pendiente = ch
            self.apuesta_ticket = None
            self._arrancar_individual()
        Clock.schedule_once(ir, 0.05)   # el cartel se cierra primero y recién después cambia la pantalla

    # ---------- Truco del día ----------
    def truco_dia_estado_texto(self):
        """Resumen corto del estado de hoy (se muestra en el menú y en el cartel)."""
        d = self.gira_datos()["diario"]
        if d["fecha"] == diario_fecha(0) and d["estado"]:
            return {"ganado": "Hoy ya lo ganaste", "perdido": "Hoy ya lo jugaste",
                    "jugando": "Hoy lo dejaste a medias"}[d["estado"]]
        return "Disponible hoy"

    def truco_dia_cartel(self, *_):
        datos = self.gira_datos()
        d = datos["diario"]
        ch = diario_rival()
        racha = diario_racha_vigente(d)
        hoy_jugado = d["fecha"] == diario_fecha(0) and bool(d["estado"])
        premio = DIARIO_PUNTOS_BASE + DIARIO_PUNTOS_RACHA * min(racha, DIARIO_RACHA_TOPE) \
            if d.get("ultima") == diario_fecha(-1) else DIARIO_PUNTOS_BASE
        if d.get("ultima") == diario_fecha(0):
            premio = 0
        lineas = ["Rival de hoy: %s\n«%s»" % (ch["nombre"], ch["frase"]),
                  "IA extrema · Una sola partida por día · Sin apuesta",
                  "Premio: +%d puntos para el ranking online (si ganás)" % premio if premio else "Hoy ya cobraste tus puntos.",
                  "Racha: %d día%s seguido%s · Mejor: %d · Ganados: %d de %d" % (
                      racha, "" if racha == 1 else "s", "" if racha == 1 else "s", d["mejor"], d["ganados"], d["jugados"])]
        if not self.tiene_cuenta():
            lineas.append("Necesitás una cuenta online para que los puntos entren al ranking.")
        if hoy_jugado:
            lineas.append("%s. Volvé mañana: cambia el rival." % self.truco_dia_estado_texto())
        botones = [] if hoy_jugado else [("JUGAR", lambda: self.truco_dia_arrancar())]
        botones.append(("CERRAR", None))
        self.mostrar_cartel("TRUCO DEL DÍA", ch["nombre"], d["estado"] != "perdido", detalle="\n\n".join(lineas),
                            botones=botones, apilados=True, alto=0.78 if not hoy_jugado else 0.74)

    def truco_dia_arrancar(self):
        """Gasta el intento de hoy apenas empieza (salirse a mitad de partida cuenta como perdida) y arranca el duelo."""
        datos = self.gira_datos()
        d = datos["diario"]
        hoy = diario_fecha(0)
        if d["fecha"] == hoy and d["estado"]:
            self.truco_dia_cartel()
            return
        d["fecha"], d["estado"] = hoy, "jugando"
        d["jugados"] += 1
        self.gira_historial(datos, "Empezaste el Truco del día")
        self.gira_guardar()
        self.desafio_arrancar(diario_rival())

    def truco_dia_resolver(self, ch, gano):
        """Resultado del Truco del día: ganar suma puntos (con bonus por racha) al ranking online; perder no descuenta."""
        datos = self.gira_datos()
        d = datos["diario"]
        hoy = diario_fecha(0)
        d["fecha"] = hoy
        if not gano:
            d["estado"] = "perdido"
            d["racha"] = 0
            self.gira_historial(datos, "Perdiste el Truco del día con %s" % ch["nombre"])
            self.gira_guardar()
            return ["Hoy no pudo ser: %s es durísimo. Mañana hay otro rival y otra chance." % ch["nombre"]]
        racha = int(d["racha"]) + 1 if d.get("ultima") == diario_fecha(-1) else 1
        d.update(estado="ganado", ultima=hoy, racha=racha)
        d["mejor"] = max(int(d["mejor"]), racha)
        d["ganados"] += 1
        self.gira_semana(datos)["truco"] += 1   # cuenta para el desafío semanal
        puntos = DIARIO_PUNTOS_BASE + DIARIO_PUNTOS_RACHA * min(racha - 1, DIARIO_RACHA_TOPE)
        d["puntos"] += puntos
        datos["puntos"] += puntos
        datos["pend_diario"].append({"evento": secrets.token_hex(12), "puntos": puntos, "fecha": hoy})
        self.gira_historial(datos, "Ganaste el Truco del día a %s (+%d pts)" % (ch["nombre"], puntos))
        avisos = ["¡Le ganaste a %s! +%d puntos para el ranking online." % (ch["nombre"], puntos),
                  "Racha: %d día%s seguido%s." % (racha, "" if racha == 1 else "s", "" if racha == 1 else "s")]
        self.gira_guardar()
        self.gira_enviar_pendientes()
        return avisos

    def gira_encolar_puntos(self, datos, logro):
        """Deja en cola un premio de puntos (Ruleta, personaje del día, desafío semanal) para informarlo al servidor."""
        datos["pend_periodico"].append({"evento": secrets.token_hex(12), "logro": logro})

    def gira_enviar_periodicos(self):
        """Informa al servidor los premios de puntos de la Ruleta, el personaje del día y los desafíos semanales (uno por uno).
        Se mandan como el logro «ruleta_50», «personaje_75», «semanal_truco»...: el servidor fija los puntos y el tope por período.
        Si todavía no los acepta, quedan en cola y se reintentan."""
        if not self.tiene_cuenta() or getattr(self, "_periodico_enviando", False):
            return
        datos = self.gira_datos()
        if not datos["sync"] or not datos["pend_periodico"]:
            return
        perfil = self.perfil_usuario
        primero = datos["pend_periodico"][0]
        self._periodico_enviando = True

        def listo(*_):
            self._periodico_enviando = False
            d = self.gira_datos()   # datos frescos (el de arriba ya quedó viejo)
            d["pend_periodico"] = [p for p in d["pend_periodico"] if p.get("evento") != primero["evento"]]
            self.gira_guardar()
            if d["pend_periodico"]:
                self.gira_enviar_periodicos()
            else:
                self.gira_refrescar_ranking()

        def fallo(mensaje="", codigo=None):
            self._periodico_enviando = False
            self.gira_error_envio = "premio: %s (%s)" % (str(mensaje)[:60], codigo)
        self.api("/gira/logro", {"id": perfil["id"], "token": perfil["token"],
                                 "nombre": perfil.get("nombre", "Jugador"), "club": perfil.get("club", ""),
                                 "evento": primero["evento"], "logro": primero["logro"]}, ok=listo, fallo=fallo)

    def gira_enviar_diario(self):
        """Informa al servidor los puntos del Truco del día (uno por uno). Va en una cola aparte: si el servidor todavía
        no los acepta, quedan pendientes y se reintentan más tarde sin trabar los demás envíos."""
        if not self.tiene_cuenta() or getattr(self, "_diario_enviando", False):
            return
        datos = self.gira_datos()
        if not datos["sync"] or not datos["pend_diario"]:
            return
        perfil = self.perfil_usuario
        primero = datos["pend_diario"][0]
        self._diario_enviando = True

        def listo(*_):
            self._diario_enviando = False
            d = self.gira_datos()   # datos frescos (el de arriba ya quedó viejo)
            d["pend_diario"] = [p for p in d["pend_diario"] if p.get("evento") != primero["evento"]]
            self.gira_guardar()
            if d["pend_diario"]:
                self.gira_enviar_diario()
            else:
                self.gira_refrescar_ranking()

        def fallo(mensaje="", codigo=None):
            self._diario_enviando = False
            self.gira_error_envio = "diario: %s (%s)" % (str(mensaje)[:60], codigo)
        self.api("/gira/logro", {"id": perfil["id"], "token": perfil["token"],
                                 "nombre": perfil.get("nombre", "Jugador"), "club": perfil.get("club", ""),
                                 "evento": primero["evento"], "logro": DIARIO_LOGRO_ID}, ok=listo, fallo=fallo)   # fecha y premio los fija el servidor

    def desafio_resolver(self, ch, gano):
        """Resultado del desafío: ganar da el voucher del rival (hotel o viaje, una vez); perder descuenta puntos de la carrera online."""
        if ch.get("tipo") == "mafia":
            return self.mafia_resolver(ch, gano)
        if ch.get("tipo") == "evento":
            return self.viaje_resolver(ch, gano)
        if ch.get("tipo") == "diario":
            return self.truco_dia_resolver(ch, gano)
        if ch.get("tipo") == "personaje":
            return self.personaje_resolver(ch, gano)
        if ch.get("tipo") == "mago":
            return self.mago_resolver(ch, gano)
        if ch.get("tipo") == "cientifico":
            return self.cientifico_resolver(ch, gano)
        datos = self.gira_datos()
        region = DESAFIO_NOMBRE_REGION[ch["region"]]
        es_hotel = ch["tipo"] == "hotel"
        clave = desafio_clave_voucher(ch)
        voucher = ("voucher de hotel de %s" if es_hotel else "voucher de viaje en colectivo a %s") % region
        datos.setdefault("vouchers", {})
        datos.setdefault("desafios", {})
        if not gano:
            antes = int(datos.get("puntos", 0))
            datos["puntos"] = max(0, antes - DESAFIO_PUNTOS_PIERDE)
            quitados = antes - datos["puntos"]
            self.gira_historial(datos, "Perdiste el desafío con %s (-%d pts de carrera online)" % (ch["nombre"], quitados))
            if quitados:   # el servidor tiene que descontarlos también del ranking online
                datos["pend_desafio"].append({"evento": secrets.token_hex(12), "puntos": quitados})
            self.gira_guardar()
            self.gira_enviar_pendientes()
            return ["Perdiste el desafío con %s: te descontaron %d puntos de tu carrera online (te quedan %d)." % (ch["nombre"], quitados, datos["puntos"])]
        datos["desafios"][ch["id"]] = int(datos["desafios"].get(ch["id"], 0)) + 1
        avisos = []
        if not gira_tiene_voucher(datos, "hotel" if es_hotel else "viaje", ch["region"]):
            datos["vouchers"][clave] = int(time.time())
            self.gira_historial(datos, "Ganaste el %s (a %s)" % (voucher, ch["nombre"]))
            avisos.append("¡Ganaste el %s! %s" % (voucher, "Ya tenés dónde quedarte." if es_hotel else "Ya podés viajar en colectivo."))
        else:
            avisos.append("Ganaste el desafío, pero ya tenías el %s." % voucher)
        avisos += self.gira_revisar_hechas(datos) or []
        self.gira_guardar()
        return avisos

    def build_top_gira(self, volver):
        """Top 10 online de la Gira: los 3 del podio, la lista hasta el 10° y en qué puesto estás vos."""
        pantalla, c = self._pantalla_con_volver("Top 10 online", volver)
        DORADO = (0.96, 0.78, 0.15, 1)
        aviso = Label(text="Cargando ranking...", markup=True, font_size="14sp", halign="center", valign="middle",
                      size_hint_y=None, height=dp(44), color=(0.92, 0.92, 0.92, 1))
        aviso.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        c.add_widget(aviso)
        if not self.tiene_cuenta():
            aviso.text = "Necesitás una cuenta online para ver el ranking."
            return pantalla
        if self.gira_conquistadas() < 1:
            aviso.text = "El ranking se abre cuando conquistes tu primera región."
            return pantalla
        perfil = self.perfil_usuario
        resultado = {}
        agregados = []   # lo que pinta pintar(): se borra y se vuelve a armar si llegan datos nuevos
        reintento = [False]
        self.gira_enviar_pendientes()   # por si quedaron victorias o logros sin informar al servidor

        def agregar(widget):
            c.add_widget(widget)
            agregados.append(widget)

        def fila_top(p, mio):
            f = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(46), spacing=dp(8), padding=[dp(8), dp(3)])
            icono = IconoPuesto(30)
            icono.fijar(int(p.get("puesto") or 0) or None)
            f.add_widget(icono)
            f.add_widget(Escudo(p.get("club", ""), 30))
            nombre = Label(text=("[b]%s[/b]" if mio else "%s") % p.get("nombre", "Jugador"), markup=True, font_size="15sp",
                           halign="left", valign="middle", shorten=True, shorten_from="right",
                           color=DORADO if mio else (1, 1, 1, 1))
            nombre.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
            f.add_widget(nombre)
            pts = Label(text="[b]%s[/b] pts" % p.get("puntos", 0), markup=True, font_size="14sp", halign="right",
                        valign="middle", size_hint_x=None, width=dp(86), color=DORADO if mio else (0.9, 0.9, 0.9, 1))
            pts.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
            f.add_widget(pts)

            def fondo(w, *_):
                w.canvas.before.clear()
                with w.canvas.before:
                    Color(0.96, 0.78, 0.15, 0.22) if mio else Color(0, 0, 0, 0.30)
                    RoundedRectangle(pos=w.pos, size=w.size, radius=[dp(6)])
                    if mio:
                        Color(0.96, 0.78, 0.15, 0.9)
                        Line(rounded_rectangle=(w.x, w.y, w.width, w.height, dp(6)), width=1.2)
            f.bind(pos=fondo, size=fondo)
            return f

        def pintar():
            if "top" not in resultado or "estado" not in resultado:
                return
            for w in agregados:
                c.remove_widget(w)
            del agregados[:]
            top = sorted(resultado["top"], key=lambda p: int(p.get("puesto") or 999))[:10]
            estado = resultado["estado"] or {}
            mi_puesto = int(estado["puesto"]) if estado.get("clasificado") and estado.get("puesto") else None
            c.remove_widget(aviso)
            if not top:
                agregar(Label(text="Todavía no hay nadie en el ranking.", font_size="14sp", size_hint_y=None, height=dp(40)))
                return
            for p in top:
                agregar(fila_top(p, mi_puesto is not None and int(p.get("puesto") or 0) == mi_puesto))
            if mi_puesto is None:
                # todavía el servidor no te cuenta: el renglón 11 muestra tus puntos y se reintenta enseguida
                agregar(fila_top({"puesto": 0, "club": perfil.get("club", ""), "nombre": perfil.get("nombre", "Vos"),
                                  "puntos": self.gira_datos().get("puntos", 0)}, True))
                txt = "Todavía no figurás en el ranking: se está sincronizando tu progreso."
                if not reintento[0]:
                    reintento[0] = True
                    Clock.schedule_once(reintentar, 6)
            elif mi_puesto <= 3:
                txt = "¡Estás en el podio! Puesto [b]%d°[/b] de %s  ·  [b]%s[/b] pts" % (mi_puesto, estado.get("total", "?"), estado.get("puntos", 0))
            elif mi_puesto <= 10:
                txt = "Estás en el Top 10: puesto [b]%d°[/b] de %s  ·  [b]%s[/b] pts" % (mi_puesto, estado.get("total", "?"), estado.get("puntos", 0))
            else:
                txt = "Tu puesto: [b]%d°[/b] de %s  ·  [b]%s[/b] pts" % (mi_puesto, estado.get("total", "?"), estado.get("puntos", 0))
                if mi_puesto > 11:   # entre el 10° y vos hay más jugadores
                    agregar(Label(text="...", font_size="18sp", size_hint_y=None, height=dp(18), color=(1, 1, 1, 0.6)))
                agregar(fila_top({"puesto": mi_puesto, "club": perfil.get("club", ""), "nombre": perfil.get("nombre", "Vos"),
                                  "puntos": estado.get("puntos", 0)}, True))   # renglón 11: tu puesto
            agregar(Adorno())
            agregar(Label(text=txt, markup=True, font_size="15sp", halign="center", valign="middle", color=DORADO,
                          size_hint_y=None, height=dp(40)))

        def reintentar(_dt):
            if pantalla.parent is None:   # ya saliste de esta pantalla
                return
            self.api("/gira/podio?limite=10", None, metodo="GET", ok=top_ok)
            self.api("/gira/mi_estado", {"id": perfil["id"], "token": perfil["token"]}, ok=estado_ok)

        def top_ok(r):
            resultado["top"] = r.get("podio", [])
            pintar()

        def top_fallo(*_):
            # el servidor no entendió el pedido del Top 10: se pide el podio común (puede traer solo 3)
            self.api("/gira/podio", None, metodo="GET", ok=top_ok, fallo=sin_conexion)

        def sin_conexion(detalle="", codigo=None):
            aviso.text = "No se pudo cargar el ranking.\n[size=11sp]%s[/size]" % (
                (("Error %s: " % codigo) if codigo else "") + str(detalle)[:90].replace("[", "(").replace("]", ")") or "Revisá tu conexión.")
            aviso.height = dp(64)

        def estado_ok(r):
            self.gira_estado_cache = r
            resultado["estado"] = r
            pintar()

        def estado_fallo(*_):
            resultado["estado"] = {}   # sin tu puesto igual se muestra la lista
            pintar()
        self.api("/gira/podio?limite=10", None, metodo="GET", ok=top_ok, fallo=top_fallo)
        self.api("/gira/mi_estado", {"id": perfil["id"], "token": perfil["token"]}, ok=estado_ok, fallo=estado_fallo)
        return pantalla

    def build_logros(self):
        """Gira Nacional > Mi carrera: tu categoría según la fama, últimos logros, las categorías, los logros con su estado,
        misiones de la Gira, puntos y todo lo que fuiste haciendo."""
        from kivy.uix.progressbar import ProgressBar
        pantalla, c = self._pantalla_con_volver("Mi carrera", lambda: self.cambiar_pantalla(self.build_gira_menu()))
        datos = self.gira_datos()
        self.gira_revisar_hechas(datos)  # por si ya había cumplido algo antes de que existieran los logros
        self.gira_guardar()
        VERDE, NARANJA, GRIS, DORADO = (0.55, 0.80, 0.25, 1), (0.93, 0.50, 0.15, 1), (0.72, 0.72, 0.72, 1), (0.96, 0.78, 0.15, 1)

        def etiqueta(texto, tam="14sp", alto=30, halign="left", color=(1, 1, 1, 1), ancho=None):
            e = Label(text=texto, markup=True, font_size=tam, halign=halign, valign="middle", color=color,
                      size_hint_y=None, height=dp(alto))
            if ancho is not None:
                e.size_hint_x = ancho
            e.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
            return e

        def fila(izq, der, color_der, alto=56):
            f = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(alto), spacing=dp(6))
            f.add_widget(etiqueta(izq, "15sp", alto, ancho=0.66))
            f.add_widget(etiqueta(der, "13sp", alto, "right", color_der, ancho=0.34))
            return f

        def fecha(t):
            return time.strftime("%d/%m/%Y", time.localtime(t)) if t else ""

        hechos = [lg for lg in GIRA_LOGROS if ("logro." + lg["id"]) in datos["hechas"]]
        puntos_logros = sum(lg["puntos"] for lg in hechos)
        orden = [0]

        def demora():
            orden[0] += 1
            return 0.12 * orden[0]

        # ---- MI CARRERA: categoría, fama, prestigio y progreso al próximo nivel ----
        fama = int(datos["puntos"])
        nivel = carrera_indice(fama)
        n_nombre, _d, _m, n_color = CARRERA_NIVELES[nivel]
        perfil_c = getattr(self, "perfil_usuario", None) or {}
        quien = str(perfil_c.get("nombre", "") or "Jugador").upper()
        cab = BoxLayout(orientation="vertical", size_hint_y=None, height=dp(330), padding=[dp(14), dp(10)], spacing=dp(6))

        def _fondo_cab(w, *_):
            w.canvas.before.clear()
            with w.canvas.before:
                Color(*n_color, 0.10)
                RoundedRectangle(pos=w.pos, size=w.size, radius=[dp(14)])
                Color(*n_color, 0.70)
                Line(rounded_rectangle=(w.x, w.y, w.width, w.height, dp(14)), width=1.3)
        cab.bind(pos=_fondo_cab, size=_fondo_cab)
        fila_t = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(30), spacing=dp(6))
        fila_t.add_widget(etiqueta("[b]MI CARRERA[/b]", "17sp", 30, color=(0.85, 0.85, 0.85, 1)))
        fila_t.add_widget(EtiquetaChip(n_nombre, n_color))
        cab.add_widget(fila_t)
        cab.add_widget(etiqueta("[b]%s[/b]" % quien, "28sp", 44))
        cab.add_widget(etiqueta("GIRA NACIONAL", "12sp", 20, color=(0.70, 0.70, 0.70, 1)))
        fila_ch = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(70), spacing=dp(10))
        fila_ch.add_widget(ChipPuntos("FAMA", "[b][size=24sp]%s[/size][/b]", fama, DORADO, 0.2))
        fila_ch.add_widget(ChipPuntos("PRESTIGIO", "[b][size=24sp]%d[/size][/b]", len(hechos), (0.45, 0.70, 0.95, 1), 0.35))
        cab.add_widget(fila_ch)
        if nivel + 1 < len(CARRERA_NIVELES):
            sig_nombre, _d2, sig_min, _c2 = CARRERA_NIVELES[nivel + 1]
            pct = min(100, int(100.0 * fama / sig_min))
            cab.add_widget(etiqueta("[b]Progreso hacia %s[/b]" % sig_nombre, "15sp", 28))
            fila_p = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(22))
            fila_p.add_widget(etiqueta("%s / %s fama" % (carrera_miles(fama), carrera_miles(sig_min)), "13sp", 22, color=(0.75, 0.75, 0.75, 1), ancho=0.7))
            fila_p.add_widget(etiqueta("[b]%d%%[/b]" % pct, "13sp", 22, "right", VERDE, ancho=0.3))
            cab.add_widget(fila_p)
            cab.add_widget(BarraCarrera(fama / float(sig_min), n_color))
            cab.add_widget(etiqueta("Te faltan %s de fama." % carrera_miles(sig_min - fama), "12sp", 20, color=(0.70, 0.70, 0.70, 1)))
        else:
            cab.add_widget(etiqueta("[b]¡Llegaste a la máxima categoría![/b]", "15sp", 28, color=DORADO))
            cab.add_widget(BarraCarrera(1.0, n_color))
        c.add_widget(cab)
        c.add_widget(Adorno())

        # ---- Últimos logros ----
        c.add_widget(etiqueta("[b]Últimos logros[/b]", "18sp", 34, color=DORADO))
        recientes = sorted(hechos, key=lambda lg: datos["hechas"].get("logro." + lg["id"], 0), reverse=True)[:3]
        if recientes:
            for lg in recientes:
                f_ = fecha(datos["hechas"].get("logro." + lg["id"], 0))
                fila_l = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(52), spacing=dp(10), padding=[dp(6), 0])
                ico = IconoPuesto(30)
                ico.fijar(1)
                fila_l.add_widget(ico)
                col_l = BoxLayout(orientation="vertical")
                col_l.add_widget(etiqueta("[b]%s[/b]" % lg["nombre"], "15sp", 26))
                col_l.add_widget(etiqueta("+%d fama%s" % (lg["puntos"], ("  ·  " + f_) if f_ else ""), "12sp", 20, color=(0.75, 0.75, 0.75, 1)))
                fila_l.add_widget(col_l)
                c.add_widget(fila_l)
        else:
            c.add_widget(etiqueta("Todavía no completaste ningún logro.", "13sp", 28, color=GRIS))
        c.add_widget(Adorno())

        # ---- Categorías de jugador ----
        c.add_widget(etiqueta("[b]Categorías de jugador[/b]", "18sp", 34, color=DORADO))
        c.add_widget(etiqueta("Subís de categoría a medida que sumás fama y escalás en el ranking.", "12sp", 36, color=(0.75, 0.75, 0.75, 1)))
        for i in range(len(CARRERA_NIVELES)):
            c.add_widget(FilaNivel(i, "actual" if i == nivel else ("alcanzado" if i < nivel else "bloqueado"), demora()))
        c.add_widget(Adorno())

        # ---- Todos los logros ----
        c.add_widget(etiqueta("[b]Logros[/b]", "18sp", 34, color=DORADO))
        c.add_widget(ResumenLogros(len(hechos), len(GIRA_LOGROS)))
        self.gira_revisar_categoria()
        for lg in GIRA_LOGROS:
            actual, meta, ok = gira_progreso(datos, lg, "logro.")
            if ok:
                f_ = fecha(datos["hechas"].get("logro." + lg["id"], 0))
                der, est, fr = "[b]Completado[/b]\n+%d pts%s" % (lg["puntos"], ("\n" + f_) if f_ else ""), "ok", 1.0
            elif actual > 0:
                der, est, fr = "[b]En progreso[/b]\n%d/%d\n+%d pts" % (actual, meta, lg["puntos"]), "prog", actual / float(meta)
            else:
                der, est, fr = "Por lograr\n+%d pts" % lg["puntos"], "no", 0.0
            c.add_widget(TarjetaLogro(lg["nombre"], lg["texto"], est, fr, der, demora(), 92))
        c.add_widget(Adorno())
        fila_chips = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(70), spacing=dp(10))
        fila_chips.add_widget(ChipPuntos("PUNTOS POR LOGROS", "[b][size=24sp]+%d[/size][/b]", puntos_logros, VERDE, 0.3))
        fila_chips.add_widget(ChipPuntos("PUNTOS DE GIRA", "[b][size=24sp]%d[/size][/b]", datos["puntos"], DORADO, 0.5))
        c.add_widget(fila_chips)
        rank = etiqueta("", "14sp", 30, color=DORADO)
        c.add_widget(rank)

        def pintar_rank(r):
            if r and r.get("clasificado"):
                rank.text = "Ranking online:  puesto [b]%s°[/b] de %s  ·  [b]%s[/b] pts" % (r.get("puesto"), r.get("total"), r.get("puntos"))
            elif self.tiene_cuenta():
                rank.text = "Ranking online: conquistá una región para figurar."
            else:
                rank.text = "Ranking online: necesitás una cuenta online."
        pintar_rank(getattr(self, "gira_estado_cache", None))
        diag = etiqueta("", "11sp", 0, color=(0.70, 0.70, 0.70, 1))
        c.add_widget(diag)

        def pintar_diag(r):
            """Si tu fama y el ranking online no coinciden, muestra por qué (qué falta informar al servidor)."""
            try:
                datos = self.gira_datos()   # datos frescos
                pend = {k: len(datos.get(k) or []) for k in ("pend_desafio", "pend_logros", "pend_diario", "pend")}
                en_cola = sum(int(p.get("puntos", 0)) for p in datos.get("pend_desafio", []))
                servidor = int(r.get("puntos", 0)) + en_cola   # total que tiene el servidor (antes de restar los descuentos en cola)
                if not r.get("registrado") or servidor == int(datos["puntos"]):
                    diag.text = ""
                else:
                    diag.text = ("Sin sincronizar: servidor %d · este celular %d · pendientes: desafíos %d, logros %d, diario %d, victorias %d · alta %s"
                                 % (servidor, int(datos["puntos"]), pend["pend_desafio"], pend["pend_logros"], pend["pend_diario"], pend["pend"],
                                    "sí" if datos.get("sync") else "no"))
                    err = getattr(self, "gira_error_envio", "")
                    if err:
                        diag.text += " · último error: " + err
                    elif any(pend.values()):
                        diag.text += " · enviando…"
            except (TypeError, ValueError, AttributeError):
                diag.text = ""
            diag.height = dp(64) if diag.text else 0
        b_top = boton_oscuro("[b]Ver Top 10 online[/b]", "15sp")
        b_top.markup = True
        b_top.color = DORADO
        b_top.size_hint_y = None
        b_top.height = dp(46)
        b_top.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_top_gira(lambda: self.cambiar_pantalla(self.build_logros()))))
        c.add_widget(b_top)
        if self.tiene_cuenta() and self.gira_conquistadas() >= 1:
            perfil = self.perfil_usuario

            def pedir_estado(intentos):
                def ok_rank(r):
                    if pantalla.parent is None:
                        return   # ya saliste de esta pantalla
                    self.gira_estado_cache = r
                    pintar_rank(r)
                    pintar_diag(r)
                    if int(self.gira_datos()["puntos"]) != fama:   # el servidor corrigió tu fama: se vuelve a armar la pantalla con el número correcto
                        self.cambiar_pantalla(self.build_logros())
                    elif intentos > 0 and any(self.gira_datos().get(k) for k in ("pend", "pend_logros", "pend_diario", "pend_periodico", "pend_desafio")):
                        # todavía se están enviando cosas al servidor: se vuelve a pedir el estado en unos segundos
                        Clock.schedule_once(lambda _dt: pedir_estado(intentos - 1), 5)
                self.api("/gira/mi_estado", {"id": perfil["id"], "token": perfil["token"]}, ok=ok_rank)
            self.gira_enviar_pendientes()   # manda al servidor lo que quedó sin informar (descuentos, logros, victorias)
            pedir_estado(6)
        c.add_widget(Adorno())
        # misiones para abrir regiones
        c.add_widget(etiqueta("[b]Misiones de la Gira[/b]", "18sp", 34, color=DORADO))
        for clave, reqs in GIRA_REQUISITOS.items():
            pid, rid = clave.split(".")
            pais = next(p for p in GIRA_PAISES if p["id"] == pid)
            reg = next(r for r in pais["regiones"] if r["id"] == rid)
            c.add_widget(etiqueta("Para abrir [b]%s[/b]" % reg["nombre"].title(), "14sp", 26))
            for req in reqs:
                actual, meta, ok = gira_progreso(datos, req, "req.")
                if ok:
                    c.add_widget(TarjetaLogro(req["texto"], "", "ok", 1.0, "[b]Hecha[/b]", demora(), 68))
                else:
                    c.add_widget(TarjetaLogro(req["texto"], "", "prog" if actual > 0 else "no", actual / float(meta) if meta else 0.0,
                                              "[b]%d/%d[/b]" % (actual, meta), demora(), 68))
        c.add_widget(Adorno())
        # todo lo que fuiste haciendo
        c.add_widget(etiqueta("[b]Lo que fuiste haciendo[/b]", "18sp", 34, color=DORADO))
        if datos["hist"]:
            for h in reversed(datos["hist"][-15:]):
                c.add_widget(etiqueta("[color=f5c518]•[/color] [size=11sp][color=b8b8b8]%s[/color][/size]   %s" % (
                    time.strftime("%d/%m %H:%M", time.localtime(h["t"])), h["txt"]), "13sp", 26))
        else:
            c.add_widget(etiqueta("Todavía no hay actividad. ¡Jugá una partida!", "13sp", 28, color=GRIS))
        return pantalla

    # ===== PRUEBAS: sección temporal para revisar festejos, conquistas y presentaciones. =====
    # Para borrarla al final: eliminar este bloque entero (hasta "FIN PRUEBAS") y las 3 líneas
    # marcadas "# PRUEBAS (borrar)" en build_menu. Salvo el botón "Darme un pase", nada de acá toca el progreso, las monedas ni las apuestas.
    def build_pruebas(self):
        pantalla, c = self._pantalla_con_volver("Pruebas", lambda: self.cambiar_pantalla(self.build_menu()))
        volver = lambda: self.cambiar_pantalla(self.build_pruebas())
        arg, chi, uru = GIRA_PAISES[0], GIRA_PAISES[1], GIRA_PAISES[2]
        ra = arg["regiones"]

        def aviso(texto):
            et = Label(text=texto, font_size="12sp", halign="center", valign="middle", color=(0.85, 0.82, 0.78, 1),
                       size_hint_y=None, height=dp(40))
            et.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
            c.add_widget(et)

        def grupo(texto):
            c.add_widget(Label(text=texto, font_size="17sp", bold=True, color=(0.93, 0.74, 0.22, 1),
                               size_hint_y=None, height=dp(36)))

        def boton(texto, accion):
            b = boton_oscuro(texto, "14sp")
            b.size_hint_y = None
            b.height = dp(46)
            b.bind(on_release=lambda *_: accion())
            c.add_widget(b)

        aviso("Acá se ven todos los festejos y presentaciones sin jugar ni gastar nada.")

        grupo("Copa Argentina y Libertadores")
        def copa_con_pase():
            self.pase_libertadores_aviso = True  # al cerrar aparece el cartel del pase, como en el juego real
            self.mostrar_animacion_campeon()
        boton("Campeón Copa Argentina + cartel del pase", copa_con_pase)
        boton("Campeón Copa Argentina con apuesta (500 monedas)", lambda: self.mostrar_animacion_campeon(premio=500))
        boton("Campeón de América (Libertadores)",
              lambda: self.mostrar_animacion_campeon(premio=1000, titulo="¡CAMPEÓN DE AMÉRICA!"))
        boton("Cartel: pase conseguido", self.mostrar_cartel_pase)
        def dar_pase(*_):
            self.copa_datos()["pases"] += 1
            if getattr(self, "perfil_usuario", None) is not None:
                self.persistir_perfil()
            self.online_aviso("Pase de prueba agregado.\nTenés %d. Usalo en Copa Libertadores." % self.copa_datos()["pases"], "Prueba")
        boton("Darme un pase a la Libertadores (cambia tus datos)", dar_pase)

        grupo("Gira Nacional")
        boton("Región ganada → se desbloquea otra",
              lambda: self.gira_celebrar(arg, ra[0], ra[0]["pt"] // 2, True, False, None))
        boton("Región ganada → la siguiente exige apuesta",
              lambda: self.gira_celebrar(arg, ra[1], ra[1]["pt"] // 2, True, False, None))
        boton("Volver a ganar una región ya conquistada",
              lambda: self.gira_celebrar(arg, ra[0], 0, False, False, None))
        boton("País completo (Argentina → Chile)",
              lambda: self.gira_celebrar(arg, ra[-1], ra[-1]["pt"] // 2, True, True, chi))
        boton("Gira completa (última región de Uruguay)",
              lambda: self.gira_celebrar(uru, uru["regiones"][-1], uru["regiones"][-1]["pt"] // 2, True, True, None))
        def ver_caminata():
            self.gira_datos()["camino"] = {}  # el muñequito vuelve a la primera región y camina hasta donde te toca
            self.cambiar_pantalla(self.build_gira())
        boton("Mapa: ver caminar al muñequito desde el inicio", ver_caminata)

        def cartel_region(indice, conquistadas):
            datos_f = {"regiones": {gira_clave(arg, r): GIRA_VICTORIAS_REGION for r in ra[:conquistadas]},
                       "camino": {}, "puntos": 0, "pais": 0}
            self.abrir_region_gira(ra[indice], prueba={"pais": arg, "datos": datos_f, "jugar": lambda r: None})
        boton("Cartel de misiones (región bloqueada: sin descripción)", lambda: cartel_region(1, 1))
        boton("Cartel de región bloqueada (falta conquistar la anterior)", lambda: cartel_region(2, 0))
        boton("Cartel de región desbloqueada (con descripción)", lambda: cartel_region(0, 0))

        grupo("Cartel de CUYO: los 3 estados")
        def cuyo_misiones():
            # Las misiones son las reales de Cuyo; el progreso es de ejemplo (0) y al tocarlas no se juega nada.
            cuyo, previa = ra[2], ra[1]["nombre"].title()
            demo = [(r["texto"], 0, r["meta"], False) for r in GIRA_REQUISITOS["arg.cuyo"]]
            def jugar_demo():
                self.online_aviso("(Prueba) Acá arrancaría la partida de la misión.", "Prueba")
            self.mostrar_cartel_region(cuyo, "misiones", "Faltan misiones", alto=0.80,
                                       extra=gira_misiones_widget(cuyo, previa, demo, [jugar_demo, jugar_demo]))
        boton("Cuyo 1/3 · Bloqueada (falta conquistar la anterior)", lambda: cartel_region(2, 0))
        boton("Cuyo 2/3 · Faltan misiones", cuyo_misiones)
        boton("Cuyo 3/3 · Ya lista (descripción, fotos y voz)", lambda: cartel_region(2, 2))
        grupo("Cartel de MESOPOTAMIA: los 3 estados")
        def meso_misiones():
            # Misiones reales de Mesopotamia; progreso de ejemplo (0) y al tocarlas no se juega nada.
            meso, previa = ra[3], ra[2]["nombre"].title()
            demo = [(r["texto"], 0, r["meta"], False) for r in GIRA_REQUISITOS["arg.mesopotamia"]]
            def jugar_demo():
                self.online_aviso("(Prueba) Acá arrancaría la partida de la misión.", "Prueba")
            self.mostrar_cartel_region(meso, "misiones", "Faltan misiones", alto=0.80,
                                       extra=gira_misiones_widget(meso, previa, demo, [jugar_demo, jugar_demo]))
        boton("Mesopotamia 1/3 · Bloqueada (falta conquistar la anterior)", lambda: cartel_region(3, 0))
        boton("Mesopotamia 2/3 · Faltan misiones", meso_misiones)
        boton("Mesopotamia 3/3 · Ya lista (descripción, fotos y voz)", lambda: cartel_region(3, 3))

        grupo("Mago del Camino (entre Patagonia y Cuyo)")
        aviso("«Ver al mago» muestra su encuentro; JUGAR arranca el duelo de verdad (si ganás, aprendés el poder).")
        boton("Ver al mago: cartel del encuentro", lambda: self.mago_encuentro())

        def dar_poder():
            d = self.gira_datos()
            d["mago"]["poder"] = int(time.time())
            d["mago"]["usado"] = 0
            self.gira_guardar()
            self.online_aviso("Ya tenés el Poder del mago.\nAparece en tus partidas contra la IA.", "Prueba")

        def quitar_poder():
            self.gira_datos()["mago"]["poder"] = 0
            self.gira_datos()["mago"]["usado"] = 0
            self.gira_guardar()
            self.online_aviso("Poder del mago quitado.", "Prueba")

        def partida_con_poder():
            self._mision_pendiente = None
            self.apuesta_ticket = None
            self.desafio_activo = None
            self._desafio_pendiente = None
            self._poder_prueba = True   # en esta partida el poder se ve y no se gasta
            self._arrancar_individual()
        boton("Darme el Poder del mago (cambia tus datos)", dar_poder)
        boton("Quitarme el Poder del mago (cambia tus datos)", quitar_poder)
        boton("Partida de prueba con el poder (no lo gasta)", partida_con_poder)

        grupo("Detective (Investigación)")
        aviso("Para probar la Investigación sin gastar monedas.")

        def dar_investigacion():
            d = self.gira_datos()
            d["detective"]["poder"] = int(time.time())
            d["detective"]["usado"] = 0
            self.gira_guardar()
            self.online_aviso("Ya tenés la Investigación del detective.\nAparece en «Poderes» al empezar una mano.", "Prueba")

        def quitar_investigacion():
            self.gira_datos()["detective"]["poder"] = 0
            self.gira_datos()["detective"]["usado"] = 0
            self.gira_guardar()
            self.online_aviso("Investigación del detective quitada.", "Prueba")
        boton("Darme la Investigación del detective", dar_investigacion)
        boton("Quitar la Investigación del detective", quitar_investigacion)

        grupo("Poderes nuevos (para probar)")
        aviso("Para probarlos sin gastar monedas.")

        def _hacer_dar_poder(pid):
            def dar():
                pp = PODER_POR_ID[pid]
                d = self.gira_datos()
                d[pp["clave"]]["poder"] = int(time.time())
                d[pp["clave"]]["usado"] = 0
                self.gira_guardar()
                self.online_aviso("Ya tenés: %s.\nAparece en «Poderes» al empezar una mano." % pp["nombre"], "Prueba")
            return dar

        def _hacer_quitar_poder(pid):
            def quitar():
                pp = PODER_POR_ID[pid]
                d = self.gira_datos()
                d[pp["clave"]]["poder"] = 0
                d[pp["clave"]]["usado"] = 0
                self.gira_guardar()
                self.online_aviso("Quitado: %s." % pp["nombre"], "Prueba")
            return quitar
        for _pid in PODERES_NUEVOS:
            boton("Darme: %s" % PODER_POR_ID[_pid]["nombre"], _hacer_dar_poder(_pid))
            boton("Quitar: %s" % PODER_POR_ID[_pid]["nombre"], _hacer_quitar_poder(_pid))

        grupo("Ave Fénix (revancha)")
        aviso("Para probar la revancha: tené el Ave Fénix y perdé un partido de un campeonato de la Gira.")

        def dar_fenix():
            d = self.gira_datos()
            d["fenix"]["poder"] = int(time.time())
            d["fenix"]["usado"] = 0
            self.gira_guardar()
            self.online_aviso("Ya tenés el Ave Fénix.\nSi perdés un partido de un campeonato de la Gira, aparece la revancha.", "Prueba")

        def quitar_fenix():
            self.gira_datos()["fenix"]["poder"] = 0
            self.gira_datos()["fenix"]["usado"] = 0
            self.gira_guardar()
            self.online_aviso("Ave Fénix quitado.", "Prueba")
        boton("Darme el Ave Fénix", dar_fenix)
        boton("Quitar el Ave Fénix", quitar_fenix)

        grupo("Científico del Camino (entre Cuyo y Mesopotamia)")
        aviso("«Ver al científico» muestra su encuentro; JUGAR arranca el duelo de verdad (si ganás, te da los lentes).")
        boton("Ver al científico: cartel del encuentro", lambda: self.cientifico_encuentro())

        def dar_lentes():
            d = self.gira_datos()
            d["cientifico"]["lentes"] = int(time.time())
            d["cientifico"]["usado"] = 0
            self.gira_guardar()
            self.online_aviso("Ya tenés los Lentes del científico.\nAparecen en tus Desafíos.", "Prueba")

        def quitar_lentes():
            self.gira_datos()["cientifico"]["lentes"] = 0
            self.gira_datos()["cientifico"]["usado"] = 0
            self.gira_guardar()
            self.online_aviso("Lentes del científico quitados.", "Prueba")

        def partida_con_lentes():
            self._mision_pendiente = None
            self.apuesta_ticket = None
            self.desafio_activo = None
            self._desafio_pendiente = None
            self._lentes_prueba = True   # en esta partida los lentes se ven y no se gastan
            self._arrancar_individual()
        boton("Darme los Lentes del científico (cambia tus datos)", dar_lentes)
        boton("Quitarme los Lentes del científico (cambia tus datos)", quitar_lentes)
        boton("Partida de prueba con los lentes (no los gasta)", partida_con_lentes)

        def partida_con_los_dos():
            self._mision_pendiente = None
            self.apuesta_ticket = None
            self.desafio_activo = None
            self._desafio_pendiente = None
            self._poder_prueba = True    # en esta partida se ven el poder y los lentes y no se gastan
            self._lentes_prueba = True
            self._arrancar_individual()
        boton("Partida de prueba con los dos poderes (no los gasta)", partida_con_los_dos)
        boton("Cartel: eliminado sin apuesta", lambda: self.gira_cartel_eliminado(ra[0], "Semifinal", False))
        boton("Cartel: eliminado con apuesta", lambda: self.gira_cartel_eliminado(ra[2], "Cuartos", True))
        boton("Gira de CHILE tal cual el juego (progreso falso)", lambda: self.cambiar_pantalla(self.build_prueba_mapa(chi)))
        boton("Aduana: papel para pasar a Chile (simulado)", lambda: self.prueba_aduana(chi))
        boton("Chile: ver qué fotos y audios ya están", lambda: self.prueba_resumen_medios(chi))

        grupo("Tarjetas y colecciones (nuevas)")
        boton("Galería: tarjeta, vouchers, figuritas y postales (todo desbloqueado)",
              lambda: self.cambiar_pantalla(self.build_prueba_galeria()))
        boton("Cartel: el Tano te frena (¡ALTO AHÍ!)", lambda: self.prueba_mafia(True))
        boton("Cartel: ficha del Tano", lambda: self.prueba_mafia(False))
        boton("Cartel de Desafío: Doña Mabel (hotel)", lambda: self.prueba_desafio("mabel"))
        boton("Cartel de Desafío: Don Nahuel (colectivo)", lambda: self.prueba_desafio("nahuel"))
        boton("Cartel de Desafío: Don Aníbal (retrato dibujado)", lambda: self.prueba_desafio("anibal"))
        for _e in VIAJE_EVENTOS:
            boton("Encuentro en el camino: %s" % _e["nombre"], lambda e=_e: self.prueba_viaje(e))

        grupo("Presentaciones")
        boton("Presentación de la Gira Nacional",
              lambda: self.cambiar_pantalla(self.build_presentacion_gira(0, al_terminar=volver, tema="gira")))
        boton("Presentación de la Copa Argentina",
              lambda: self.cambiar_pantalla(self.build_presentacion_gira(0, al_terminar=volver, tema="copa")))

        grupo("Otros carteles")
        boton("Envido ganado", lambda: self.cartel_envido(31, 27, True))
        boton("Envido perdido", lambda: self.cartel_envido(25, 31, False))
        boton("Fin de partida: ganaste", lambda: self.mostrar_cartel(
            "FIN DE PARTIDA", "¡Ganaste el partido!", True, detalle="Resultado final: 30 - 22", alto=0.5))
        boton("Fin de partida: perdiste", lambda: self.mostrar_cartel(
            "FIN DE PARTIDA", "Perdiste el partido...", False, detalle="Resultado final: 18 - 30", alto=0.5))
        return pantalla
    def _prueba_estado_medios(self, pais, region):
        """(cantidad de fotos, hay audio) de la ficha de una región, para ver cómo van las carpetas."""
        info = GIRA_INFO_REGION.get(gira_clave(pais, region))
        if not info:
            return 0, False
        try:
            fotos = len(fotos_info_gira(info.get("fotos", "")))
        except Exception:
            fotos = 0
        try:
            audio = bool(audio_info_gira(info.get("audio", ""))) if info.get("audio") else False
        except Exception:
            audio = False
        return fotos, audio

    def build_prueba_mapa(self, pais, k=0, desde=0):
        """La pantalla de la Gira tal cual es en el juego, pero con progreso FALSO (k regiones conquistadas).
        No toca tu progreso, monedas ni apuestas. Tocá una zona o JUGAR: el cartel es el real y al "jugar" se simula
        que ganás (festejo real) y el muñequito camina a la zona siguiente."""
        n = len(pais["regiones"])
        k = max(0, min(n, k))
        indice = GIRA_PAISES.index(pais)
        datos = {"regiones": {gira_clave(pais, r): GIRA_VICTORIAS_REGION for r in pais["regiones"][:k]},
                 "camino": {pais["id"]: max(0, min(desde, n - 1))}, "puntos": 0, "pais": indice}

        def jugar(region):
            i = pais["regiones"].index(region)
            completo = i == k and k + 1 >= n   # ganás la última región del país
            nuevo_pais = GIRA_PAISES[indice + 1] if (completo and indice + 1 < len(GIRA_PAISES)) else None
            nuevo_k = k + 1 if i == k else k
            self.gira_celebrar(pais, region, region["pt"] // 2, i == k, completo, nuevo_pais,
                               al_terminar=lambda: self.cambiar_pantalla(self.build_prueba_mapa(pais, nuevo_k, min(k, n - 1))))
        ctx = {"pais": pais, "datos": datos, "jugar": jugar}

        raiz = MesaBox(orientation="vertical", padding=dp(8), spacing=dp(5))
        DORADO, NARANJA = (0.96, 0.78, 0.15), (0.95, 0.55, 0.15)
        cabecera = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(58), spacing=dp(6))
        atras = BotonColor("< Pruebas", DORADO, ancho=96, font_size="13sp")
        atras.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_pruebas()))
        cabecera.add_widget(atras)
        cabecera.add_widget(TituloTruco("GIRA NACIONAL", 26, 58))
        cabecera.add_widget(self.nuevo_boton_sonido(40))
        raiz.add_widget(cabecera)
        raiz.add_widget(Adorno())
        fila = TarjetaFondo(DORADO, demora=0.05, orientation="horizontal", size_hint_y=None, height=dp(50),
                            padding=[dp(6), 0, dp(6), 0], spacing=dp(6))
        anterior = BotonColor("<", DORADO, ancho=44, font_size="18sp")
        siguiente = BotonColor(">", DORADO, ancho=44, font_size="18sp")
        fila.add_widget(anterior)
        fila.add_widget(Label(text=f"[b]{pais['nombre']}[/b]  ·  {k}/{n} regiones", markup=True, font_size="15sp",
                              color=(1.0, 0.93, 0.72, 1)))
        fila.add_widget(siguiente)
        raiz.add_widget(fila)
        anterior.disabled = indice == 0
        siguiente.disabled = indice + 1 >= len(GIRA_PAISES)
        for b in (anterior, siguiente):
            b.opacity = 0.35 if b.disabled else 1
        def ir_a(destino):
            ir = lambda: self.cambiar_pantalla(self.build_prueba_mapa(destino, 0, 0))
            if destino["id"] in GIRA_ADUANA:
                self.gira_aduana_cartel(destino, ir, simulado=self._aduana_demo())
            else:
                ir()
        anterior.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_prueba_mapa(GIRA_PAISES[indice - 1], 0, 0)))
        siguiente.bind(on_release=lambda *_: ir_a(GIRA_PAISES[indice + 1]))
        pista = (f"Ganá un mini campeonato para conquistar la región.\n"
                 f"Desde la 3.ª región, una sí y una no se juega con apuesta de {GIRA_APUESTA_REGION}.")
        tarjeta_pista = TarjetaFondo(NARANJA, demora=0.15, orientation="vertical", size_hint_y=None, height=dp(64),
                                     padding=[dp(8), dp(4)])
        _lp = Label(text=f"[color=f5c726]Puntos de gira:[/color] [b]{datos['puntos']}[/b]\n[size=11sp]{pista}[/size]",
                    markup=True, font_size="14sp", halign="center", valign="middle", color=(1.0, 0.95, 0.85, 1))
        _lp.bind(size=lambda w, sz: setattr(w, "text_size", (sz[0], None)))
        tarjeta_pista.add_widget(_lp)
        raiz.add_widget(tarjeta_pista)
        podio = PodioGira()
        podio.mostrar(None, None, 0, self.tiene_cuenta())
        raiz.add_widget(podio)
        raiz.add_widget(MapaGira(pais, datos, al_tocar=lambda r: self.abrir_region_gira(r, prueba=ctx)))
        proxima = next((r for r, e, _v in gira_estados(datos, pais) if e == "disponible"), None)
        if proxima is not None:
            texto = "JUGAR EN %s%s" % (proxima["nombre"], " · APUESTA %d" % GIRA_APUESTA_REGION
                                       if gira_region_exige_apuesta(pais, proxima) else "")
        else:
            texto = "¡PAÍS COMPLETO!"
        boton_jugar = boton_cartel(texto, NARANJA if proxima is not None else (0.35, 0.85, 0.45), "16sp", 58)
        boton_jugar.disabled = proxima is None
        if proxima is not None:
            boton_jugar.bind(on_release=lambda *_: self.abrir_region_gira(proxima, prueba=ctx))
        raiz.add_widget(boton_jugar)
        return raiz

    def _aduana_demo(self, reiniciar=False):
        if reiniciar or not hasattr(self, "_aduana_demo_datos"):
            self._aduana_demo_datos = {"regiones": {}, "aduana": {}}
        return self._aduana_demo_datos

    def prueba_aduana(self, pais):
        """Muestra la pregunta de la aduana (simulada) desde cero y, si "pasás", abre el mapa de ese país."""
        self.gira_aduana_cartel(pais, lambda: self.cambiar_pantalla(self.build_prueba_mapa(pais, 0, 0)),
                                simulado=self._aduana_demo(reiniciar=True))

    def prueba_resumen_medios(self, pais):
        lineas = []
        for r in pais["regiones"]:
            f, a = self._prueba_estado_medios(pais, r)
            lineas.append("%s: %d fotos · audio %s" % (r["nombre"].title(), f, "sí" if a else "no"))
        foto = "OK" if ruta_mapa_gira(pais["id"]) else "NO está mapa_%s.jpg" % pais["id"]
        self.mostrar_cartel("Fotos y audios", pais["nombre"].title(), True,
                            detalle="Foto del mapa: %s\n%s" % (foto, "\n".join(lineas)), alto=0.62, botones=[("CERRAR", None)])
    def prueba_mafia(self, emboscada):
        """Cartel del Tano tal cual el juego, con botones que no juegan nada."""
        ch = MAFIA_JEFE
        sin_jugar = lambda: self.online_aviso("(Prueba) Acá arrancaría la partida contra %s." % ch["nombre"], "Prueba")
        if emboscada:
            self.mostrar_cartel("¡ALTO AHÍ!", ch["nombre"], False,
                                detalle="Si ganás: la aprobación de la Familia y su tarjeta.\nModo difícil. Si no jugás... sos boleta.",
                                extra=ConversacionMafia(ch["frase"], "escena"),
                                botones=[("JUGAR", sin_jugar), ("ME VOY", None)], apilados=True, alto=0.95)
        else:
            self.mostrar_cartel("LA FAMILIA", ch["titulo"], False,
                                detalle="Si ganás: la aprobación de la Familia y su tarjeta.\nSi perdés, no pasa nada: podés reintentar.",
                                extra=ConversacionMafia(ch["frase_ficha"], "ficha"),
                                botones=[("JUGAR", sin_jugar), ("CERRAR", None)], apilados=True, alto=0.95)

    def prueba_desafio(self, rid):
        """Cartel de Desafío de un rival, con botones que no juegan ni compran nada."""
        ch = next(d for d in DESAFIOS if d["id"] == rid)
        sin_jugar = lambda: self.online_aviso("(Prueba) Acá arrancaría la partida contra %s." % ch["nombre"], "Prueba")
        conversacion = (ConversacionFoto(rid, ch["frase"]) if rid in DESAFIO_FOTO_B64 else ConversacionDesafio(DESAFIO_LOOK[rid], ch["frase"]))
        self.mostrar_cartel("DESAFÍO", ch["nombre"], True,
                            detalle="Rival: %s · Modo difícil · Sin apuesta" % ch["perfil"], extra=conversacion,
                            botones=[("JUGAR", sin_jugar), ("CERRAR", None)], apilados=True, alto=0.58 + 0.085 * 2)

    def prueba_viaje(self, e):
        """Encuentro del camino con todas sus opciones; no guarda postales ni toca tu progreso."""
        def elegir(i):
            o = e["opciones"][i]
            if o.get("duelo"):
                self.online_aviso("(Prueba) Acá se jugaría una mano contra %s.\nSi ganás: %s" % (e["nombre"], o["gana"]), "Prueba")
                return
            texto = o["res"] + ("\n\n¡Postal nueva! La ves en Gira > Mis pertenencias." if o.get("postal") else "")
            self._viaje_cartel_resultado(e, texto, bool(o.get("postal")))
        botones = [(o["texto"], lambda i=i: elegir(i)) for i, o in enumerate(e["opciones"])]
        self.mostrar_cartel("EN EL CAMINO", e["nombre"], True, detalle="Un encuentro en la ruta...",
                            extra=ConversacionDesafio(e["look"], e["frase"]), botones=botones, apilados=True,
                            alto=0.58 + 0.085 * len(botones))

    def build_prueba_galeria(self):
        """Todas las tarjetas nuevas a la vista (con todo desbloqueado), más cómo se ven sin conseguir."""
        pantalla, c = self._pantalla_con_volver("Galería de pruebas", lambda: self.cambiar_pantalla(self.build_pruebas()))
        DORADO = (0.96, 0.78, 0.15, 1)
        quien = self.online_nombre() or "Viajero"

        def titulo(texto):
            c.add_widget(Label(text="[b]%s[/b]" % texto, markup=True, font_size="15sp", color=DORADO, size_hint_y=None, height=dp(34)))

        titulo("Tarjeta de la Familia")
        c.add_widget(TarjetaMafia(quien, int(time.time()), favor=1, height=dp(196)))
        c.add_widget(TarjetaMafia(quien, int(time.time()), favor=0, height=dp(196)))
        titulo("Vouchers de papel")
        for _tipo, _tdes in (("hotel", "hotel"), ("viaje", "colectivo")):
            for r in DESAFIO_REGIONES:
                ch = next((d for d in DESAFIOS if d["region"] == r and d["tipo"] == _tdes), None)
                lugar = ch["lugar"].split(" · ")[0] if ch else DESAFIO_NOMBRE_REGION[r]
                c.add_widget(VoucherPapel(_tipo, DESAFIO_NOMBRE_REGION[r], lugar, quien))
        album = list(DESAFIOS) + [MAFIA_JEFE] + [personaje_ficha(p) for p in PERSONAJES_DIA]
        titulo("Álbum de figuritas (todas)")
        filas = (len(album) + 2) // 3
        g = GridLayout(cols=3, spacing=dp(6), size_hint_y=None, height=filas * dp(160) + (filas - 1) * dp(6))
        for n, d in enumerate(album, 1):
            g.add_widget(Figurita(d, True, n, len(album)))
        c.add_widget(g)
        titulo("Postales (todas)")
        filas = (len(POSTALES) + 1) // 2
        g2 = GridLayout(cols=2, spacing=dp(6), size_hint_y=None, height=filas * dp(124) + (filas - 1) * dp(6))
        for n, po in enumerate(POSTALES, 1):
            g2.add_widget(PostalCard(po, True, n, len(POSTALES)))
        c.add_widget(g2)
        titulo("Así se ven sin conseguir")
        g3 = GridLayout(cols=3, spacing=dp(6), size_hint_y=None, height=dp(160))
        for n, d in enumerate(album[:3], 1):
            g3.add_widget(Figurita(d, False, n, len(album)))
        c.add_widget(g3)
        g4 = GridLayout(cols=2, spacing=dp(6), size_hint_y=None, height=dp(124))
        g4.add_widget(PostalCard(POSTALES[1], False, 2, len(POSTALES)))
        g4.add_widget(PostalCard(POSTALES[6], False, 7, len(POSTALES)))
        c.add_widget(g4)
        return pantalla

    # ===== FIN PRUEBAS =====

    def build_academia(self):
        pantalla, c = self._pantalla_con_volver("Academia", lambda: self.cambiar_pantalla(self.build_menu()))
        c.add_widget(Label(text="[i]Aprendé a jugar al truco[/i]", markup=True, font_size="14sp",
                           color=(0.96, 0.82, 0.40, 1), size_hint_y=None, height=dp(22)))
        b_reglas = ItemMenuColor("libro", "Reglas", "Cómo se juega al truco, paso a paso.", (0.52, 0.62, 0.96), 0.05)
        b_trivia = ItemMenuColor("pregunta", "Trivia", "Preguntas sobre el truco para aprender.", (0.72, 0.58, 0.96), 0.12)
        b_reglas.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_reglas()))
        b_trivia.bind(on_release=lambda *_: self.iniciar_trivia())
        c.add_widget(b_reglas)
        c.add_widget(b_trivia)
        c.add_widget(Adorno())
        return pantalla

    def build_reglas(self):
        pantalla, c = self._pantalla_con_volver("Reglas", lambda: self.cambiar_pantalla(self.build_academia()))
        paleta = [(0.55, 0.80, 0.25), (0.45, 0.72, 0.95), (0.96, 0.78, 0.15), (0.95, 0.55, 0.15),
                  (0.93, 0.42, 0.40), (0.72, 0.58, 0.96), (0.35, 0.80, 0.75), (0.52, 0.62, 0.96)]
        for i, (titulo, texto) in enumerate(REGLAS_TRUCO):
            c.add_widget(TarjetaTexto(titulo, texto, color=paleta[i % len(paleta)]))
        return pantalla

    # ---------- trivia ----------
    def iniciar_trivia(self, *_, cantidad=10):
        preguntas = random.sample(TRIVIA_TRUCO, min(cantidad, len(TRIVIA_TRUCO)))
        self.trivia = {"preguntas": preguntas, "i": 0, "aciertos": 0}
        self.mostrar_pregunta_trivia()

    def mostrar_pregunta_trivia(self):
        t = self.trivia
        total = len(t["preguntas"])
        if t["i"] >= total:
            return self.mostrar_resultado_trivia()
        texto, opciones, correcta, explicacion = t["preguntas"][t["i"]]
        orden = list(range(len(opciones)))
        random.shuffle(orden)
        pantalla, c = self._pantalla_con_volver(f"Trivia · {t['i'] + 1}/{total}",
                                                lambda: self.cambiar_pantalla(self.build_academia()), "< Salir")
        pregunta = TarjetaTexto("Pregunta", f"[size=18sp]{texto}[/size]", color=(0.72, 0.58, 0.96))
        c.add_widget(pregunta)
        botones = []
        estado = {"respondida": False}
        aviso = Label(text="", markup=True, font_size="14sp", halign="center", valign="middle",
                      size_hint_y=None, height=dp(70))
        aviso.bind(width=lambda w, *_: setattr(w, "text_size", (w.width, None)))
        siguiente = boton_oscuro("Siguiente" if t["i"] + 1 < total else "Ver resultado", "16sp")
        siguiente.size_hint_y = None
        siguiente.height = 0
        siguiente.opacity = 0
        siguiente.disabled = True

        def responder(indice_visible, original):
            if estado["respondida"]:
                return
            estado["respondida"] = True
            acerto = original == correcta
            if acerto:
                t["aciertos"] += 1
            for (bt, orig) in botones:
                bt.disabled = True
                if orig == correcta:
                    bt.background_color = (0.15, 0.50, 0.20, 1)
                elif orig == original:
                    bt.background_color = (0.62, 0.15, 0.12, 1)
            aviso.text = ("[color=8fcc3f][b]¡Correcto![/b][/color] " if acerto else "[color=ee8026][b]Incorrecto.[/b][/color] ") + explicacion
            siguiente.height = dp(50)
            siguiente.opacity = 1
            siguiente.disabled = False

        for pos, original in enumerate(orden):
            b = boton_oscuro(opciones[original], "15sp")
            b.size_hint_y = None
            b.height = dp(54)
            b.bind(on_release=lambda *_, p=pos, o=original: responder(p, o))
            botones.append((b, original))
            c.add_widget(b)
        c.add_widget(aviso)

        def avanzar(*_):
            t["i"] += 1
            self.mostrar_pregunta_trivia()
        siguiente.bind(on_release=avanzar)
        c.add_widget(siguiente)
        self.cambiar_pantalla(pantalla)

    def mostrar_resultado_trivia(self):
        t = self.trivia
        total = len(t["preguntas"])
        aciertos = t["aciertos"]
        pantalla, c = self._pantalla_con_volver("Trivia", lambda: self.cambiar_pantalla(self.build_academia()), "< Academia")
        if aciertos >= total * 0.8:
            mensaje = "¡Sos un maestro del truco!"
        elif aciertos >= total * 0.5:
            mensaje = "¡Muy bien! Repasá las reglas y vas a mejorar."
        else:
            mensaje = "Leé las reglas en la Academia y volvé a intentarlo."
        c.add_widget(TarjetaTexto("Tu resultado", f"[size=26sp][b]{aciertos} / {total}[/b][/size]\n{mensaje}",
                                  color=(0.96, 0.78, 0.15)))
        otra = ItemMenuColor("pregunta", "Jugar otra trivia", "Diez preguntas nuevas.", (0.72, 0.58, 0.96), 0.05)
        reglas = ItemMenuColor("libro", "Ver las reglas", "Repasá cómo se juega.", (0.52, 0.62, 0.96), 0.12)
        for b in (otra, reglas):
            c.add_widget(b)
        otra.bind(on_release=self.iniciar_trivia)
        reglas.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_reglas()))
        self.cambiar_pantalla(pantalla)

    def online_nombre(self):
        perfil = getattr(self, "perfil_usuario", {}) or {}
        return (perfil.get("nombre", "Jugador") + " " + perfil.get("apellido", "")).strip() or "Jugador"

    # ---------- silencio ----------
    def audio_permitido(self):
        return not getattr(self, "silenciado", False)

    def alternar_silencio(self, *_):
        self.silenciado = not getattr(self, "silenciado", False)
        perfil = getattr(self, "perfil_usuario", None)
        if perfil is not None:
            perfil["silenciado"] = self.silenciado
            self.persistir_perfil()
        if self.silenciado:
            for nombre in ("sonido_actual", "sonido_inicio", "sonido_efecto", "sonido_campeon", "sonido_region"):
                sonido = getattr(self, nombre, None)
                if sonido is not None:
                    try: sonido.stop()
                    except Exception: pass
        else:
            self._musica_fallos = 0
            self._musica_menu_tocar()
        for boton in list(getattr(self, "botones_sonido", [])):
            try: boton.dibujar()
            except Exception: pass

    def nuevo_boton_sonido(self, lado=42):
        boton = BotonSonido(self, lado)
        lista = getattr(self, "botones_sonido", None)
        if lista is None:
            lista = self.botones_sonido = []
        lista[:] = lista[-6:] + [boton]
        return boton

    # ---------- Gira Nacional ----------
    @staticmethod
    def _gira_norm_viaje(v, entero):
        """Encuentros del camino: cuántos regiones conquistadas ya tuvieron su encuentro y cuáles viste."""
        if not isinstance(v, dict):
            return {"hechos": 0, "vistos": []}
        vistos = [str(x)[:20] for x in (v.get("vistos") if isinstance(v.get("vistos"), list) else [])[:20]]
        return {"hechos": entero(v.get("hechos", 0)), "vistos": vistos}

    @staticmethod
    def _gira_norm_diario(d, entero):
        """Truco del día: fecha del último intento, cómo salió, racha de días ganados y estadísticas."""
        d = d if isinstance(d, dict) else {}
        estado = str(d.get("estado", ""))
        return {"fecha": str(d.get("fecha", ""))[:10], "estado": estado if estado in ("jugando", "ganado", "perdido") else "",
                "ultima": str(d.get("ultima", ""))[:10], "racha": entero(d.get("racha", 0)),
                "mejor": entero(d.get("mejor", 0)), "ganados": entero(d.get("ganados", 0)),
                "jugados": entero(d.get("jugados", 0)), "puntos": entero(d.get("puntos", 0))}

    @staticmethod
    def _gira_norm_personaje(d, entero):
        """Personaje del día: fecha del último intento, cómo salió y estadísticas."""
        d = d if isinstance(d, dict) else {}
        estado = str(d.get("estado", ""))
        return {"fecha": str(d.get("fecha", ""))[:10], "estado": estado if estado in ("jugando", "ganado", "perdido") else "",
                "ganados": entero(d.get("ganados", 0)), "jugados": entero(d.get("jugados", 0)), "ultimo": str(d.get("ultimo", ""))[:40],
                "figuritas": [str(x)[:24] for x in d.get("figuritas", [])][:30] if isinstance(d.get("figuritas"), list) else []}

    @staticmethod
    def _gira_norm_semana(d, entero):
        """Desafíos semanales: semana en curso, avance de cada meta y cuáles ya se cobraron."""
        d = d if isinstance(d, dict) else {}
        lista = lambda v: [str(x)[:24] for x in v][:20] if isinstance(v, list) else []
        return {"clave": str(d.get("clave", ""))[:10], "ruleta": entero(d.get("ruleta", 0)), "truco": entero(d.get("truco", 0)),
                "personajes": lista(d.get("personajes")), "cobrados": lista(d.get("cobrados"))}

    @staticmethod
    def _gira_norm_periodicos(datos, entero):
        """Cola de puntos de la Ruleta, el personaje del día y los desafíos semanales que todavía no se informaron al servidor.
        (También recoge la cola vieja `pend_ruleta`, que tenía los puntos en vez del id del logro.)"""
        lista = datos.get("pend_periodico") if isinstance(datos.get("pend_periodico"), list) else []
        viejos = datos.get("pend_ruleta") if isinstance(datos.get("pend_ruleta"), list) else []
        todos = [p for p in lista if isinstance(p, dict)] + [
            {"evento": q.get("evento"), "logro": "ruleta_%d" % entero(q.get("puntos", 0))} for q in viejos if isinstance(q, dict)]
        return [{"evento": str(p["evento"])[:64], "logro": str(p["logro"])[:40]}
                for p in todos[:50] if p.get("evento") and p.get("logro")]

    @staticmethod
    def _gira_norm_ruleta(d, entero):
        """Ruleta: fecha del último giro, cuántos giraste, puntos ganados y el último premio."""
        d = d if isinstance(d, dict) else {}
        return {"fecha": str(d.get("fecha", ""))[:10], "giros": entero(d.get("giros", 0)),
                "puntos": entero(d.get("puntos", 0)), "ultimo": str(d.get("ultimo", ""))[:40]}

    @staticmethod
    def _gira_norm_mago(m, entero):
        """Poder del mago: cuándo lo aprendiste (0 = todavía no) y cuántas partidas jugaste contra Eliseo."""
        m = m if isinstance(m, dict) else {}
        return {"poder": entero(m.get("poder", 0)), "usado": entero(m.get("usado", 0)),
                "ganadas": entero(m.get("ganadas", 0)), "perdidas": entero(m.get("perdidas", 0))}

    @staticmethod
    def _gira_norm_cientifico(m, entero):
        """Lentes del científico: cuándo los ganaste (0 = todavía no), cuándo los gastaste y cuántas partidas jugaste contra él."""
        m = m if isinstance(m, dict) else {}
        return {"lentes": entero(m.get("lentes", 0)), "usado": entero(m.get("usado", 0)),
                "ganadas": entero(m.get("ganadas", 0)), "perdidas": entero(m.get("perdidas", 0))}

    @staticmethod
    def _gira_norm_detective(m, entero):
        """Investigación del detective: cuándo la conseguiste (0 = todavía no) y cuándo la gastaste."""
        m = m if isinstance(m, dict) else {}
        return {"poder": entero(m.get("poder", 0)), "usado": entero(m.get("usado", 0))}

    @staticmethod
    def _gira_norm_fenix(m, entero):
        """Ave Fénix: cuándo lo conseguiste (0 = todavía no) y cuándo lo gastaste."""
        m = m if isinstance(m, dict) else {}
        return {"poder": entero(m.get("poder", 0)), "usado": entero(m.get("usado", 0))}

    @staticmethod
    def _gira_norm_poder(m, entero):
        """Poder de un solo uso (soplón, espía, escudo): cuándo lo conseguiste (0 = todavía no) y cuándo lo gastaste."""
        m = m if isinstance(m, dict) else {}
        return {"poder": entero(m.get("poder", 0)), "usado": entero(m.get("usado", 0))}

    @staticmethod
    def _gira_norm_mafia(m, entero):
        """Tarjeta de la Familia: aprobación, partidas contra el campeón y el favor (1 = disponible)."""
        if not isinstance(m, dict):
            return {"aprobado": 0, "ganadas": 0, "perdidas": 0, "favor": 0}
        r = {k: entero(m.get(k, 0)) for k in ("aprobado", "ganadas", "perdidas")}
        r["favor"] = 1 if ("favor" not in m and r["aprobado"]) else min(1, entero(m.get("favor", 0)))
        return r

    def gira_normalizar(self, datos):
        datos = datos if isinstance(datos, dict) else {}
        def entero(valor, tope=None):
            try: v = max(0, int(valor))
            except (TypeError, ValueError): v = 0
            return min(v, tope) if tope is not None else v
        regiones = {}
        for clave, valor in (datos.get("regiones") or {}).items() if isinstance(datos.get("regiones"), dict) else []:
            regiones[str(clave)] = entero(valor, GIRA_VICTORIAS_REGION)
        return {"puntos": entero(datos.get("puntos", 0)), "regiones": regiones,
                "pais": entero(datos.get("pais", 0), len(GIRA_PAISES) - 1),
                "torneos": entero(datos.get("torneos", 0)), "intro": bool(datos.get("intro", False)),
                "sync": bool(datos.get("sync", False)),
                "prog": {k: (entero(datos["prog"].get(k, 0)) if isinstance(datos.get("prog"), dict) else 0)
                         for k in ("victorias", "derrotas", "seguidas", "mejor", "apuestas", "margen", "apuesta100", "online", "ia50")},
                "hechas": ({str(k)[:40]: entero(v) for k, v in datos["hechas"].items()}
                           if isinstance(datos.get("hechas"), dict) else {}),
                "hist": [{"t": entero(h.get("t", 0)), "txt": str(h["txt"])[:90]}
                         for h in (datos.get("hist") if isinstance(datos.get("hist"), list) else [])[-40:]
                         if isinstance(h, dict) and h.get("txt")],
                "camino": ({str(k)[:12]: entero(v, 20) for k, v in datos["camino"].items()}
                           if isinstance(datos.get("camino"), dict) else {}),
                "aduana": ({str(k)[:12]: {"ok": bool(v.get("ok")), "hasta": entero(v.get("hasta", 0)),
                                           "fecha": entero(v.get("fecha", 0)), "visto": bool(v.get("visto"))}
                            for k, v in datos["aduana"].items() if isinstance(v, dict)}
                           if isinstance(datos.get("aduana"), dict) else {}),
                "pend_desafio": [{"evento": str(p["evento"])[:64], "puntos": entero(p.get("puntos", 0))}
                                 for p in (datos.get("pend_desafio") if isinstance(datos.get("pend_desafio"), list) else [])[:50]
                                 if isinstance(p, dict) and p.get("evento") and entero(p.get("puntos", 0)) > 0],
                "vouchers": ({str(k)[:20]: entero(v) for k, v in datos["vouchers"].items()}
                             if isinstance(datos.get("vouchers"), dict) else {}),
                "desafios": ({str(k)[:20]: entero(v) for k, v in datos["desafios"].items()}
                             if isinstance(datos.get("desafios"), dict) else {}),
                "postales": ({str(k)[:20]: entero(v) for k, v in datos["postales"].items()}
                             if isinstance(datos.get("postales"), dict) else {}),
                "viaje": self._gira_norm_viaje(datos.get("viaje"), entero),
                "compradas": ({str(k)[:30]: 1 for k, v in datos["compradas"].items() if v}
                              if isinstance(datos.get("compradas"), dict) else {}),
                "viajadas": ({str(k)[:30]: 1 for k, v in datos["viajadas"].items() if v}
                             if isinstance(datos.get("viajadas"), dict) else {}),
                "mafia": self._gira_norm_mafia(datos.get("mafia"), entero),
                "diario": self._gira_norm_diario(datos.get("diario"), entero),
                "ruleta": self._gira_norm_ruleta(datos.get("ruleta"), entero),
                "personaje": self._gira_norm_personaje(datos.get("personaje"), entero),
                "semana": self._gira_norm_semana(datos.get("semana"), entero),
                "pend_periodico": self._gira_norm_periodicos(datos, entero),
                "mago": self._gira_norm_mago(datos.get("mago"), entero),
                "cientifico": self._gira_norm_cientifico(datos.get("cientifico"), entero),
                "detective": self._gira_norm_detective(datos.get("detective"), entero),
                "fenix": self._gira_norm_fenix(datos.get("fenix"), entero),
                "soplon": self._gira_norm_poder(datos.get("soplon"), entero),
                "espia": self._gira_norm_poder(datos.get("espia"), entero),
                "escudo": self._gira_norm_poder(datos.get("escudo"), entero),
                "silencio": self._gira_norm_poder(datos.get("silencio"), entero),
                "ancho": self._gira_norm_poder(datos.get("ancho"), entero),
                "halcon": self._gira_norm_poder(datos.get("halcon"), entero),
                "baqueano": self._gira_norm_poder(datos.get("baqueano"), entero),
                "chaleco": self._gira_norm_poder(datos.get("chaleco"), entero),
                "comodin": self._gira_norm_poder(datos.get("comodin"), entero),
                "pase": self._gira_norm_poder(datos.get("pase"), entero),
                "pend_diario": [{"evento": str(p["evento"])[:64], "puntos": entero(p.get("puntos", 0)),
                                 "fecha": str(p.get("fecha", ""))[:10]}
                                for p in (datos.get("pend_diario") if isinstance(datos.get("pend_diario"), list) else [])[:50]
                                if isinstance(p, dict) and p.get("evento") and entero(p.get("puntos", 0)) > 0],
                "pend_logros": [{"evento": str(p["evento"])[:64], "logro": str(p["logro"])[:40]}
                                for p in (datos.get("pend_logros") if isinstance(datos.get("pend_logros"), list) else [])[:50]
                                if isinstance(p, dict) and p.get("evento") and p.get("logro")],
                "pend": [{"evento": str(p["evento"])[:64], "region": str(p["region"])[:40]}
                         for p in (datos.get("pend") if isinstance(datos.get("pend"), list) else [])[:50]
                         if isinstance(p, dict) and p.get("evento") and p.get("region")],
                "categoria": self._gira_norm_categoria(datos.get("categoria"))}

    @staticmethod
    def _gira_norm_categoria(valor):
        """Última categoría de Mi carrera que ya viste (-1 = todavía ninguna)."""
        try: return max(-1, min(len(CARRERA_NIVELES) - 1, int(valor)))
        except (TypeError, ValueError): return -1

    def gira_revisar_categoria(self):
        """Si subiste de categoría desde la última vez, muestra un cartel de festejo (una sola vez por categoría).
        La primera vez que se llama solo anota tu categoría, sin festejar."""
        datos = self.gira_datos()
        actual = carrera_indice(datos["puntos"])
        visto = datos.get("categoria", -1)
        if visto == actual:
            return
        datos["categoria"] = max(visto, actual)
        self.gira_guardar()
        if visto < 0 or actual < visto:
            return   # primera vez (o bajaste por un descuento): no se festeja
        nombre, desc, _m, _c = CARRERA_NIVELES[actual]

        def mostrar(_dt):
            self.mostrar_cartel("¡SUBISTE DE NIVEL!", nombre, True,
                                detalle="%s\nTenés %s de fama." % (desc, carrera_miles(datos["puntos"])),
                                botones=[("VER MI CARRERA", lambda: self.cambiar_pantalla(self.build_logros())), ("ACEPTAR", None)],
                                apilados=True, alto=0.55)
        Clock.schedule_once(mostrar, 0.7)

    def gira_datos(self):
        perfil = getattr(self, "perfil_usuario", None)
        if perfil is None:
            if not hasattr(self, "_gira_sin_perfil"):
                self._gira_sin_perfil = self.gira_normalizar(None)
            return self._gira_sin_perfil
        perfil["gira"] = self.gira_normalizar(perfil.get("gira"))
        return perfil["gira"]

    def gira_guardar(self):
        if getattr(self, "perfil_usuario", None) is not None:
            self.persistir_perfil()

    def gira_reiniciar(self):
        """Borra TODO el progreso local de la Gira Nacional: regiones, país actual, logros, misiones,
        vouchers, aduana, desafíos, historial y envíos pendientes al servidor."""
        perfil = getattr(self, "perfil_usuario", None)
        if perfil is None:
            return False
        previo = self.gira_datos()
        nuevo = self.gira_normalizar(None)
        nuevo["intro"] = previo.get("intro", False)   # la presentación ya la viste
        nuevo["sync"] = previo.get("sync", False)     # no se vuelve a dar de alta en el servidor
        nuevo["diario"] = previo.get("diario", nuevo["diario"])           # reiniciar la Gira no da otro Truco del día
        nuevo["ruleta"] = previo.get("ruleta", nuevo["ruleta"])           # ni da otro giro de ruleta el mismo día
        nuevo["personaje"] = previo.get("personaje", nuevo["personaje"])   # ni da otro personaje del día
        nuevo["semana"] = previo.get("semana", nuevo["semana"])           # ni borra el avance ni los cobros de la semana
        nuevo["pend_periodico"] = previo.get("pend_periodico", [])        # ni pierde puntos aún sin informar
        nuevo["pend_diario"] = previo.get("pend_diario", [])             # ni pierde los puntos aún sin informar
        perfil["gira"] = nuevo
        self.gira_estado_cache = None
        self.gira_estado_error = None
        return self.persistir_perfil()

    def gira_pedir_reinicio(self, *_):
        panel = MesaBox(orientation="vertical", padding=dp(12), spacing=dp(8))
        panel.add_widget(Label(text="Vas a borrar todo tu progreso de la Gira Nacional:\nregiones, logros, vouchers y papeles.\nNo se puede deshacer.",
                               halign="center"))
        borrar = boton_oscuro("Sí, reiniciar la Gira")
        cancelar = boton_oscuro("Cancelar")
        for b in (borrar, cancelar):
            b.size_hint_y = None
            b.height = dp(44)
            panel.add_widget(b)
        popup = Popup(title="Reiniciar Gira Nacional", content=panel, size_hint=(0.9, 0.48), auto_dismiss=False)
        cancelar.bind(on_release=popup.dismiss)

        def hacer(*_):
            popup.dismiss()
            self.gira_reiniciar()
            self.cambiar_pantalla(self.build_gira_menu())
        borrar.bind(on_release=hacer)
        popup.open()

    def gira_historial(self, datos, texto):
        datos["hist"].append({"t": int(time.time()), "txt": texto})
        del datos["hist"][:-40]

    def gira_revisar_hechas(self, datos):
        """Marca las misiones y logros recién cumplidos (con fecha) y devuelve los avisos de lo nuevo."""
        nuevos, ahora = [], int(time.time())
        for reqs in GIRA_REQUISITOS.values():
            for req in reqs:
                if ("req." + req["id"]) not in datos["hechas"] and gira_progreso(datos, req, "req.")[2]:
                    datos["hechas"]["req." + req["id"]] = ahora
                    self.gira_historial(datos, "Misión cumplida: " + req["texto"])
                    nuevos.append("Misión cumplida: " + req["texto"])
        for lg in GIRA_LOGROS:
            if ("logro." + lg["id"]) not in datos["hechas"] and gira_progreso(datos, lg, "logro.")[2]:
                datos["hechas"]["logro." + lg["id"]] = ahora
                self.gira_historial(datos, "Logro desbloqueado: %s (+%d pts)" % (lg["nombre"], lg["puntos"]))
                nuevos.append("Logro desbloqueado: %s (+%d pts)" % (lg["nombre"], lg["puntos"]))
        for lg in GIRA_LOGROS:  # cobra los puntos de cada logro cumplido, una sola vez (marca "pago.")
            if ("logro." + lg["id"]) in datos["hechas"] and ("pago." + lg["id"]) not in datos["hechas"]:
                datos["hechas"]["pago." + lg["id"]] = ahora
                datos["puntos"] += lg["puntos"]
                datos["pend_logros"].append({"evento": secrets.token_hex(12), "logro": lg["id"]})
        return nuevos

    def gira_registrar_partida(self, gano, monto, margen=0, vs_ia=False, de_mision=True):
        """Cuenta una partida suelta terminada (no de torneo): victorias, racha sin apostar, apuestas ganadas y logros.
        Las partidas con apuesta no cortan ni suman la racha. Devuelve los avisos de misiones/logros nuevos."""
        datos = self.gira_datos()
        prog = datos["prog"]
        if not de_mision:
            # Partida común (no se entró desde el botón JUGAR de una misión de la Gira): no toca racha, apuestas
            # ni contadores de misiones. Solo suma victorias/derrotas totales.
            if gano:
                prog["victorias"] += 1
                self.gira_historial(datos, "Ganaste una partida")
            else:
                prog["derrotas"] += 1
                self.gira_historial(datos, "Perdiste una partida")
            nuevos = self.gira_revisar_hechas(datos)
            self.gira_guardar()
            self.gira_enviar_pendientes()
            return nuevos
        if vs_ia:  # misiones de Cuyo: solo cuentan las partidas contra la IA (no las online)
            if gano and monto <= 0 and margen >= 4:
                prog["margen"] += 1
            if monto >= 100:
                prog["apuesta100"] += 1
        if gano and not vs_ia:  # misión de Mesopotamia: victorias online
            prog["online"] += 1
        if gano and vs_ia and monto == GIRA_APUESTA_MINIMA:  # misión de Mesopotamia: ganarle a la IA apostando 50
            prog["ia50"] += 1
        if gano:
            prog["victorias"] += 1
            if monto <= 0:
                prog["seguidas"] += 1
                prog["mejor"] = max(prog["mejor"], prog["seguidas"])
            elif monto >= GIRA_APUESTA_MINIMA:
                prog["apuestas"] += 1
            self.gira_historial(datos, "Ganaste una partida" + (" apostando %d" % monto if monto > 0 else ""))
        else:
            prog["derrotas"] += 1
            if monto <= 0:
                prog["seguidas"] = 0
            self.gira_historial(datos, "Perdiste una partida" + (" apostando %d" % monto if monto > 0 else ""))
        nuevos = self.gira_revisar_hechas(datos)
        self.gira_guardar()
        self.gira_enviar_pendientes()  # manda al servidor los puntos de los logros recién cumplidos
        return nuevos

    # ---------- Copa Argentina / Copa Libertadores ----------
    def copa_normalizar(self, datos):
        datos = datos if isinstance(datos, dict) else {}
        def entero(v):
            try: return max(0, int(v))
            except (TypeError, ValueError): return 0
        titulos = entero(datos.get("titulos", 0))
        pases = entero(datos["pases"]) if "pases" in datos else (1 if datos.get("pase") else 0)
        return {"intro": bool(datos.get("intro", False)), "pases": pases, "titulos": titulos,
                "lib_jugadas": entero(datos.get("lib_jugadas", 0)), "lib_titulos": entero(datos.get("lib_titulos", 0))}

    def copa_datos(self):
        perfil = getattr(self, "perfil_usuario", None)
        if perfil is None:
            if not hasattr(self, "_copa_sin_perfil"):
                self._copa_sin_perfil = self.copa_normalizar(None)
            return self._copa_sin_perfil
        perfil["copa"] = self.copa_normalizar(perfil.get("copa"))
        return perfil["copa"]

    def copa_presentacion(self, despues):
        """Muestra la presentación de la Copa Argentina y luego sigue con `despues`."""
        def terminar():
            self.detener_voz()
            self.copa_datos()["intro"] = True
            if getattr(self, "perfil_usuario", None) is not None:
                self.persistir_perfil()
            despues()
        self.cambiar_pantalla(self.build_presentacion_gira(0, terminar, tema="copa"))

    def copa_ganada(self):
        """El usuario ganó la Copa Argentina: obtiene el pase a la Libertadores."""
        datos = self.copa_datos()
        datos["pases"] += 1
        datos["titulos"] += 1
        if getattr(self, "perfil_usuario", None) is not None:
            self.persistir_perfil()
        self.pase_libertadores_aviso = True

    def mostrar_cartel_pase(self):
        """Cartel 'CLASIFICADO' a pantalla completa con el escudo del equipo que ganó el pase."""
        equipo = getattr(self, "equipo_usuario", "Boca Juniors")
        anterior = getattr(self, "cartel_actual", None)
        if anterior is not None:
            try: anterior.dismiss()
            except Exception: pass
        popup = Popup(title="", separator_height=0, background="", background_color=(0, 0, 0, 1),
                      content=Widget(), size_hint=(1, 1), auto_dismiss=False)

        def cerrar(*_):
            popup.dismiss()
            if getattr(self, "cartel_actual", None) is popup:
                self.cartel_actual = None

        def ver(*_):
            cerrar()
            self.cambiar_pantalla(self.build_libertadores())
        popup.content = CartelPase(equipo, "Argentina", al_ver=ver, al_cerrar=cerrar)
        self.cartel_actual = popup
        popup.open()

    def build_libertadores(self):
        """Menú de la Copa Libertadores con el mismo estilo del menú principal: título con relieve, tarjeta de estado,
        contadores de colores y opciones con color propio. (La presentación de la Copa Argentina quedó en Pruebas.)"""
        datos = self.copa_datos()
        scroll, contenido = self._pantalla_con_volver("LIBERTADORES", lambda: self.cambiar_pantalla(self.build_menu()),
                                                      titulo_truco=True, tam_truco=(38, 66))
        DORADO, CELESTE, VERDE, GRIS = (0.96, 0.78, 0.15), (0.45, 0.72, 0.95), (0.55, 0.80, 0.25), (0.58, 0.62, 0.66)
        tiene_pase = datos["pases"] > 0
        contenido.add_widget(Label(text="[i]Copa Libertadores de América[/i]", markup=True, font_size="14sp",
                                   color=(0.96, 0.82, 0.40, 1), size_hint_y=None, height=dp(22)))

        # tarjeta de estado: copa + si tenés pase
        if tiene_pase:
            estado = "[b]¡Tenés %s![/b]\nGanaste la Copa Argentina %d %s." % (
                "un pase" if datos["pases"] == 1 else "%d pases" % datos["pases"],
                datos["titulos"], "vez" if datos["titulos"] == 1 else "veces")
        else:
            estado = "[b]Todavía no tenés pase.[/b]\nGanale la final a la Copa Argentina para conseguir uno."
        if datos["lib_titulos"]:
            estado += "\n[color=f5c518]Campeón de América: %d %s.[/color]" % (
                datos["lib_titulos"], "vez" if datos["lib_titulos"] == 1 else "veces")
        color_estado = DORADO if tiene_pase else GRIS
        tarjeta = TarjetaFondo(color_estado, demora=0.05, orientation="horizontal", size_hint_y=None,
                               height=dp(88 if datos["lib_titulos"] else 74), padding=[dp(12), dp(6)], spacing=dp(12))
        icono = IconoCirculo("copa", 56)
        icono.DORADO = (color_estado[0], color_estado[1], color_estado[2], 1)
        icono._dibujar()
        tarjeta.add_widget(icono)
        tarjeta.add_widget(_etiqueta_logro(estado, "14sp", (0.95, 0.92, 0.86, 1)))
        contenido.add_widget(tarjeta)

        # contadores de colores
        fila = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(70), spacing=dp(10))
        plantilla = "[b][size=24sp]%d[/size][/b]"
        fila.add_widget(ChipPuntos("PASES", plantilla, datos["pases"], DORADO, 0.15))
        fila.add_widget(ChipPuntos("ARGENTINA", plantilla, datos["titulos"], CELESTE, 0.25))
        fila.add_widget(ChipPuntos("AMÉRICA", plantilla, datos["lib_titulos"], VERDE, 0.35))
        contenido.add_widget(fila)

        info = _etiqueta_logro("[i]El torneo más grande del continente: 32 equipos, 8 zonas, igual que la Copa Argentina. "
                               "Cada pase vale una Libertadores.[/i]", "12sp", (0.93, 0.90, 0.85, 0.85), "center",
                               size_hint_y=None, height=dp(48))
        contenido.add_widget(info)

        # opción principal, con el estilo de los botones del menú principal
        if tiene_pase:
            jugar = ItemMenuColor("copa", "Jugar la Libertadores", "Usá un pase: 32 equipos, 8 zonas.", DORADO, 0.12)
            jugar.bind(on_release=lambda *_: self.preguntar_apuesta("Copa Libertadores", self._iniciar_libertadores_elegida, APUESTA_MAX_IA))
        else:
            jugar = ItemMenuColor("copa", "Necesitás un pase", "Ganá la Copa Argentina para clasificar.", GRIS, 0.12)
            jugar.bind(on_release=lambda *_: self.online_aviso(
                "Todavía no tenés pase.\nGanale la final a la Copa Argentina para conseguir uno.", "Copa Libertadores"))
        contenido.add_widget(jugar)

        contenido.add_widget(Adorno())
        contenido.add_widget(Label(text="[b]PARTICIPANTES[/b]", markup=True, font_size="16sp", color=(0.93, 0.74, 0.22, 1),
                                   size_hint_y=None, height=dp(30)))
        usuario = getattr(self, "equipo_usuario", "Boca Juniors")
        for pais, clubes in LIBERTADORES_EQUIPOS:
            cab = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(34), spacing=dp(8),
                            padding=[dp(4), dp(4), 0, 0])
            cab.add_widget(Bandera(BANDERA_DE_PAIS.get(pais, "uru"), 34))
            titulo_pais = Label(text="[b]%s[/b]" % pais.upper(), markup=True, font_size="15sp", halign="left",
                                valign="middle", color=(0.93, 0.74, 0.22, 1))
            titulo_pais.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
            cab.add_widget(titulo_pais)
            contenido.add_widget(cab)
            for club in clubes:
                suyo = club == usuario
                contenido.add_widget(FilaClub([club], [("[b]%s[/b]  (vos)" if suyo else "%s") % club],
                                              fondo=(0.55, 0.40, 0.08, 0.55) if suyo else (0, 0, 0, 0.28),
                                              alto=38, tam="14sp"))
            if pais == "Argentina" and usuario not in clubes:
                contenido.add_widget(FilaClub([usuario], ["[b]%s[/b]  (vos, en lugar de uno de ellos)" % usuario],
                                              fondo=(0.55, 0.40, 0.08, 0.55), alto=38, tam="12sp"))
        contenido.add_widget(Adorno())
        return scroll

    def gira_conquistadas(self):
        datos = self.gira_datos()
        return sum(1 for v in datos["regiones"].values() if v >= GIRA_VICTORIAS_REGION)

    def refrescar_fila_gira(self):
        """Puntos de gira y puesto en el ranking (último dato conocido; se pide de nuevo al servidor)."""
        fila = getattr(self, "fila_gira_menu", None)
        if fila is None:
            return
        datos = self.gira_datos()
        conquistadas = self.gira_conquistadas()
        cache = getattr(self, "gira_estado_cache", None)
        fila.actualizar(datos["puntos"], conquistadas, cache,
                        cargando=bool(conquistadas >= 1 and self.tiene_cuenta() and not cache))
        if conquistadas < 1 or not self.tiene_cuenta():
            return
        perfil = self.perfil_usuario

        def ok(r):
            self.gira_estado_cache = r
            self.gira_estado_error = None
            if getattr(self, "fila_gira_menu", None) is fila:
                fila.actualizar(self.gira_datos()["puntos"], self.gira_conquistadas(), r)

        def fallo(detalle="", codigo=None):
            self.gira_estado_error = (codigo, str(detalle)[:120])
            print("Ranking: fallo /gira/mi_estado ->", codigo, detalle)
            if getattr(self, "fila_gira_menu", None) is fila:
                fila.actualizar(self.gira_datos()["puntos"], self.gira_conquistadas(),
                                getattr(self, "gira_estado_cache", None), error=self.gira_estado_error)
        self.api("/gira/mi_estado", {"id": perfil["id"], "token": perfil["token"]}, ok=ok, fallo=fallo)

    def gira_enviar_logros(self):
        """Informa al servidor los logros cumplidos (uno por uno) para que sus puntos entren al ranking online.
        Si falla (sin conexión, o el servidor todavía no tiene /gira/logro) queda en cola y se reintenta más tarde."""
        if not self.tiene_cuenta() or getattr(self, "_logros_enviando", False):
            return
        datos = self.gira_datos()
        if not datos["sync"] or not datos["pend_logros"]:
            return
        perfil = self.perfil_usuario
        primero = datos["pend_logros"][0]
        self._logros_enviando = True

        def listo(*_):
            self._logros_enviando = False
            d = self.gira_datos()   # datos frescos: gira_datos() arma un diccionario nuevo cada vez, el de arriba ya quedó viejo
            d["pend_logros"] = [p for p in d["pend_logros"] if p.get("evento") != primero["evento"]]
            self.gira_guardar()
            if d["pend_logros"]:
                self.gira_enviar_logros()
            else:
                self.gira_refrescar_ranking()

        def fallo(mensaje="", codigo=None):
            self._logros_enviando = False
            self.gira_error_envio = "logros: %s (%s)" % (str(mensaje)[:60], codigo)
            if codigo == 400:
                listo()   # rechazado de forma definitiva: no se reintenta (así no traba a los que siguen)
        self.api("/gira/logro", {"id": perfil["id"], "token": perfil["token"],
                                 "nombre": perfil.get("nombre", "Jugador"), "club": perfil.get("club", ""),
                                 "evento": primero["evento"], "logro": primero["logro"]}, ok=listo, fallo=fallo)

    def gira_enviar_descuentos(self):
        """Informa al servidor los puntos descontados por desafíos perdidos para que bajen también en el ranking online.
        Si falla (sin conexión o el servidor todavía no tiene /gira/descuento) queda en cola y se reintenta más tarde."""
        if not self.tiene_cuenta() or getattr(self, "_descuentos_enviando", False):
            return
        datos = self.gira_datos()
        if not datos["sync"] or not datos["pend_desafio"]:
            return
        perfil = self.perfil_usuario
        primero = datos["pend_desafio"][0]
        self._descuentos_enviando = True

        def listo(*_):
            self._descuentos_enviando = False
            d = self.gira_datos()   # datos frescos (el de arriba ya quedó viejo)
            d["pend_desafio"] = [p for p in d["pend_desafio"] if p.get("evento") != primero["evento"]]
            self.gira_guardar()
            if d["pend_desafio"]:
                self.gira_enviar_descuentos()
            else:
                self.gira_refrescar_ranking()

        def fallo(mensaje="", codigo=None):
            self._descuentos_enviando = False
            self.gira_error_envio = "descuentos: %s (%s)" % (str(mensaje)[:60], codigo)
            if codigo == 400:
                listo()   # rechazado de forma definitiva: no se reintenta (así no traba a los que siguen)
        self.api("/gira/descuento", {"id": perfil["id"], "token": perfil["token"],
                                     "nombre": perfil.get("nombre", "Jugador"), "club": perfil.get("club", ""),
                                     "evento": primero["evento"], "puntos": primero["puntos"], "motivo": "desafio"},
                 ok=listo, fallo=fallo)

    def gira_enviar_pendientes(self):
        """Informa al servidor las victorias de gira (una por una, en orden) y sincroniza el progreso previo."""
        self.gira_enviar_logros()
        self.gira_enviar_descuentos()
        self.gira_enviar_diario()
        self.gira_enviar_periodicos()
        if not self.tiene_cuenta() or getattr(self, "_gira_enviando", False):
            return
        datos = self.gira_datos()
        perfil = self.perfil_usuario
        base = {"id": perfil["id"], "token": perfil["token"],
                "nombre": perfil.get("nombre", "Jugador"), "club": perfil.get("club", "")}
        if not datos["sync"]:
            self._gira_enviando = True
            def sync_ok(r):
                self._gira_enviando = False
                d = self.gira_datos()   # datos frescos (el de arriba ya quedó viejo)
                d["sync"] = True
                if not r.get("ya"):
                    d["pend"] = []  # el alta ya incluyó esas victorias
                self.gira_guardar()
                self.gira_refrescar_ranking()
                self.gira_enviar_logros()
            def sync_fallo(*_):
                self._gira_enviando = False
            self.api("/gira/sincronizar", dict(base, regiones=datos["regiones"]), ok=sync_ok, fallo=sync_fallo)
            return
        if not datos["pend"]:
            return
        self._gira_enviando = True
        primero = datos["pend"][0]

        def listo(*_):
            self._gira_enviando = False
            d = self.gira_datos()   # datos frescos (el de arriba ya quedó viejo)
            d["pend"] = [p for p in d["pend"] if p.get("evento") != primero["evento"]]
            d["sync"] = True
            self.gira_guardar()
            if d["pend"]:
                self.gira_enviar_pendientes()
            else:
                self.gira_refrescar_ranking()

        def fallo(mensaje, codigo):
            self._gira_enviando = False
            self.gira_error_envio = "victorias: %s (%s)" % (str(mensaje)[:60], codigo)
            if codigo is not None and 400 <= codigo < 500 and "rápida" not in str(mensaje):
                listo()  # rechazado de forma definitiva: no se reintenta
        self.api("/gira/victoria", dict(base, evento=primero["evento"], region=primero["region"]),
                 ok=listo, fallo=fallo)

    def gira_refrescar_ranking(self, *_):
        """Pide podio + tu puesto y los pinta si la pantalla de la gira sigue abierta."""
        conquistadas = self.gira_conquistadas()
        widget = getattr(self, "podio_gira", None)
        if widget is None or conquistadas < 1 or not self.tiene_cuenta():
            return
        resultado = {}
        perfil = self.perfil_usuario

        def pintar():
            if getattr(self, "podio_gira", None) is widget and "podio" in resultado:
                widget.mostrar(resultado["podio"], resultado.get("estado"), conquistadas, True)

        def podio_ok(r):
            resultado["podio"] = r.get("podio", [])
            pintar()

        def estado_ok(r):
            self.gira_estado_cache = r
            resultado["estado"] = r
            pintar()
        self.api("/gira/podio", None, metodo="GET", ok=podio_ok)
        self.api("/gira/mi_estado", {"id": perfil["id"], "token": perfil["token"]}, ok=estado_ok)

    def build_gira(self):
        datos = self.gira_datos()
        if not datos["intro"]:
            return self.build_presentacion_gira(0, al_terminar=lambda: self.gira_intro_terminada())
        self.musica_menu_reanudar()
        indice = min(datos["pais"], len(GIRA_PAISES) - 1)
        if not gira_pais_desbloqueado(datos, indice):
            indice = 0
        while indice > 0 and gira_aduana_estado(datos, GIRA_PAISES[indice])[0] in ("pendiente", "espera"):
            indice -= 1  # todavía no tiene el papel aduanero para estar en ese país
        pais = GIRA_PAISES[indice]
        encuentro_camino = None   # (tramo, marca, cartel): sale cuando el muñequito pasa por la mitad de ESE tramo
        if not getattr(self, "_mafia_avisado", False) and gira_mafia_pendiente(datos, pais):
            self._mafia_avisado = True   # te para una vez por sesión, hasta que le ganes
            Clock.schedule_once(lambda dt: self.mafia_encuentro(), 0.9)
        elif not getattr(self, "_mago_avisado", False) and gira_mago_pendiente(datos, pais):
            encuentro_camino = (1, "_mago_avisado", self.mago_encuentro)   # tramo Patagonia > Cuyo
        elif not getattr(self, "_cientifico_avisado", False) and gira_cientifico_pendiente(datos, pais):
            encuentro_camino = (2, "_cientifico_avisado", self.cientifico_encuentro)   # tramo Cuyo > Mesopotamia
        # Los encuentros del camino (viaje_evento) están desactivados: en la ruta solo te frenan el mafioso, el mago y el científico.
        raiz = MesaBox(orientation="vertical", padding=dp(8), spacing=dp(5))
        DORADO, NARANJA = (0.96, 0.78, 0.15), (0.95, 0.55, 0.15)
        cabecera = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(58), spacing=dp(6))
        atras = BotonColor("< Volver", DORADO, ancho=84, font_size="13sp")
        atras.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_gira_menu()))
        cabecera.add_widget(atras)
        cabecera.add_widget(TituloTruco("GIRA NACIONAL", 26, 58))
        info = BotonColor("?", DORADO, ancho=40, font_size="16sp")
        info.bind(on_release=lambda *_: self.cambiar_pantalla(self.build_presentacion_gira(
            0, al_terminar=lambda: self.cambiar_pantalla(self.build_gira()))))
        cabecera.add_widget(info)
        cabecera.add_widget(self.nuevo_boton_sonido(40))
        raiz.add_widget(cabecera)
        raiz.add_widget(Adorno())
        # selector de país
        fila = TarjetaFondo(DORADO, demora=0.05, orientation="horizontal", size_hint_y=None, height=dp(50),
                            padding=[dp(6), 0, dp(6), 0], spacing=dp(6))
        anterior = BotonColor("<", DORADO, ancho=44, font_size="18sp")
        siguiente = BotonColor(">", DORADO, ancho=44, font_size="18sp")
        hechas = sum(1 for _, e, _v in gira_estados(datos, pais) if e == "conquistada")
        fila.add_widget(anterior)
        fila.add_widget(Label(text=f"[b]{pais['nombre']}[/b]  ·  {hechas}/{len(pais['regiones'])} regiones", markup=True, font_size="15sp",
                              color=(1.0, 0.93, 0.72, 1)))
        fila.add_widget(siguiente)
        raiz.add_widget(fila)
        anterior.disabled = indice == 0
        siguiente.disabled = indice + 1 >= len(GIRA_PAISES) or not gira_pais_desbloqueado(datos, indice + 1)
        for b in (anterior, siguiente):
            b.opacity = 0.35 if b.disabled else 1
        def cambiar(delta):
            def pasar():
                self.gira_datos()["pais"] = indice + delta
                self.gira_guardar()
                self.cambiar_pantalla(self.build_gira())
            destino = GIRA_PAISES[indice + delta]
            if delta > 0 and gira_aduana_estado(self.gira_datos(), destino)[0] in ("pendiente", "espera"):
                self.gira_aduana_cartel(destino, pasar)  # pregunta por el papel aduanero
            else:
                pasar()
        anterior.bind(on_release=lambda *_: cambiar(-1))
        siguiente.bind(on_release=lambda *_: cambiar(1))
        _est_g = gira_estados(datos, pais)
        _pendiente = None
        if not any(e == "disponible" for _r, e, _v in _est_g) and not gira_pais_completo(datos, pais):
            _pendiente = next((r for r, e, _v in _est_g if e != "conquistada"), None)  # región que espera misiones
        if indice + 1 < len(GIRA_PAISES) and not gira_pais_desbloqueado(datos, indice + 1):
            pista = f"Conquistá todas las regiones de {pais['nombre'].title()} para viajar a {GIRA_PAISES[indice + 1]['nombre'].title()}."
        elif indice + 1 >= len(GIRA_PAISES) and gira_pais_completo(datos, pais):
            pista = "¡Recorriste toda la gira! Sos el campeón del continente."
        elif indice + 1 < len(GIRA_PAISES) and gira_aduana_estado(datos, GIRA_PAISES[indice + 1])[0] in ("pendiente", "espera"):
            _sig = GIRA_PAISES[indice + 1]
            _est, _falta = gira_aduana_estado(datos, _sig)
            _cfg = GIRA_ADUANA[_sig["id"]]
            pista = ("Papel aduanero en trámite para pasar a %s: faltan %s." % (_sig["nombre"].title(), gira_texto_tiempo(_falta))
                     if _est == "espera" else
                     "Para pasar a %s necesitás el papel aduanero: %d monedas o esperar %d días. Tocá >." %
                     (_sig["nombre"].title(), _cfg["costo"], _cfg["dias"]))
        else:
            pista = ("Ganá un mini campeonato para conquistar la región.\n"
                     f"Desde la 3.ª región, una sí y una no se juega con apuesta de {GIRA_APUESTA_REGION}.")
        _prox_pas = next((r for r, e, _v in _est_g if e == "disponible"), None)
        _faltan_pas = _prox_pas is not None and gira_faltan_vouchers(datos, pais, _prox_pas)
        if _faltan_pas:
            pista = "Ya tenés la invitación a %s.\nConseguí el pasaje y la estadía para viajar." % _prox_pas["nombre"].title()
            if gira_sin_estadia(datos, pais, _prox_pas):
                pista = "Estás en %s sin estadía.\nPara la revancha conseguí otro voucher de hotel." % _prox_pas["nombre"].title()
        if _pendiente is not None:
            pista = "Cumplí las misiones para abrir %s.\nTocá el botón de abajo para ver qué te falta." % _pendiente["nombre"].title()
        tarjeta_pista = TarjetaFondo(NARANJA, demora=0.15, orientation="vertical", size_hint_y=None, height=dp(64),
                                     padding=[dp(8), dp(4)])
        _lp = Label(text=f"[color=f5c726]Puntos de gira:[/color] [b]{datos['puntos']}[/b]\n[size=11sp]{pista}[/size]",
                    markup=True, font_size="14sp", halign="center", valign="middle", color=(1.0, 0.95, 0.85, 1))
        _lp.bind(size=lambda w, sz: setattr(w, "text_size", (sz[0], None)))
        tarjeta_pista.add_widget(_lp)
        raiz.add_widget(tarjeta_pista)
        self.pais_gira = pais
        self.podio_gira = PodioGira()
        self.podio_gira.mostrar(None, None, self.gira_conquistadas(), self.tiene_cuenta())
        self.podio_gira.al_tocar = lambda: self.cambiar_pantalla(self.build_top_gira(lambda: self.cambiar_pantalla(self.build_gira())))
        raiz.add_widget(self.podio_gira)
        self.gira_enviar_pendientes()
        self.gira_refrescar_ranking()
        self.mapa_gira = MapaGira(pais, datos, al_tocar=self.abrir_region_gira, al_llegar=self.gira_guardar)
        raiz.add_widget(self.mapa_gira)
        if encuentro_camino is not None:
            _tramo_enc, _marca_enc, _cartel_enc = encuentro_camino
            def _frena(_marca=_marca_enc, _cartel=_cartel_enc):
                setattr(self, _marca, True)   # te frena una vez por sesión, hasta que le ganes
                _cartel()
            self.mapa_gira.parar_en(_tramo_enc, _frena)
        proxima = next((r for r, e, _v in gira_estados(datos, pais) if e == "disponible"), None)
        if proxima is not None and _faltan_pas:
            texto = "PASAJES PARA %s" % proxima["nombre"]
        elif proxima is not None:
            texto = "JUGAR EN %s%s" % (proxima["nombre"], " · APUESTA %d" % GIRA_APUESTA_REGION
                                       if gira_region_exige_apuesta(pais, proxima) else "")
        elif _pendiente is not None:
            texto = "MISIONES PARA ABRIR %s" % _pendiente["nombre"]
        else:
            texto = "¡PAÍS COMPLETO!"
        _col = ((0.72, 0.58, 0.96) if _faltan_pas else NARANJA) if proxima is not None else ((0.72, 0.58, 0.96) if _pendiente is not None else (0.35, 0.85, 0.45))
        jugar = boton_cartel(texto, _col, "16sp", 58)
        jugar.disabled = proxima is None and _pendiente is None
        if proxima is not None:
            _regs_g = pais["regiones"]
            _dest = _regs_g[_regs_g.index(proxima) - 1] if (_faltan_pas and _regs_g.index(proxima) > 0) else proxima
            jugar.bind(on_release=lambda *_: self.abrir_region_gira(_dest))
        elif _pendiente is not None:
            jugar.bind(on_release=lambda *_: self.abrir_region_gira(_pendiente))
        raiz.add_widget(jugar)
        return raiz

    def gira_intro_terminada(self):
        self.detener_voz()
        self.gira_datos()["intro"] = True
        self.gira_guardar()
        self.cambiar_pantalla(self.build_gira())

    def gira_aduana_cartel(self, pais, al_pasar, simulado=None):
        """Pregunta si querés pasar al país: papel aduanero pagando monedas o esperando unos días (gratis).
        Al aprobarse (pagando o cumplida la espera) aparece el papel con tu nombre y el sello APROBADO.
        simulado = dict de datos falsos (sólo la sección Pruebas): no cobra monedas ni toca tu progreso."""
        cfg = GIRA_ADUANA[pais["id"]]
        costo, dias = cfg["costo"], cfg["dias"]
        nombre = pais["nombre"].title()
        datos = simulado if simulado is not None else self.gira_datos()
        estado, falta = gira_aduana_estado(datos, pais)

        def poner(ok, hasta, fecha=0, visto=False):
            d = simulado if simulado is not None else self.gira_datos()
            d.setdefault("aduana", {})[pais["id"]] = {"ok": ok, "hasta": int(hasta), "fecha": int(fecha), "visto": visto}
            if simulado is None:
                self.gira_guardar()

        def mostrar_papel(fecha):
            perfil = getattr(self, "perfil_usuario", None) or {}
            papel = PapelAduana(self.online_nombre(), perfil.get("id") or "—", nombre.upper(),
                                time.strftime("%d/%m/%Y", time.localtime(fecha)))
            self.mostrar_cartel("ADUANA", "¡Papel aprobado!", True, alto=0.94, extra=papel,
                                botones=[("PASAR A %s" % nombre.upper(), al_pasar)])

        if estado in ("libre", "aprobado"):
            papel = (datos.get("aduana") or {}).get(pais["id"]) or {}
            if estado == "aprobado" and (papel.get("ok") or int(papel.get("hasta", 0) or 0) > 0) and not papel.get("visto"):
                # se cumplieron los días de espera: recién ahora se entrega el papel aprobado
                fecha = int(papel.get("fecha", 0) or 0) or int(papel.get("hasta", 0) or 0)
                if fecha < 86400 * 365:
                    fecha = int(time.time())
                poner(bool(papel.get("ok")), papel.get("hasta", 0), fecha, True)
                mostrar_papel(fecha)
            else:
                al_pasar()
            return

        def pagar():
            if simulado is not None:
                ahora = int(time.time())
                poner(True, 0, ahora, True)
                mostrar_papel(ahora)
                return
            saldo = getattr(self, "saldo", None) or 0
            if not self.tiene_cuenta() or saldo < costo:
                self.online_aviso("Para pagar el papel aduanero necesitás una cuenta online y %d monedas.\nTenés %d." % (costo, saldo), "Aduana")
                return

            def cobrado():
                self.reclamar_apuesta("perder", silencioso=True)  # las monedas retenidas quedan cobradas
                ahora = int(time.time())
                poner(True, 0, ahora, True)
                mostrar_papel(ahora)
            self.abrir_apuesta("torneo", costo, cobrado)

        def esperar():
            poner(False, time.time() + dias * 86400)
            self.gira_aduana_cartel(pais, al_pasar, simulado)

        if estado == "espera":
            detalle = ("Tu papel aduanero está en trámite.\nFalta: %s\n\n"
                       "Cuando se cumpla, pasás gratis. O pagá %d monedas y pasás ahora." % (gira_texto_tiempo(falta), costo))
            botones = [("PAGAR %d Y PASAR AHORA" % costo, pagar)]
            if simulado is not None:
                botones.append(("(PRUEBA) YA PASARON LOS %d DÍAS" % dias,
                                lambda: (poner(False, time.time() - 1), self.gira_aduana_cartel(pais, al_pasar, simulado))))
        else:
            gentilicio = pais["gentilicio"]
            tierra = gentilicio[:-1] + "a" if gentilicio.endswith("o") else gentilicio
            detalle = ("Para pasar a tierra %s necesitás el papel aduanero.\n\n"
                       "• Pagarlo: %d monedas y pasás ya.\n• Esperar %d días: sale gratis." % (tierra, costo, dias))
            botones = [("PAGAR %d MONEDAS" % costo, pagar), ("ESPERAR %d DÍAS (GRATIS)" % dias, esperar)]
        botones.append(("CERRAR", None))
        self.mostrar_cartel("ADUANA", "Papel aduanero", False, detalle=detalle, alto=0.34 + 0.085 * len(botones) + 0.12,
                            botones=botones, apilados=True)

    def abrir_region_gira(self, region, prueba=None, saltar_ficha=False):
        # prueba: sólo la usa la sección Pruebas (progreso falso). El cartel es el mismo que en el juego real.
        pais = prueba["pais"] if prueba else getattr(self, "pais_gira", GIRA_PAISES[0])
        datos = prueba["datos"] if prueba else self.gira_datos()
        estado = next(e for r, e, _v in gira_estados(datos, pais) if r is region)
        # la descripción de la región recién se ve cuando la región está desbloqueada (disponible o conquistada)
        info = gira_info_widget(pais, region) if estado != "bloqueada" else None
        if not prueba and estado == "disponible" and gira_sin_estadia(datos, pais, region):
            _dh = next((d for d in DESAFIOS if d["region"] == region["id"] and d["tipo"] == "hotel"), None)
            self.mostrar_cartel_region(region, "bloqueada", "Sin estadía",
                                       detalle=("Perdiste y se usó tu voucher de hotel.\nPara la revancha en [b]%s[/b] necesitás otro:\n"
                                                "ganale a %s en Desafío o comprá uno.") % (region["nombre"].title(), _dh["nombre"] if _dh else "su dueño"),
                                       alto=0.62,
                                       botones=[("IR A DESAFÍOS", lambda: self.cambiar_pantalla(self.build_desafios())), ("CERRAR", None)])
            return
        if estado == "bloqueada":
            indice = pais["regiones"].index(region)
            previa = pais["regiones"][indice - 1]
            reqs = gira_requisitos_region(datos, pais, region)
            if reqs and indice > 0 and gira_region_conquistada(datos, pais, previa):
                # Las misiones se cumplen desde la región donde está el muñequito, pero al tocar ésta se ve SU propio cartel (no el de la anterior).
                self.mostrar_cartel_region(region, "bloqueada", "Región bloqueada",
                                           detalle=f"Cumplí las misiones en [b]{previa['nombre'].title()}[/b]\npara abrir [b]{region['nombre'].title()}[/b].",
                                           alto=0.56,
                                           botones=[("VER MISIONES", lambda p=previa: self.abrir_region_gira(p)), ("CERRAR", None)])
                return
            self.mostrar_cartel_region(region, "bloqueada", "Región bloqueada",
                                       detalle=f"Primero conquistá [b]{previa['nombre'].title()}[/b]:\nganá un mini campeonato ahí.", alto=0.52)
            return
        _ficha_a_lista = False   # True: se muestra primero la ficha de la región y su JUGAR lleva al menú de misiones
        if not prueba:
            _regs = pais["regiones"]
            _i = _regs.index(region)
            # ¿El muñequito ya está acá? Si la región está desbloqueada pero faltan el voucher de hotel y el de colectivo, todavía no viajó.
            _llego = not (estado == "disponible" and _i > 0 and gira_faltan_vouchers(datos, pais, region)
                          and not gira_ya_viajo(datos, pais, region))
            # Cartel de la región donde estás: lo que falta para abrir la siguiente (campeonato de ésta, misiones y vouchers).
            if _i + 1 < len(_regs):
                _sig = _regs[_i + 1]
                _reqs = gira_requisitos_region(datos, pais, _sig)
                _defs = GIRA_REQUISITOS.get(gira_clave(pais, _sig), [])
                _pares = list(zip(_reqs, _defs))
                _falta_mision = any(not rq[3] for rq, d in _pares if not str(d["cuenta"]).startswith("voucher_"))
                _falta_pasaje = any(not rq[3] for rq, d in _pares if str(d["cuenta"]).startswith("voucher_"))
                if _reqs and (estado != "conquistada" or _falta_mision or _falta_pasaje):
                    _ok = estado == "conquistada"
                    if _llego and not _ok and not saltar_ficha:
                        _ficha_a_lista = True   # primero la presentación (fotos y voz); su JUGAR lleva a este menú
                    else:
                        if _llego:
                            def _jugar_torneo(r=region):   # fila "Ganar el campeonato": cierra el cartel y arranca el torneo
                                _c = getattr(self, "cartel_actual", None)
                                if _c is not None:
                                    try: _c.dismiss()
                                    except Exception: pass
                                    self.cartel_actual = None
                                self.iniciar_gira_torneo(r)
                            _extra = gira_misiones_widget(
                                _sig, region["nombre"].title(), _reqs,
                                [(lambda c=d["cuenta"]: self.gira_jugar_mision(c)) for d in _defs],
                                previa_ok=_ok, accion_previa=None if _ok else _jugar_torneo)
                            _botones = None
                        else:   # se ve, pero deshabilitado hasta que el muñequito llegue
                            _extra = gira_misiones_widget(
                                _sig, region["nombre"].title(), _reqs, [], previa_ok=False,
                                pie_texto="Se habilita cuando el muñequito llegue a %s.\nPrimero conseguí los pasajes." % region["nombre"].title())
                            _botones = [("VER PASAJES", lambda r=_regs[_i - 1]: self.abrir_region_gira(r)), ("CERRAR", None)]
                        _corto = len(_reqs) + 1 <= 3   # con pocas filas hay lugar para el texto de la invitación
                        _detalle = ""
                        if _ok and _corto:
                            _detalle = ("Ya tenés la invitación a [b]%s[/b],\npero faltan los pasajes." % _sig["nombre"].title()
                                        if not _falta_mision else "Cumplí las misiones para abrir [b]%s[/b]." % _sig["nombre"].title())
                        self.mostrar_cartel_region(region, "lista" if _ok else "misiones",
                                                   "Torneo ganado" if _ok else "Rumbo a %s" % _sig["nombre"].title(),
                                                   detalle=_detalle, alto=0.80 if _llego else 0.88, extra=_extra, botones=_botones)
                        return
            if not _llego:   # región sin cartel de misiones (por ejemplo la última): llevar a los pasajes de la anterior
                self.abrir_region_gira(_regs[_i - 1])
                return
        premio = region["pt"] // 2
        repetir = estado == "conquistada"
        exige = gira_region_exige_apuesta(pais, region)
        saldo = getattr(self, "saldo", None)
        saldo = saldo if (self.tiene_cuenta() and saldo is not None) else 0
        detalle = (f"Mini campeonato de 16 equipos: ganá 4 partidas.\n"
                   + ("Región conquistada: no se puede volver a jugar\n" if repetir
                      else f"Premio: +{premio} puntos para el ranking online (solo la primera vez)\n"))
        if pais["id"] == "arg" and region["id"] in DESAFIO_REGIONES and not repetir:
            detalle += "Si perdés o abandonás se usa tu voucher de hotel: para la revancha necesitás otro.\n"
        if exige:
            detalle += f"Apuesta obligatoria: {GIRA_APUESTA_REGION} monedas · Tenés {saldo}"
            if saldo < GIRA_APUESTA_REGION and not prueba:
                motivo = ("Necesitás una cuenta online y al menos %d monedas." % GIRA_APUESTA_REGION)
                self.mostrar_cartel_region(region, "apuesta", "Apuesta obligatoria",
                                           detalle=f"Esta región solo se juega apostando {GIRA_APUESTA_REGION} monedas.\n{motivo}", alto=0.56)
                return
        else:
            detalle += "Sin apuesta · Inscripción gratis"
        if repetir:   # región ya conquistada: se ve la presentación, pero no se vuelve a jugar
            self.mostrar_cartel_region(region, "lista", "Región conquistada",
                                       detalle=detalle.strip(), alto=0.66 if info is None else 0.94, extra=info,
                                       botones=[("JUGAR", None, True), ("CERRAR", None)])
            return
        if _ficha_a_lista:
            _accion_jugar = lambda: self.abrir_region_gira(region, None, True)
        elif prueba:
            _accion_jugar = lambda: prueba["jugar"](region)
        else:
            _accion_jugar = lambda: self.iniciar_gira_torneo(region)
        self.mostrar_cartel_region(region, "lista", "Conquistada · jugar de nuevo" if repetir else "¡Anotate!",
                                   detalle=detalle.strip(), alto=0.66 if info is None else 0.94, extra=info,
                                   botones=[(f"APOSTAR {GIRA_APUESTA_REGION} Y JUGAR" if (exige and not _ficha_a_lista) else "JUGAR",
                                             _accion_jugar),
                                            ("CERRAR", None)])

    def gira_jugar_mision(self, cuenta):
        """Desde el cartel de misiones: arranca directo la partida individual que pide la misión."""
        cartel = getattr(self, "cartel_actual", None)
        if cartel is not None:
            try: cartel.dismiss()
            except Exception: pass
            self.cartel_actual = None
        if str(cuenta).startswith("voucher_"):   # el voucher se consigue en el Desafío
            Clock.schedule_once(lambda _dt: self.cambiar_pantalla(self.build_desafios()), 0.05)
            return
        if cuenta == "online":  # esta misión se juega contra otra persona: se abre el menú online
            self._online_mision_pendiente = True
            Clock.schedule_once(lambda _dt: self.cambiar_pantalla(self.build_online_menu()), 0.05)
            return
        self._mision_pendiente = cuenta   # _arrancar_individual la toma: la partida sabe que viene de una misión de la Gira

        def arrancar(_dt):
            try:
                monto = GIRA_MISION_APUESTA.get(cuenta, 0)
                if monto > 0:  # misión con apuesta
                    self.abrir_apuesta("ia", monto, self._arrancar_individual)
                else:  # misión sin apostar
                    self.apuesta_ticket = None
                    self._arrancar_individual()
            except Exception:
                import traceback; traceback.print_exc()
                self._mision_pendiente = None
                self.cambiar_pantalla(self.build_gira())
        Clock.schedule_once(arrancar, 0.05)  # el cartel se cierra primero y recién después cambia la pantalla

    def gira_mision_pendiente(self, cuenta):
        """True si todavía falta cumplir alguna misión de la Gira que se mide con ese contador."""
        datos = self.gira_datos()
        for reqs in GIRA_REQUISITOS.values():
            for req in reqs:
                if req["cuenta"] == cuenta:
                    _actual, _meta, ok = gira_progreso(datos, req, "req.")
                    if not ok:
                        return True
        return False

    def gira_armar_equipos(self, pais, indice_region):
        usuario = getattr(self, "equipo_usuario", "Boca Juniors")
        pool = pais["clubes"] if pais["clubes"] is not None else CLUBES_ARGENTINOS
        pool = [c for c in pool if c != usuario]
        equipos = random.sample(pool, min(15, len(pool)))
        while len(equipos) < 15:  # países con pocos clubes: se completan con selecciones de otras ligas
            extra = random.choice([c for c in CLUBES_ARGENTINOS if c != usuario and c not in equipos])
            equipos.append(extra)
        # más dificultad hacia adelante: más equipos fareros en las últimas regiones
        peso_farol = min(0.6, 0.15 + 0.08 * indice_region)
        perfiles = {}
        for e in equipos:
            r = random.random()
            perfiles[e] = "Farolero" if r < peso_farol else ("Prudente" if r < peso_farol + 0.25 else "Equilibrado")
        return equipos, perfiles

    def iniciar_gira_torneo(self, region):
        pais = getattr(self, "pais_gira", GIRA_PAISES[0])
        try:
            if gira_region_conquistada(self.gira_datos(), pais, region):
                return   # una región conquistada no se vuelve a jugar
        except Exception:
            pass
        try:
            if gira_sin_estadia(self.gira_datos(), pais, region):
                self.abrir_region_gira(region)   # muestra el cartel "Sin estadía"
                return
        except Exception:
            pass
        if gira_region_exige_apuesta(pais, region):
            # Apuesta obligatoria: el torneo recién arranca cuando el servidor retuvo las monedas.
            self.abrir_apuesta("torneo", GIRA_APUESTA_REGION, lambda: self._arrancar_gira_torneo(pais, region))
        else:
            self.apuesta_ticket = None
            self._arrancar_gira_torneo(pais, region)

    def _arrancar_gira_torneo(self, pais, region):
        """Antes de arrancar un campeonato: si tenés el Pase a cuartos, te pregunta si lo querés usar."""
        try:
            tiene = poder_sin_gastar(self.gira_datos(), PODER_POR_ID["pase"])
        except Exception:
            tiene = False
        if not tiene:
            self._arrancar_gira_torneo_base(pais, region, False)
            return
        self.mostrar_cartel("PASE A CUARTOS", "¿Usás el pase?", True,
                            detalle="Arrancás este campeonato directo desde cuartos de final y salteás los octavos.\nSe usa UNA sola vez.",
                            botones=[("USAR EL PASE", lambda: self._arrancar_gira_torneo_base(pais, region, True)),
                                     ("ARRANCAR NORMAL", lambda: self._arrancar_gira_torneo_base(pais, region, False))],
                            apilados=True, alto=0.5)

    def _arrancar_gira_torneo_base(self, pais, region, pase=False):
        try:
            _d = self.gira_datos()
            _d.setdefault("viajadas", {})[gira_clave(pais, region)] = 1   # el muñequito ya viajó: si perdés, se queda acá
            self.gira_guardar()
        except Exception:
            pass
        self.cancelar_timers()
        self.online_cerrar_ws()
        self.modo_online = False
        self.modo_gira = False
        self.modo_torneo = True
        self.modo_libertadores = False
        self.modo_gira_torneo = True
        self.gira_pais_id, self.gira_region_id = pais["id"], region["id"]
        self.torneo_celebrado = True
        self._fenix_partido = None
        self.torneo_premio_acum = 0
        self.torneo_con_apuesta = bool(getattr(self, "apuesta_ticket", None))
        self.celebracion_pendiente = False
        self.equipo_usuario = getattr(self, "equipo_usuario", "Boca Juniors")
        equipos, perfiles = self.gira_armar_equipos(pais, pais["regiones"].index(region))
        self.perfiles_mentira = perfiles
        self.estadisticas_farol = {e: {"cantados": 0, "descubiertos": 0} for e in equipos}
        todos = ["VOS"] + equipos
        random.shuffle(todos)
        self.torneo_etapa = "eliminatorias"
        self.torneo_ronda = 0
        self.torneo_finalizado = False
        self.torneo_campeon = None
        self.torneo_fixture_grupos = []
        self.torneo_partido_usuario_pendiente = False
        self.torneo_resultado_registrado = False
        self.torneo_eliminatorias = [(todos[i], todos[i + 1], False, None) for i in range(0, 16, 2)]
        if pase:
            d = self.gira_datos()
            d["pase"]["usado"] = int(time.time())
            self.gira_historial(d, "Usaste el Pase a cuartos en %s" % region["nombre"].title())
            self.gira_guardar()
            for j, (a_, b_, _h, _w) in enumerate(self.torneo_eliminatorias):   # los octavos se dan por jugados
                if "VOS" in (a_, b_):
                    self.torneo_eliminatorias[j] = (a_, b_, True, "VOS")
                else:
                    g_, _s1, _s2 = self.simular_resultado_torneo(a_, b_)
                    self.torneo_eliminatorias[j] = (a_, b_, True, g_)
            self.cerrar_ronda_eliminatoria()   # pasa a cuartos
        self.mostrar_panel_torneo()

    def gira_volver_mapa(self, *_):
        self.cancelar_timers()
        if getattr(self, "modo_gira_torneo", False):   # abandonar el torneo a medias cuenta como perderlo: se usa el voucher de hotel
            try:
                _pais = next(p for p in GIRA_PAISES if p["id"] == getattr(self, "gira_pais_id", ""))
                _region = next(r for r in _pais["regiones"] if r["id"] == getattr(self, "gira_region_id", ""))
                _datos = self.gira_datos()
                if not gira_region_conquistada(_datos, _pais, _region) and gira_gastar_hotel(_datos, _pais, _region):
                    self.gira_historial(_datos, "Abandonaste %s: se usó tu voucher de hotel" % _region["nombre"].title())
                    self.gira_guardar()
            except StopIteration:
                pass
        if getattr(self, "apuesta_ticket", None):
            self.apuesta_tipo = "ia"  # fuerza el cierre del ticket: abandonar con apuesta es perderla
            self.reclamar_apuesta("perder", silencioso=True)
        self.modo_torneo = False
        self.modo_gira_torneo = False
        self.cambiar_pantalla(self.build_gira())

    def gira_torneo_terminado(self, gano):
        """Cierra el mini campeonato: premio, conquista de región y de país, o eliminación."""
        pais = next((p for p in GIRA_PAISES if p["id"] == getattr(self, "gira_pais_id", "")), GIRA_PAISES[0])
        region = next((r for r in pais["regiones"] if r["id"] == getattr(self, "gira_region_id", "")), pais["regiones"][0])
        ronda = self.torneo_nombre_ronda() if not getattr(self, "torneo_finalizado", False) else "Final"
        self.modo_torneo = False
        self.modo_gira_torneo = False
        self.pais_gira = pais
        if not gano:
            con_apuesta = getattr(self, "torneo_con_apuesta", False)

            def perder_inscripcion():
                """Lo normal al perder: la Familia cubre tu voucher de hotel o se gasta. Devuelve el aviso para el cartel."""
                aviso = ""
                datos = self.gira_datos()
                _m = datos.get("mafia") or {}
                if (_m.get("favor") and pais["id"] == "arg" and region["id"] in DESAFIO_REGIONES
                        and gira_tiene_voucher(datos, "hotel", region["id"])):
                    _m["favor"] = 0
                    self.gira_historial(datos, "Perdiste en %s: la Familia cubrió tu voucher de hotel" % region["nombre"].title())
                    self.gira_guardar()
                    aviso = ("¡La Familia te cubrió! Tu voucher de hotel de %s sigue vigente: podés jugar la revancha.\n"
                             "El favor se recarga cuando conquistes otra región.\n" % region["nombre"].title())
                elif gira_gastar_hotel(datos, pais, region):
                    self.gira_historial(datos, "Perdiste en %s: se usó tu voucher de hotel" % region["nombre"].title())
                    self.gira_guardar()
                    aviso = ("Se usó tu voucher de hotel de %s. Para la revancha necesitás otro: ganale al dueño del hotel en Desafío "
                             "o comprá uno.\n" % region["nombre"].title())
                return aviso

            _j = getattr(self, "_fenix_partido", None)
            self._fenix_partido = None
            if _j is not None and gira_tiene_fenix(self.gira_datos()):
                # Ave Fénix: se vuelve a jugar SOLO ese partido (misma ronda y mismo rival) y se sigue en el campeonato.
                def revancha_fenix():
                    d = self.gira_datos()
                    d["fenix"]["usado"] = int(time.time())
                    self.gira_historial(d, "Usaste el Ave Fénix: rejugás la %s en %s" % (ronda.lower(), region["nombre"].title()))
                    self.gira_guardar()
                    a, b, _hecho, _w = self.torneo_eliminatorias[_j]
                    self.torneo_eliminatorias[_j] = (a, b, False, None)   # el partido vuelve a estar pendiente
                    self.modo_torneo = True
                    self.modo_gira_torneo = True
                    self.torneo_finalizado = False
                    self.torneo_campeon = None
                    self.torneo_resultado_registrado = False
                    self.avanzar_campeonato()   # arranca el partido pendiente: el tuyo, contra el mismo rival

                def sin_fenix():
                    if getattr(self, "apuesta_ticket", None):
                        self.reclamar_apuesta("perder", silencioso=True)   # recién ahora se cierra la apuesta
                    self.gira_cartel_eliminado(region, ronda, con_apuesta,
                                               botones=[("VOLVER AL MAPA", lambda: self.gira_volver_mapa())],
                                               aviso=perder_inscripcion())
                try:
                    _rival = self.nombre_equipo(self.torneo_oponente)
                except Exception:
                    _rival = "el mismo rival"
                self.mostrar_cartel("ELIMINADO", "Caíste en %s" % ronda.lower(), False,
                                    detalle="¡Tenés el Ave Fénix!\nRevancha especial: volvés a jugar esta misma %s contra %s "
                                            "y seguís en el campeonato, sin pagar de nuevo la inscripción.\n"
                                            "Se usa UNA sola vez." % (ronda.lower(), _rival),
                                    botones=[("REVANCHA CON EL AVE FÉNIX", revancha_fenix), ("NO USARLO: VOLVER AL MAPA", sin_fenix)],
                                    apilados=True, alto=0.66)
                self.reproducir_efecto("envido_perdido", "pierde")
                return
            self.gira_cartel_eliminado(region, ronda, con_apuesta,
                                       botones=[("VOLVER AL MAPA", lambda: self.gira_volver_mapa())], aviso=perder_inscripcion())
            return
        datos = self.gira_datos()
        premio = region["pt"] // 2
        completo_antes = gira_pais_completo(datos, pais)
        clave = gira_clave(pais, region)
        antes = gira_victorias(datos, pais, region)
        datos["regiones"][clave] = min(GIRA_VICTORIAS_REGION, antes + 1)
        premio = premio if antes < GIRA_VICTORIAS_REGION else 0   # los puntos se cobran solo la primera vez que se conquista la región
        datos["puntos"] += premio
        datos["torneos"] += 1
        datos["pend"].append({"evento": secrets.token_hex(12), "region": clave})
        conquistada = antes < GIRA_VICTORIAS_REGION <= datos["regiones"][clave]
        self.gira_historial(datos, ("Conquistaste %s" if conquistada else "Ganaste el campeonato de %s") % region["nombre"].title())
        completo = (not completo_antes) and gira_pais_completo(datos, pais)
        if conquistada and gira_tiene_tarjeta_mafia(datos):
            datos["mafia"]["favor"] = 1   # el favor de la Familia se recarga con cada región conquistada
        indice = GIRA_PAISES.index(pais)
        ultimo = indice + 1 >= len(GIRA_PAISES)
        nuevo_pais = GIRA_PAISES[indice + 1] if (completo and not ultimo) else None
        datos["pais"] = indice + 1 if nuevo_pais else indice
        self.gira_revisar_hechas(datos)
        self.gira_guardar()
        self.gira_enviar_pendientes()
        self.gira_celebrar(pais, region, premio, conquistada, completo, nuevo_pais,
                           al_terminar=lambda: self.cambiar_pantalla(self.build_gira()))

    def gira_cartel_eliminado(self, region, ronda, con_apuesta, botones=None, aviso=""):
        self.mostrar_cartel("ELIMINADO", f"Caíste en {ronda.lower()}", False,
                            detalle=("No hubo premio y perdiste la apuesta.\n" if con_apuesta else "No hubo premio.\n")
                                   + aviso + (f"Volvé a intentarlo en {region['nombre'].title()}." if not aviso else ""),
                            botones=botones or [("CERRAR", None)], alto=0.5 if not aviso else 0.62)
        self.reproducir_efecto("envido_perdido", "pierde")

    def gira_celebrar(self, pais, region, premio, conquistada, completo, nuevo_pais, al_terminar=None):
        """Celebración al ganar un mini campeonato: región ganada y región (o país) desbloqueado."""
        ultimo = GIRA_PAISES.index(pais) + 1 >= len(GIRA_PAISES)
        if completo:
            titulo = "¡CAMPEÓN DE LA GIRA!" if ultimo else f"¡CAMPEÓN {pais['gentilicio'].upper()}!"
        else:
            titulo = "¡CAMPEÓN!"
        DORADO, VERDE, NARANJA = (1.0, 0.86, 0.35, 1), (0.60, 0.90, 0.40, 1), (0.95, 0.75, 0.35, 1)
        lineas = [(f"Región ganada: [b]{region['nombre']}[/b]", "18sp", DORADO)]
        if premio <= 0:
            lineas.append(("Ya la tenías conquistada: no suma puntos", "13sp", NARANJA))
        if nuevo_pais:
            lineas.append((f"País desbloqueado: [b]{nuevo_pais['nombre']}[/b]", "18sp", VERDE))
        elif completo:
            lineas.append(("¡Recorriste toda la gira!", "18sp", VERDE))
        elif conquistada and region is not pais["regiones"][-1]:
            siguiente_region = pais["regiones"][pais["regiones"].index(region) + 1]
            lineas.append((f"Región desbloqueada: [b]{siguiente_region['nombre']}[/b]", "18sp", VERDE))
            if gira_region_exige_apuesta(pais, siguiente_region):
                lineas.append((f"Se juega con apuesta de {GIRA_APUESTA_REGION} monedas", "13sp", NARANJA))
        if conquistada and pais["id"] == "arg" and any(p.get("region") == region["id"] for p in POSTALES):
            lineas.append(("Postal nueva en Mis pertenencias", "13sp", VERDE))
        if conquistada and not completo and not nuevo_pais and region is not pais["regiones"][-1]:
            siguiente = pais["regiones"][pais["regiones"].index(region) + 1]
            if gira_faltan_vouchers(self.gira_datos(), pais, siguiente):
                seguir = al_terminar
                al_terminar = lambda: self.gira_cartel_invitacion(region, siguiente, seguir)
        self.mostrar_animacion_campeon(getattr(self, "equipo_usuario", "Boca Juniors"), premio=premio, titulo=titulo,
                                       unidad="puntos de gira", lineas=lineas, al_terminar=al_terminar)

    def gira_cartel_invitacion(self, region, siguiente, seguir=None):
        """Cartel aparte, después del de campeón: invitación al torneo de la región siguiente.
        Para viajar hay que tener el pasaje en colectivo y la estadía en el hotel (ganarlos o comprarlos)."""
        datos = self.gira_datos()
        VERDE, GRIS = (0.55, 0.80, 0.25, 1), (0.85, 0.82, 0.78, 1)
        de, a = {"patagonia": ("de la Patagonia", "a la Patagonia"), "cuyo": ("de Cuyo", "a Cuyo"),
                 "mesopotamia": ("de la Mesopotamia", "a la Mesopotamia"), "norte": ("del Norte", "al Norte"),
                 "malvinas": ("de las Malvinas", "a las Malvinas")}.get(
                     siguiente["id"], ("de " + siguiente["nombre"].title(), "a " + siguiente["nombre"].title()))

        def item(texto, tengo):
            return "[color=8ccc40]• %s (listo)[/color]" % texto if tengo else "• %s" % texto
        detalle = "Para poder viajar al torneo necesitás:\n\n%s\n%s\n\nConseguilos y viajá %s!!!" % (
            item("Pasajes de colectivo", gira_tiene_voucher(datos, "viaje", siguiente["id"])),
            item("Estadía en un hotel", gira_tiene_voucher(datos, "hotel", siguiente["id"])), a)

        def etiqueta(texto, tam, alto, color=(1, 1, 1, 1), bold=False):
            et = Label(text=texto, font_size=tam, bold=bold, color=color, markup=True, halign="center",
                       valign="middle", size_hint_y=None, height=dp(alto))
            et.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
            return et
        fondo = CartelFondo(orientation="vertical", padding=[dp(18), dp(14)], spacing=dp(4))
        fondo.add_widget(Adorno())
        fondo.add_widget(etiqueta("%s GANADO" % region["nombre"].upper(), "22sp", 52, bold=True))
        fondo.add_widget(etiqueta("Invitación al torneo %s" % de, "18sp", 52, VERDE))
        cuerpo = Label(text=detalle, font_size="16sp", markup=True, halign="center", valign="middle", color=GRIS)
        cuerpo.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        fondo.add_widget(cuerpo)
        fondo.add_widget(Adorno())
        botones = [("IR A DESAFÍO", lambda: self.cambiar_pantalla(self.build_desafios())), ("VER EL MAPA", seguir)]
        fila = BoxLayout(orientation="vertical", size_hint_y=None, height=dp(50) * len(botones) + dp(8) * (len(botones) - 1),
                         spacing=dp(8))
        popup = Popup(title="", separator_height=0, background="", background_color=(0, 0, 0, 0),
                      content=fondo, size_hint=(0.86, 0.72), auto_dismiss=False)
        for texto, callback in botones:
            b = boton_oscuro(texto, "14sp")

            def cerrar(*_, cb=callback):
                popup.dismiss()
                if getattr(self, "cartel_actual", None) is popup:
                    self.cartel_actual = None
                if cb:
                    cb()
            b.bind(on_release=cerrar)
            fila.add_widget(b)
        fondo.add_widget(fila)
        anterior = getattr(self, "cartel_actual", None)
        if anterior is not None:
            try: anterior.dismiss()
            except Exception: pass
        self.cartel_actual = popup
        popup.open()

    # ---------- presentación de la Gira (con voz) ----------
    def detener_voz(self):
        self._parar_si_suena(getattr(self, "sonido_voz", None))
        tts = getattr(self, "_tts_android", None)
        if tts is not None:
            try: tts.stop()
            except Exception: pass

    def hablar_gira(self, indice, tema="gira"):
        """Narra la diapositiva: audio/gira_N.* (o copa_N.*) si existe; si no, la voz del sistema (Android)."""
        self.detener_voz()
        if not self.audio_permitido():
            return
        self.musica_menu_pausar()
        texto = (COPA_PRESENTACION if tema == "copa" else GIRA_PRESENTACION)[indice][1]
        try:
            ruta = buscar_audio("%s_%d" % (tema, indice + 1)) or (buscar_audio("%s_presentacion" % tema) if indice == 0 else None)
            if ruta:
                self.sonido_voz = SoundLoader.load(ruta)
                if self.sonido_voz is not None:
                    _SONIDOS_VIVOS.append(self.sonido_voz)
                    del _SONIDOS_VIVOS[:-6]
                    self.sonido_voz.play()
                    return
        except Exception as error:
            print("Error voz gira:", error)
        self.tts_hablar(texto)

    def tts_hablar(self, texto):
        """Voz del sistema en español (Android). Si no está disponible, la presentación queda con texto."""
        try:
            from plyer import tts as plyer_tts
            plyer_tts.speak(message=texto)
            return True
        except Exception:
            pass
        try:
            from jnius import autoclass
            PythonActivity = autoclass("org.kivy.android.PythonActivity")
            TextToSpeech = autoclass("android.speech.tts.TextToSpeech")
            Locale = autoclass("java.util.Locale")
            nuevo = getattr(self, "_tts_android", None) is None
            if nuevo:
                self._tts_android = TextToSpeech(PythonActivity.mActivity, None)
            tts = self._tts_android

            def decir(_dt=0):
                try:
                    tts.setLanguage(Locale("es", "AR"))
                    tts.speak(texto, TextToSpeech.QUEUE_FLUSH, None)
                except Exception as error:
                    print("Error TTS:", error)
            if nuevo:
                Clock.schedule_once(decir, 1.0)  # el motor tarda un instante en iniciar
            else:
                decir()
            return True
        except Exception as error:
            print("Sin voz del sistema:", error)
            return False

    def build_presentacion_gira(self, paso=0, al_terminar=None, tema="gira"):
        if self.audio_permitido():
            self.musica_menu_pausar()  # la narración reemplaza a la música del menú
        diapositivas = COPA_PRESENTACION if tema == "copa" else GIRA_PRESENTACION
        paso = max(0, min(paso, len(diapositivas) - 1))
        titulo, texto = diapositivas[paso]
        ultimo = paso == len(diapositivas) - 1
        raiz = MesaBox(orientation="vertical", padding=dp(12), spacing=dp(6))
        raiz.add_widget(Label(text=titulo, font_size="21sp", bold=True, color=(0.96, 0.78, 0.15, 1),
                              size_hint_y=None, height=dp(48), halign="center"))
        if tema == "copa" and paso == 0:
            diapo = EscudosPasan()
        else:
            diapo = DiapositivaGira()
            diapo.tema = tema
        diapo.n = paso
        raiz.add_widget(diapo)
        leyenda = Label(text=texto, font_size="15sp", halign="center", valign="middle", size_hint_y=None, height=dp(120))
        leyenda.bind(size=lambda w, *_: setattr(w, "text_size", (w.width - dp(12), w.height)))
        raiz.add_widget(leyenda)
        puntos = Label(text="  ".join("●" if i == paso else "○" for i in range(len(diapositivas))),
                       font_size="14sp", color=(0.93, 0.74, 0.22, 1), size_hint_y=None, height=dp(24))
        raiz.add_widget(puntos)
        fila = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(50), spacing=dp(10))
        saltar = boton_oscuro("SALTAR", "14sp")
        siguiente = boton_oscuro("EMPEZAR" if ultimo else "SIGUIENTE", "16sp")
        fila.add_widget(saltar)
        fila.add_widget(siguiente)
        fila.add_widget(self.nuevo_boton_sonido(44))
        raiz.add_widget(fila)

        auto = {"evento": None}

        def cancelar_auto():
            if auto["evento"] is not None:
                auto["evento"].cancel()
                auto["evento"] = None

        def terminar(*_):
            cancelar_auto()
            diapo.detener()
            self.detener_voz()
            if al_terminar:
                al_terminar()

        def avanzar(*_):
            cancelar_auto()
            diapo.detener()
            if ultimo:
                terminar()
            else:
                self.cambiar_pantalla(self.build_presentacion_gira(paso + 1, al_terminar, tema))
        saltar.bind(on_release=terminar)
        siguiente.bind(on_release=avanzar)
        diapo.iniciar()
        Clock.schedule_once(lambda _dt: self.hablar_gira(paso, tema), 0.5)
        if tema == "copa":  # la Copa avanza sola cuando termina la narración
            auto["evento"] = Clock.schedule_once(avanzar, self.duracion_diapositiva(texto, tema, paso))
        return raiz

    def duracion_diapositiva(self, texto, tema, indice):
        """Segundos que dura la narración (audio real si existe; si no, estimada por el largo del texto)."""
        try:
            if self.audio_permitido():
                ruta = buscar_audio("%s_%d" % (tema, indice + 1)) or (
                    buscar_audio("%s_presentacion" % tema) if indice == 0 else None)
                dur = duracion_audio(ruta) if ruta else 0.0
                if dur > 0:
                    return dur + 1.0
                return len(texto) / 12.0 + 2.5   # voz del sistema: ~12 caracteres por segundo
        except Exception:
            pass
        return len(texto) / 15.0 + 3.0           # sin sonido: tiempo de lectura

    def mostrar_animacion_campeon(self, equipo=None, premio=0, titulo="¡CAMPEÓN!", unidad="monedas", al_terminar=None,
                                  lineas=None):
        """Celebración de campeón (copa, cartas, confeti, fuegos y fanfarria)."""
        equipo = equipo or getattr(self, "equipo_usuario", "Boca Juniors")
        if titulo == "¡CAMPEÓN!" and getattr(self, "modo_libertadores", False) and getattr(self, "modo_torneo", False):
            titulo = "¡CAMPEÓN DE AMÉRICA!"
        if not getattr(self, "imagenes", None):
            try: self.cargar_imagenes()
            except Exception: self.imagenes = {}
        rutas = {c: self.imagenes.get(c) for c in CARTAS_CAMPEON if getattr(self, "imagenes", None) and self.imagenes.get(c)}
        anterior = getattr(self, "popup_campeon", None)
        if anterior is not None:
            try: anterior.dismiss()
            except Exception: pass
        sonido = None
        try:
            ruta = ruta_fanfarria()
            if ruta and self.audio_permitido():
                self.musica_menu_pausar()
            sonido = SoundLoader.load(ruta) if (ruta and self.audio_permitido()) else None
            self.sonido_campeon = sonido
            if sonido is not None:
                sonido.play()
        except Exception as error:
            print("Error sonido campeón:", error)
        anim = AnimacionCampeon(equipo, rutas, premio=int(premio or 0), titulo=titulo, unidad=unidad, lineas=lineas)
        popup = Popup(title="", separator_height=0, background="", background_color=(0, 0, 0, 0),
                      content=anim, size_hint=(1, 1), auto_dismiss=False)

        def cerrar(*_):
            anim.detener()
            try:
                if sonido is not None:
                    sonido.stop()
            except Exception:
                pass
            if getattr(self, "popup_campeon", None) is popup:
                self.popup_campeon = None
            if al_terminar:
                al_terminar()
            elif getattr(self, "pase_libertadores_aviso", False):
                self.pase_libertadores_aviso = False
                self.mostrar_cartel_pase()
        anim.al_cerrar = popup.dismiss
        popup.bind(on_dismiss=cerrar)
        self.popup_campeon = popup
        popup.open()
        anim.iniciar()

    def mostrar_cartel(self, titulo, resultado, ganaste=True, lineas=(), detalle="", botones=None, alto=0.5, extra=None, apilados=False):
        """Cartel oscuro con borde dorado. lineas = [(texto, resaltada)]; botones = [(texto, callback|None)]."""
        VERDE, NARANJA = (0.55, 0.80, 0.25, 1), (0.93, 0.50, 0.15, 1)
        fondo = CartelFondo(orientation="vertical", padding=[dp(18), dp(14)], spacing=dp(4))
        fondo.add_widget(Adorno())
        fondo.add_widget(Label(text=titulo, font_size="30sp", bold=True, size_hint_y=None, height=dp(58)))
        fondo.add_widget(Label(text=resultado, font_size="24sp", color=VERDE if ganaste else NARANJA,
                               size_hint_y=None, height=dp(48)))
        if detalle:
            et = Label(text=detalle, font_size="15sp", halign="center", valign="middle", color=(0.85, 0.82, 0.78, 1))
            if extra is not None:  # con ficha: el texto toma su alto justo (si no, se cortaba) y la ficha va debajo
                et.size_hint_y = None
                et.bind(width=lambda w, *_: setattr(w, "text_size", (w.width, None)))
                et.bind(texture_size=lambda w, ts: setattr(w, "height", ts[1] + dp(8)))
            else:
                et.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
            fondo.add_widget(et)
        if extra is not None:  # ficha informativa opcional (por ejemplo, las fotos de una región de la Gira)
            fondo.add_widget(extra)
        for texto, resaltada in lineas:
            fondo.add_widget(Label(text=texto, font_size="20sp", size_hint_y=None, height=dp(32),
                                   color=(VERDE if ganaste else NARANJA) if resaltada else (1, 1, 1, 1)))
        fondo.add_widget(Widget())
        if detalle:
            fondo.add_widget(Adorno())
        lista_botones = botones or [("ACEPTAR", None)]
        if apilados:  # botones largos: uno debajo del otro
            fila = BoxLayout(orientation="vertical", size_hint_y=None, height=dp(50) * len(lista_botones) + dp(8) * (len(lista_botones) - 1), spacing=dp(8))
        else:
            fila = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(50), spacing=dp(14))
        popup = Popup(title="", separator_height=0, background="", background_color=(0, 0, 0, 0),
                      content=fondo, size_hint=(0.86, alto), auto_dismiss=False)
        for texto, callback in lista_botones:
            b = boton_oscuro(texto, "14sp" if apilados else "16sp")
            def cerrar(*_, cb=callback):
                popup.dismiss()
                if getattr(self, "cartel_actual", None) is popup:
                    self.cartel_actual = None
                if cb:
                    cb()
            b.bind(on_release=cerrar)
            fila.add_widget(b)
        fondo.add_widget(fila)
        anterior = getattr(self, "cartel_actual", None)
        if anterior is not None:
            try: anterior.dismiss()
            except Exception: pass
        self.cartel_actual = popup
        if extra is not None and hasattr(extra, "detener"):
            popup.bind(on_dismiss=lambda *_: extra.detener())
        popup.open()
        if isinstance(extra, PostalCard):  # ya con el cartel armado, la postal se vuelve a centrar
            Clock.schedule_once(lambda _dt: extra._dibujar(), 0.1)
        if extra is not None and hasattr(extra, "iniciar"):
            extra.iniciar()
        return popup

    def mostrar_cartel_region(self, region, estado, mensaje, detalle="", extra=None, botones=None, alto=0.8):
        """Cartel de una región de la Gira con el estilo del menú principal: mesa de madera con paño, título con relieve,
        etiqueta de estado de color con su icono, y botones de color apilados. estado: bloqueada | misiones | lista | apuesta."""
        ESTADOS = {"bloqueada": ((0.72, 0.58, 0.96), "candado"), "misiones": ((0.95, 0.55, 0.15), "pelota"),
                   "lista": ((0.55, 0.80, 0.25), "copa"), "apuesta": ((0.93, 0.42, 0.40), "copa")}
        color, icono = ESTADOS.get(estado, ESTADOS["lista"])
        claro = tuple(min(1.0, c + 0.18) for c in color) + (1,)
        fondo = MesaBox(orientation="vertical", padding=[dp(22), dp(20)], spacing=dp(7))
        nombre = region["nombre"]
        tam, alto_titulo = (34, 64) if len(nombre) <= 8 else ((28, 58) if len(nombre) <= 11 else (23, 54))
        fondo.add_widget(TituloTruco(nombre, tam, alto_titulo))
        fondo.add_widget(Adorno())
        chip = TarjetaFondo(color, orientation="horizontal", size_hint_y=None, height=dp(54),
                            padding=[dp(10), dp(4), dp(10), dp(4)], spacing=dp(10))
        chip.add_widget(IconoCirculo(icono, 36))
        et = Label(text=mensaje, font_size="17sp", bold=True, color=claro, halign="left", valign="middle")
        et.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        chip.add_widget(et)
        fondo.add_widget(chip)
        if detalle:
            txt = Label(text=detalle, markup=True, font_size="14sp", halign="center", valign="middle",
                        color=(0.96, 0.91, 0.80, 1), size_hint_y=None, height=dp(40))
            txt.bind(width=lambda w, *_: setattr(w, "text_size", (w.width, None)))
            txt.bind(texture_size=lambda w, ts: setattr(w, "height", ts[1] + dp(8)))
            fondo.add_widget(txt)
        if extra is not None:
            if hasattr(extra, "iniciar"):  # ficha con fotos y voz: va dentro de una tarjeta dorada
                marco = TarjetaFondo((0.96, 0.78, 0.30), orientation="vertical", size_hint_y=None,
                                     height=extra.height + dp(14), padding=dp(6))
                marco.add_widget(extra)
                fondo.add_widget(marco)
            else:
                fondo.add_widget(extra)
        fondo.add_widget(Widget())
        if extra is None or not hasattr(extra, "iniciar"):  # con la ficha de fotos no sobra lugar para el adorno
            fondo.add_widget(Adorno())
        lista_botones = botones or [("CERRAR", None)]
        fila = BoxLayout(orientation="vertical", size_hint_y=None, spacing=dp(8),
                         height=dp(50) * len(lista_botones) + dp(8) * (len(lista_botones) - 1))
        popup = Popup(title="", separator_height=0, background="", background_color=(0, 0, 0, 0),
                      content=fondo, size_hint=(0.88, alto), auto_dismiss=False)
        for item in lista_botones:
            texto, callback = item[0], item[1]
            deshabilitado = len(item) > 2 and item[2]   # tercer valor True: botón apagado (se ve pero no se toca)
            gris = texto.upper().startswith("CERRAR")
            b = boton_cartel(texto, (0.72, 0.68, 0.62) if gris else (0.95, 0.55, 0.15), "16sp", 50)
            if deshabilitado:
                b.disabled = True
                b.opacity = 0.4
                fila.add_widget(b)
                continue
            def cerrar(*_, cb=callback):
                popup.dismiss()
                if getattr(self, "cartel_actual", None) is popup:
                    self.cartel_actual = None
                if cb:
                    cb()
            b.bind(on_release=cerrar)
            fila.add_widget(b)
        fondo.add_widget(fila)
        anterior = getattr(self, "cartel_actual", None)
        if anterior is not None:
            try: anterior.dismiss()
            except Exception: pass
        self.cartel_actual = popup
        if extra is not None and hasattr(extra, "detener"):
            popup.bind(on_dismiss=lambda *_: extra.detener())
        popup.open()
        if extra is not None and hasattr(extra, "iniciar"):
            extra.iniciar()
        return popup

    def reproducir_efecto(self, nombre, tipo):
        """Efecto de celebración/derrota (archivo en audio/ o generado)."""
        try:
            ruta = ruta_efecto(nombre, tipo)
            if not ruta or not self.audio_permitido():
                return
            self.musica_menu_pausar()
            anterior = getattr(self, "sonido_efecto", None)
            if anterior is not None:
                try: anterior.stop()
                except Exception: pass
            self.sonido_efecto = SoundLoader.load(ruta)
            if self.sonido_efecto is not None:
                _SONIDOS_VIVOS.append(self.sonido_efecto)
                del _SONIDOS_VIVOS[:-6]
                self.sonido_efecto.play()
        except Exception as error:
            print("Error efecto:", error)

    def reproducir_reparto(self):
        """Corta la música del menú y hace sonar el reparto (audio/reparto.* si existe; si no, uno generado)."""
        try:
            self.musica_menu_pausar()
            if not self.audio_permitido():
                return
            ruta = ruta_efecto("reparto", "reparto")
            if not ruta:
                return
            sonido = getattr(self, "sonido_reparto", None)
            if sonido is None or getattr(self, "_ruta_sonido_reparto", None) != ruta:
                sonido = SoundLoader.load(ruta)
                if sonido is None:
                    return
                self.sonido_reparto = sonido
                self._ruta_sonido_reparto = ruta
                _SONIDOS_VIVOS.append(sonido)
                del _SONIDOS_VIVOS[:-6]
            self._parar_si_suena(sonido)
            sonido.play()
        except Exception as error:
            print("Error sonido de reparto:", error)

    def cartel_envido(self, mis_tantos, tantos_rival, gane, rival="IA"):
        self.reproducir_efecto("envido_ganado" if gane else "envido_perdido", "gana" if gane else "pierde")
        self.mostrar_cartel("Envido", "¡Ganaste!" if gane else "Perdiste...", gane,
                            lineas=[(f"Yo: {mis_tantos}", gane), (f"{rival}: {tantos_rival}", not gane)],
                            alto=0.46)

    def cartel_fin_partida(self, gane, novedades=()):
        online = getattr(self, "modo_online", False)
        botones = []
        mision = getattr(self, "mision_gira_activa", None)
        if online:
            botones.append(("REVANCHA", lambda: self.online_pedir_revancha()))
        elif getattr(self, "desafio_activo", None):
            _des = self.desafio_activo
            _viaje = _des.get("tipo") == "evento"   # el duelo de un encuentro del camino se juega una sola vez
            _diario = _des.get("tipo") in ("diario", "personaje")   # el Truco del día y el personaje del día se juegan una sola vez por día
            if not gane and not _viaje and not _diario:
                botones.append(("REINTENTAR", lambda d=_des: self.desafio_arrancar(d)))
            if _viaje or _des.get("tipo") in ("mago", "cientifico"):
                botones.append(("SEGUIR VIAJE", lambda: self.salir_al_menu(destino=self.build_gira)))
            elif _diario:
                botones.append(("VOLVER A DESAFÍOS", lambda: self.salir_al_menu(destino=self.build_desafios_diarios)))
            else:
                botones.append(("VOLVER A DESAFÍOS", lambda: self.salir_al_menu(destino=self.build_desafios)))
        elif mision:
            if self.gira_mision_pendiente(mision):
                monto = GIRA_MISION_APUESTA.get(mision, 0)
                botones.append(("SEGUIR: APOSTAR %d" % monto if monto else "SEGUIR: OTRA PARTIDA",
                                lambda m=mision: self.gira_jugar_mision(m)))
            botones.append(("VOLVER A LA GIRA", lambda: self.salir_al_menu(destino=self.build_gira)))
        elif not getattr(self, "apuesta_ticket", None) and not getattr(self, "desafio_activo", None):
            botones.append(("REVANCHA", lambda: self.reiniciar()))
        if not mision and not getattr(self, "desafio_activo", None):
            botones.append(("CONTINUAR", None))
        detalle = f"Resultado final: {self.puntos_jugador} - {self.puntos_ia}"
        if novedades:
            detalle += "\n\n" + "\n".join(novedades)
        self.mostrar_cartel("FIN DE PARTIDA", "¡Ganaste el partido!" if gane else "Perdiste el partido...", gane,
                            detalle=detalle, botones=botones, alto=min(0.84, 0.5 + 0.07 * len(novedades)))

    # ---------- chat con el rival (online) ----------
    def chat_no_leidos_texto(self):
        n = int(getattr(self, "chat_no_leidos", 0))
        return f"Chat ({n})" if n else "Chat"

    def chat_refrescar_boton(self):
        boton = getattr(self, "btn_chat", None)
        if boton is not None:
            boton.text = self.chat_no_leidos_texto()
            boton.background_color = (0.55, 0.38, 0.05, 1) if getattr(self, "chat_no_leidos", 0) else COLOR_BOTON

    def chat_agregar(self, autor, texto, mio):
        mensajes = getattr(self, "chat_mensajes", None)
        if mensajes is None:
            mensajes = self.chat_mensajes = []
        mensajes.append((autor, texto, mio))
        del mensajes[:-100]
        lista = getattr(self, "chat_lista", None)
        if lista is not None and getattr(self, "chat_popup", None) is not None:
            lista.add_widget(BurbujaChat(autor, texto, mio))
            scroll = getattr(self, "chat_scroll", None)
            if scroll is not None:
                Clock.schedule_once(lambda _dt: setattr(scroll, "scroll_y", 0), 0.05)

    def enviar_chat(self, texto):
        texto = limpiar_chat(texto)
        if not texto or not getattr(self, "modo_online", False):
            return False
        ahora = time.time()
        if ahora - getattr(self, "chat_ultimo_envio", 0) < 0.7:
            return False  # evita spam
        if not self.online_enviar_evento("chat", {"texto": texto}):
            return False
        self.chat_ultimo_envio = ahora
        self.chat_agregar("Yo", texto, True)
        return True

    def online_recibir_chat(self, datos):
        texto = limpiar_chat((datos or {}).get("texto", ""))
        if not texto:
            return
        rival = str(getattr(self, "equipo_ia", "Rival"))[:24]
        self.chat_agregar(rival, texto, False)
        if getattr(self, "chat_popup", None) is None:
            self.chat_no_leidos = int(getattr(self, "chat_no_leidos", 0)) + 1
            self.chat_refrescar_boton()

    def abrir_chat(self, *_):
        if not getattr(self, "modo_online", False):
            return
        self.chat_no_leidos = 0
        self.chat_refrescar_boton()
        contenido = MesaBox(orientation="vertical", padding=dp(10), spacing=dp(6))
        rival = str(getattr(self, "equipo_ia", "Rival"))
        contenido.add_widget(Label(text=f"Chat con {rival}", font_size="16sp", bold=True,
                                   color=(0.93, 0.74, 0.22, 1), size_hint_y=None, height=dp(30)))
        scroll = ScrollView(do_scroll_x=False, bar_width=dp(4))
        lista = GridLayout(cols=1, spacing=dp(2), size_hint_y=None)
        lista.bind(minimum_height=lista.setter("height"))
        for autor, texto, mio in getattr(self, "chat_mensajes", []):
            lista.add_widget(BurbujaChat(autor, texto, mio))
        scroll.add_widget(lista)
        contenido.add_widget(scroll)
        frases = GridLayout(cols=2, spacing=dp(4), size_hint_y=None, height=dp(34) * (len(FRASES_CHAT) // 2))
        for frase in FRASES_CHAT:
            b = boton_oscuro(frase, "12sp")
            b.bind(on_release=lambda *_, f=frase: self.enviar_chat(f))
            frases.add_widget(b)
        contenido.add_widget(frases)
        fila = BoxLayout(orientation="horizontal", size_hint_y=None, height=dp(46), spacing=dp(6))
        entrada = TextInput(hint_text="Escribí un mensaje", multiline=False, font_size="15sp")
        enviar = boton_oscuro("Enviar", "14sp")
        enviar.size_hint_x = None
        enviar.width = dp(80)

        def mandar(*_):
            if self.enviar_chat(entrada.text):
                entrada.text = ""
        enviar.bind(on_release=mandar)
        entrada.bind(on_text_validate=mandar)
        fila.add_widget(entrada)
        fila.add_widget(enviar)
        contenido.add_widget(fila)
        cerrar = boton_oscuro("Cerrar", "14sp")
        cerrar.size_hint_y = None
        cerrar.height = dp(40)
        contenido.add_widget(cerrar)
        popup = Popup(title="", separator_height=0, content=contenido, size_hint=(0.95, 0.88), auto_dismiss=False)

        def limpiar(*_):
            if getattr(self, "chat_popup", None) is popup:
                self.chat_popup = None
                self.chat_lista = None
                self.chat_scroll = None
        popup.bind(on_dismiss=limpiar)
        cerrar.bind(on_release=popup.dismiss)
        self.chat_popup, self.chat_lista, self.chat_scroll = popup, lista, scroll
        popup.open()
        Clock.schedule_once(lambda _dt: setattr(scroll, "scroll_y", 0), 0.1)

    # ---------- invitación a una sala ----------
    def texto_invitacion(self, codigo):
        nombre = (getattr(self, "perfil_usuario", None) or {}).get("nombre", "").strip() or "Un amigo"
        _t = getattr(self, "tpriv", None)
        if _t and _t.get("room") == codigo:
            return (f"¡{nombre} te invita a su torneo privado de Truco! En el juego entrá a Online > Entrar con código "
                    f"y poné este código: {codigo}")
        return (f"¡{nombre} te invita a jugar al Truco! En el juego entrá a Online > Entrar con código "
                f"y poné este código: {codigo}")

    def invitar_whatsapp(self, codigo):
        url = "https://wa.me/?text=" + urllib.parse.quote(self.texto_invitacion(codigo))
        try:
            webbrowser.open(url)
        except Exception:
            try: Clipboard.copy(self.texto_invitacion(codigo))
            except Exception: pass

    def compartir_invitacion(self, codigo):
        texto = self.texto_invitacion(codigo)
        try:
            from jnius import autoclass  # disponible en Android (APK / Pydroid)
            Intent = autoclass("android.content.Intent")
            PythonActivity = autoclass("org.kivy.android.PythonActivity")
            intento = Intent(Intent.ACTION_SEND)
            intento.setType("text/plain")
            intento.putExtra(Intent.EXTRA_TEXT, texto)
            PythonActivity.mActivity.startActivity(Intent.createChooser(intento, "Invitar a jugar"))
        except Exception:
            try: Clipboard.copy(texto)
            except Exception: pass
            self.online_aviso("Copié la invitación. Pegala donde quieras para mandarla.")

    def online_aviso(self, mensaje, titulo="Online", botones=None):
        contenido = self._cartel_online(titulo)
        etiqueta = Label(text=mensaje, font_size="15sp", halign="center", valign="middle", color=(0.93, 0.90, 0.85, 1))
        etiqueta.bind(size=lambda inst, size: setattr(inst, "text_size", size))
        contenido.add_widget(etiqueta)
        for texto_b, accion_b in (botones or []):
            extra = boton_cartel(texto_b, (0.96, 0.78, 0.15), "15sp", 56)
            extra.bind(on_release=lambda *_, a=accion_b: a())
            contenido.add_widget(extra)
        cerrar = boton_cartel("CERRAR", (0.70, 0.67, 0.62), "15sp", 56)
        contenido.add_widget(cerrar)
        anterior = getattr(self, "online_popup_actual", None)
        if anterior is not None:
            try: anterior.dismiss()
            except Exception: pass
        popup = self._popup_cartel(contenido, alto_rel=0.44 + 0.09 * len(botones or []))
        cerrar.bind(on_release=popup.dismiss)

        def limpiar(*_):
            # Evita escribir después en una etiqueta de un popup ya cerrado.
            if getattr(self, "online_popup_actual", None) is popup:
                self.online_popup_actual = None
                self.online_label_actual = None
        popup.bind(on_dismiss=limpiar)
        popup.open()
        self.online_popup_actual = popup
        self.online_label_actual = etiqueta

    def online_pedir_codigo(self):
        panel = self._cartel_online("Unirse a sala")
        pista = Label(text="Ingresá el código que te pasó tu rival", font_size="14sp", halign="center", valign="middle",
                      color=(0.93, 0.90, 0.85, 1), size_hint_y=None, height=dp(34))
        pista.bind(size=lambda w, *_: setattr(w, "text_size", (w.width, w.height)))
        panel.add_widget(pista)
